@Composable
private fun HomeOfflineNotice(
    title: String,
    message: String,
    retryLabel: String,
    onRetry: () -> Unit
) {
    Surface(
        color = CinematicGlass.copy(alpha = 0.62f),
        border = BorderStroke(1.dp, DerbisCyan.copy(alpha = 0.20f)),
        shape = DerbisCardDesign.SurfaceShape,
        modifier = Modifier.fillMaxWidth()
    ) {
        Row(
            modifier = Modifier.padding(start = 16.dp, top = 12.dp, end = 8.dp, bottom = 12.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(14.dp)
        ) {
            Icon(
                imageVector = Icons.Rounded.CloudOff,
                contentDescription = null,
                tint = DerbisCyan.copy(alpha = 0.82f),
                modifier = Modifier.size(22.dp)
            )
            Column(
                modifier = Modifier.weight(1f),
                verticalArrangement = Arrangement.spacedBy(3.dp)
            ) {
                Text(
                    text = title,
                    color = DerbisText,
                    fontSize = 15.sp,
                    lineHeight = DerbisTypeRhythm.lineHeight(15.sp),
                    fontWeight = FontWeight.SemiBold
                )
                Text(
                    text = message,
                    color = DerbisMuted,
                    fontSize = 12.sp,
                    lineHeight = DerbisTypeRhythm.lineHeight(12.sp),
                    fontWeight = FontWeight.Medium
                )
            }
            Box(
                modifier = Modifier
                    .heightIn(min = 48.dp)
                    .clip(DerbisHomeDesign.MoodChipShape)
                    .derbisPressable(
                        onClick = onRetry,
                        pressedScale = DerbisPressScale.Control,
                        role = Role.Button,
                        onClickLabel = retryLabel
                    )
                    .padding(horizontal = 14.dp, vertical = 14.dp),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = retryLabel,
                    color = DerbisCyan,
                    fontSize = 13.sp,
                    lineHeight = DerbisTypeRhythm.lineHeight(13.sp),
                    fontWeight = FontWeight.Bold
                )
            }
        }
    }
}

@Composable
private fun HomeOfflinePlaylistRow(
    playlists: List<com.yasuda.derbis.domain.Playlist>,
    animationsEnabled: Boolean,
    onOpen: (com.yasuda.derbis.domain.Playlist) -> Unit
) {
    if (playlists.isEmpty()) return
    val strings = LocalDerbisStrings.current
    val effectiveAnimationsEnabled = animationsEnabled && LocalAnimationsEnabled.current
    BoxWithConstraints(modifier = Modifier.fillMaxWidth()) {
        val cardWidth = rememberShelfItemWidth(maxWidth, DerbisHomeDesign.ArtworkCardWidth)
        LazyRow(
            horizontalArrangement = Arrangement.spacedBy(DerbisHomeDesign.ShelfItemGap),
            contentPadding = PaddingValues(start = HomeHorizontalInset, end = HomeHorizontalShelfEndPadding)
        ) {
            items(
                items = playlists,
                key = { playlist -> "home-offline-playlist-" + playlist.id },
                contentType = { "home-offline-playlist-card" }
            ) { playlist ->
                val interaction = remember { MutableInteractionSource() }
                val isPressed by interaction.collectIsPressedAsState()
                val scale by animateFloatAsState(
                    targetValue = if (isPressed && effectiveAnimationsEnabled) 0.975f else 1f,
                    animationSpec = tween(durationMillis = 150, easing = FastOutSlowInEasing),
                    label = "homeOfflinePlaylistScale"
                )
                Column(
                    modifier = Modifier
                        .graphicsLayer {
                            scaleX = scale
                            scaleY = scale
                        }
                        .width(cardWidth)
                        .clickable(
                            interactionSource = interaction,
                            indication = null,
                            onClick = { onOpen(playlist) }
                        ),
                    verticalArrangement = Arrangement.spacedBy(DerbisCardDesign.CaptionTopGap)
                ) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .aspectRatio(1f)
                            .clip(DerbisHomeDesign.ArtworkShape)
                            .background(Brush.linearGradient(listOf(DerbisPanel, DerbisInk))),
                        contentAlignment = Alignment.Center
                    ) {
                        if (playlist.coverUrl.isNotBlank()) {
                            StableRemoteArtwork(
                                url = playlist.coverUrl,
                                contentDescription = playlist.name,
                                contentScale = ContentScale.Crop,
                                modifier = Modifier.fillMaxSize()
                            )
                        } else {
                            Icon(
                                imageVector = Icons.AutoMirrored.Rounded.QueueMusic,
                                contentDescription = null,
                                tint = DerbisCyan.copy(alpha = 0.78f),
                                modifier = Modifier.size(42.dp)
                            )
                        }
                    }
                    DerbisCardCaption(
                        title = playlist.name,
                        subtitle = strings.formatTrackCount(playlist.size)
                    )
                }
            }
        }
    }
}

private fun cinematicGlassBrush(
    accentStart: Color = DerbisCyan,
    accentEnd: Color = DerbisViolet,
    intensity: Float = 1f
): Brush {
    if (DerbisIsNocturne) return Brush.linearGradient(listOf(DerbisPanel, DerbisPanel))
    return if (DerbisIsLight) {
        Brush.linearGradient(
            listOf(
                Color.White.copy(alpha = 0.96f),
                Color(0xFFF7F9FF).copy(alpha = 0.94f),
                accentStart.copy(alpha = 0.08f * intensity),
                accentEnd.copy(alpha = 0.06f * intensity),
                Color(0xFFF2F5FF).copy(alpha = 0.92f)
            )
        )
    } else {
        Brush.linearGradient(
            listOf(
                accentStart.copy(alpha = 0.13f * intensity),
                CinematicGlass.copy(alpha = 0.96f),
                CinematicGlassDeep.copy(alpha = 0.98f),
                accentEnd.copy(alpha = 0.10f * intensity)
            )
        )
    }
}

private fun cinematicTextBrush(): Brush {
    return if (DerbisIsLight) {
        Brush.linearGradient(
            listOf(
                DerbisText,
                DerbisCyan.copy(alpha = 0.95f),
                DerbisViolet.copy(alpha = 0.90f),
                Color(0xFF283044)
            )
        )
    } else {
        Brush.linearGradient(
            listOf(
                Color.White,
                DerbisCyan.copy(alpha = 0.92f),
                DerbisViolet.copy(alpha = 0.86f),
                CinematicGold.copy(alpha = 0.82f)
            )
        )
    }
}

internal data class DerbisTabEntry(
    val tab: DerbisTab,
    val selectedIcon: ImageVector,
    val unselectedIcon: ImageVector,
    val label: String
)

@Composable
internal fun rememberDerbisTabEntries(): List<DerbisTabEntry> {
    val strings = LocalDerbisStrings.current
    val nocturne = DerbisIsNocturne
    return remember(strings, nocturne) {
        listOf(
            DerbisTabEntry(DerbisTab.Home, if (nocturne) Icons.Outlined.Home else Icons.Rounded.Home, Icons.Outlined.Home, strings.home),
            DerbisTabEntry(DerbisTab.Search, if (nocturne) Icons.Outlined.Search else Icons.Rounded.Search, Icons.Outlined.Search, strings.search),
            DerbisTabEntry(DerbisTab.Explore, if (nocturne) Icons.Outlined.Explore else Icons.Rounded.Explore, Icons.Outlined.Explore, strings.explore),
            DerbisTabEntry(DerbisTab.Library, if (nocturne) Icons.Outlined.LibraryMusic else Icons.Rounded.LibraryMusic, Icons.Outlined.LibraryMusic, strings.library)
        )
    }
}

@Composable
private fun RowScope.TabButton(
    entry: DerbisTabEntry,
    isSelected: Boolean,
    selectedTint: Color,
    compaction: () -> Float,
    onClick: () -> Unit
) {
    val animationsEnabled = LocalAnimationsEnabled.current
    val interactionSource = remember { MutableInteractionSource() }
    val pressed by interactionSource.collectIsPressedAsState()
    val idleTint = DerbisMuted
    val selectedProgress by animateFloatAsState(
        targetValue = if (isSelected) 1f else 0f,
        animationSpec = if (animationsEnabled) {
            spring(dampingRatio = 0.82f, stiffness = Spring.StiffnessMediumLow)
        } else {
            snap()
        },
        label = "tab-selected-progress"
    )
    val iconScale by animateFloatAsState(
        targetValue = if (pressed) 0.88f else if (isSelected) 1.06f else 1f,
        animationSpec = if (animationsEnabled) {
            spring(dampingRatio = 0.62f, stiffness = Spring.StiffnessMedium)
        } else {
            snap()
        },
        label = "tab-icon-scale"
    )
    val iconTint by animateColorAsState(
        targetValue = if (isSelected) selectedTint else idleTint,
        animationSpec = if (animationsEnabled) tween(220) else snap(),
        label = "tab-icon-tint"
    )
    val labelTint by animateColorAsState(
        targetValue = if (isSelected) selectedTint else idleTint,
        animationSpec = if (animationsEnabled) tween(220) else snap(),
        label = "tab-label-tint"
    )

    Box(
        modifier = Modifier
            .weight(1f)
            .fillMaxHeight()
            .semantics(mergeDescendants = true) {
                role = Role.Tab
                selected = isSelected
            }
            .pressable(
                interactionSource = interactionSource,
                pressedScale = 0.93f,
                onClick = onClick
            ),
        contentAlignment = Alignment.TopCenter
    ) {
        Column(
            modifier = Modifier.padding(top = DerbisTabIndicatorTop),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(3.dp)
        ) {
            Box(
                modifier = Modifier.height(DerbisTabIndicatorHeight),
                contentAlignment = Alignment.Center
            ) {
                Icon(
                    imageVector = if (isSelected) entry.selectedIcon else entry.unselectedIcon,
                    contentDescription = null,
                    tint = iconTint,
                    modifier = Modifier
                        .size(22.dp)
                        .graphicsLayer {
                            scaleX = iconScale
                            scaleY = iconScale
                            translationY = -1.5.dp.toPx() * selectedProgress
                        }
                )
            }
            Text(
                text = entry.label,
                color = labelTint,
                fontSize = 10.5.sp,
                lineHeight = DerbisTypeRhythm.lineHeight(10.5.sp),
                letterSpacing = 0.1.sp,
                fontWeight = if (isSelected) FontWeight.ExtraBold else FontWeight.Medium,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                textAlign = TextAlign.Center,
                modifier = Modifier
                    .padding(horizontal = 3.dp)
                    .graphicsLayer { alpha = dockFade(compaction()) }
            )
        }
    }
}
