@Composable
private fun HomeChip(
    label: String,
    selected: Boolean,
    onClick: () -> Unit,
    exposeSelectionState: Boolean = true
) {
    val background = when {
        selected && DerbisIsLight -> Color(0xFF11131F)
        selected -> Color.White
        DerbisIsLight -> Color(0x1411131F)
        else -> Color.White.copy(alpha = 0.10f)
    }
    val content = when {
        selected && DerbisIsLight -> Color.White
        selected -> Color(0xFF07080C)
        else -> DerbisText
    }
    Box(
        modifier = Modifier
            .height(DerbisHomeDesign.MoodChipHeight)
            .pressable(onClick = onClick)
            .then(
                if (exposeSelectionState) Modifier.semantics { this.selected = selected } else Modifier
            ),
        contentAlignment = Alignment.Center
    ) {
        Row(
            modifier = Modifier
                .height(DerbisHomeDesign.MoodChipVisualHeight)
                .background(background, DerbisHomeDesign.MoodChipShape)
                .padding(horizontal = 14.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(6.dp)
        ) {
            Text(
                text = label,
                color = content,
                fontSize = 14.sp,
                lineHeight = DerbisTypeRhythm.lineHeight(14.sp),
                fontWeight = FontWeight.Medium,
                maxLines = 1
            )
        }
    }
}

private val DerbisWideArtworkAlignment = BiasAlignment(0f, -0.35f)

@Composable
internal fun CoverImage(
    track: Track,
    modifier: Modifier,
    highRes: Boolean = true,
    zoom: Float = 1f,
    alignment: Alignment = Alignment.Center,
    onImageLoaded: ((CoilImage) -> Unit)? = null
) {
    val context = LocalContext.current
    val models = remember(
        context,
        track.id,
        track.title,
        track.artist,
        track.videoUrl,
        track.thumbnailUrl,
        track.largeThumbnailUrl,
        highRes
    ) {
        DerbisArtworkCache.models(context, track, highRes)
    }
    var modelIndex by remember(models) { mutableStateOf(0) }
    val model = models.getOrNull(modelIndex)
    val crossfadeMs = if (LocalAnimationsEnabled.current && highRes && model !is File) 120 else 0
    var artworkLoaded by remember(track.id, highRes, model) { mutableStateOf(false) }
    var artworkSucceeded by remember(track.id, highRes, model) { mutableStateOf(false) }
    var artworkUnavailable by remember(track.id, highRes) { mutableStateOf(false) }
    LaunchedEffect(artworkSucceeded, crossfadeMs) {
        if (artworkSucceeded) {
            if (crossfadeMs > 0) delay(crossfadeMs.toLong())
            artworkLoaded = true
        }
    }
    val artworkKey = remember(track.id, highRes) { "${track.id}:${if (highRes) "large" else "small"}" }
    val modelIdentity = remember(model) {
        when (model) {
            is File -> "file:${model.absolutePath}"
            null -> "missing"
            else -> "remote:${model}"
        }
    }
    val requestSource = remember(model) {
        when (model) {
            is File -> ArtworkRequestSource.PersistentFile
            null -> ArtworkRequestSource.Missing
            else -> ArtworkRequestSource.Remote
        }
    }
    if (BuildConfig.DEBUG) {
        LaunchedEffect(artworkKey, modelIdentity, requestSource) {
            DerbisArtworkStartupMetrics.recordArtworkRequest(artworkKey, modelIdentity, requestSource)
            if (model == null) DerbisArtworkStartupMetrics.recordArtworkLoading(artworkKey)
        }
    }
    Box(modifier = modifier, contentAlignment = Alignment.Center) {
        if (!artworkLoaded) {
            InstantArtworkPlaceholder(
                loading = model != null && !artworkUnavailable,
                modifier = Modifier.fillMaxSize()
            )
        }
        if (model != null) {
            val request = remember(context, model, crossfadeMs) {
                ImageRequest.Builder(context)
                    .data(model)
                    .memoryCachePolicy(CachePolicy.ENABLED)
                    .diskCachePolicy(CachePolicy.ENABLED)
                    .networkCachePolicy(CachePolicy.ENABLED)
                    .crossfade(crossfadeMs)
                    .build()
            }
            AsyncImage(
                model = request,
                contentDescription = track.title,
                contentScale = ContentScale.Crop,
                alignment = alignment,
                filterQuality = FilterQuality.High,
                onLoading = { DerbisArtworkStartupMetrics.recordArtworkLoading(artworkKey) },
                onSuccess = { state ->
                    artworkSucceeded = true
                    DerbisArtworkStartupMetrics.recordArtworkDisplayed(artworkKey)
                    onImageLoaded?.invoke(state.result.image)
                },
                onError = {
                    DerbisArtworkStartupMetrics.recordArtworkFailure(artworkKey)
                    if (modelIndex < models.lastIndex) modelIndex += 1 else artworkUnavailable = true
                },
                modifier = Modifier.fillMaxSize().scale(zoom)
            )
        }
    }
}

@Composable
internal fun InstantArtworkPlaceholder(
    modifier: Modifier,
    loading: Boolean = false
) {
    // Never manufacture cover text, genre stickers, or initials. A cover is either loading or
    // unavailable; both states stay visually quiet until real artwork exists.
    val neutralSurface = if (DerbisIsLight) Color(0xFFE6E7EB) else Color(0xFF24262C)
    Box(
        modifier = modifier.background(neutralSurface),
        contentAlignment = Alignment.Center
    ) {
        if (loading) {
            DerbisLoadingIndicator(
                modifier = Modifier.size(26.dp),
                color = DerbisText.copy(alpha = 0.72f)
            )
        }
    }
}
@Composable
private fun EmptyCover(modifier: Modifier) {
    Box(
        modifier = modifier.background(Brush.linearGradient(listOf(DerbisCyan.copy(alpha = 0.72f), DerbisViolet.copy(alpha = 0.72f)))),
        contentAlignment = Alignment.Center
    ) {
        Icon(Icons.Rounded.MusicNote, null, tint = DerbisBlack, modifier = Modifier.size(30.dp))
    }
}

@Composable
private fun HomeNowPlayingScrim(
    isPlaying: Boolean,
    isResolving: Boolean,
    modifier: Modifier = Modifier
) {
    Surface(
        color = Color.Black.copy(alpha = 0.52f),
        modifier = modifier.fillMaxSize()
    ) {
        Box(contentAlignment = Alignment.Center) {
            when {
                isResolving -> DerbisLoadingIndicator(
                    modifier = Modifier.size(18.dp),
                    color = DerbisCyan
                )
                isPlaying -> ActiveTrackEqualizer(
                    color = DerbisCyan,
                    isPlaying = true,
                    width = 16.dp,
                    height = 13.dp
                )
                else -> Icon(
                    imageVector = Icons.Rounded.PlayArrow,
                    contentDescription = null,
                    tint = Color.White,
                    modifier = Modifier.size(18.dp)
                )
            }
        }
    }
}

@Composable
private fun HomeTrackRow(
    track: Track,
    isCurrent: Boolean,
    isPlaying: Boolean,
    isResolving: Boolean,
    onPlay: () -> Unit,
    modifier: Modifier = Modifier,
    leadingContent: (@Composable () -> Unit)? = null,
    trailingContent: (@Composable () -> Unit)? = null,
    onActions: (() -> Unit)? = null
) {
    Row(
        modifier = modifier
            .fillMaxWidth()
            .height(DerbisHomeDesign.TrackRowHeight)
            .clip(DerbisCardDesign.ThumbShape)
            .pressable(onClick = onPlay)
            .padding(horizontal = 4.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        leadingContent?.invoke()
        Box(
            modifier = Modifier
                .size(DerbisHomeDesign.TrackThumbSize)
                .clip(DerbisHomeDesign.ThumbShape)
                .background(DerbisPanel),
            contentAlignment = Alignment.Center
        ) {
            CoverImage(
                track = track,
                modifier = Modifier.fillMaxSize(),
                highRes = false
            )
            if (isCurrent) {
                HomeNowPlayingScrim(
                    isPlaying = isPlaying,
                    isResolving = isResolving
                )
            }
        }
        DerbisRowText(
            title = track.title,
            subtitle = track.artist,
            titleColor = if (isCurrent) DerbisCyan else DerbisText,
            modifier = Modifier
                .weight(1f)
                .padding(start = 12.dp, end = 8.dp)
        )
        when {
            trailingContent != null -> trailingContent()
            onActions != null -> {
                IconButton(
                    onClick = onActions,
                    modifier = Modifier.size(36.dp)
                ) {
                    Icon(
                        imageVector = Icons.Rounded.MoreVert,
                        contentDescription = "${LocalDerbisStrings.current.songOptions}, ${track.title}",
                        tint = DerbisMuted,
                        modifier = Modifier.size(20.dp)
                    )
                }
            }
        }
    }
}

@Composable
private fun HomeArtworkCard(
    track: Track,
    isCurrent: Boolean,
    isPlaying: Boolean,
    isResolving: Boolean,
    width: Dp,
    onPlay: () -> Unit,
    modifier: Modifier = Modifier
) {
    Column(
        modifier = modifier
            .width(width)
            .pressable(onClick = onPlay),
        verticalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .aspectRatio(1f)
                .clip(DerbisHomeDesign.ArtworkShape)
                .background(DerbisPanel)
        ) {
            CoverImage(
                track = track,
                modifier = Modifier.fillMaxSize(),
                highRes = false
            )
            if (isCurrent) {
                HomeNowPlayingScrim(
                    isPlaying = isPlaying,
                    isResolving = isResolving
                )
            }
        }
        Column(verticalArrangement = Arrangement.spacedBy(2.dp)) {
            Text(
                text = track.title,
                color = if (isCurrent) DerbisCyan else DerbisText,
                fontSize = DerbisHomeDesign.CardTitleSize,
                lineHeight = DerbisTypeRhythm.lineHeight(DerbisHomeDesign.CardTitleSize),
                fontWeight = FontWeight.SemiBold,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
            val meta = displayableAlbumLabel(track) ?: track.artist
            Text(
                text = meta,
                color = DerbisMuted,
                fontSize = DerbisHomeDesign.CardSubtitleSize,
                lineHeight = DerbisTypeRhythm.lineHeight(DerbisHomeDesign.CardSubtitleSize),
                fontWeight = FontWeight.Normal,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
        }
    }
}

@Composable
private fun HomeTrackColumnsShelf(
    title: String,
    tracks: List<Track>,
    currentId: String?,
    isPlaying: Boolean,
    isResolving: Boolean,
    onPlay: (Track) -> Unit,
    onPlayAll: (() -> Unit)? = null,
    onTrackActions: ((Track) -> Unit)? = null
) {
    if (tracks.isEmpty()) return
    val distinctTracks = remember(tracks) {
        tracks.distinctBy(DerbisPersonalOrbit::identityKey)
    }
    val columns = remember(distinctTracks) {
        distinctTracks.chunked(DerbisHomeDesign.TRACK_COLUMN_ROWS)
    }
    if (columns.isEmpty()) return

    val density = LocalDensity.current
    val containerWidthPx = LocalWindowInfo.current.containerSize.width
    val columnWidth = remember(containerWidthPx, density) {
        val availableWidth = with(density) { containerWidthPx.toDp() }
        (availableWidth - DerbisHomeDesign.HorizontalInset - DerbisHomeDesign.TrackColumnPeek)
            .coerceIn(280.dp, 360.dp)
    }

    val lazyListState = rememberLazyListState()

    Column(verticalArrangement = Arrangement.spacedBy(homeHeaderContentGap())) {
        HomeSectionInset {
            HomeSectionHeader(
                title = title,
                onPlayAll = onPlayAll
            )
        }
        LazyRow(
            state = lazyListState,
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(DerbisHomeDesign.TrackColumnGap),
            contentPadding = PaddingValues(
                start = DerbisHomeDesign.HorizontalInset,
                end = DerbisHomeDesign.HorizontalInset + DerbisHomeDesign.TrackColumnPeek
            )
        ) {
            itemsIndexed(
                items = columns,
                key = { columnIndex, col ->
                    col.joinToString(prefix = "track-col-$columnIndex-", separator = "|") { it.id.ifBlank { it.title } }
                },
                contentType = { _, _ -> "home-track-column" }
            ) { _, col ->
                Column(
                    modifier = Modifier.width(columnWidth),
                    verticalArrangement = Arrangement.spacedBy(3.dp)
                ) {
                    col.forEachIndexed { rowIndex, track ->
                        val isCurrent = track.id == currentId
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(derbisGroupedListShape(rowIndex, col.size))
                                .background(MaterialTheme.colorScheme.surfaceContainerHigh.copy(alpha = 0.62f))
                                .padding(horizontal = 8.dp, vertical = 2.dp)
                        ) {
                            HomeTrackRow(
                                track = track,
                                isCurrent = isCurrent,
                                isPlaying = isPlaying && isCurrent,
                                isResolving = isResolving && isCurrent,
                                onPlay = { onPlay(track) },
                                onActions = onTrackActions?.let { actions -> { actions(track) } }
                            )
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun EmptyState(text: String) {
    Surface(
        color = CinematicGlass.copy(alpha = 0.66f),
        border = BorderStroke(1.dp, Color.White.copy(alpha = 0.10f)),
        shape = RoundedCornerShape(24.dp),
        modifier = Modifier.fillMaxWidth()
    ) {
        Column(
            modifier = Modifier.padding(24.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            Text("🎵", fontSize = 28.sp)
            Text(text, color = DerbisMuted, fontSize = 14.sp, fontWeight = FontWeight.Bold, textAlign = TextAlign.Center)
        }
    }
}
@Composable
internal fun Modifier.pressable(
    enabled: Boolean = true,
    interactionSource: MutableInteractionSource? = null,
    pressedScale: Float = DerbisPressScale.Control,
    onLongClickLabel: String? = null,
    onLongClick: (() -> Unit)? = null,
    haptic: DerbisHapticAction? = null,
    onClick: () -> Unit
): Modifier = derbisPressable(
    onClick = onClick,
    enabled = enabled,
    pressedScale = pressedScale,
    interactionSource = interactionSource,
    onLongClickLabel = onLongClickLabel,
    onLongClick = onLongClick,
    haptic = haptic
)

private fun Modifier.blockTouchesBehind(): Modifier = pointerInput(Unit) {
    awaitPointerEventScope {
        while (true) awaitPointerEvent()
    }
}

private fun Modifier.consumeOverlayTouches(): Modifier = pointerInput(Unit) {
    awaitPointerEventScope {
        while (true) {
            val event = awaitPointerEvent(PointerEventPass.Final)
            event.changes.forEach { change ->
                if (!change.isConsumed) change.consume()
            }
        }
    }
}

@Composable
fun DerbisApp(
    viewModel: DerbisViewModel,
    onExitApplication: () -> Unit = {},
    isInPictureInPicture: Boolean = false,
    onRetryPreUpdateBackup: () -> Unit = {},
    onContinueUpdateWithoutBackup: () -> Unit = {}
) {
    val youtubeMusicViewModel = androidx.lifecycle.viewmodel.compose.viewModel<com.yasuda.derbis.viewmodel.youtubemusic.YoutubeMusicAccountViewModel>()
    val screenViewModelFactory = remember(viewModel, youtubeMusicViewModel) {
        DerbisScreenViewModelFactory(viewModel, youtubeMusicViewModel.homeSource)
    }
    val youtubeMusicState by youtubeMusicViewModel.state.collectAsStateWithLifecycle()
    var showYoutubeMusic by rememberSaveable { mutableStateOf(false) }

    val rawState by viewModel.state.collectAsStateWithLifecycle()
    val state = remember(rawState, rawState.interfaceSettings.blockAiContent) { rawState.withAiContentBlocked() }
    val miniPlayerStudio by viewModel.miniPlayerStudio.collectAsStateWithLifecycle()
    val customThemes by viewModel.customThemes.collectAsStateWithLifecycle()
    val navigationStudio by viewModel.navigationStudio.collectAsStateWithLifecycle()
    LaunchedEffect(youtubeMusicState.active?.id, state.languageCode) {
        youtubeMusicViewModel.loadHome(state.languageCode)
    }
    LaunchedEffect(state.isDeviceOffline) {
        if (!state.isDeviceOffline) youtubeMusicViewModel.onNetworkRestored(state.languageCode)
    }
    val currentStrings = DerbisStrings.forCode(state.languageCode)
    val layoutDirection = if (DerbisLanguageCatalog.isRtl(currentStrings.code)) LayoutDirection.Rtl else LayoutDirection.Ltr
    val toastContext = LocalContext.current
    val downloadLocationScope = rememberCoroutineScope()
    LaunchedEffect(viewModel) {
        viewModel.integrationAuthorizationUrls.collect { url ->
            openExternalUrl(toastContext, url, currentStrings)
        }
    }
    val activity = toastContext as? Activity
    var showLanguageRestartDialog by remember { mutableStateOf(false) }
    var showPlaybackDiagnostics by remember { mutableStateOf(false) }
    var showDownloadsFolder by remember { mutableStateOf(false) }
    var liveRadioOpen by rememberSaveable { mutableStateOf(false) }
    var discoveryOpen by rememberSaveable { mutableStateOf(false) }
    var trackActionTarget by remember { mutableStateOf<Track?>(null) }
    var queueRemovalTarget by remember { mutableStateOf<QueueRemovalTarget?>(null) }
    var trackActionPlaylistTarget by remember { mutableStateOf<Track?>(null) }
    val profilePhotoLauncher = rememberLauncherForActivityResult(ActivityResultContracts.PickVisualMedia()) { uri ->
        uri?.let(viewModel::setProfilePhoto)
    }
    val createBackupLauncher = rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("application/zip")) { uri ->
        uri?.let(viewModel::createBackup)
    }
    val restoreBackupLauncher = rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()) { uri ->
        uri?.let(viewModel::previewRestore)
    }
    val restoreMediaPermissionLauncher = rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()) { granted ->
        if (granted) viewModel.confirmRestore()
    }
    val manageBackupsLauncher = rememberLauncherForActivityResult(ActivityResultContracts.StartActivityForResult()) { result ->
        if (result.resultCode == Activity.RESULT_OK) {
            result.data?.data?.let(viewModel::previewRestore)
        }
    }
    val openManageBackups = {
        val initialUri = state.backupLocationUri
            ?.let { raw -> try { Uri.parse(raw) } catch (_: Throwable) { null } }
            ?: DocumentsContract.buildRootUri(
                "${toastContext.packageName}.automatic-backups",
                "derbis-automatic-backups"
            )
        manageBackupsLauncher.launch(
            Intent(Intent.ACTION_OPEN_DOCUMENT)
                .addCategory(Intent.CATEGORY_OPENABLE)
                .setType("application/zip")
                .putExtra(DocumentsContract.EXTRA_INITIAL_URI, initialUri)
        )
    }
    val backupLocationLauncher = rememberLauncherForActivityResult(ActivityResultContracts.OpenDocumentTree()) { uri ->
        uri?.let(viewModel::setBackupLocation)
    }
    val downloadLocationLauncher = rememberLauncherForActivityResult(ActivityResultContracts.OpenDocumentTree()) { uri ->
        if (uri != null) {
            downloadLocationScope.launch {
                val persisted = withContext(Dispatchers.IO) {
                    DownloadFolderAccess.persist(toastContext, uri)
                }
                if (persisted) {
                    viewModel.setDownloadSettings(
                        viewModel.state.value.downloadSettings.copy(destinationTreeUri = uri.toString())
                    )
                } else {
                    Toast.makeText(
                        toastContext,
                        currentStrings.downloadLocationPermissionFailed,
                        Toast.LENGTH_LONG
                    ).show()
                }
            }
        }
    }
    val accent = if (state.dynamicColor) state.currentTrack ?: state.tracks.firstOrNull() else null
    val overlayEnter = DerbisMotion.overlayEnter(state.animationsEnabled)
    val overlayExit = DerbisMotion.overlayExit(state.animationsEnabled)
    val panelEnter = DerbisMotion.panelEnter(state.animationsEnabled)
    val panelExit = DerbisMotion.panelExit(state.animationsEnabled)
    val pageEnter = DerbisMotion.pageEnter(state.animationsEnabled)
    val pageExit = DerbisMotion.pageExit(state.animationsEnabled)
    val detailUnderPlayer = state.selectedTab == DerbisTab.Player
    val detailEnter = if (detailUnderPlayer) EnterTransition.None else pageEnter
    val miniEnter = if (state.animationsEnabled) {
        slideInVertically(animationSpec = tween(260, easing = FastOutSlowInEasing), initialOffsetY = { it / 2 }) + fadeIn(animationSpec = tween(180, easing = LinearOutSlowInEasing))
    } else {
        EnterTransition.None
    }
    val miniExit = if (state.animationsEnabled) {
        slideOutVertically(animationSpec = tween(180, easing = FastOutSlowInEasing), targetOffsetY = { it / 3 }) + fadeOut(animationSpec = tween(140, easing = FastOutSlowInEasing))
    } else {
        ExitTransition.None
    }
    val visualCapabilities = rememberDerbisVisualCapabilities(
        selected = state.interfaceSettings.visualPerformance,
        animationsEnabled = state.animationsEnabled
    )
    val accentTrack = state.currentTrack ?: state.tracks.firstOrNull()
    when (state.interfaceSettings.skin) {
        DerbisSkin.LiquidGlass -> PrismThemeEffect(state.interfaceSettings)
        DerbisSkin.Torque -> TorqueThemeEffect(state.interfaceSettings, state.currentTrack)
        DerbisSkin.Ivory -> IvoryThemeEffect(state.interfaceSettings)
        DerbisSkin.AppleMusicStyle -> AppleMusicThemeEffect()
        DerbisSkin.TidalStyle -> TidalThemeEffect()
        DerbisSkin.YouTubeMusicStyle -> YouTubeMusicThemeEffect()
        else -> Unit
    }
    val pureBlack = state.interfaceSettings.pureBlack
    LaunchedEffect(
        state.themePreset,
        state.themeAccent,
        state.interfaceSettings.skin,
        accentTrack?.accentStart,
        accentTrack?.accentEnd,
        state.selectedMood?.id,
        pureBlack,
        customThemes
    ) {
        if (state.interfaceSettings.skin == DerbisSkin.LiquidGlass || state.interfaceSettings.skin == DerbisSkin.Torque || state.interfaceSettings.skin == DerbisSkin.Ivory || state.interfaceSettings.skin == DerbisSkin.AppleMusicStyle || state.interfaceSettings.skin == DerbisSkin.TidalStyle || state.interfaceSettings.skin == DerbisSkin.YouTubeMusicStyle) return@LaunchedEffect
        DerbisThemeController.apply(
            state.themePreset,
            accentTrack?.accentStart,
            accentTrack?.accentEnd,
            state.selectedMood?.accentStart,
            state.selectedMood?.accentEnd,
            pureBlack,
            state.themeAccent.takeIf { it != 0 },
            state.interfaceSettings.skin
        )
    }
    val rootView = LocalView.current
    LaunchedEffect(state.themePreset, pureBlack, customThemes, state.interfaceSettings.skin, DerbisActivePalette.isLight) {
        val nocturne = state.interfaceSettings.skin == DerbisSkin.Nocturne78
        val base = when (state.interfaceSettings.skin) {
            DerbisSkin.Nocturne78 -> Nocturne78Palette
            DerbisSkin.LiquidGlass, DerbisSkin.Torque, DerbisSkin.Ivory, DerbisSkin.AppleMusicStyle, DerbisSkin.TidalStyle, DerbisSkin.YouTubeMusicStyle -> DerbisActivePalette
            DerbisSkin.SpotifyStyle -> spotifyPalette()
            DerbisSkin.Default -> DerbisThemes.byId(state.themePreset)
        }
        val palette = if (pureBlack && state.interfaceSettings.skin == DerbisSkin.Default) DerbisThemeController.asPureBlack(base) else base
        (rootView.context as? Activity)?.window?.let { window ->
            window.decorView.setBackgroundColor(palette.black.toArgb())
            WindowCompat.getInsetsController(window, rootView).apply {
                isAppearanceLightStatusBars = palette.isLight
                isAppearanceLightNavigationBars = palette.isLight
            }
        }
    }
    val pendingShortcut by DerbisLaunchActions.pendingShortcut
    LaunchedEffect(pendingShortcut) {
        when (pendingShortcut) {
            DerbisLaunchActions.SHORTCUT_FAVORITES -> viewModel.selectTab(DerbisTab.Library)
            DerbisLaunchActions.SHORTCUT_OFFLINE -> viewModel.selectTab(DerbisTab.Library)
            DerbisLaunchActions.SHORTCUT_SEARCH -> viewModel.selectTab(DerbisTab.Search)
            DerbisLaunchActions.SHORTCUT_LIBRARY -> viewModel.selectTab(DerbisTab.Library)
            DerbisLaunchActions.SHORTCUT_FLOW -> viewModel.playDailyFlow()
            DerbisLaunchActions.SHORTCUT_LYRICS -> {
                viewModel.selectTab(DerbisTab.Player)
                viewModel.openLyrics()
            }
            DerbisLaunchActions.SHORTCUT_RECOGNITION -> {
                viewModel.selectTab(DerbisTab.Search)
                viewModel.startMusicRecognition()
            }
            DerbisLaunchActions.SHORTCUT_AMBIENT -> viewModel.openAmbient()
            DerbisLaunchActions.SHORTCUT_RESUME -> viewModel.resumePlaybackFromShortcut()
            DerbisLaunchActions.SHORTCUT_PLAYER -> viewModel.selectTab(DerbisTab.Player)
            DerbisLaunchActions.SHORTCUT_QUEUE -> {
                viewModel.selectTab(DerbisTab.Player)
                viewModel.openQueue()
            }
        }
        if (pendingShortcut != null) DerbisLaunchActions.pendingShortcut.value = null
    }
    val pendingJamCode by DerbisLaunchActions.pendingJamCode
    LaunchedEffect(pendingJamCode) {
        pendingJamCode?.let { code ->
            viewModel.openJam()
            viewModel.joinJam(code)
            DerbisLaunchActions.pendingJamCode.value = null
        }
    }
    val pendingArtist by DerbisLaunchActions.pendingArtist
    LaunchedEffect(pendingArtist) {
        pendingArtist?.let { artistName ->
            viewModel.openArtistByName(artistName)
            DerbisLaunchActions.pendingArtist.value = null
        }
    }
    val pendingRelease by DerbisLaunchActions.pendingRelease
    LaunchedEffect(pendingRelease) {
        pendingRelease?.let { release ->
            viewModel.openAlbum(
                AlbumHit(
                    title = release.title,
                    artist = release.artist,
                    year = release.year,
                    thumbnailUrl = release.artworkUrl,
                    query = "${release.artist} ${release.title}".trim(),
                    browseId = release.browseId
                )
            )
            DerbisLaunchActions.pendingRelease.value = null
        }
    }
    val pendingSharedMedia by DerbisLaunchActions.pendingSharedMedia
    LaunchedEffect(pendingSharedMedia?.key) {
        pendingSharedMedia?.let { request ->
            viewModel.handleSharedMedia(request)
            DerbisLaunchActions.pendingSharedMedia.value = null
        }
    }
    LaunchedEffect(state.offlineExportMessage) {
        state.offlineExportMessage?.let { message ->
            Toast.makeText(toastContext, message, Toast.LENGTH_LONG).show()
            viewModel.clearOfflineExportMessage()
        }
    }
    LaunchedEffect(state.updateMessage) {
        state.updateMessage?.let { message ->
            Toast.makeText(toastContext, message, Toast.LENGTH_LONG).show()
            viewModel.clearUpdateMessage()
        }
    }
    LaunchedEffect(state.backupMessage) {
        state.backupMessage?.let { message ->
            Toast.makeText(toastContext, message, Toast.LENGTH_LONG).show()
            viewModel.clearBackupMessage()
        }
    }
    val otherRootOverlayOpen = showYoutubeMusic || showLanguageRestartDialog || state.youtubeEngagement.comments.visible || state.showRecognition || state.showJam || state.showThemeStudio || state.showLyricsStudio || state.showHomeStudio || miniPlayerStudio.visible || navigationStudio.visible || state.showYourSound || state.showListeningInsights || state.showListeningRecap || state.sharedMediaPreview != null || showDownloadsFolder || state.playlistHitPreview != null || state.openPlaylist != null || state.showAlbum || state.showArtist || state.showQueue || state.showLyrics || state.showAudioQualityPanel
    val rootOverlayOpen = otherRootOverlayOpen || state.showSettings
    val settingsDockVisible = state.showSettings && !otherRootOverlayOpen
    BackHandler(enabled = rootOverlayOpen || state.selectedTab != DerbisTab.Home) {
        if (showYoutubeMusic) {
            if (youtubeMusicState.showLogin) youtubeMusicViewModel.cancelLogin()
            else if (youtubeMusicState.detail != null) youtubeMusicViewModel.closeDetail()
            else showYoutubeMusic = false
        } else if (showLanguageRestartDialog) {
            showLanguageRestartDialog = false
        } else if (state.showRecognition) {
            viewModel.closeRecognition()
        } else if (state.showThemeStudio) {
            viewModel.closeThemeStudio()
        } else if (state.showLyricsStudio) {
            viewModel.closeLyricsStudio()
        } else if (state.showHomeStudio) {
            viewModel.closeHomeStudio()
        } else if (miniPlayerStudio.visible) {
            viewModel.closeMiniPlayerStudio()
        } else if (navigationStudio.visible) {
            viewModel.closeNavigationStudio()
        } else if (state.showJam) {
            viewModel.closeJam()
        } else if (state.showListeningInsights) {
            viewModel.closeListeningInsights()
        } else if (state.showListeningRecap) {
            viewModel.closeListeningRecap()
        } else if (state.showYourSound) {
            viewModel.closeYourSound()
        } else if (state.sharedMediaPreview != null) {
            viewModel.dismissSharedMedia()
        } else if (showDownloadsFolder) {
            showDownloadsFolder = false
        } else if (state.showAudioQualityPanel) {
            viewModel.closeAudioQualityPanel()
        } else if (state.playlistHitPreview != null) {
            viewModel.closePlaylistHit()
        } else if (state.openPlaylist != null) {
            viewModel.closePlaylist()
        } else if (!viewModel.navigateBack()) {
            activity?.finish()
        }
    }
    val navArtworkSeed = rememberNavArtworkSeed(
        track = state.currentTrack,
        enabled = navigationStudio.visible ||
            navigationStudio.settings.activeTuning().colorSource == NavColorSource.Artwork
    )
    // Keep Liquid Glass legible when Android's High text contrast accessibility setting is on.
    // Reduced Motion is intentionally independent: motion may stop while material remains useful.
    val glassAccessibility = rememberDerbisGlassAccessibility()
    val glassMaterialIsOpaque = glassAccessibility.prefersOpaqueMaterials ||
        LocalDerbisGlassStyle.current.prefersOpaqueMaterials
    // Resolved once for the whole app: every glass panel reads this instead of re-querying the
    // device on each row of a scrolling list.
    val glassLensTier = com.yasuda.derbis.ui.rememberDerbisGlassTier(
        heavyBlur = visualCapabilities.heavyBlur
    )
    CompositionLocalProvider(
        LocalAnimationsEnabled provides state.animationsEnabled,
        LocalDerbisVisualCapabilities provides visualCapabilities,
        com.yasuda.derbis.ui.LocalDerbisGlassTier provides glassLensTier,
        LocalDerbisStrings provides currentStrings,
        LocalDerbisHaptics provides rememberDerbisHaptics(state.interfaceSettings.hapticFeedback),
        LocalLayoutDirection provides layoutDirection,
        LocalNocturneNavigationHeight provides remember { mutableStateOf(64.dp) },
        LocalNavDockExtraClearance provides if (DerbisSkinManagesLayout) 0.dp else navDockExtraClearance(navigationStudio.settings.style, navigationStudio.settings.activeTuning()),
        LocalNavArtworkSeed provides navArtworkSeed,
        LocalDerbisGlassAccessibility provides glassAccessibility
    ) {
        Box(modifier = Modifier.fillMaxSize()) {
            BoxWithConstraints(
                modifier = Modifier
                    .fillMaxSize()
                    .background(DerbisBlack)
            ) {
            val dockState = rememberDerbisDockState()
            val glassBlurAllowed = rememberGlassBlurAllowed()
            val dockGlass = rememberGlassBackdropState(
                enabled = (state.interfaceSettings.liquidGlassEnabled ||
                    state.interfaceSettings.skin == DerbisSkin.LiquidGlass) &&
                    !glassMaterialIsOpaque &&
                    glassBlurAllowed &&
                    (!DerbisSkinManagesLayout || state.interfaceSettings.skin == DerbisSkin.LiquidGlass)
            )

            val homeListState = rememberLazyListState()
            val homeDeferredSectionsRevealed = remember { mutableStateOf(false) }
            val rootDensity = LocalDensity.current
            val rootLayoutMode = resolveDerbisLayoutMode(maxWidth.value, maxHeight.value)
            val dockSideBySide = derbisWindowIsCompactLandscape()
            val expansionTravelPx = with(rootDensity) { maxHeight.toPx() }.coerceAtLeast(1f)
            val expansionScope = rememberCoroutineScope()
            val playerExpansion = remember {
                Animatable(if (state.selectedTab == DerbisTab.Player) 1f else 0f)
            }
            val morphAnchors = rememberPlayerMorphAnchors { playerExpansion.value }
            var expansionDragStart by remember { mutableFloatStateOf(0f) }
            var expansionDragAccum by remember { mutableFloatStateOf(0f) }
            var expansionDragGeneration by remember { mutableIntStateOf(0) }
            var backgroundTab by rememberSaveable {
                mutableStateOf(state.selectedTab.takeIf { it != DerbisTab.Player } ?: DerbisTab.Home)
            }
            LaunchedEffect(state.selectedTab) {
                if (state.selectedTab != DerbisTab.Player) backgroundTab = state.selectedTab
            }
            LaunchedEffect(backgroundTab) {
                if (backgroundTab != DerbisTab.Explore) liveRadioOpen = false
                if (backgroundTab != DerbisTab.Home) discoveryOpen = false
            }
            LaunchedEffect(state.selectedTab, state.animationsEnabled) {
                val target = if (state.selectedTab == DerbisTab.Player) 1f else 0f
                if (playerExpansion.value == target) return@LaunchedEffect
                if (state.animationsEnabled) {
                    if (target > playerExpansion.value && playerExpansion.value <= 0f) {
                        playerExpansion.snapTo(PlayerPrewarmExpansion)
                        withFrameNanos { }
                        withFrameNanos { }
                    }
                    playerExpansion.animateTo(
                        target,
                        if (target > playerExpansion.value) {
                            DerbisPlayerDesign.expandSpring()
                        } else {
                            DerbisPlayerDesign.collapseSpring()
                        }
                    )
                } else {
                    playerExpansion.snapTo(target)
                }
            }
            val expansionProvider: () -> Float = { playerExpansion.value }
            val chromeVisible by remember { derivedStateOf { playerExpansion.value < 1f } }
            val playerVisible by remember { derivedStateOf { playerExpansion.value > 0f } }
            val morphAllowed = state.animationsEnabled && !state.isVideoMode
            val artworkMorphActive by remember(morphAllowed) {
                derivedStateOf {
                    morphAllowed &&
                        morphAnchors.miniBounds != null &&
                        morphAnchors.targetBounds != null &&
                        playerMorphActive(playerExpansion.value)
                }
            }
            val onExpansionDragStart: () -> Unit = {
                expansionDragStart = playerExpansion.value
                expansionDragAccum = 0f
                expansionDragGeneration += 1
            }
            val onExpansionDrag: (Float) -> Unit = { delta ->
                expansionDragAccum += delta
                val generation = expansionDragGeneration
                expansionScope.launch {
                    if (generation == expansionDragGeneration) {
                        playerExpansion.snapTo(
                            playerExpansionFromDrag(
                                expansionDragStart,
                                expansionDragAccum,
                                morphAnchors.miniCardBounds?.top?.takeIf { it > 1f } ?: expansionTravelPx
                            )
                        )
                    }
                }
            }
            val settleExpansion: (Float, Boolean) -> Unit = { velocity, wasExpanded ->
                expansionDragGeneration += 1
                val target = resolvePlayerExpansionTarget(playerExpansion.value, velocity, wasExpanded)
                expansionScope.launch {
                    if (target >= 1f) {
                        if (state.selectedTab != DerbisTab.Player) viewModel.selectTab(DerbisTab.Player)
                        playerExpansion.animateTo(1f, DerbisPlayerDesign.expandSpring())
                    } else {
                        viewModel.revealPlayerReturnDetail()
                        playerExpansion.animateTo(0f, DerbisPlayerDesign.collapseSpring())
                        if (state.selectedTab == DerbisTab.Player) viewModel.selectTab(backgroundTab)
                    }
                }
            }
            val yourSoundAccent = rememberNowPlayingAccent(state.currentTrack, DerbisCyan)
            val collapsePlayer: () -> Unit = {
                viewModel.revealPlayerReturnDetail()
                expansionScope.launch {
                    if (state.animationsEnabled) {
                        playerExpansion.animateTo(0f, DerbisPlayerDesign.collapseSpring())
                    } else {
                        playerExpansion.snapTo(0f)
                    }
                    if (state.selectedTab == DerbisTab.Player) viewModel.selectTab(backgroundTab)
                }
            }
            BackHandler(enabled = settingsDockVisible && state.selectedTab == DerbisTab.Player) {
                collapsePlayer()
            }
            val playerPredictiveBackEnabled = state.animationsEnabled &&
                state.selectedTab == DerbisTab.Player &&
                !state.showQueue &&
                !state.showLyrics &&
                !state.showSettings &&
                !state.showAlbum &&
                !state.showArtist &&
                !state.showAudioQualityPanel &&
                !state.youtubeEngagement.comments.visible &&
                !state.showYourSound &&
                !state.showListeningInsights &&
                !state.showListeningRecap &&
                !state.showJam &&
                !state.showRecognition &&
                state.openPlaylist == null &&
                state.sharedMediaPreview == null &&
                !showDownloadsFolder &&
                !showLanguageRestartDialog
            PredictiveBackHandler(enabled = playerPredictiveBackEnabled) { backProgress ->
                val startExpansion = playerExpansion.value
                try {
                    backProgress.collect { backEvent ->
                        playerExpansion.snapTo(
                            playerPredictiveBackExpansion(startExpansion, backEvent.progress)
                        )
                    }
                    viewModel.revealPlayerReturnDetail()
                    playerExpansion.animateTo(0f, DerbisPlayerDesign.collapseSpring())
                    if (state.selectedTab == DerbisTab.Player) viewModel.selectTab(backgroundTab)
                } catch (cancelled: CancellationException) {
                    playerExpansion.animateTo(
                        startExpansion,
                        DerbisPlayerDesign.expandSpring()
                    )
                    throw cancelled
                }
            }

            LaunchedEffect(backgroundTab) { dockState.expand() }
            LaunchedEffect(state.currentTrack == null) { dockState.expand() }
            LaunchedEffect(chromeVisible, state.showSettings) {
                if (!chromeVisible || state.showSettings) dockState.expand()
            }
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .nestedScroll(dockState)
            ) {
                // The shared layer intentionally contains only the atmospheric backdrop. Recording
                // foreground content here would turn a glass panel into a blurred echo of itself.
                DerbisHomeAtmosphere(
                    isLight = DerbisIsLight,
                    accent = yourSoundAccent,
                    modifier = Modifier.glassBackdropSource(dockGlass)
                )
                CompositionLocalProvider(LocalGlassBackdrop provides dockGlass) {
            val homeSaveableState = rememberSaveableStateHolder()
            AnimatedContent(
                targetState = backgroundTab,
                modifier = Modifier
                    .fillMaxSize()
                    .graphicsLayer {
                        val depth = playerBackgroundScale(expansionProvider())
                        scaleX = depth
                        scaleY = depth
                    },
                transitionSpec = {
                    val forward = targetState.ordinal >= initialState.ordinal
                    val rtl = layoutDirection == LayoutDirection.Rtl
                    DerbisMotion.tabSwap(state.animationsEnabled, if (forward != rtl) 1 else -1)
                },
                label = "derbis-page-transition"
            ) { tab ->
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .windowInsetsPadding(DerbisHorizontalSafeInsets)
                        .derbisSystemGlass()
                ) {
                    when (tab) {
                        DerbisTab.Home -> {
                            val homeViewModel: HomeViewModel = composeViewModel(key = "derbis-home", factory = screenViewModelFactory)
                            val renderSnapshot by homeViewModel.renderState.collectAsStateWithLifecycle()
                            homeSaveableState.SaveableStateProvider("derbis-home") {
                                CompositionLocalProvider(
                                    LocalHomeCompactDensity provides
                                        renderSnapshot.state.interfaceSettings.compactHome
                                ) {
                                    val youtubeMusicLibrary = youtubeMusicState.library
                                    val youtubeMusicCreatedLabel = com.yasuda.derbis.ui.i18n.youtubeMusicHomeCopy(state.languageCode).createdByYou
                                    val youtubeMusicShelf = remember(youtubeMusicLibrary, youtubeMusicCreatedLabel) {
                                        youtubeMusicLibrary?.let { library ->
                                            com.yasuda.derbis.ui.youtubemusic.youtubeMusicShelfAlbums(library, youtubeMusicCreatedLabel)
                                        }.orEmpty()
                                    }
                                    LaunchedEffect(youtubeMusicState.active?.id, state.languageCode, youtubeMusicState.restoring) {
                                        youtubeMusicViewModel.loadLibraryShelf(state.languageCode)
                                    }
                                    val youtubeMusicHome = youtubeMusicState.active?.let { account ->
                                        com.yasuda.derbis.ui.youtubemusic.YoutubeMusicHomeShelfUi(
                                            accountName = account.name,
                                            avatarUrl = account.avatarUrl,
                                            albums = youtubeMusicShelf,
                                            loading = youtubeMusicState.libraryLoading,
                                            error = youtubeMusicState.libraryError,
                                            onOpen = { album ->
                                                val entry = youtubeMusicLibrary?.entryFor(album)
                                                if (entry != null) {
                                                    if (entry.collection == com.yasuda.derbis.data.youtubemusic.YoutubeMusicCollection.Albums) {
                                                        viewModel.openAlbum(album)
                                                    } else {
                                                        youtubeMusicViewModel.open(state.languageCode)
                                                        youtubeMusicViewModel.openDetail(entry)
                                                        showYoutubeMusic = true
                                                    }
                                                }
                                            },
                                            onRefresh = { youtubeMusicViewModel.loadLibraryShelf(state.languageCode, force = true) },
                                            onShowAll = {
                                                youtubeMusicViewModel.open(state.languageCode)
                                                showYoutubeMusic = true
                                            },
                                            onReconnect = {
                                                showYoutubeMusic = true
                                                youtubeMusicViewModel.open(state.languageCode)
                                                youtubeMusicViewModel.beginLogin()
                                            }
                                        )
                                    }?.takeIf { it.albums.isNotEmpty() || it.loading || it.error != null }
                                    DiscoveryHomeHost(
                                        factory = screenViewModelFactory,
                                        open = discoveryOpen,
                                        onOpenChange = { discoveryOpen = it },
                                        backEnabled = !rootOverlayOpen && state.selectedTab == DerbisTab.Home,
                                        style = state.homeStudioSettings.style,
                                        animationsEnabled = state.animationsEnabled,
                                        bottomInset = tabBarBottomContentInset(
                                            miniPlayerVisible = state.currentTrack != null,
                                            animationsEnabled = state.animationsEnabled
                                        )
                                    ) {
                                        HomeStudioHost(
                                            viewModel = homeViewModel,
                                            renderSnapshot = renderSnapshot,
                                            homeListState = homeListState,
                                            deferredSectionsRevealed = homeDeferredSectionsRevealed,
                                            accountAvatarUrl = youtubeMusicState.active?.avatarUrl.orEmpty(),
                                            youtubeMusicHome = youtubeMusicHome,
                                            homeStudio = state.homeStudioSettings,
                                            onPullRefresh = {
                                                homeViewModel.refreshHome { youtubeMusicViewModel.refreshHomeAndAwait(state.languageCode) }
                                            },
                                            onTrackActions = { track ->
                                                queueRemovalTarget = null
                                                trackActionTarget = track
                                            }
                                        )
                                    }
                                }
                            }
                        }
                        DerbisTab.Search -> {
                            val searchViewModel: SearchViewModel = composeViewModel(key = "derbis-search", factory = screenViewModelFactory)
                            val screenState by searchViewModel.state.collectAsStateWithLifecycle()
                            SearchScreen(searchViewModel, screenState) { track -> trackActionTarget = track }
                        }
                        DerbisTab.Explore -> {
                            val exploreViewModel: ExploreViewModel = composeViewModel(key = "derbis-explore", factory = screenViewModelFactory)
                            val screenState by exploreViewModel.state.collectAsStateWithLifecycle()
                            ExploreScreen(
                                viewModel = exploreViewModel,
                                state = screenState,
                                liveRadioOpen = liveRadioOpen,
                                backEnabled = !rootOverlayOpen && state.selectedTab == DerbisTab.Explore,
                                onLiveRadioOpenChange = { liveRadioOpen = it },
                                onOpenJam = viewModel::openJam
                            )
                        }
                        DerbisTab.Library -> {
                            val libraryViewModel: LibraryViewModel = composeViewModel(key = "derbis-library", factory = screenViewModelFactory)
                            val screenState by libraryViewModel.state.collectAsStateWithLifecycle()
                            DerbisLibraryScreen(
                                libraryViewModel, screenState, onOpenDownloads = { showDownloadsFolder = true },
                                youtubeMusicAccount = youtubeMusicState.active,
                                onOpenYoutubeMusic = { showYoutubeMusic = true }
                            )
                        }
                        DerbisTab.Player -> Unit
                    }
                }
            }
            }

            if (chromeVisible) {
                val miniMaxWidth = derbisMiniPlayerMaxWidthDp(rootLayoutMode)
                Column(
                    modifier = Modifier
                        .align(Alignment.BottomCenter)
                        .zIndex(if (settingsDockVisible) 1f else 0f)
                        .fillMaxWidth()
                        .windowInsetsPadding(DerbisHorizontalSafeInsets)
                        .graphicsLayer { alpha = playerChromeAlpha(expansionProvider()) },
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(0.dp)
                ) {
                    if (!state.showSettings && !DerbisIsSpotify) BottomTabsScrim()
                    val dockCompaction = dockState.animatedCompaction(state.animationsEnabled)
                    val compactionProvider: () -> Float = { dockCompaction.value }
                    val miniPlayerVisible = state.currentTrack != null
                    val dockLink = rememberConnectedDockLink(
                        navigation = navigationStudio.settings,
                        attached = miniPlayerVisible && !dockSideBySide && !state.showSettings,
                        compaction = dockCompaction,
                        animated = state.animationsEnabled
                    )
                    val miniPlayerSlot: @Composable () -> Unit = {
                        AnimatedVisibility(
                            visible = miniPlayerVisible,
                            enter = miniEnter,
                            exit = miniExit
                        ) {
                            state.currentTrack?.let { track ->
                                val miniStepDirection = rememberTrackStepDirection(
                                    trackId = track.id,
                                    queue = state.queue,
                                    queueIndex = state.queueCurrentIndex
                                )
                                Box(
                                    modifier = if (miniMaxWidth.isFinite()) {
                                        Modifier.widthIn(max = miniMaxWidth.dp)
                                    } else {
                                        Modifier
                                    }
                                ) {
                                    val miniModel = MiniPlayerModel(
                                        track = track,
                                        isPlaying = state.isPlaying,
                                        isResolving = state.isResolving,
                                        progress = progressOf(state.positionMs, state.durationMs),
                                        bufferedProgress = progressOf(state.bufferedPositionMs, state.durationMs),
                                        liveNowPlaying = when {
                                            state.liveRadioStation == null -> state.liveRadioNowPlaying
                                            state.isResolving && state.liveRadioReconnectAttempt > 0 ->
                                                com.yasuda.derbis.ui.i18n.DerbisLiveRadioCatalog.reconnecting(state.languageCode)
                                            else -> state.playerError ?: state.liveRadioNowPlaying
                                        },
                                        animated = state.animationsEnabled,
                                        gesturesEnabled = true,
                                        swipeTrackChangeEnabled = state.interfaceSettings.swipeTrackChangeEnabled,
                                        stepDirection = miniStepDirection
                                    )
                                    val miniPlaybackActions = MiniPlayerPlaybackActions(
                                        open = { viewModel.selectTab(DerbisTab.Player) },
                                        toggle = viewModel::togglePlay,
                                        next = viewModel::next,
                                        previous = viewModel::previous,
                                        close = viewModel::closePlayer
                                    )
                                    val miniExpansionActions = MiniPlayerExpansionActions(
                                        start = onExpansionDragStart,
                                        drag = onExpansionDrag,
                                        end = { velocity -> settleExpansion(velocity, false) }
                                    )
                                    val miniStudio = skinMiniSettings(miniPlayerStudio.settings)
                                    if (miniStudio.style == MiniPlayerStyle.Original) {
                                        MiniPlayer(
                                            model = miniModel,
                                            morphAnchors = morphAnchors,
                                            compaction = compactionProvider,
                                            artworkHidden = { artworkMorphActive },
                                            playbackActions = miniPlaybackActions,
                                            expansionActions = miniExpansionActions,
                                            fixedAccents = rememberPlayerFixedAccents(state.interfaceSettings)
                                        )
                                    } else {
                                        StyledMiniPlayer(
                                            style = miniStudio.style,
                                            tuning = miniStudio.activeTuning(),
                                            model = miniModel,
                                            morphAnchors = morphAnchors,
                                            compaction = compactionProvider,
                                            artworkHidden = { artworkMorphActive },
                                            playbackActions = miniPlaybackActions,
                                            expansionActions = miniExpansionActions,
                                            glass = dockGlass,
                                            link = dockLink.takeIf { miniStudio.style == MiniPlayerStyle.Connected && !state.showSettings }
                                        )
                                    }
                                }
                            }
                        }
                    }
                    val bottomTabsSlot: @Composable () -> Unit = {
                        val selectDockTab: (DerbisTab) -> Unit = { tab ->
                            if (state.showSettings) viewModel.closeSettings()
                            viewModel.selectTab(tab)
                        }
                        Box(
                            modifier = if (miniMaxWidth.isFinite()) {
                                Modifier.widthIn(max = miniMaxWidth.dp)
                            } else {
                                Modifier
                            }
                        ) {
                            val navStudio = skinNavigationSettings(navigationStudio.settings)
                            if (navStudio.style == NavStyle.Original) {
                                BottomTabs(
                                    selected = backgroundTab,
                                    compaction = compactionProvider,
                                    onSelect = selectDockTab
                                )
                            } else {
                                StyledBottomTabs(
                                    style = navStudio.style,
                                    tuning = navStudio.activeTuning(),
                                    selected = backgroundTab,
                                    compaction = compactionProvider,
                                    onSelect = selectDockTab,
                                    glass = dockGlass,
                                    link = dockLink.takeIf { navStudio.style == NavStyle.ConnectedDock }
                                )
                            }
                        }
                    }
                    if (state.showSettings) {
                        miniPlayerSlot()
                        Spacer(modifier = Modifier.navigationBarsPadding())
                    } else {
                        if (!dockSideBySide) {
                            miniPlayerSlot()
                        }
                        val dockModifier = if (miniMaxWidth.isFinite()) {
                            Modifier.widthIn(max = miniMaxWidth.dp)
                        } else {
                            Modifier.fillMaxWidth()
                        }
                        val dockContent: @Composable ColumnScope.() -> Unit = {
                            if (dockSideBySide && miniPlayerVisible) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    verticalAlignment = Alignment.Top
                                ) {
                                    Box(modifier = Modifier.weight(DerbisLandscapeDockMiniWeight)) { miniPlayerSlot() }
                                    Box(modifier = Modifier.weight(1f)) { bottomTabsSlot() }
                                }
                            } else {
                                bottomTabsSlot()
                            }
                        }
                        if (skinNavigationSettings(navigationStudio.settings).style == NavStyle.Original) {
                            DerbisAdaptiveDockSurface(glass = dockGlass, modifier = dockModifier, content = dockContent)
                        } else {
                            StyledDockSurface(
                                style = skinNavigationSettings(navigationStudio.settings).style,
                                tuning = skinNavigationSettings(navigationStudio.settings).activeTuning(),
                                glass = dockGlass,
                                modifier = dockModifier,
                                content = dockContent
                            )
                        }
                    }
                }
                }
            }

            if (!playerVisible && state.currentTrack != null && state.interfaceSettings.derbisNotchEnabled) {
                DerbisMusicNotch(
                    track = state.currentTrack,
                    lyrics = state.lyrics,
                    lyricsSynced = state.lyricsSynced,
                    positionMs = state.positionMs,
                    durationMs = state.durationMs,
                    isPlaying = state.isPlaying,
                    style = state.interfaceSettings.derbisNotchStyle,
                    onStyleChange = { chosen ->
                        viewModel.setInterfaceSettings(
                            state.interfaceSettings.copy(derbisNotchStyle = chosen)
                        )
                    },
                    onTogglePlay = viewModel::togglePlay,
                    onPrevious = viewModel::previous,
                    onNext = viewModel::next,
                    onOpen = viewModel::openPlayerScreen,
                    modifier = Modifier
                        .align(Alignment.TopCenter)
                        .statusBarsPadding()
                        .padding(top = 4.dp)
                        .zIndex(42f)
                )
            }

            if (playerVisible) {
                DisposableEffect(morphAnchors) {
                    onDispose { morphAnchors.playerContainer = null }
                }
                val playerViewModel: PlayerViewModel = composeViewModel(key = "derbis-player", factory = screenViewModelFactory)
                val playerScreenState by playerViewModel.state.collectAsStateWithLifecycle()
                val playerAboveDetail = detailUnderPlayer && (state.showAlbum || state.showArtist || state.openPlaylist != null || state.playlistHitPreview != null)
                Box(
                    modifier = Modifier
                        .zIndex(if (playerAboveDetail) 41f else if (settingsDockVisible) 1f else 0f)
                        .fillMaxSize()
                        .graphicsLayer {
                            val expansion = expansionProvider()
                            alpha = playerSurfaceAlpha(expansion)
                            val origin = morphAnchors.miniCardBounds
                            val container = playerContainerBounds(expansion, origin, size.width, size.height)
                            val scale = if (size.width > 0f) container.width / size.width else 1f
                            transformOrigin = TransformOrigin(0f, 0f)
                            scaleX = scale
                            scaleY = scale
                            translationX = container.left
                            translationY = container.top
                            clip = expansion < PlayerExpansionExpanded && scale > 0f
                            shape = if (clip) {
                                PlayerContainerShape(
                                    heightPx = container.height / scale,
                                    cornerPx = playerContainerCornerPx(expansion, origin) / scale
                                )
                            } else {
                                RectangleShape
                            }
                        }
                        .playerMorphContainer(morphAnchors)
                        .blockTouchesBehind()
                ) {
                    val lyricsLandscapeActive = lyricsLandscapeLayoutActive(LocalConfiguration.current)
                    PlayerScreen(
                        viewModel = playerViewModel,
                        state = playerScreenState,
                        morphAnchors = morphAnchors,
                        morphActive = { artworkMorphActive },
                        collapseActions = PlayerCollapseActions(
                            collapse = collapsePlayer,
                            dragStart = onExpansionDragStart,
                            drag = onExpansionDrag,
                            dragEnd = { velocity -> settleExpansion(velocity, true) }
                        ),
                        motionSuspended = state.showAlbum || state.showArtist || (state.showLyrics && lyricsLandscapeActive)
                    )
                }
            }

            if (state.youtubeEngagement.comments.visible) {
                PlayerYoutubeCommentsSheet(
                    comments = state.youtubeEngagement.comments,
                    primary = yourSoundAccent,
                    secondary = DerbisViolet,
                    strings = currentStrings,
                    onDismiss = viewModel::closeYoutubeComments,
                    onRetry = viewModel::retryYoutubeComments,
                    onLoadMore = viewModel::loadMoreYoutubeComments,
                    onRetryLoadMore = viewModel::retryYoutubeCommentsPage,
                    onToggleReplies = viewModel::toggleYoutubeCommentReplies,
                    onLoadMoreReplies = viewModel::loadMoreYoutubeCommentReplies
                )
            }

            val morphTrack = state.currentTrack
            if (morphAllowed && morphTrack != null) {
                PlayerArtworkMorphLayer(
                    track = morphTrack,
                    anchors = morphAnchors,
                    active = { artworkMorphActive },
                    expansion = expansionProvider
                )
            }

            val downloadsActive = state.downloadingTrackIds.isNotEmpty()
            var downloadHudMinimized by rememberSaveable { mutableStateOf(false) }
            var downloadHudDismissed by rememberSaveable { mutableStateOf(false) }
            LaunchedEffect(downloadsActive) {
                if (!downloadsActive) {
                    downloadHudMinimized = false
                    downloadHudDismissed = false
                }
            }
            val downloadHudOverPlayer = state.selectedTab == DerbisTab.Player
            AnimatedVisibility(
                visible = downloadsActive && !downloadHudDismissed,
                modifier = Modifier
                    .align(if (downloadHudOverPlayer) Alignment.TopCenter else Alignment.BottomCenter)
                    .zIndex(18f)
                    .padding(horizontal = 16.dp)
                    .then(
                        if (downloadHudOverPlayer) {
                            Modifier.statusBarsPadding().padding(top = DerbisPlayerDesign.MinimumTouchTarget + DerbisPlayerDesign.SpaceLg)
                        } else {
                            Modifier.navigationBarsPadding().padding(bottom = downloadHudBottomPadding(state, dockSideBySide))
                        }
                    ),
                enter = miniEnter,
                exit = miniExit
            ) {
                DownloadProgressHud(
                    state = state,
                    minimized = downloadHudMinimized,
                    onMinimizedChange = { downloadHudMinimized = it },
                    onDismiss = { downloadHudDismissed = true }
                )
            }

            AnimatedVisibility(visible = state.showOnboarding, enter = overlayEnter, exit = overlayExit) {
                if (state.showOnboarding) {
                    val onboardingArtwork by viewModel.onboardingArtwork.collectAsStateWithLifecycle()
                    OnboardingOverlay(
                        selectedLanguageCode = state.languageCode,
                        artwork = onboardingArtwork,
                        youtubeMusic = youtubeMusicState,
                        onTasteLanguage = viewModel::loadOnboardingArtwork,
                        onConnectYoutubeMusic = { code ->
                            youtubeMusicViewModel.open(code)
                            youtubeMusicViewModel.beginLogin()
                        },
                        onYoutubeMusicCookie = youtubeMusicViewModel::acceptCookie,
                        onCancelYoutubeMusicLogin = youtubeMusicViewModel::cancelLogin,
                        onAppearance = { light ->
                            viewModel.setThemePreset(if (light) DerbisThemes.FROST else DerbisThemes.DERBIS_AURA)
                        },
                        onDone = viewModel::completeOnboarding
                    )
                }
            }

            val playlistImportState by viewModel.playlistImport.state.collectAsStateWithLifecycle()
            com.yasuda.derbis.ui.playlistimport.PlaylistImportHub(
                state = playlistImportState,
                controller = viewModel.playlistImport,
                onPickFile = viewModel::importPlaylistFile
            )

            state.sharedMediaPreview?.let { preview ->
                SharedMediaPreviewDialog(
                    preview = preview,
                    languageCode = state.languageCode,
                    onPlay = viewModel::playSharedMedia,
                    onPlayNext = viewModel::playNextSharedMedia,
                    onQueue = viewModel::queueSharedMedia,
                    onDownload = viewModel::downloadSharedMedia,
                    onImport = viewModel::importSharedPlaylist,
                    onSavePlaylist = viewModel::saveSharedMediaAsPlaylist,
                    onDismiss = viewModel::dismissSharedMedia
                )
            }

            AnimatedVisibility(visible = state.showSettings, enter = overlayEnter, exit = overlayExit) {
                SettingsOverlay(
                    onExitApplication = onExitApplication,
                    backEnabled = !playerVisible && !(state.showJam || state.showThemeStudio || state.showLyricsStudio ||
                        state.showHomeStudio || miniPlayerStudio.visible || navigationStudio.visible),
                    miniPlayerVisible = state.currentTrack != null,
                    animationsEnabled = state.animationsEnabled,
                    dynamicColor = state.dynamicColor,
                    sponsorBlock = state.sponsorBlockEnabled,
                    skipSilence = state.skipSilence,
                    updateInfo = state.updateInfo,
                    isCheckingUpdates = state.isCheckingUpdates,
                    currentLanguageCode = state.languageCode,
                    themePreset = state.themePreset,
                    interfaceSettings = state.interfaceSettings,
                    ambientSettings = state.ambientSettings,
                    excludedArtists = state.excludedArtists,
                    downloadSettings = state.downloadSettings,
                    smartOfflineSettings = state.smartOfflineSettings,
                    advancedQueuePrefetchTracks = state.audioSettings.advancedQueuePrefetchTracks,
                    advancedQueuePrefetchOnMobileData = state.audioSettings.advancedQueuePrefetchOnMobileData,
                    backupSettings = state.backupSettings,
                    automationSettings = state.automationSettings,
                    vaultStatus = state.vaultStatus,
                    lastBackupAtMs = state.lastBackupAtMs,
                    backupLocationUri = state.backupLocationUri,
                    downloadQueue = state.downloadQueue,
                    playbackDiagnostics = state.playbackDiagnostics,
                    lastFmConfigured = state.lastFmConfigured,
                    lastFmAuthorizationPending = state.lastFmAuthorizationPending,
                    listenBrainzConfigured = state.listenBrainzConfigured,
                    audDConfigured = state.audDConfigured,
                    networkSettings = state.networkSettings,
                    networkProxyPasswordSet = state.networkProxyPasswordSet,
                    networkTesting = state.networkTesting,
                    networkTestOutcome = state.networkTestOutcome,
                    networkErrors = state.networkErrors,
                    lyricsProviderOrdering = state.lyricsProviderOrdering,
                    onLyricsProviderOrdering = viewModel::setLyricsProviderOrdering,
                    onNetworkSettings = viewModel::updateNetworkSettings,
                    onTestNetwork = viewModel::testNetworkConfiguration,
                    onOpenJam = {
                        viewModel.openJam()
                    },
                    onOpenThemeStudio = {
                        viewModel.openThemeStudio()
                    },
                    onOpenLyricsStudio = {
                        viewModel.openLyricsStudio()
                    },
                    homeStudioStyle = state.homeStudioSettings.style,
                    onOpenHomeStudio = {
                        viewModel.openHomeStudio()
                    },
                    miniPlayerStyle = miniPlayerStudio.settings.style,
                    onOpenMiniPlayerStudio = {
                        viewModel.openMiniPlayerStudio()
                    },
                    navigationStyle = navigationStudio.settings.style,
                    onOpenNavigationStudio = {
                        viewModel.openNavigationStudio()
                    },
                    onOpenAudioSettings = viewModel::openAudioQualityPanel,
                    onInterfaceSettings = viewModel::setInterfaceSettings,
                    onAmbientSettings = viewModel::updateAmbientSettings,
                    onOpenAmbient = {
                        viewModel.closeSettings()
                        viewModel.openAmbient()
                    },
                    onIncludeArtist = viewModel::includeArtist,
                    onDownloadSettings = viewModel::setDownloadSettings,
                    onSmartOfflineSettings = viewModel::setSmartOfflineSettings,
                    onRefreshSmartOffline = viewModel::refreshSmartOffline,
                    onAdvancedQueuePrefetch = viewModel::setAdvancedQueuePrefetchTracks,
                    onAdvancedQueuePrefetchOnMobileData = viewModel::setAdvancedQueuePrefetchOnMobileData,
                    onSelectDownloadLocation = { downloadLocationLauncher.launch(null) },
                    onClearDownloadLocation = {
                        viewModel.setDownloadSettings(
                            viewModel.state.value.downloadSettings.copy(destinationTreeUri = "")
                        )
                    },
                    onBackupSettings = viewModel::setBackupSettings,
                    onAutomationSettings = viewModel::setAutomationSettings,
                    onAnimations = viewModel::setAnimationsEnabled,
                    motionArtworkEnabled = state.motionArtworkEnabled,
                    onMotionArtwork = viewModel::setMotionArtworkEnabled,
                    onDynamicColor = viewModel::setDynamicColor,
                    onSponsorBlock = viewModel::setSponsorBlock,
                    onSkipSilence = viewModel::setSkipSilence,
                    onLanguage = { code ->
                        val normalized = DerbisLanguageCatalog.normalize(code)
