                        queueRemovalTarget = null
                    },
                    onPlayNext = { viewModel.playNext(target) },
                    onAddToQueue = { viewModel.addTracksToQueue(listOf(target)) },
                    onAddToPlaylist = { trackActionPlaylistTarget = target },
                    onRemoveFromQueue = queueRemovalTarget?.takeIf { it.removable }?.let { removal ->
                        {
                            viewModel.removeFromQueue(
                                removal.track,
                                removal.spaceId
                            )
                        }
                    },
                    onToggleFavorite = { viewModel.toggleFavorite(target) },
                    onDownload = { viewModel.exportTrack(target) },
                    onDeleteDownload = { download?.let(viewModel::deleteDownload) },
                    onKeepOffline = download?.takeIf { it.ownership == DownloadOwnership.SMART_OFFLINE }?.let {
                        { viewModel.exportTrack(target) }
                    },
                    onOpenAlbum = { viewModel.openAlbum(trackAlbumHit(target)) },
                    onOpenArtist = { viewModel.openArtist(target) },
                    onRemoveFromHistory = { viewModel.removeRecentSearch(target) },
                    onMoreLikeThis = {
                        viewModel.setTrackFeedback(target, RecommendationFeedbackKind.MORE_LIKE_THIS)
                    },
                    onLessLikeThis = {
                        viewModel.setTrackFeedback(target, RecommendationFeedbackKind.LESS_LIKE_THIS)
                    },
                    onToggleExcludeArtist = {
                        viewModel.toggleExcludeArtist(
                            target.artistBrowseIds.firstOrNull().orEmpty(),
                            target.artist
                        )
                    },
                    isPinnedToHome = SpeedDial.songKey(target)?.let { key -> state.speedDialPins.any { it.key == key } } == true,
                    homePinsFull = state.speedDialPins.size >= SpeedDial.MAX_PINS,
                    onTogglePinToHome = { viewModel.toggleSpeedDialTrack(target) }
                )
            }

            trackActionPlaylistTarget?.let { track ->
                AddToPlaylistDialog(
                    track = track,
                    playlists = state.playlists,
                    onDismiss = { trackActionPlaylistTarget = null },
                    onAddTo = { playlistId ->
                        viewModel.addToPlaylist(playlistId, track)
                        trackActionPlaylistTarget = null
                    },
                    onCreateWith = { name ->
                        viewModel.createPlaylist(name, track)
                        trackActionPlaylistTarget = null
                    }
                )
            }
            }
        }
    }
}

@Composable
private fun SharedMediaPreviewDialog(
    preview: SharedMediaPreview,
    languageCode: String,
    onPlay: () -> Unit,
    onPlayNext: () -> Unit,
    onQueue: () -> Unit,
    onDownload: () -> Unit,
    onImport: () -> Unit,
    onSavePlaylist: () -> Unit,
    onDismiss: () -> Unit
) {
    val italian = languageCode.equals("it", ignoreCase = true)
    val bulkCopy = remember(languageCode) { bulkLinkCaptureCopy(languageCode) }
    val bulkSummary = preview.bulkSummary
    Dialog(
        onDismissRequest = onDismiss,
        properties = DialogProperties(usePlatformDefaultWidth = false)
    ) {
        Surface(
            color = DerbisInk.copy(alpha = 0.98f),
            shape = RoundedCornerShape(30.dp),
            border = BorderStroke(1.dp, Color.White.copy(alpha = 0.12f)),
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 18.dp)
        ) {
            Column(
                modifier = Modifier.padding(20.dp),
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(14.dp)
                ) {
                    if (preview.thumbnailUrl.isNotBlank()) {
                        AsyncImage(
                            model = preview.thumbnailUrl,
                            contentDescription = null,
                            contentScale = ContentScale.Crop,
                            modifier = Modifier
                                .size(78.dp)
                                .clip(RoundedCornerShape(18.dp))
                        )
                    } else {
                        EmptyCover(
                            Modifier
                                .size(78.dp)
                                .clip(RoundedCornerShape(18.dp))
                        )
                    }
                    Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(5.dp)) {
                        Text(
                            text = if (italian) "Condiviso con Derbis" else "Shared with Derbis",
                            color = DerbisCyan,
                            fontSize = 11.sp,
                            fontWeight = FontWeight.Black
                        )
                        Text(
                            text = preview.title.ifBlank { bulkCopy.title.takeIf { bulkSummary != null }.orEmpty() },
                            color = DerbisText,
                            fontSize = 19.sp,
                            fontWeight = FontWeight.Black,
                            maxLines = 2,
                            overflow = TextOverflow.Ellipsis
                        )
                        if (preview.subtitle.isNotBlank()) Text(
                            text = preview.subtitle,
                            color = DerbisMuted,
                            fontSize = 12.sp,
                            fontWeight = FontWeight.SemiBold,
                            maxLines = 2,
                            overflow = TextOverflow.Ellipsis
                        )
                    }
                    CircleIconButton(
                        icon = Icons.Rounded.Close,
                        tint = DerbisText,
                        background = Color.White.copy(alpha = 0.08f),
                        onClick = onDismiss
                    )
                }
                when {
                    preview.loading -> {
                        Row(
                            modifier = Modifier.fillMaxWidth().padding(vertical = 12.dp),
                            horizontalArrangement = Arrangement.Center,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            CircularProgressIndicator(modifier = Modifier.size(24.dp), strokeWidth = 2.5.dp, color = DerbisCyan)
                        }
                    }
                    preview.error.isNotBlank() -> {
                        Text(
                            text = preview.error,
                            color = DerbisOrange,
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Bold
                        )
                    }
                    bulkSummary != null && !preview.playable -> {
                        BulkLinkCaptureSummaryText(bulkSummary, bulkCopy)
                        Text(
                            text = bulkCopy.noTracks,
                            color = DerbisOrange,
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Bold
                        )
                    }
                    preview.playable -> {
                        bulkSummary?.let { BulkLinkCaptureSummaryText(it, bulkCopy) }
                        if (bulkSummary == null) Text(
                            text = if (italian) "${preview.tracks.size} ${if (preview.tracks.size == 1) "brano pronto" else "brani pronti"}" else "${preview.tracks.size} ${if (preview.tracks.size == 1) "track ready" else "tracks ready"}",
                            color = DerbisMuted,
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold
                        )
                        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                            SharedMediaAction(
                                modifier = Modifier.weight(1f),
                                icon = Icons.Rounded.PlayArrow,
                                title = if (italian) "Riproduci" else "Play",
                                primary = true,
                                onClick = onPlay
                            )
                            SharedMediaAction(
                                modifier = Modifier.weight(1f),
                                icon = Icons.Rounded.Download,
                                title = if (italian) "Scarica" else "Download",
                                primary = false,
                                onClick = onDownload
                            )
                        }
                        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                            SharedMediaAction(
                                modifier = Modifier.weight(1f),
                                icon = Icons.Rounded.SkipNext,
                                title = if (italian) "Dopo" else "Play next",
                                primary = false,
                                onClick = onPlayNext
                            )
                            SharedMediaAction(
                                modifier = Modifier.weight(1f),
                                icon = Icons.AutoMirrored.Rounded.QueueMusic,
                                title = if (italian) "In coda" else "Queue",
                                primary = false,
                                onClick = onQueue
                            )
                        }
                        if (preview.request.kind == SharedMediaKind.DerbisPlaylist) {
                            Row(modifier = Modifier.fillMaxWidth()) {
                                SharedMediaAction(
                                    modifier = Modifier.weight(1f),
                                    icon = Icons.Rounded.LibraryAdd,
                                    title = if (italian) "Importa" else "Import",
                                    primary = false,
                                    onClick = onImport
                                )
                            }
                        }
                        if (preview.request.kind == SharedMediaKind.BulkLinks) {
                            Row(modifier = Modifier.fillMaxWidth()) {
                                SharedMediaAction(
                                    modifier = Modifier.weight(1f),
                                    icon = Icons.Rounded.LibraryAdd,
                                    title = bulkCopy.savePlaylist,
                                    primary = false,
                                    onClick = onSavePlaylist
                                )
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun BulkLinkCaptureSummaryText(summary: BulkLinkCaptureSummary, copy: BulkLinkCaptureCopy) {
    val lines = buildList {
        add(copy.detected(summary.detectedLinks))
        add(copy.found(summary.resolvedTracks))
        if (summary.duplicates > 0) add(copy.duplicates(summary.duplicates))
        if (summary.unrecognized > 0) add(copy.unrecognized(summary.unrecognized))
    }
    Column(
        modifier = Modifier.semantics(mergeDescendants = true) {},
        verticalArrangement = Arrangement.spacedBy(3.dp)
    ) {
        lines.forEach { line ->
            Text(
                text = line,
                color = DerbisMuted,
                fontSize = 12.sp,
                fontWeight = FontWeight.Bold
            )
        }
    }
}

