private data class DownloadHudItem(
    val taskKey: String,
    val progress: Int,
    val title: String,
    val count: Int
)

private fun DerbisUiState.activeDownloadHudItem(strings: DerbisStrings): DownloadHudItem? {
    val ids = downloadingTrackIds.toList()
    if (ids.isEmpty()) return null
    val primaryId = ids.maxByOrNull { downloadProgressByTrackId[it] ?: 1 } ?: return null
    val progress = (downloadProgressByTrackId[primaryId] ?: 1).coerceIn(1, 99)
    val rawTitle = downloadTitleByTrackId[primaryId].orEmpty().ifBlank { strings.song }
    val title = if (ids.size > 1) "$rawTitle +${ids.size - 1}" else rawTitle
    return DownloadHudItem(taskKey = primaryId, progress = progress, title = title, count = ids.size)
}

private fun downloadHudBottomPadding(state: DerbisUiState, dockSideBySide: Boolean): Dp {
    return when {
        state.currentTrack != null && !dockSideBySide -> 154.dp
        else -> 96.dp
    }
}

@Composable
private fun tabBarBottomContentInset(miniPlayerVisible: Boolean, animationsEnabled: Boolean): Dp {
    val navigationBarInset = WindowInsets.navigationBars.asPaddingValues().calculateBottomPadding()
    val navigationHeight = when {
        DerbisIsNocturne -> (LocalNocturneNavigationHeight.current?.value ?: 64.dp) + 1.dp
        DerbisIsPrism -> LocalNocturneNavigationHeight.current?.value ?: 80.dp
        else -> DerbisTabBarCompactHeight
    }
    val collapsed = navigationHeight + navigationBarInset + DerbisBottomContentGap + LocalNavDockExtraClearance.current
    val miniPlayerExtra = if (DerbisIsPrism) {
        84.dp
    } else if (derbisWindowIsCompactLandscape()) {
        (DerbisMiniPlayerHeight - DerbisTabBarHeight).coerceAtLeast(0.dp)
    } else {
        DerbisMiniPlayerHeight
    }
    return animatedBottomContentInset(
        collapsed = collapsed,
        expanded = collapsed + miniPlayerExtra,
        miniPlayerVisible = miniPlayerVisible,
        animationsEnabled = animationsEnabled
    )
}

@Composable
internal fun derbisTabContentBottomPadding(miniPlayerVisible: Boolean): Dp =
    tabBarBottomContentInset(miniPlayerVisible, LocalAnimationsEnabled.current) + 16.dp

@Composable
private fun animatedBottomContentInset(
    collapsed: Dp,
    expanded: Dp,
    miniPlayerVisible: Boolean,
    animationsEnabled: Boolean
): Dp {
    val effectiveAnimationsEnabled = animationsEnabled && LocalAnimationsEnabled.current
    val inset by animateDpAsState(
        targetValue = if (miniPlayerVisible) expanded else collapsed,
        animationSpec = if (effectiveAnimationsEnabled) {
            tween(durationMillis = 260, easing = FastOutSlowInEasing)
        } else {
            snap()
        },
        label = "bottomContentInset"
    )
    return inset
}

@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
private fun DownloadProgressHud(
    state: DerbisUiState,
    minimized: Boolean,
    onMinimizedChange: (Boolean) -> Unit,
    onDismiss: () -> Unit
) {
    val strings = LocalDerbisStrings.current
    val item = state.activeDownloadHudItem(strings) ?: return
    val colors = MaterialTheme.colorScheme
    val progress by animateFloatAsState(
        targetValue = item.progress / 100f,
        animationSpec = spring(dampingRatio = Spring.DampingRatioNoBouncy, stiffness = Spring.StiffnessLow),
        label = "downloadHudProgress"
    )
    AnimatedContent(
        targetState = minimized,
        transitionSpec = {
            fadeIn(tween(180)) + scaleIn(spring(dampingRatio = 0.7f, stiffness = 500f), initialScale = 0.85f) togetherWith
                fadeOut(tween(120)) using SizeTransform(clip = false)
        },
        modifier = Modifier.fillMaxWidth(),
        contentAlignment = Alignment.CenterEnd,
        label = "downloadHudMode"
    ) { compact ->
        if (compact) {
            Surface(
                onClick = { onMinimizedChange(false) },
                shape = CircleShape,
                color = colors.primaryContainer,
                contentColor = colors.onPrimaryContainer,
                shadowElevation = 6.dp,
                modifier = Modifier
                    .wrapContentWidth(Alignment.End)
                    .size(52.dp)
                    .semantics { contentDescription = "${strings.downloadInProgress} ${item.progress}%" }
            ) {
                Box(contentAlignment = Alignment.Center) {
                    CircularWavyProgressIndicator(
                        progress = { progress },
                        modifier = Modifier.size(44.dp),
                        color = colors.primary,
                        trackColor = colors.primary.copy(alpha = 0.18f)
                    )
                    Icon(Icons.Rounded.Download, contentDescription = null, modifier = Modifier.size(20.dp))
                }
            }
        } else {
            Surface(
                shape = RoundedCornerShape(28.dp),
                color = colors.surfaceContainerHigh,
                contentColor = colors.onSurface,
                shadowElevation = 6.dp,
                modifier = Modifier.fillMaxWidth()
            ) {
                Row(
                    modifier = Modifier.padding(start = 10.dp, end = 4.dp, top = 8.dp, bottom = 8.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    Box(
                        modifier = Modifier
                            .size(44.dp)
                            .clip(CircleShape)
                            .background(colors.primaryContainer),
                        contentAlignment = Alignment.Center
                    ) {
                        CircularWavyProgressIndicator(
                            progress = { progress },
                            modifier = Modifier.size(40.dp),
                            color = colors.primary,
                            trackColor = colors.primary.copy(alpha = 0.18f)
                        )
                        Icon(
                            Icons.Rounded.Download,
                            contentDescription = null,
                            tint = colors.onPrimaryContainer,
                            modifier = Modifier.size(18.dp)
                        )
                    }
                    Column(modifier = Modifier.weight(1f)) {
                        Text(
                            text = item.title,
                            style = MaterialTheme.typography.titleSmall,
                            fontWeight = FontWeight.SemiBold,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                        Text(
                            text = "${if (item.count > 1) strings.downloadsInProgress else strings.downloadInProgress} · ${item.progress}%",
                            style = MaterialTheme.typography.labelMedium,
                            color = colors.onSurfaceVariant,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                    }
                    IconButton(onClick = { onMinimizedChange(true) }) {
                        Icon(Icons.Rounded.KeyboardArrowDown, contentDescription = strings.showLess, tint = colors.onSurfaceVariant)
                    }
                    IconButton(onClick = onDismiss) {
                        Icon(Icons.Rounded.Close, contentDescription = strings.close, tint = colors.onSurfaceVariant)
                    }
                }
            }
        }
    }
}

