private fun compactReleaseNotes(notes: String): String {
    val clean = notes
        .lineSequence()
        .map { it.trim().trimStart('-', '*', '•').trim() }
        .filter { it.isNotBlank() }
        .take(3)
        .joinToString(" · ")
    return clean.ifBlank { "General improvements and bug fixes." }
}

internal fun isLaunchableUpdateTarget(url: String): Boolean =
    AppUpdateContract.matches(Intent.ACTION_VIEW, url) || url.startsWith("https://", ignoreCase = true)

private fun shareJamInvite(
    context: android.content.Context,
    payload: String,
    strings: DerbisStrings
) {
    if (payload.isBlank()) return
    runCatching {
        val intent = Intent(Intent.ACTION_SEND).apply {
            type = "text/plain"
            putExtra(Intent.EXTRA_SUBJECT, strings.jamTitle)
            putExtra(Intent.EXTRA_TEXT, payload)
        }
        context.startActivity(
            Intent.createChooser(intent, strings.share).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        )
    }.onFailure {
        Toast.makeText(context, strings.cannotOpenExternalLink, Toast.LENGTH_LONG).show()
    }
}

private fun openExternalUrl(
    context: android.content.Context,
    url: String,
    strings: DerbisStrings = DerbisStrings.forCode("en")
) {
    if (url.isBlank()) {
        Toast.makeText(context, strings.externalLinkUnavailable, Toast.LENGTH_LONG).show()
        return
    }
    runCatching {
        val intent = Intent(Intent.ACTION_VIEW, Uri.parse(url)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        context.startActivity(intent)
    }.onFailure {
        Toast.makeText(context, strings.cannotOpenExternalLink, Toast.LENGTH_LONG).show()
    }
}

internal data class QueueEntry(
    val key: String,
    val track: Track,
    /** Index in the backing playback queue; differs from a filtered display position. */
    val queueIndex: Int = -1
)

private data class QueueRemovalTarget(
    val track: Track,
    val spaceId: String,
    val removable: Boolean
)

internal fun queueSelectionKeys(queue: List<Track>): List<String> =
    buildQueueEntries(queue).map { it.key }

/**
 * Endless Listening is a sliding queue: tracks before the current one are playback history, not
 * upcoming songs.  Keep the current track and every later entry visible so newly appended radio
 * recommendations are shown immediately, while completed entries never grow the song list.
 */
internal fun endlessListeningVisibleEntries(
    entries: List<QueueEntry>,
    currentQueueIndex: Int,
    enabled: Boolean
): List<QueueEntry> {
    if (!enabled || currentQueueIndex < 0) return entries
    return entries.filter { entry -> entry.queueIndex >= currentQueueIndex }
}

internal fun reorderQueueEntries(
    entries: List<QueueEntry>,
    from: Int,
    to: Int
): List<QueueEntry> {
    if (from !in entries.indices || to !in entries.indices || from == to) return entries
    val mutable = entries.toMutableList()
    val moved = mutable.removeAt(from)
    mutable.add(to, moved)
    return mutable.mapIndexed { queueIndex, entry -> entry.copy(queueIndex = queueIndex) }
}

internal fun buildQueueEntries(
    queue: List<Track>,
    existingEntries: List<QueueEntry> = emptyList()
): List<QueueEntry> {
    if (queue.isEmpty()) return emptyList()
    if (existingEntries.isNotEmpty() && existingEntries.size == queue.size && existingEntries.map { it.track } == queue) {
        return existingEntries
    }
    val available = existingEntries.toMutableList()
    val usedKeys = hashSetOf<String>()
    val result = ArrayList<QueueEntry>(queue.size)

    for ((queueIndex, track) in queue.withIndex()) {
        val exactIndex = available.indexOfFirst { it.track === track }
            .takeIf { it >= 0 }
            ?: available.indexOfFirst { it.track == track }
                .takeIf { it >= 0 }
            ?: available.indexOfFirst { it.track.id == track.id && it.track.videoUrl == track.videoUrl }
                .takeIf { it >= 0 }

        if (exactIndex != null) {
            val matched = available.removeAt(exactIndex)
            usedKeys.add(matched.key)
            result.add(QueueEntry(matched.key, track, queueIndex))
        } else {
            val base = "${track.id}|${track.videoUrl}"
            var occurrence = 1
            while ("$base#$occurrence" in usedKeys) {
                occurrence++
            }
            val key = "$base#$occurrence"
            usedKeys.add(key)
            result.add(QueueEntry(key, track, queueIndex))
        }
    }
    return result
}

private val queueSelectionSaver = listSaver<Set<String>, String>(
    save = { it.toList() },
    restore = { it.toSet() }
)

@OptIn(ExperimentalFoundationApi::class, ExperimentalMaterial3Api::class)
@Composable
private fun QueueOverlay(
    state: DerbisUiState,
    onPlay: (Track) -> Unit,
    onPrevious: () -> Unit,
    onTogglePlay: () -> Unit,
    onNext: () -> Unit,
    onSeek: (Float) -> Unit,
    onToggleShuffle: () -> Unit,
    onToggleRepeat: () -> Unit,
    onToggleFavorite: (Track) -> Unit,
    onRemove: (QueueRemovalTarget) -> Unit,
    onRemoveSelected: (List<Int>) -> Unit,
    onMove: (Int, Int) -> Unit,
    onUndo: () -> Unit,
    onToggleRadio: () -> Unit,
    onLoadMoreEndless: () -> Unit,
    onOpenJam: () -> Unit = {},
    onPrepareQueuePlaylist: (String) -> Unit,
    onDismissQueuePlaylist: () -> Unit,
    onTrackActions: (QueueRemovalTarget) -> Unit,
    onAddSelectedToPlaylist: (String, List<Track>) -> Unit,
    onCreatePlaylistWithSelected: (String, List<Track>) -> Unit,
    onDownloadSelected: (List<Track>) -> Unit,
    onClose: () -> Unit
) {
    val strings = LocalDerbisStrings.current
    val haptics = LocalDerbisHaptics.current
    val queueAccent = rememberNowPlayingAccent(state.currentTrack, DerbisCyan)
    var selectedQueueKeys by rememberSaveable(stateSaver = queueSelectionSaver) { mutableStateOf(emptySet<String>()) }
    var addToPlaylistTracks by remember { mutableStateOf(emptyList<Track>()) }
    var queueEntries by remember(state.activeQueueSpaceId) { mutableStateOf(buildQueueEntries(state.queue)) }

    val currentEntries = remember(state.queue, queueEntries) {
        if (queueEntries.size == state.queue.size && queueEntries.map { it.track } == state.queue) queueEntries
        else buildQueueEntries(state.queue, queueEntries).also { queueEntries = it }
    }
    val displayEntries = remember(currentEntries, state.queueCurrentIndex, state.radioEnabled) {
        endlessListeningVisibleEntries(
            entries = currentEntries,
            currentQueueIndex = state.queueCurrentIndex,
            enabled = state.radioEnabled
        )
    }
    // The current song is presented in the compact player header.  In Endless Listening, completed
    // tracks are intentionally absent; the list is a live window of current/upcoming tracks and all
    // newly appended continuation picks, rather than a growing playback history.
    val upcomingEntries = remember(displayEntries, state.queueCurrentIndex) {
        displayEntries.filter { it.queueIndex != state.queueCurrentIndex }
    }
    val currentQueueEntry = remember(displayEntries, state.queueCurrentIndex) {
        displayEntries.firstOrNull { it.queueIndex == state.queueCurrentIndex }
    }
    val selectedTracks = remember(upcomingEntries, selectedQueueKeys) {
        upcomingEntries.filter { it.key in selectedQueueKeys }.map { it.track }
    }
    val removableIndices = remember(upcomingEntries, selectedQueueKeys) {
        upcomingEntries.mapNotNull { entry -> entry.queueIndex.takeIf { entry.key in selectedQueueKeys } }
    }
    val selectionActive = selectedTracks.isNotEmpty()
    val allSelected = upcomingEntries.isNotEmpty() && selectedTracks.size == upcomingEntries.size
    val queueItemFade: FiniteAnimationSpec<Float>? = if (state.animationsEnabled) tween(DerbisMotion.Durations.Short, easing = DerbisMotion.Easings.Standard) else null
    val queueItemPlacement: FiniteAnimationSpec<IntOffset>? = if (state.animationsEnabled) DerbisMotion.reorder.spec(visibilityThreshold = IntOffset.VisibilityThreshold) else null

    val onMoveEntry: (Int, Int) -> Unit = move@{ from, to ->
        val sourceFrom = upcomingEntries.getOrNull(from)?.queueIndex ?: return@move
        val sourceTo = upcomingEntries.getOrNull(to)?.queueIndex ?: return@move
        queueEntries = reorderQueueEntries(currentEntries, sourceFrom, sourceTo)
        onMove(sourceFrom, sourceTo)
    }

    val queueTrackRow: @Composable (Int, QueueEntry, Modifier) -> Unit = { index, entry, rowModifier ->
        val track = entry.track
        val isCurrent = entry.queueIndex == state.queueCurrentIndex
        val wasPlayed = state.queueCurrentIndex >= 0 && entry.queueIndex < state.queueCurrentIndex
        val rowSelected = entry.key in selectedQueueKeys
        var dragDistance by remember(entry.key) { mutableFloatStateOf(0f) }
        val latestMove by rememberUpdatedState(onMoveEntry)
        val latestRemove by rememberUpdatedState(onRemove)
        val dismissThreshold = SwipeToDismissBoxDefaults.positionalThreshold
        val dismissState = remember(entry.key, dismissThreshold) {
            SwipeToDismissBoxState(SwipeToDismissBoxValue.Settled, dismissThreshold)
        }
        LaunchedEffect(dismissState.currentValue) {
            if (isCurrent || dismissState.currentValue != SwipeToDismissBoxValue.EndToStart) return@LaunchedEffect
            haptics.perform(DerbisHapticAction.TrackSwipe)
            latestRemove(QueueRemovalTarget(track = track, spaceId = state.activeQueueSpaceId, removable = true))
            dismissState.reset()
        }
        SwipeToDismissBox(
            state = dismissState,
            enableDismissFromStartToEnd = false,
            enableDismissFromEndToStart = !isCurrent && !selectionActive,
            // A transparent foreground must not reveal a permanent dismiss backdrop. The upstream
            // queue is a flat text-and-artwork list; removal remains available through swipe/menu
            // without leaving a colored card or trash glyph visible at rest.
            backgroundContent = { Box(Modifier.fillMaxSize()) },
            modifier = rowModifier.fillMaxWidth()
        ) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    // Queue songs are intentionally a flat list: no card outline, rounded shell,
                    // or individual tile chrome. Selection uses a quiet full-width wash instead.
                    .then(if (rowSelected) Modifier.background(Color.White.copy(alpha = 0.11f)) else Modifier)
                    .derbisPressable(
                        onClick = {
                            if (selectionActive) selectedQueueKeys = if (rowSelected) selectedQueueKeys - entry.key else selectedQueueKeys + entry.key
                            else onPlay(track)
                        },
                        pressedScale = DerbisPressScale.Row,
                        role = if (selectionActive) Role.Checkbox else Role.Button,
                        onClickLabel = if (selectionActive) strings.selectTrack else strings.play,
                        onLongClickLabel = strings.selectTrack,
                        onLongClick = { selectedQueueKeys = selectedQueueKeys + entry.key }
                    )
                    .padding(vertical = 7.dp, horizontal = 4.dp)
                    .semantics {
                        if (selectionActive) selected = rowSelected
                        if (!selectionActive) {
                            customActions = listOf(
                                CustomAccessibilityAction(strings.remove) {
                                    onRemove(QueueRemovalTarget(track = track, spaceId = state.activeQueueSpaceId, removable = true))
                                    true
                                }
                            )
                        }
                    },
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(14.dp)
            ) {
                CoverImage(
                    track,
                    Modifier
                        .size(58.dp)
                        .clip(RoundedCornerShape(6.dp))
                        .alpha(if (wasPlayed) 0.42f else 1f)
                )
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(3.dp)) {
                    Text(
                        track.title,
                        color = if (wasPlayed) Color.White.copy(alpha = 0.48f) else Color.White,
                        fontSize = 16.sp,
                        fontWeight = FontWeight.Bold,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                        if (track.explicit) {
                            Text(
                                "E",
                                color = Color(0xFF233138),
                                fontSize = 10.sp,
                                fontWeight = FontWeight.Black,
                                modifier = Modifier.clip(RoundedCornerShape(3.dp)).background(Color.White.copy(alpha = 0.72f)).padding(horizontal = 3.dp, vertical = 1.dp)
                            )
                        }
                        Text(
                            track.artist,
                            color = Color.White.copy(alpha = if (wasPlayed) 0.40f else 0.72f),
                            fontSize = 13.sp,
                            fontWeight = FontWeight.SemiBold,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                    }
                }
                if (isCurrent) {
                    DerbisPlayingIndicator(
                        playing = state.isPlaying,
                        color = queueAccent,
                        size = 18.dp,
                        contentDescription = strings.playing
                    )
                }
                if (selectionActive) {
                    Icon(
                        if (rowSelected) Icons.Rounded.CheckCircle else Icons.Rounded.RadioButtonUnchecked,
                        contentDescription = null,
                        tint = if (rowSelected) Color.White else Color.White.copy(alpha = 0.40f),
                        modifier = Modifier.size(25.dp)
                    )
                } else {
                    val reorderModifier = Modifier.pointerInput(entry.key) {
                        var dragIndex = index
                        detectVerticalDragGestures(
                            onDragStart = { dragDistance = 0f; dragIndex = index },
                            onDragCancel = { dragDistance = 0f },
                            onDragEnd = { dragDistance = 0f },
                            onVerticalDrag = { change, amountY ->
                                change.consume()
                                dragDistance += amountY
                                val threshold = 42.dp.toPx()
                                when {
                                    dragDistance > threshold && dragIndex < upcomingEntries.lastIndex -> {
                                        latestMove(dragIndex, dragIndex + 1)
                                        dragIndex += 1
                                        dragDistance = 0f
                                        haptics.perform(DerbisHapticAction.Reorder)
                                    }
                                    dragDistance < -threshold && dragIndex > 0 -> {
                                        latestMove(dragIndex, dragIndex - 1)
                                        dragIndex -= 1
                                        dragDistance = 0f
                                        haptics.perform(DerbisHapticAction.Reorder)
                                    }
                                }
                            }
                        )
                    }
                    // Keep queue actions, including remove, behind the one ⋮ overflow button
                    // (and swipe) so every queue row remains visually focused on the track.
                    IconButton(
                        onClick = {
                            onTrackActions(
                                QueueRemovalTarget(track = track, spaceId = state.activeQueueSpaceId, removable = !isCurrent)
                            )
                        },
                        modifier = reorderModifier.size(42.dp)
                    ) {
                        Icon(
                            Icons.Rounded.MoreVert,
                            contentDescription = strings.options,
                            tint = Color.White.copy(alpha = 0.96f),
                            modifier = Modifier.size(25.dp)
                        )
                    }
                }
            }
        }
    }

    BackHandler(enabled = selectionActive) { selectedQueueKeys = emptySet() }

    val queueListState = rememberLazyListState()
    val reachedEndlessQueueTail by remember(queueListState) {
        derivedStateOf {
            val layout = queueListState.layoutInfo
            val lastVisible = layout.visibleItemsInfo.lastOrNull()?.index ?: -1
            layout.totalItemsCount > 0 && lastVisible >= layout.totalItemsCount - 3
        }
    }
    LaunchedEffect(state.radioEnabled, reachedEndlessQueueTail) {
        if (state.radioEnabled && reachedEndlessQueueTail && upcomingEntries.isNotEmpty()) {
            onLoadMoreEndless()
        }
    }

    val currentTrack = state.currentTrack ?: currentQueueEntry?.track
    val queueFocusTrack = upcomingEntries.firstOrNull()?.track ?: currentTrack
    Box(
        modifier = Modifier
            .fillMaxSize()
            .windowInsetsPadding(DerbisHorizontalSafeInsets)
    ) {
        // The page-level artwork wash is static for the current song. It is behind the entire
        // source-style queue and never participates in row scrolling or playback-clock updates.
        QueueReferenceArtworkBackdrop(
            track = currentTrack,
            accent = queueAccent
        )

        Column(
            modifier = Modifier
                .fillMaxSize()
                .statusBarsPadding()
        ) {
            Box(
                Modifier
                    .fillMaxWidth()
                    .padding(top = 8.dp, bottom = 4.dp),
                contentAlignment = Alignment.Center
            ) {
                Box(
                    Modifier
                        .width(42.dp)
                        .height(6.dp)
                        .clip(CircleShape)
                        .background(Color.White.copy(alpha = 0.40f))
                )
            }

            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 20.dp)
            ) {
                currentTrack?.let { playingTrack ->
                    QueueReferenceCurrentTrack(
                        track = playingTrack,
                        isFavorite = playingTrack.id in state.favoriteIds,
                        onToggleFavorite = { onToggleFavorite(playingTrack) },
                        onMore = {
                            onTrackActions(
                                QueueRemovalTarget(
                                    track = playingTrack,
                                    spaceId = state.activeQueueSpaceId,
                                    removable = currentQueueEntry?.queueIndex != state.queueCurrentIndex
                                )
                            )
                        }
                    )
                }
                QueueReferenceModeControls(
                    shuffleEnabled = state.shuffleEnabled,
                    repeatMode = state.repeatMode,
                    onSaveQueue = { onPrepareQueuePlaylist(state.activeQueueSpaceId) },
                    onShuffle = onToggleShuffle,
                    onRepeat = onToggleRepeat
                )
                queueFocusTrack?.let { focus ->
                    QueueReferenceHeading(
                        label = strings.nowPlaying,
                        title = focus.title,
                        endlessLabel = strings.continuousRadio,
                        endlessEnabled = state.radioEnabled,
                        undoAvailable = state.queueUndoAvailable,
                        onToggleEndless = onToggleRadio,
                        onOpenJam = onOpenJam,
                        onUndo = onUndo
                    )
                }
            }

            // This is the only scrolling region. The bottom cluster is a sibling below it, so no
            // song can appear or receive touches behind the runtime, transport, volume, or output
            // controls.
            Box(modifier = Modifier.weight(1f).fillMaxWidth()) {
                LazyColumn(
                    state = queueListState,
                    modifier = Modifier.fillMaxSize(),
                    contentPadding = PaddingValues(start = 20.dp, end = 20.dp, top = 10.dp, bottom = 24.dp),
                    verticalArrangement = Arrangement.spacedBy(0.dp)
                ) {
                    if (upcomingEntries.isEmpty()) {
                        item(contentType = "queue-empty") {
                            Text(
                                strings.queueEmpty,
                                color = Color.White.copy(alpha = 0.72f),
                                fontSize = 15.sp,
                                fontWeight = FontWeight.SemiBold,
                                modifier = Modifier.padding(vertical = 24.dp)
                            )
                        }
                    } else {
                        itemsIndexed(
                            upcomingEntries,
                            key = { _, entry -> "queue-reference-${entry.key}" },
                            contentType = { _, _ -> "queue-reference-track" }
                        ) { index, entry ->
                            queueTrackRow(
                                index,
                                entry,
                                Modifier.animateItem(queueItemFade, queueItemPlacement, queueItemFade)
                            )
                        }
                    }
                }
            }

            QueueReferencePlaybackRail(
                state = state,
                onPrevious = onPrevious,
                onTogglePlay = onTogglePlay,
                onNext = onNext,
                onSeek = onSeek,
                onSaveQueue = { onPrepareQueuePlaylist(state.activeQueueSpaceId) },
                onClose = onClose,
                modifier = Modifier.fillMaxWidth()
            )
        }

        AnimatedVisibility(
            visible = selectionActive,
            enter = fadeIn(),
            exit = fadeOut(),
            modifier = Modifier
                .align(Alignment.BottomCenter)
                .navigationBarsPadding()
                .padding(start = 12.dp, end = 12.dp, bottom = 18.dp)
        ) {
            QueueSelectionBar(
                count = selectedTracks.size,
                allSelected = allSelected,
                canRemove = removableIndices.isNotEmpty(),
                onSelectAll = { selectedQueueKeys = upcomingEntries.map { it.key }.toSet() },
                onClear = { selectedQueueKeys = emptySet() },
                onAddToPlaylist = { addToPlaylistTracks = selectedTracks },
                onDownload = { onDownloadSelected(selectedTracks); selectedQueueKeys = emptySet() },
                onRemove = { onRemoveSelected(removableIndices); selectedQueueKeys = emptySet() }
            )
        }
    }

    if (addToPlaylistTracks.isNotEmpty()) {
        val pendingTracks = addToPlaylistTracks
        AddTracksToPlaylistDialog(
            tracks = pendingTracks,
            playlists = state.playlists,
            onDismiss = { addToPlaylistTracks = emptyList() },
            onAdd = { playlistId ->
                onAddSelectedToPlaylist(playlistId, pendingTracks)
                addToPlaylistTracks = emptyList()
                selectedQueueKeys = emptySet()
            },
            onCreate = { name ->
                onCreatePlaylistWithSelected(name, pendingTracks)
                addToPlaylistTracks = emptyList()
                selectedQueueKeys = emptySet()
            }
        )
    }

    state.queuePlaylistDraft?.let { draft ->
        key(draft.sourceSpaceId, draft.tracks) {
            AddTracksToPlaylistDialog(
                tracks = draft.tracks,
                playlists = state.playlists,
                onDismiss = onDismissQueuePlaylist,
                onAdd = { playlistId ->
                    onAddSelectedToPlaylist(playlistId, draft.tracks)
                    onDismissQueuePlaylist()
                },
                onCreate = { name ->
                    onCreatePlaylistWithSelected(name, draft.tracks)
                    onDismissQueuePlaylist()
                }
            )
        }
    }
}

@Composable
private fun QueueReferenceArtworkBackdrop(
    track: Track?,
    accent: Color
) {
    val artworkUrl = track?.let { active ->
        active.largeThumbnailUrl.ifBlank { active.thumbnailUrl }
    }.orEmpty()
    val fallbackTop = remember(accent) { lerp(accent, Color(0xFF123E47), 0.36f) }
    val fallbackBottom = remember(accent) { lerp(accent, Color(0xFF091218), 0.86f) }
    Box(Modifier.fillMaxSize().background(fallbackBottom)) {
        SeamlessArtworkImage(
            url = artworkUrl,
            modifier = Modifier
                .fillMaxSize()
                .graphicsLayer {
                    scaleX = 1.09f
                    scaleY = 1.09f
                }
                .blur(22.dp, BlurredEdgeTreatment.Rectangle),
            contentDescription = null,
            fallback = {
                Box(
                    Modifier
                        .fillMaxSize()
                        .background(Brush.verticalGradient(0f to fallbackTop, 1f to fallbackBottom))
                )
            }
        )
        Box(
            Modifier
                .fillMaxSize()
                .background(
                    Brush.verticalGradient(
                        0f to Color(0x66102B34),
                        0.46f to Color(0x73101C23),
                        1f to Color(0xDC090F14)
                    )
                )
        )
    }
}

@Composable
private fun QueueReferenceCurrentTrack(
    track: Track,
    isFavorite: Boolean,
    onToggleFavorite: () -> Unit,
    onMore: () -> Unit
) {
    Row(
        modifier = Modifier.fillMaxWidth().padding(top = 10.dp, bottom = 8.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(14.dp)
    ) {
        CoverImage(track, Modifier.size(58.dp).clip(RoundedCornerShape(4.dp)))
        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
            Text(track.title, color = Color.White, fontSize = 17.sp, fontWeight = FontWeight.Black, maxLines = 1, overflow = TextOverflow.Ellipsis)
            Text(track.artist, color = Color.White.copy(alpha = 0.70f), fontSize = 14.sp, fontWeight = FontWeight.Medium, maxLines = 1, overflow = TextOverflow.Ellipsis)
        }
        QueueReferenceHeaderAction(if (isFavorite) Icons.Rounded.Star else Icons.Rounded.StarBorder, "Favorite", onToggleFavorite)
        QueueReferenceHeaderAction(Icons.Rounded.MoreVert, "More", onMore)
    }
}

@Composable
private fun QueueReferenceHeaderAction(icon: ImageVector, label: String, onClick: () -> Unit) {
    IconButton(onClick = onClick, modifier = Modifier.size(42.dp)) {
        Icon(icon, label, tint = Color.White, modifier = Modifier.size(29.dp))
    }
}

@Composable
private fun QueueReferenceModeControls(
    shuffleEnabled: Boolean,
    repeatMode: PlaybackRepeatMode,
    onSaveQueue: () -> Unit,
    onShuffle: () -> Unit,
    onRepeat: () -> Unit
) {
    Row(
        modifier = Modifier.fillMaxWidth().padding(top = 4.dp, bottom = 12.dp),
        horizontalArrangement = Arrangement.spacedBy(10.dp)
    ) {
        QueueReferenceModeButton(Icons.AutoMirrored.Rounded.PlaylistAdd, "Save queue", active = false, onClick = onSaveQueue, modifier = Modifier.weight(1f))
        QueueReferenceModeButton(Icons.Rounded.Shuffle, "Shuffle", active = shuffleEnabled, onClick = onShuffle, modifier = Modifier.weight(1f))
        QueueReferenceModeButton(if (repeatMode == PlaybackRepeatMode.One) Icons.Rounded.RepeatOne else Icons.Rounded.Repeat, "Repeat", active = repeatMode != PlaybackRepeatMode.Off, onClick = onRepeat, modifier = Modifier.weight(1f))
    }
}

@Composable
private fun QueueReferenceModeButton(icon: ImageVector, label: String, active: Boolean, onClick: () -> Unit, modifier: Modifier = Modifier) {
    Box(
        modifier = modifier
            .height(40.dp)
            .clip(RoundedCornerShape(20.dp))
            .background(if (active) Color.White.copy(alpha = 0.78f) else Color.White.copy(alpha = 0.17f))
            .derbisPressable(onClick = onClick, pressedScale = DerbisPressScale.Control, role = Role.Button, onClickLabel = label),
        contentAlignment = Alignment.Center
    ) {
        Icon(icon, label, tint = if (active) Color(0xFF12242A) else Color.White, modifier = Modifier.size(20.dp))
    }
}

@Composable
private fun QueueReferenceHeading(
    label: String,
    title: String,
    endlessLabel: String,
    endlessEnabled: Boolean,
    undoAvailable: Boolean,
    onToggleEndless: () -> Unit,
    onOpenJam: (() -> Unit)? = null,
    onUndo: () -> Unit
) {
    Row(
        modifier = Modifier.fillMaxWidth().padding(top = 12.dp, bottom = 14.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(3.dp)) {
            Text(label, color = Color.White.copy(alpha = 0.64f), fontSize = 13.sp, fontWeight = FontWeight.SemiBold)
            Text(title, color = Color.White, fontSize = 23.sp, lineHeight = 28.sp, fontWeight = FontWeight.Black, maxLines = 1, overflow = TextOverflow.Ellipsis)
        }
        if (onOpenJam != null) {
            Surface(
                shape = RoundedCornerShape(12.dp),
                color = Color.White.copy(alpha = 0.12f),
                border = BorderStroke(1.dp, Color.White.copy(alpha = 0.20f)),
                onClick = onOpenJam,
                modifier = Modifier.padding(end = 10.dp)
            ) {
                Row(
                    modifier = Modifier.padding(horizontal = 9.dp, vertical = 6.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(5.dp)
                ) {
                    Icon(
                        com.yasuda.derbis.ui.components.ModernListenTogetherVector,
                        contentDescription = "Listen Together",
                        tint = Color.White,
                        modifier = Modifier.size(15.dp)
                    )
                    Text(
                        "Listen Together",
                        color = Color.White,
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Bold
                    )
                }
            }
        }
        if (undoAvailable) {
            IconButton(onClick = onUndo) { Icon(Icons.AutoMirrored.Rounded.Undo, contentDescription = null, tint = Color.White) }
        }
        Column(horizontalAlignment = Alignment.End, verticalArrangement = Arrangement.spacedBy(5.dp)) {
            Text(endlessLabel, color = Color.White.copy(alpha = 0.70f), fontSize = 12.sp, fontWeight = FontWeight.Bold, maxLines = 1)
            Switch(
                checked = endlessEnabled,
                onCheckedChange = { onToggleEndless() },
                colors = SwitchDefaults.colors(
                    checkedThumbColor = Color(0xFF08212A),
                    checkedTrackColor = Color.White.copy(alpha = 0.86f),
                    uncheckedThumbColor = Color.White.copy(alpha = 0.72f),
                    uncheckedTrackColor = Color.Black.copy(alpha = 0.35f),
                    uncheckedBorderColor = Color.White.copy(alpha = 0.30f)
                )
            )
        }
    }
}

@Composable
private fun QueueReferencePlaybackRail(
    state: DerbisUiState,
    onPrevious: () -> Unit,
    onTogglePlay: () -> Unit,
    onNext: () -> Unit,
    onSeek: (Float) -> Unit,
    onSaveQueue: () -> Unit,
    onClose: () -> Unit,
    modifier: Modifier = Modifier
) {
    // Source-style fixed bottom cluster: it is below (not above) the sole LazyColumn, so the
    // list never leaks behind progress/time and the controls do not interfere with scrolling.
    Column(
        modifier = modifier
            .fillMaxWidth()
            .background(
                Brush.verticalGradient(
                    0f to Color.Transparent,
                    0.20f to Color(0x4210171B),
                    1f to Color(0xB0091014)
                )
            )
            .navigationBarsPadding()
            .padding(start = 26.dp, end = 26.dp, top = 8.dp, bottom = 8.dp),
        verticalArrangement = Arrangement.spacedBy(2.dp)
    ) {
        AppleMusicSeekbar(state.positionMs, state.bufferedPositionMs, state.durationMs, onSeek)
        Row(
            modifier = Modifier.fillMaxWidth().height(76.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.SpaceAround
        ) {
            IconButton(onClick = onPrevious, modifier = Modifier.size(58.dp)) {
                Icon(
                    Icons.Rounded.SkipPrevious,
                    contentDescription = "Previous",
                    tint = Color.White,
                    modifier = Modifier.size(40.dp)
                )
            }
            IconButton(onClick = onTogglePlay, modifier = Modifier.size(78.dp)) {
                Icon(
                    if (state.isPlaying) Icons.Rounded.Pause else Icons.Rounded.PlayArrow,
                    contentDescription = if (state.isPlaying) "Pause" else "Play",
                    tint = Color.White,
                    modifier = Modifier.size(58.dp)
                )
            }
            IconButton(onClick = onNext, modifier = Modifier.size(58.dp)) {
                Icon(
                    Icons.Rounded.SkipNext,
                    contentDescription = "Next",
                    tint = Color.White,
                    modifier = Modifier.size(40.dp)
                )
            }
        }
        PlayerOutputVolume(
            contentColor = Color.White,
            mutedColor = Color.White.copy(alpha = 0.72f),
            activeColor = Color.White,
            trackColor = Color.White.copy(alpha = 0.28f),
            condensed = true
        )
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceAround,
            verticalAlignment = Alignment.CenterVertically
        ) {
            CastRouteButton(modifier = Modifier.size(46.dp))
            QueueReferenceHeaderAction(Icons.AutoMirrored.Rounded.PlaylistAdd, "Save queue", onSaveQueue)
            QueueReferenceHeaderAction(Icons.Rounded.Close, "Close queue", onClose)
        }
    }
}

@Composable
private fun QueueSelectionBar(
    count: Int,
    allSelected: Boolean,
    canRemove: Boolean,
    onSelectAll: () -> Unit,
    onClear: () -> Unit,
    onAddToPlaylist: () -> Unit,
    onDownload: () -> Unit,
    onRemove: () -> Unit,
    modifier: Modifier = Modifier
) {
    val strings = LocalDerbisStrings.current
    Surface(
        color = DerbisPanel.copy(alpha = 0.98f),
        shape = RoundedCornerShape(24.dp),
        border = BorderStroke(1.dp, Color.White.copy(alpha = 0.12f)),
        shadowElevation = 14.dp,
        modifier = modifier.fillMaxWidth()
    ) {
        Column(modifier = Modifier.padding(horizontal = 10.dp, vertical = 8.dp)) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                IconButton(onClick = onClear) {
                    Icon(Icons.Rounded.Close, contentDescription = strings.clear, tint = DerbisText)
                }
                Text(
                    strings.formatTrackCount(count),
                    color = DerbisText,
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Black,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    modifier = Modifier.weight(1f)
                )
                TextButton(onClick = onSelectAll, enabled = !allSelected) {
                    Text(
                        strings.selectAll,
                        color = if (allSelected) DerbisMuted.copy(alpha = 0.35f) else DerbisCyan,
                        fontSize = 12.sp,
                        fontWeight = FontWeight.Bold,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                }
            }
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceEvenly,
                verticalAlignment = Alignment.CenterVertically
            ) {
                LibrarySelectionAction(
                    icon = Icons.AutoMirrored.Rounded.PlaylistAdd,
                    label = strings.addToPlaylist,
                    enabled = true,
                    onClick = onAddToPlaylist,
                    tint = DerbisText,
                    modifier = Modifier.weight(1f)
                )
                LibrarySelectionAction(
                    icon = Icons.Rounded.Download,
                    label = strings.offline,
                    enabled = true,
                    onClick = onDownload,
                    tint = DerbisText,
                    modifier = Modifier.weight(1f)
                )
                LibrarySelectionAction(
                    icon = Icons.Rounded.Delete,
                    label = strings.removeFromQueue,
                    enabled = canRemove,
                    onClick = onRemove,
                    tint = DerbisPink,
                    modifier = Modifier.weight(1f)
                )
            }
        }
    }
}

@Composable
private fun SmartMusicProfileCard(profile: SmartMusicProfile, onPlayFlow: () -> Unit) {
    val strings = LocalDerbisStrings.current
    val artists = profile.topArtists.take(3).joinToString(" • ") { it.label }
    val albums = profile.topAlbums.take(2).joinToString(" • ") { it.label.substringBefore(" • ") }
    Surface(
        color = Color.White.copy(alpha = 0.055f),
        border = BorderStroke(1.dp, Color.White.copy(alpha = 0.10f)),
        shape = RoundedCornerShape(28.dp),
        modifier = Modifier.fillMaxWidth()
    ) {
        Box {
            Box(
                modifier = Modifier
                    .matchParentSize()
                    .background(Brush.linearGradient(listOf(DerbisCyan.copy(alpha = 0.16f), DerbisViolet.copy(alpha = 0.10f), Color.Transparent)))
            )
            Column(modifier = Modifier.padding(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
                Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                    Box(
                        modifier = Modifier
                            .size(42.dp)
                            .clip(CircleShape)
                            .background(Brush.linearGradient(listOf(DerbisCyan, DerbisViolet))),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(Icons.Rounded.GraphicEq, null, tint = Color.White, modifier = Modifier.size(23.dp))
                    }
                    Column(modifier = Modifier.weight(1f)) {
                        Text(LocalDerbisStrings.current.smartMusicProfile, color = DerbisText, fontSize = 18.sp, fontWeight = FontWeight.Black, maxLines = 1, overflow = TextOverflow.Ellipsis)
                        Text(
                            if (profile.isWarm) strings.profileActive else strings.profileLearning,
                            color = DerbisMuted,
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                    }
                    Surface(
                        color = DerbisCyan.copy(alpha = 0.16f),
                        border = BorderStroke(1.dp, DerbisCyan.copy(alpha = 0.24f)),
                        shape = CircleShape,
                        modifier = Modifier.pressable(onClick = onPlayFlow)
                    ) {
                        Row(modifier = Modifier.padding(horizontal = 12.dp, vertical = 8.dp), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                            Icon(Icons.Rounded.PlayArrow, null, tint = DerbisCyan, modifier = Modifier.size(18.dp))
                            Text(LocalDerbisStrings.current.flow, color = DerbisCyan, fontSize = 12.sp, fontWeight = FontWeight.Black)
                        }
                    }
                }
                if (artists.isNotBlank()) {
                    Text(strings.formatArtists(artists), color = DerbisText.copy(alpha = 0.88f), fontSize = 13.sp, lineHeight = 18.sp, fontWeight = FontWeight.SemiBold, maxLines = 2, overflow = TextOverflow.Ellipsis)
                }
                if (albums.isNotBlank()) {
                    Text(strings.formatAlbumMood(albums), color = DerbisMuted, fontSize = 12.sp, lineHeight = 17.sp, fontWeight = FontWeight.SemiBold, maxLines = 2, overflow = TextOverflow.Ellipsis)
                }
            }
        }
    }
}

internal enum class LyricsViewMode {
    PAGE,
    CINEMA,
    COMPACT
}

@OptIn(ExperimentalLayoutApi::class, ExperimentalMaterial3Api::class)
@Composable
private fun LyricsOverlay(
    state: DerbisUiState,
    onTranslation: (Boolean) -> Unit,
    onLoadVersions: () -> Unit,
    onSelectVersion: (com.yasuda.derbis.data.LyricsRepository.LyricsVersion) -> Unit,
    onAutomatic: () -> Unit,
    onAdjustTrackOffset: (String, Long) -> Unit,
    onSetTrackOffset: (String, Long) -> Unit,
    onAdjustLatencyOffset: (String?, Boolean, Long) -> Unit,
    onClearLatencyOffset: (String) -> Unit,
    onSeekToMs: (Long) -> Unit,
    onPrevious: () -> Unit,
    onTogglePlay: () -> Unit,
    onNext: () -> Unit,
    onToggleFavorite: (Track) -> Unit = {},
    onOpenQueue: () -> Unit = {},
    onOpenLyricsStudio: () -> Unit = {},
    onUpdateLyricsStudioSettings: (DerbisLyricsStudioSettings) -> Unit = {},
    onClose: () -> Unit
) {
    val strings = LocalDerbisStrings.current
    val track = state.currentTrack
    val overlayConfiguration = LocalConfiguration.current
    val landscapeLayout = lyricsLandscapeLayoutActive(overlayConfiguration)
    val landscapeMetrics = if (landscapeLayout) {
        lyricsLandscapeMetrics(
            widthDp = overlayConfiguration.screenWidthDp.toFloat(),
            heightDp = overlayConfiguration.screenHeightDp.toFloat()
        )
    } else {
        null
    }
    LyricsImmersiveSystemBars(active = landscapeLayout)
    val accentStart = if (track != null) Color(track.accentStart) else DerbisCyan
    val accentEnd = if (track != null) Color(track.accentEnd) else DerbisViolet
    val listState = rememberLazyListState()
    val haptics = LocalDerbisHaptics.current
    val clipboard = LocalClipboard.current
    val clipboardScope = rememberCoroutineScope()
    val latencyProfiles = state.lyricsLatencyProfiles
    val audioOutputRoute = rememberLyricsAudioOutputRoute()
    val latencyOffsetMs = latencyProfiles.resolve(
        routeKey = audioOutputRoute?.stableKey,
        bluetooth = audioOutputRoute?.bluetooth == true
    )
    val trackLyricsOffsetMs = latencyProfiles.trackOffsetMs(track?.id)
    val lyricsOffsetMs = latencyOffsetMs + trackLyricsOffsetMs
    // The lyrics surface provides two modern choices: Default (Apple Music 13) and Spicy.
    val isSpicyLyrics = state.lyricsStudioSettings.isSpicyLyrics
    val appleMusic13Lyrics = !isSpicyLyrics
    var viewMode by remember(track?.id, appleMusic13Lyrics) { mutableStateOf(LyricsViewMode.CINEMA) }
    LaunchedEffect(appleMusic13Lyrics) {
        if (appleMusic13Lyrics) viewMode = LyricsViewMode.CINEMA
    }
    var showRomanization by rememberSaveable { mutableStateOf(true) }
    var showFurigana by rememberSaveable { mutableStateOf(true) }
    val showTranslation = state.lyricsTranslationEnabled
    val translationContext = LocalContext.current
    var awaitingTranslationLanguage by rememberSaveable { mutableStateOf(false) }
    var translationSettingsUnavailable by rememberSaveable { mutableStateOf(false) }
    LifecycleEventEffect(Lifecycle.Event.ON_RESUME) {
        if (awaitingTranslationLanguage) {
            awaitingTranslationLanguage = false
            if (state.lyricsTranslationEnabled) onTranslation(true)
        }
    }
    val feedbackState = when {
        !translationSettingsUnavailable -> state.lyricsTranslationState
        state.lyricsTranslationState == LyricsTranslationState.MODEL_DOWNLOAD_REQUIRED ||
            state.lyricsTranslationState == LyricsTranslationState.MODEL_DOWNLOADING -> LyricsTranslationState.UNAVAILABLE
        else -> state.lyricsTranslationState
    }
    val translationFeedback = if (showTranslation) lyricsTranslationFeedback(strings, feedbackState) else null
    val onTranslationFeedback: () -> Unit = {
        when (feedbackState) {
            LyricsTranslationState.PENDING -> Unit
            LyricsTranslationState.MODEL_DOWNLOAD_REQUIRED,
            LyricsTranslationState.MODEL_DOWNLOADING -> {
                awaitingTranslationLanguage = openTranslationLanguageSettings(translationContext)
                translationSettingsUnavailable = !awaitingTranslationLanguage
            }
            else -> onTranslation(true)
        }
    }
    var showSecondaryVoices by remember(track?.id) { mutableStateOf(true) }
    var autoScrollEnabled by remember(track?.id) { mutableStateOf(true) }
    val lyricsAnimationsEnabled = LocalAnimationsEnabled.current
    var lyricsFocusMode by remember(track?.id, appleMusic13Lyrics) {
        mutableStateOf(if (appleMusic13Lyrics) true else lyricsAnimationsEnabled)
    }
    var userScrollGeneration by remember { mutableIntStateOf(0) }
    var showLyricsOptions by remember(track?.id) { mutableStateOf(false) }
    var initialLyricsPositioned by remember(track?.id) { mutableStateOf(false) }
    var selectionMode by remember(track?.id) { mutableStateOf(false) }
    var selectedRange by remember(track?.id) { mutableStateOf<IntRange?>(null) }
    var shareSnapshot by remember(track?.id) { mutableStateOf<LyricsShareSnapshot?>(null) }
    var showVersions by remember(track?.id) { mutableStateOf(false) }
    var calibrateMode by remember(track?.id) { mutableStateOf(false) }
    var showSyncBar by rememberSaveable { mutableStateOf(false) }
    var showSyncSheet by remember(track?.id) { mutableStateOf(false) }
    val visibleLyrics = remember(state.lyrics, showSecondaryVoices) {
        if (showSecondaryVoices) {
            state.lyrics
        } else {
            state.lyrics.filter { line -> line.role == LyricVocalRole.MAIN }
        }
    }
    LaunchedEffect(state.lyrics, showSecondaryVoices) {
        selectedRange = null
        selectionMode = false
    }
    val selectedLines = remember(visibleLyrics, selectedRange) {
        lyricsShareSelectedLines(selectedRange, visibleLyrics)
    }
    fun selectedLyricsText(): String = selectedLines.joinToString("\n") { line ->
        buildString {
            append(line.text)
            if (showTranslation && line.translated.isNotBlank()) append("\n").append(line.translated)
        }
    }
    val syncedLyrics = state.lyricsSynced
    val lyricsClock = rememberLyricsPlaybackClock(
        trackKey = track?.id.orEmpty(),
        reportedPositionMs = state.positionMs,
        isPlaying = state.isPlaying,
        speed = state.audioSettings.playbackSpeed,
        smoothingEnabled = syncedLyrics && lyricsAnimationsEnabled
    )
    val currentLyricsOffsetMs by rememberUpdatedState(lyricsOffsetMs)
    val lyricsPositionProvider: () -> Long = remember(lyricsClock) {
        { lyricsOffsetPosition(lyricsClock.positionMs, currentLyricsOffsetMs) }
    }
    val backgroundLineIndices = remember(visibleLyrics) {
        visibleLyrics.withIndex()
            .filter { (_, line) -> line.role == LyricVocalRole.BACKGROUND }
            .map { (index, _) -> index }
    }
    val timedActiveIndex = remember(visibleLyrics, syncedLyrics, lyricsPositionProvider) {
        derivedStateOf {
            if (syncedLyrics) activeLyricIndex(lyricsPositionProvider(), visibleLyrics) else -1
        }
    }.value
    val canShareLyrics = remember(visibleLyrics) { visibleLyrics.any(::isLyricsShareSelectable) }
    fun toggleShareMode() {
        selectionMode = !selectionMode
        if (selectionMode) {
            calibrateMode = false
            selectedRange = timedActiveIndex
                .takeIf { syncedLyrics && it >= 0 }
                ?.let { toggleLyricsShareSelection(null, it, visibleLyrics) }
        } else {
            selectedRange = null
        }
    }
    val visualActiveIndex = remember(visibleLyrics, syncedLyrics, lyricsAnimationsEnabled, lyricsPositionProvider) {
        derivedStateOf {
            if (syncedLyrics) {
                activeLyricIndex(
                    lyricsLineFocusPositionMs(lyricsPositionProvider(), lyricsAnimationsEnabled),
                    visibleLyrics
                )
            } else {
                -1
            }
        }
    }.value
    val backgroundActiveIndex = remember(visibleLyrics, backgroundLineIndices, syncedLyrics, lyricsPositionProvider) {
        derivedStateOf {
            if (!syncedLyrics || backgroundLineIndices.isEmpty()) {
                -1
            } else {
                val position = lyricsPositionProvider()
                backgroundLineIndices.firstOrNull { index ->
                    val line = visibleLyrics[index]
                    position >= line.startMs && position <= line.endMs
                } ?: -1
            }
        }
    }.value
    val instrumentalGaps = remember(visibleLyrics, syncedLyrics) {
        lyricsInstrumentalGaps(visibleLyrics, syncedLyrics)
    }
    val instrumentalGap = remember(instrumentalGaps, lyricsPositionProvider) {
        derivedStateOf { activeLyricsInstrumentalGap(lyricsPositionProvider(), instrumentalGaps) }
    }.value
    val lyricsStartIndex = 3
    val hasRomanization = state.lyrics.any { it.romanized.isNotBlank() || it.words.any { word -> word.romanized.isNotBlank() } }
    val hasFurigana = remember(state.lyrics) { state.lyrics.any { KanjiFurigana.containsKanji(it.text) } }
    val hasMultipleVoices = state.lyrics.any { it.role != LyricVocalRole.MAIN }
    val sectionStarts = remember(state.lyricsSections, visibleLyrics) {
        val mapped = LinkedHashMap<Int, LyricSection>()
        state.lyricsSections.forEach { section ->
            val exactIndex = visibleLyrics.indexOfFirst { line ->
                line.role != LyricVocalRole.BACKGROUND && line.startMs >= section.startMs
            }
            val fallbackIndex = visibleLyrics.indexOfLast { line ->
                line.role != LyricVocalRole.BACKGROUND && line.startMs <= section.startMs
            }
            val index = if (exactIndex >= 0) exactIndex else fallbackIndex
            if (index >= 0 && mapped[index] == null) mapped[index] = section
        }
        mapped
    }
    val activeSection = remember(state.lyricsSections, lyricsPositionProvider) {
        derivedStateOf {
            val position = lyricsPositionProvider()
            state.lyricsSections.lastOrNull { section -> position >= section.startMs }
        }
    }.value
    val chorusPhrase = state.intelligenceSummary.repeatedPhrases.firstOrNull()
    val chorusIndex = remember(visibleLyrics, chorusPhrase, state.lyricsSections) {
        val sectionStart = state.lyricsSections.firstOrNull { it.type == LyricSectionType.CHORUS }?.startMs
        if (sectionStart != null) {
            visibleLyrics.indexOfFirst { line -> line.role != LyricVocalRole.BACKGROUND && line.startMs >= sectionStart }
        } else if (chorusPhrase.isNullOrBlank()) {
            -1
        } else {
            visibleLyrics.indexOfFirst { line -> line.text.contains(chorusPhrase, ignoreCase = true) }
        }
    }
    var requestedLyricIndex by remember { mutableStateOf<Int?>(null) }
    var showIntelligenceDialog by remember(track?.id) { mutableStateOf(false) }
    val anchorFraction = when (viewMode) {
        LyricsViewMode.CINEMA -> 0.36f
        LyricsViewMode.PAGE -> 0.42f
        LyricsViewMode.COMPACT -> 0.50f
    }

    val userScrollConnection = remember {
        object : NestedScrollConnection {
            override fun onPostScroll(consumed: Offset, available: Offset, source: NestedScrollSource): Offset {
                if (source == NestedScrollSource.UserInput) {
                    autoScrollEnabled = false
                    userScrollGeneration++
                }
                return Offset.Zero
            }

            override suspend fun onPostFling(consumed: Velocity, available: Velocity): Velocity {
                userScrollGeneration++
                return Velocity.Zero
            }
        }
    }

    LaunchedEffect(userScrollGeneration, listState.isScrollInProgress, selectionMode) {
        if (!autoScrollEnabled && !listState.isScrollInProgress && !selectionMode) {
            delay(LYRICS_AUTO_SCROLL_RESUME_MS)
            autoScrollEnabled = true
        }
    }

    val scrollFocusIndex = instrumentalGap?.nextLineIndex ?: visualActiveIndex

    val followActiveLine = lyricsShouldFollowActiveLine(autoScrollEnabled, selectionMode)

    LaunchedEffect(scrollFocusIndex, lyricsStartIndex, followActiveLine, viewMode, visibleLyrics.size, landscapeLayout) {
        if (scrollFocusIndex >= 0 && followActiveLine) {
            runCatching {
                val targetIndex = lyricsStartIndex + scrollFocusIndex
                val targetVisible = listState.layoutInfo.visibleItemsInfo.any { it.index == targetIndex }
                centerLyricsItem(
                    listState = listState,
                    index = targetIndex,
                    animate = lyricsAnimationsEnabled && initialLyricsPositioned && targetVisible,
                    anchorFraction = anchorFraction
                )
                initialLyricsPositioned = true
            }
        }
    }

    LaunchedEffect(requestedLyricIndex, lyricsStartIndex, viewMode) {
        val requested = requestedLyricIndex ?: return@LaunchedEffect
        runCatching {
            centerLyricsItem(
                listState = listState,
                index = lyricsStartIndex + requested,
                animate = lyricsAnimationsEnabled,
                anchorFraction = anchorFraction
            )
        }
        requestedLyricIndex = null
    }

    // Lyrics own the whole page already; fullscreen only strips the transport chrome and pushes
    // the progress strip to the very bottom edge. Nothing changes until the button is pressed.
    var lyricsFullscreen by rememberSaveable { mutableStateOf(false) }
    androidx.activity.compose.BackHandler(enabled = lyricsFullscreen) { lyricsFullscreen = false }

    val lyricsActionRow: @Composable (Modifier, Boolean) -> Unit = { rowModifier, includeClose ->
        Row(
            modifier = rowModifier,
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            Box(modifier = Modifier.weight(1f)) {
                if (translationFeedback != null && visibleLyrics.isNotEmpty()) {
                    LyricsTranslationStatus(
                        label = translationFeedback,
                        working = state.lyricsTranslationState == LyricsTranslationState.PENDING,
                        onClick = onTranslationFeedback
                    )
                } else if (visibleLyrics.isNotEmpty() && viewMode != LyricsViewMode.COMPACT) {
                    LyricsSyncStatus(
                        synced = state.lyricsSynced,
                        syncedLabel = strings.lyricsSyncedStatus,
                        unsyncedLabel = strings.lyricsUnsyncedStatus
                    )
                } else if (activeSection != null) {
                    Text(
                        text = lyricSectionLabel(strings, activeSection),
                        color = accentEnd.copy(alpha = 0.90f),
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Black,
                        letterSpacing = 0.7.sp,
                        maxLines = 1
                    )
                }
            }
            if (canShareLyrics) {
                CircleIconButton(
                    icon = Icons.Rounded.Share,
                    tint = if (selectionMode) DerbisCyan else Color.White,
                    background = if (selectionMode) DerbisCyan.copy(alpha = 0.22f) else Color.White.copy(alpha = 0.10f),
                    onClick = { toggleShareMode() },
                    contentDescription = strings.shareLyrics
                )
            }
            if (state.lyricsSynced && track != null) {
                val syncActive = showSyncBar || trackLyricsOffsetMs != 0L
                CircleIconButton(
                    icon = Icons.Rounded.Timer,
                    tint = if (syncActive) DerbisCyan else Color.White,
                    background = if (syncActive) DerbisCyan.copy(alpha = 0.22f) else Color.White.copy(alpha = 0.10f),
                    onClick = { showSyncBar = !showSyncBar },
                    contentDescription = lyricsSyncCopy(strings.code).title
                )
            }
            CircleIconButton(
                icon = Icons.Rounded.Tune,
                tint = if (calibrateMode) DerbisCyan else Color.White,
                background = if (calibrateMode) DerbisCyan.copy(alpha = 0.22f) else Color.White.copy(alpha = 0.10f),
                onClick = { showLyricsOptions = true },
                contentDescription = strings.options
            )
            CircleIconButton(
                icon = if (lyricsFullscreen) Icons.Rounded.CloseFullscreen else Icons.Rounded.Fullscreen,
                tint = if (lyricsFullscreen) DerbisCyan else Color.White,
                background = if (lyricsFullscreen) {
                    DerbisCyan.copy(alpha = 0.22f)
                } else {
                    Color.White.copy(alpha = 0.10f)
                },
                onClick = { lyricsFullscreen = !lyricsFullscreen },
                contentDescription = if (lyricsFullscreen) strings.collapsePlayer else strings.expandPlayer
            )
            if (includeClose) {
                CircleIconButton(
                    icon = Icons.Rounded.Close,
                    tint = Color.White,
                    background = Color.White.copy(alpha = 0.13f),
                    onClick = onClose,
                    contentDescription = strings.closeLyrics
                )
            }
        }
    }

    if (isSpicyLyrics && !landscapeLayout) {
        SpicyFullscreenLyrics(
            state = state,
            accentStart = accentStart,
            accentEnd = accentEnd,
            onSeekToMs = onSeekToMs,
            onPrevious = onPrevious,
            onTogglePlay = onTogglePlay,
            onNext = onNext,
            onToggleFavorite = onToggleFavorite,
            onShareLyrics = { selectedLines ->
                shareSnapshot = lyricsShareSnapshot(track, selectedLines)
            },
            onOpenQueue = onOpenQueue,
            onOpenOptions = { showLyricsOptions = true },
            lyricsOffsetMs = lyricsOffsetMs,
            showTranslation = showTranslation,
            showRomanization = showRomanization,
            showFurigana = showFurigana,
            calibrateMode = calibrateMode,
            onCalibrateLine = { lineStartMs ->
                track?.id?.let { trackId ->
                    onSetTrackOffset(
                        trackId,
                        calibratedLyricsTrackOffset(state.positionMs, lineStartMs, latencyOffsetMs)
                    )
                }
                calibrateMode = false
            }
        )
    } else {
        AppleMusic13FullscreenLyrics(
            state = state,
            accentStart = accentStart,
            accentEnd = accentEnd,
            fullscreen = lyricsFullscreen,
            onSeekToMs = onSeekToMs,
            onPrevious = onPrevious,
            onTogglePlay = onTogglePlay,
            onNext = onNext,
            onToggleFavorite = onToggleFavorite,
            onShareLyrics = { selectedLines ->
                shareSnapshot = lyricsShareSnapshot(track, selectedLines)
            },
            onOpenQueue = onOpenQueue,
            onOpenOptions = { showLyricsOptions = true },
            lyricsOffsetMs = lyricsOffsetMs,
            showTranslation = showTranslation,
            showRomanization = showRomanization,
            showFurigana = showFurigana,
            calibrateMode = calibrateMode,
            onCalibrateLine = { lineStartMs ->
                track?.id?.let { trackId ->
                    onSetTrackOffset(
                        trackId,
                        calibratedLyricsTrackOffset(state.positionMs, lineStartMs, latencyOffsetMs)
                    )
                }
                calibrateMode = false
            }
        )
    }

    if (showIntelligenceDialog) {
        LyricsIntelligenceDialog(
            summary = state.intelligenceSummary,
            onDismiss = { showIntelligenceDialog = false },
            onJumpToChorus = if (chorusIndex >= 0) {
                {
                    showIntelligenceDialog = false
                    requestedLyricIndex = chorusIndex
                    val chorusStartMs = visibleLyrics.getOrNull(chorusIndex)?.startMs ?: 0L
                    if (state.lyricsSynced) onSeekToMs((chorusStartMs + lyricsOffsetMs).coerceAtLeast(0L))
                }
            } else {
                null
            }
        )
    }
    if (showLyricsOptions) {
        ModalBottomSheet(
            onDismissRequest = { showLyricsOptions = false },
            sheetState = rememberBottomSheetState(
                initialValue = SheetValue.Hidden,
                enabledValues = setOf(SheetValue.Hidden, SheetValue.Expanded)
            )
        ) {
            Text(
                text = strings.options,
                color = DerbisText,
                fontSize = 20.sp,
                fontWeight = FontWeight.Black,
                modifier = Modifier.padding(horizontal = 20.dp)
            )
            lyricsProviderDisplayName(state.lyricsProvider).takeIf(String::isNotBlank)?.let { source ->
                Text(
                    text = "${strings.lyricsSource} · $source",
                    color = DerbisMuted,
                    fontSize = 12.sp,
                    fontWeight = FontWeight.SemiBold,
                    modifier = Modifier.padding(start = 20.dp, end = 20.dp, top = 2.dp)
                )
            }
            FlowRow(
                modifier = Modifier
                    .fillMaxWidth()
                    .navigationBarsPadding()
                    .padding(horizontal = 20.dp, vertical = 16.dp),
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                verticalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                LyricsControlChip(
                    label = strings.lyricsRendererDefault,
                    selected = !isSpicyLyrics,
                    icon = Icons.Rounded.MusicNote,
                    onClick = {
                        onUpdateLyricsStudioSettings(
                            state.lyricsStudioSettings.withRendererMode(LyricsRendererMode.DEFAULT)
                        )
                    }
                )
                LyricsControlChip(
                    label = strings.lyricsRendererSpicy,
                    selected = isSpicyLyrics,
                    icon = Icons.Rounded.Whatshot,
                    onClick = {
                        onUpdateLyricsStudioSettings(
                            state.lyricsStudioSettings.withRendererMode(LyricsRendererMode.SPICY)
                        )
                    }
                )
                LyricsControlChip(
                    label = strings.lyricsStudio,
                    selected = false,
                    icon = Icons.Rounded.AutoAwesome,
                    onClick = {
                        showLyricsOptions = false
                        onOpenLyricsStudio()
                    }
                )
                val translationLabel = when (state.lyricsTranslationState) {
                    LyricsTranslationState.ON_DEVICE -> "${strings.automaticTranslation} · ${strings.offline}"
                    LyricsTranslationState.MODEL_DOWNLOAD_REQUIRED -> "${strings.automaticTranslation} · ${strings.download}"
                    LyricsTranslationState.MODEL_DOWNLOADING -> "${strings.automaticTranslation} · ${strings.updateDownloading}"
                    LyricsTranslationState.UNAVAILABLE,
                    LyricsTranslationState.FAILED,
                    LyricsTranslationState.DISABLED,
                    LyricsTranslationState.PENDING,
                    LyricsTranslationState.PROVIDER,
                    LyricsTranslationState.SAME_LANGUAGE -> strings.automaticTranslation
                }
                LyricsControlChip(
                    label = translationLabel,
                    selected = state.lyricsTranslationEnabled,
                    icon = Icons.Rounded.Translate,
                    onClick = { onTranslation(!state.lyricsTranslationEnabled) }
                )
                LyricsControlChip(
                    label = strings.changeLyrics,
                    selected = state.lyricsManualSelection,
                    icon = Icons.Rounded.LibraryMusic,
                    onClick = {
                        showLyricsOptions = false
                        showVersions = true
                        onLoadVersions()
                    }
                )
                if (state.lyricsSynced) {
                    LyricsControlChip(
                        label = strings.lyricsCalibrate,
                        selected = calibrateMode,
                        icon = Icons.Rounded.Schedule,
                        onClick = {
                            calibrateMode = !calibrateMode
                            if (calibrateMode) {
                                selectionMode = false
                                selectedRange = null
                                showLyricsOptions = false
                            }
                        }
                    )
                }
                if (hasRomanization) {
                    LyricsControlChip(
                        label = strings.lyricsRomanization,
                        selected = showRomanization,
                        icon = Icons.Rounded.Language,
                        onClick = { showRomanization = !showRomanization }
                    )
                }
                if (hasFurigana) {
                    LyricsControlChip(
                        label = strings.lyricsFurigana,
                        selected = showFurigana,
                        icon = DerbisIonicons.Lyrics,
                        onClick = { showFurigana = !showFurigana }
                    )
                }
                if (hasMultipleVoices) {
                    LyricsControlChip(
                        label = strings.lyricsDuet,
                        selected = showSecondaryVoices,
                        icon = Icons.Rounded.GraphicEq,
                        onClick = { showSecondaryVoices = !showSecondaryVoices }
                    )
                }
                if (state.intelligenceSummary.available) {
                    LyricsControlChip(
                        label = strings.lyricsAnalysis,
                        selected = false,
                        icon = Icons.Rounded.Insights,
                        onClick = {
                            showLyricsOptions = false
                            showIntelligenceDialog = true
                        }
                    )
                }
                if (state.lyricsSynced && track != null) {
                    LyricsControlChip(
                        label = "${lyricsSyncCopy(strings.code).title} · ${lyricsOffsetIsolated(trackLyricsOffsetMs)}",
                        selected = trackLyricsOffsetMs != 0L,
                        icon = Icons.Rounded.Timer,
                        onClick = {
                            showLyricsOptions = false
                            showSyncSheet = true
                        }
                    )
                }
            }
        }
    }
    if (showSyncSheet && track != null) {
        val bluetoothRoute = audioOutputRoute?.takeIf { route -> route.bluetooth && route.stableKey != null }
        val deviceProfileKey = bluetoothRoute?.stableKey?.takeIf(latencyProfiles.deviceOffsetsMs::containsKey)
        LyricsSyncSheet(
            trackOffsetMs = trackLyricsOffsetMs,
            latencyOffsetMs = latencyOffsetMs,
            latencyDeviceName = bluetoothRoute?.displayName?.ifBlank { strings.connected },
            latencyResettable = latencyOffsetMs != 0L,
            onAdjustTrack = { delta -> onAdjustTrackOffset(track.id, delta) },
            onSetTrack = { value -> onSetTrackOffset(track.id, value) },
            onAdjustLatency = { delta ->
                onAdjustLatencyOffset(audioOutputRoute?.stableKey, audioOutputRoute?.bluetooth == true, delta)
            },
            onResetLatency = {
                if (deviceProfileKey != null && latencyProfiles.globalOffsetMs == 0L) {
                    onClearLatencyOffset(deviceProfileKey)
                } else {
                    onAdjustLatencyOffset(audioOutputRoute?.stableKey, audioOutputRoute?.bluetooth == true, -latencyOffsetMs)
                }
            },
            onDismiss = { showSyncSheet = false }
        )
    }
    shareSnapshot?.let { snapshot ->
        LyricsShareSheet(
            snapshot = snapshot,
            onDismiss = { shareSnapshot = null }
        )
    }
    if (showVersions) {
        LyricsVersionDialog(
            versions = state.lyricsVersions,
            loading = state.lyricsVersionsLoading,
            strings = strings,
            onAutomatic = {
                showVersions = false
                onAutomatic()
            },
            onSelect = { version ->
                showVersions = false
                onSelectVersion(version)
            },
            onDismiss = { showVersions = false }
        )
    }
}

/**
 * Derbis' full-screen Apple Music 13 lyrics surface. It keeps Derbis' own seek, calibration,
 * sharing and discrete word-timed renderer while prioritising a compact header, a readable
 * scrolling lyric page and auto-hiding utilities.
 */
@Composable
private fun AppleMusic13FullscreenLyrics(
    state: DerbisUiState,
    accentStart: Color,
    accentEnd: Color,
    fullscreen: Boolean = false,
    onSeekToMs: (Long) -> Unit,
    onPrevious: () -> Unit,
    onTogglePlay: () -> Unit,
    onNext: () -> Unit,
    onToggleFavorite: (Track) -> Unit,
    onShareLyrics: (List<LyricLine>) -> Unit,
    onOpenQueue: () -> Unit,
    onOpenOptions: () -> Unit,
    lyricsOffsetMs: Long,
    showTranslation: Boolean,
    showRomanization: Boolean,
    showFurigana: Boolean = true,
    calibrateMode: Boolean,
    onCalibrateLine: (Long) -> Unit
) {
    val strings = LocalDerbisStrings.current
    val track = state.currentTrack
    val lyrics = state.lyrics
    val listState = rememberLazyListState()
    val clock = rememberLyricsPlaybackClock(
        trackKey = track?.id.orEmpty(),
        reportedPositionMs = state.positionMs,
        isPlaying = state.isPlaying,
        speed = state.audioSettings.playbackSpeed,
        smoothingEnabled = state.lyricsSynced && state.animationsEnabled
    )
    // The playback clock advances every frame for word timing.  Deriving this index means the
    // surrounding header/list only recompose when the active LINE changes, not at display refresh
    // rate; the active line still receives the smooth clock inside its own word renderer.
    val latestLyricsOffsetMs by rememberUpdatedState(lyricsOffsetMs)
    val activeIndex by remember(lyrics, state.lyricsSynced, clock) {
        derivedStateOf {
            if (state.lyricsSynced) {
                activeLyricIndex(lyricsOffsetPosition(clock.positionMs, latestLyricsOffsetMs), lyrics)
            } else {
                -1
            }
        }
    }
    val lyricPositionProvider: () -> Long = remember(clock) {
        { lyricsOffsetPosition(clock.positionMs, latestLyricsOffsetMs) }
    }
    LaunchedEffect(activeIndex, lyrics.size) {
        if (activeIndex >= 0 && lyrics.isNotEmpty()) {
            centerLyricsItem(
                listState = listState,
                index = activeIndex,
                animate = state.animationsEnabled,
                anchorFraction = 0.36f
            )
        }
    }

    // Let the lyrics reclaim the player controls' space after a short idle period. Any tap,
    // lyric seek, or scroll brings the cluster back and resets the same timer.
    var showCluster by rememberSaveable(track?.id) { mutableStateOf(true) }
    var interactionTick by remember(track?.id) { mutableIntStateOf(0) }
    LaunchedEffect(showCluster, interactionTick) {
        if (showCluster) {
            delay(8_000L)
            showCluster = false
        }
    }
    val wakeCluster: () -> Unit = {
        showCluster = true
        interactionTick++
    }
    val scrollWakesCluster = remember {
        object : NestedScrollConnection {
            override fun onPreScroll(available: Offset, source: NestedScrollSource): Offset {
                if (available.y != 0f) wakeCluster()
                return Offset.Zero
            }
        }
    }

    var dragProgress by remember(track?.id) { mutableStateOf<Float?>(null) }
    val progress = if (state.durationMs > 0L) {
        (state.positionMs.toFloat() / state.durationMs.toFloat()).coerceIn(0f, 1f)
    } else {
        0f
    }
    val shownProgress = dragProgress ?: progress
    val shownPosition = (state.durationMs * shownProgress).toLong()

    // Image sharing in this variant is intentionally a lyric-line selection action, not a
    // generic track-share shortcut. The same model limits the card to five selectable verses.
    var imageShareSelectionMode by rememberSaveable(track?.id) { mutableStateOf(false) }
    var imageShareRange by remember(track?.id, lyrics) { mutableStateOf<IntRange?>(null) }
    val selectedImageShareLines = remember(lyrics, imageShareRange) {
        lyricsShareSelectedLines(imageShareRange, lyrics)
    }
    fun beginImageShareSelection() {
        imageShareSelectionMode = true
        imageShareRange = activeIndex
            .takeIf { index -> lyrics.getOrNull(index)?.let(::isLyricsShareSelectable) == true }
            ?.let { index -> toggleLyricsShareSelection(null, index, lyrics) }
    }

    MaterialTheme(
        colorScheme = MaterialTheme.colorScheme,
        typography = AppleMusic13Typography,
        shapes = MaterialTheme.shapes
    ) {
        Box(Modifier.fillMaxSize().consumeOverlayTouches()) {
        if (imageShareSelectionMode) {
            // A dedicated selection surface keeps image-card choices separate from live lyrics.
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(top = 62.dp)
                    .clip(RoundedCornerShape(topStart = 42.dp, topEnd = 42.dp))
                    .background(
                        Brush.verticalGradient(
                            0f to Color(0xFF0087A6),
                            0.52f to Color(0xFF00596A),
                            1f to Color(0xFF001317)
                        )
                    )
            )
        } else {
            AppleMusic13LyricsArtworkBackdrop(
                track = track,
                accentStart = accentStart,
                accentEnd = accentEnd
            )
        }

        Column(
            modifier = Modifier
                .fillMaxSize()
                .statusBarsPadding()
                .navigationBarsPadding()
                .padding(top = if (imageShareSelectionMode) 52.dp else 0.dp)
        ) {
            if (imageShareSelectionMode) {
                ImageLyricsSelectionHeader(
                    title = strings.selectVerses,
                    selectedCount = selectedImageShareLines.size,
                    linesLabel = strings.linesLabel,
                    selectedLabel = strings.shareLyricsLineSelected,
                    onClose = {
                        imageShareSelectionMode = false
                        imageShareRange = null
                    }
                )
            } else {
                // A compact record header keeps the music identifiable while lyrics take the
                // page rather than being framed as a separate dialog.
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(start = 20.dp, end = 12.dp, top = 14.dp, bottom = 10.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    if (track != null) {
                        AsyncImage(
                            model = track.largeThumbnailUrl.ifBlank { track.thumbnailUrl },
                            contentDescription = null,
                            contentScale = ContentScale.Crop,
                            modifier = Modifier
                                .size(55.dp)
                                .clip(RoundedCornerShape(4.dp))
                        )
                    }
                    Column(Modifier.weight(1f)) {
                        Text(
                            text = track?.title ?: strings.lyrics,
                            color = Color.White,
                            style = AppleMusic13Typography.titleMedium.copy(
                                fontFamily = AppleMusic13SfProFallbackFont,
                                fontSize = 18.sp,
                                fontWeight = FontWeight.ExtraBold
                            ),
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                        Text(
                            text = track?.artist.orEmpty(),
                            color = Color.White.copy(alpha = 0.70f),
                            style = AppleMusic13Typography.bodyMedium.copy(
                                fontFamily = AppleMusic13SfProFallbackFont,
                                fontSize = 14.sp,
                                fontWeight = FontWeight.Medium
                            ),
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                    }
                    IconButton(
                        onClick = {
                            wakeCluster()
                            track?.let(onToggleFavorite)
                        },
                        enabled = track != null
                    ) {
                        Icon(
                            imageVector = if (track?.id in state.favoriteIds) Icons.Rounded.Favorite else Icons.Rounded.FavoriteBorder,
                            contentDescription = strings.favorite,
                            tint = Color.White,
                            modifier = Modifier.size(24.dp)
                        )
                    }
                    IconButton(onClick = { wakeCluster(); onOpenOptions() }) {
                        Icon(Icons.Rounded.MoreVert, contentDescription = strings.options, tint = Color.White, modifier = Modifier.size(25.dp))
                    }
                }
            }

            Box(
                modifier = Modifier
                    .weight(1f)
                    .fillMaxWidth()
                    .nestedScroll(scrollWakesCluster)
                    // Lyric lines consume taps to seek. This page-level gesture remains for the
                    // gutters and whitespace.
                    .clickable(
                        indication = null,
                        interactionSource = remember { MutableInteractionSource() }
                    ) {
                        showCluster = !showCluster
                        interactionTick++
                    }
            ) {
                LazyColumn(
                    state = listState,
                    modifier = Modifier.fillMaxSize(),
                    contentPadding = PaddingValues(
                        start = 24.dp,
                        end = 24.dp,
                        top = if (imageShareSelectionMode) 22.dp else 38.dp,
                        bottom = if (imageShareSelectionMode) 104.dp else 34.dp
                    ),
                    verticalArrangement = Arrangement.spacedBy(if (imageShareSelectionMode) 16.dp else 26.dp)
                ) {
                    if (lyrics.isEmpty()) {
                        item {
                            Text(
                                text = if (state.lyricsLoading) strings.searchingLyrics else strings.lyricsUnavailable,
                                color = Color.White.copy(alpha = 0.58f),
                                style = AppleMusic13Typography.titleLarge.copy(fontWeight = FontWeight.ExtraBold)
                            )
                        }
                    } else {
                        itemsIndexed(lyrics, key = { index, line -> "apple-lyrics-${line.startMs}-${line.role}-$index" }) { index, line ->
                            // Image lyric selection is deliberately static: it is a separate share-card
                            // flow, never a second live-lyrics renderer competing with the timed view.
                            val liveLyricActive = !imageShareSelectionMode && index == activeIndex
                            val imageShareSelected = imageShareRange?.contains(index) == true && isLyricsShareSelectable(line)
                            val imageSelectionActive = imageShareSelectionMode && imageShareSelected
                            val lyricLineBlur = if (!imageShareSelectionMode && !liveLyricActive) 2.dp else 0.dp
                            val lineColor by animateColorAsState(
                                targetValue = when {
                                    imageSelectionActive -> Color(0xFF102026)
                                    liveLyricActive -> Color.White
                                    else -> Color.White.copy(alpha = 0.52f)
                                },
                                animationSpec = tween(if (state.animationsEnabled) 180 else 0),
                                label = "simp-lyrics-line-color"
                            )
                            val lineScale by animateFloatAsState(
                                targetValue = if (liveLyricActive) 1f else 0.94f,
                                animationSpec = tween(if (state.animationsEnabled) 180 else 0),
                                label = "simp-lyrics-line-scale"
                            )
                            Column(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .graphicsLayer {
                                        scaleX = lineScale
                                        scaleY = lineScale
                                        transformOrigin = TransformOrigin(0f, 0.5f)
                                    }
                                    .blur(lyricLineBlur)
                                    .clip(RoundedCornerShape(if (imageShareSelectionMode) 14.dp else 16.dp))
                                    .background(
                                        if (imageSelectionActive) Color.White else Color.Transparent
                                    )
                                    .clickable(enabled = state.lyricsSynced || imageShareSelectionMode) {
                                        wakeCluster()
                                        when {
                                            imageShareSelectionMode -> {
                                                if (isLyricsShareSelectable(line)) {
                                                    imageShareRange = toggleLyricsShareSelection(imageShareRange, index, lyrics)
                                                }
                                            }
                                            calibrateMode -> onCalibrateLine(line.startMs)
                                            else -> onSeekToMs((line.startMs + lyricsOffsetMs).coerceAtLeast(0L))
                                        }
                                    }
                                    .padding(horizontal = 10.dp, vertical = 8.dp)
                            ) {
                                // Full lines, not individual words, follow the sync clock: the current
                                // line is bright white while surrounding lyrics stay monochrome and blurred.
                                val hasKanji = remember(line.text) { KanjiFurigana.containsKanji(line.text) }
                                if (showFurigana && hasKanji) {
                                    FuriganaRubyLine(
                                        lineText = line.text,
                                        baseColor = lineColor,
                                        rubyColor = lineColor.copy(alpha = 0.85f),
                                        fontSize = 31.sp,
                                        lineHeight = 38.sp,
                                        fontWeight = FontWeight.ExtraBold,
                                        fontFamily = AppleMusic13SfProFallbackFont
                                    )
                                } else {
                                    Text(
                                        text = line.text,
                                        color = lineColor,
                                        style = AppleMusic13Typography.headlineLarge.copy(
                                            fontFamily = AppleMusic13SfProFallbackFont,
                                            fontSize = 31.sp,
                                            lineHeight = 38.sp,
                                            fontWeight = FontWeight.ExtraBold
                                        )
                                    )
                                }
                                if (showRomanization && line.romanized.isNotBlank()) {
                                    Text(
                                        text = line.romanized,
                                        color = lineColor.copy(alpha = 0.72f),
                                        style = AppleMusic13Typography.bodyLarge.copy(
                                            fontFamily = AppleMusic13SfProFallbackFont,
                                            fontSize = 17.sp,
                                            lineHeight = 22.sp,
                                            fontWeight = FontWeight.Medium
                                        ),
                                        modifier = Modifier.padding(top = 3.dp)
                                    )
                                }
                                if (showTranslation && line.translated.isNotBlank()) {
                                    Text(
                                        text = line.translated,
                                        color = lineColor.copy(alpha = 0.82f),
                                        style = AppleMusic13Typography.bodyLarge.copy(
                                            fontFamily = AppleMusic13SfProFallbackFont,
                                            fontSize = 18.sp,
                                            lineHeight = 23.sp,
                                            fontWeight = FontWeight.Medium
                                        ),
                                        modifier = Modifier.padding(top = 5.dp)
                                    )
                                }
                            }
                        }
                    }
                }

                // No black edge or control gradient is layered over the artwork. The lyric list
                // meets the compact header and transport directly so cover colors stay continuous.

                androidx.compose.animation.AnimatedVisibility(
                    visible = showCluster && !imageShareSelectionMode,
                    enter = fadeIn(),
                    exit = fadeOut(),
                    modifier = Modifier.align(Alignment.BottomEnd)
                ) {
                    Column(
                        modifier = Modifier.padding(end = 20.dp, bottom = 14.dp),
                        verticalArrangement = Arrangement.spacedBy(10.dp),
                        horizontalAlignment = Alignment.End
                    ) {
                        if (track != null && lyrics.any(::isLyricsShareSelectable)) {
                            AppleMusic13LyricsFloatingButton(
                                icon = Icons.Rounded.Image,
                                label = if (imageShareSelectionMode) {
                                    "${selectedImageShareLines.size}/$LYRICS_SHARE_MAX_LINES ${strings.linesLabel}"
                                } else {
                                    strings.shareLyrics
                                },
                                onClick = {
                                    wakeCluster()
                                    if (imageShareSelectionMode) {
                                        imageShareSelectionMode = false
                                        imageShareRange = null
                                    } else {
                                        beginImageShareSelection()
                                    }
                                }
                            )
                        }
                        if (state.lyricsSynced) {
                            AppleMusic13LyricsFloatingButton(
                                icon = Icons.Rounded.Timer,
                                label = lyricsSyncCopy(strings.code).title,
                                onClick = { wakeCluster(); onOpenOptions() }
                            )
                        }
                        AppleMusic13LyricsFloatingButton(
                            icon = Icons.AutoMirrored.Rounded.QueueMusic,
                            label = strings.queue,
                            onClick = { wakeCluster(); onOpenQueue() }
                        )
                    }
                }

                androidx.compose.animation.AnimatedVisibility(
                    visible = imageShareSelectionMode,
                    enter = fadeIn() + slideInVertically { it / 2 },
                    exit = fadeOut() + slideOutVertically { it / 2 },
                    modifier = Modifier
                        .align(Alignment.BottomCenter)
                        .padding(bottom = 20.dp)
                ) {
                    Button(
                        onClick = {
                            onShareLyrics(selectedImageShareLines)
                            imageShareSelectionMode = false
                            imageShareRange = null
                        },
                        enabled = selectedImageShareLines.isNotEmpty(),
                        colors = ButtonDefaults.buttonColors(
                            containerColor = Color.White,
                            contentColor = Color(0xFF102026),
                            disabledContainerColor = Color.White.copy(alpha = 0.34f),
                            disabledContentColor = Color(0xFF102026).copy(alpha = 0.55f)
                        ),
                        shape = RoundedCornerShape(28.dp),
                        modifier = Modifier
                            .height(58.dp)
                            .widthIn(min = 176.dp)
                    ) {
                        Text(
                            text = strings.shareLyricsContinue,
                            fontSize = 17.sp,
                            fontWeight = FontWeight.SemiBold
                        )
                    }
                }

                // After the listener is idle, retain a quiet progress strip and a single timing
                // control instead of leaving a completely blank lyric page. A tap still restores
                // the complete transport and action rail above.
                val stripBottom by animateDpAsState(
                    targetValue = if (fullscreen) 2.dp else 22.dp,
                    label = "lyrics-progress-bottom"
                )
                androidx.compose.animation.AnimatedVisibility(
                    visible = (!showCluster || fullscreen) && !imageShareSelectionMode,
                    enter = fadeIn(),
                    exit = fadeOut(),
                    modifier = Modifier.align(Alignment.BottomCenter)
                ) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(start = 32.dp, end = 32.dp, bottom = stripBottom)
                    ) {
                        Column(modifier = Modifier.fillMaxWidth()) {
                            Slider(
                                value = shownProgress,
                                onValueChange = { dragProgress = it },
                                onValueChangeFinished = {
                                    dragProgress?.let { onSeekToMs((state.durationMs * it).toLong()) }
                                    dragProgress = null
                                },
                                enabled = state.durationMs > 0L,
                                colors = SliderDefaults.colors(
                                    thumbColor = Color.White,
                                    activeTrackColor = Color.White,
                                    inactiveTrackColor = Color.White.copy(alpha = 0.30f)
                                ),
                                modifier = Modifier.fillMaxWidth().height(24.dp)
                            )
                            Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                Text(
                                    text = formatSeekbarMillis(shownPosition),
                                    color = Color.White.copy(alpha = 0.76f),
                                    style = AppleMusic13Typography.labelMedium.copy(fontFamily = AppleMusic13SfProFallbackFont)
                                )
                                Text(
                                    text = if (state.durationMs > 0L) formatSeekbarMillis(state.durationMs) else "--:--",
                                    color = Color.White.copy(alpha = 0.76f),
                                    style = AppleMusic13Typography.labelMedium.copy(fontFamily = AppleMusic13SfProFallbackFont)
                                )
                            }
                        }
                        if (state.lyricsSynced) {
                            AppleMusic13LyricsFloatingButton(
                                icon = Icons.Rounded.Timer,
                                label = lyricsSyncCopy(strings.code).title,
                                onClick = onOpenOptions,
                                modifier = Modifier
                                    .align(Alignment.TopEnd)
                                    .offset(y = (-56).dp)
                            )
                        }
                    }
                }
            }

            // expand/shrink deliberately changes the lyric viewport, which is what lets the list
            // grow into the freed room instead of leaving an empty control-shaped band behind.
            AnimatedVisibility(
                visible = showCluster && !fullscreen && !imageShareSelectionMode,
                enter = expandVertically() + fadeIn(),
                exit = shrinkVertically() + fadeOut()
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 20.dp)
                        .padding(top = 6.dp, bottom = 14.dp)
                ) {
                    Slider(
                        value = shownProgress,
                        onValueChange = {
                            dragProgress = it
                            wakeCluster()
                        },
                        onValueChangeFinished = {
                            dragProgress?.let { onSeekToMs((state.durationMs * it).toLong()) }
                            dragProgress = null
                            wakeCluster()
                        },
                        enabled = state.durationMs > 0L,
                        colors = SliderDefaults.colors(
                            thumbColor = Color.White,
                            activeTrackColor = Color.White,
                            inactiveTrackColor = Color.White.copy(alpha = 0.34f)
                        ),
                        modifier = Modifier.fillMaxWidth().height(28.dp)
                    )
                    Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                        Text(
                            text = formatSeekbarMillis(shownPosition),
                            color = Color.White.copy(alpha = 0.78f),
                            style = AppleMusic13Typography.labelMedium.copy(fontFamily = AppleMusic13SfProFallbackFont)
                        )
                        Text(
                            text = if (state.durationMs > 0L) "-" + formatSeekbarMillis((state.durationMs - shownPosition).coerceAtLeast(0L)) else "--:--",
                            color = Color.White.copy(alpha = 0.78f),
                            style = AppleMusic13Typography.labelMedium.copy(fontFamily = AppleMusic13SfProFallbackFont)
                        )
                    }
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(top = 8.dp),
                        horizontalArrangement = Arrangement.spacedBy(58.dp, Alignment.CenterHorizontally),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        IconButton(onClick = { wakeCluster(); onPrevious() }, modifier = Modifier.size(56.dp)) {
                            Icon(Icons.Rounded.SkipPrevious, contentDescription = strings.previous, tint = Color.White, modifier = Modifier.size(46.dp))
                        }
                        IconButton(onClick = { wakeCluster(); onTogglePlay() }, modifier = Modifier.size(76.dp)) {
                            Icon(
                                imageVector = if (state.isPlaying) Icons.Rounded.Pause else Icons.Rounded.PlayArrow,
                                contentDescription = if (state.isPlaying) strings.pause else strings.play,
                                tint = Color.White,
                                modifier = Modifier.size(62.dp)
                            )
                        }
                        IconButton(onClick = { wakeCluster(); onNext() }, modifier = Modifier.size(56.dp)) {
                            Icon(Icons.Rounded.SkipNext, contentDescription = strings.next, tint = Color.White, modifier = Modifier.size(46.dp))
                        }
                    }
                    PlayerOutputVolume(
                        contentColor = Color.White,
                        mutedColor = Color.White.copy(alpha = 0.68f),
                        activeColor = Color.White,
                        trackColor = Color.White.copy(alpha = 0.24f),
                        condensed = true,
                        modifier = Modifier.padding(top = 4.dp)
                    )
                }
            }
        }
        }
    }
}

@Composable
private fun ImageLyricsSelectionHeader(
    title: String,
    selectedCount: Int,
    linesLabel: String,
    selectedLabel: String,
    onClose: () -> Unit
) {
    val strings = LocalDerbisStrings.current
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 20.dp, vertical = 8.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        IconButton(onClick = onClose, modifier = Modifier.size(48.dp)) {
            Icon(
                imageVector = Icons.Rounded.KeyboardArrowDown,
                contentDescription = strings.close,
                tint = Color.White,
                modifier = Modifier.size(30.dp)
            )
        }
        Column(
            modifier = Modifier.weight(1f),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Text(
                text = title,
                color = Color.White,
                fontSize = 20.sp,
                fontWeight = FontWeight.Bold
            )
            Text(
                text = "$selectedCount ${linesLabel.lowercase()} ${selectedLabel.lowercase()}",
                color = Color.White.copy(alpha = 0.78f),
                fontSize = 14.sp,
                fontWeight = FontWeight.Medium
            )
        }
        Spacer(modifier = Modifier.size(48.dp))
    }
}

@Composable
private fun AppleMusic13LyricsFloatingButton(
    icon: ImageVector,
    label: String,
    onClick: () -> Unit,
    modifier: Modifier = Modifier
) {
    Box(
        modifier = modifier
            .size(38.dp)
            .clip(CircleShape)
            .background(Color.White.copy(alpha = 0.24f))
            .clickable(role = Role.Button, onClick = onClick)
            .semantics { contentDescription = label },
        contentAlignment = Alignment.Center
    ) {
        Icon(icon, contentDescription = null, tint = Color.White, modifier = Modifier.size(18.dp))
    }
}


// Kept deliberately below half opacity so high-key album art never washes out white lyrics.
private const val AppleMusic13LyricsArtworkOpacity = 0.34f

@Composable
private fun AppleMusic13LyricsArtworkBackdrop(
    track: Track?,
    accentStart: Color,
    accentEnd: Color
) {
    val artworkUrl = track?.let { active ->
        active.largeThumbnailUrl.ifBlank { active.thumbnailUrl }
    }.orEmpty()
    val fallbackTop = remember(accentStart) { lerp(accentStart, Color.Black, 0.62f) }
    val fallbackBottom = remember(accentEnd) { lerp(accentEnd, Color.Black, 0.88f) }

    Box(Modifier.fillMaxSize().background(fallbackBottom)) {
        // The image is deliberately dimmed as one uniform static layer. This preserves legibility
        // for white active lyrics on very bright album covers without restoring the old dark
        // gradient bands or introducing a moving/palette-based overlay.
        SeamlessArtworkImage(
            url = artworkUrl,
            modifier = Modifier
                .fillMaxSize()
                .graphicsLayer {
                    alpha = AppleMusic13LyricsArtworkOpacity
                    scaleX = 1.08f
                    scaleY = 1.08f
                }
                .blur(22.dp, BlurredEdgeTreatment.Rectangle),
            contentDescription = null,
            fallback = {
                Box(
                    Modifier
                        .fillMaxSize()
                        .background(Brush.verticalGradient(0f to fallbackTop, 1f to fallbackBottom))
                )
            }
        )
        // The dark fallback stays behind the low-opacity artwork. There is intentionally no
        // foreground black-gradient band, so the lyric viewport remains an even contrast field.
    }
}

