@Composable
private fun DerbisBackground() {
    if (DerbisIsNocturne) {
        Box(Modifier.fillMaxSize().background(DerbisBlack))
        return
    }
    val isLight = DerbisIsLight

    Box(
        modifier = Modifier
            .fillMaxSize()
            .drawWithCache {
                val width = size.width
                val height = size.height
                if (size.minDimension <= 0f) {
                    onDrawBehind {}
                } else if (isLight) {
                    val backgroundBrush = Brush.verticalGradient(
                        listOf(
                            Color(0xFFFFFFFF),
                            Color(0xFFF8FAFF),
                            Color(0xFFF2F5FB)
                        )
                    )
                    val haloCenter = androidx.compose.ui.geometry.Offset(width * 0.16f, -height * 0.02f)
                    val haloRadius = width * 1.10f
                    val haloBrush = Brush.radialGradient(
                        colors = listOf(
                            DerbisNavigationBlue.copy(alpha = 0.10f),
                            DerbisNavigationBlue.copy(alpha = 0.03f),
                            Color.Transparent
                        ),
                        center = haloCenter,
                        radius = haloRadius
                    )
                    val violetCenter = androidx.compose.ui.geometry.Offset(width * 1.02f, height * 0.16f)
                    val violetRadius = width * 0.82f
                    val violetBrush = Brush.radialGradient(
                        colors = listOf(
                            DerbisHomeGlowViolet.copy(alpha = 0.07f),
                            DerbisHomeGlowViolet.copy(alpha = 0.02f),
                            Color.Transparent
                        ),
                        center = violetCenter,
                        radius = violetRadius
                    )
                    onDrawBehind {
                        drawRect(backgroundBrush)
                        drawCircle(brush = haloBrush, radius = haloRadius, center = haloCenter)
                        drawCircle(brush = violetBrush, radius = violetRadius, center = violetCenter)
                    }
                } else {
                    val backgroundBrush = Brush.verticalGradient(
                        colorStops = arrayOf(
                            0f to Color(0xFF0B0C10),
                            0.16f to Color(0xFF05060A),
                            0.34f to Color(0xFF000000),
                            1f to Color(0xFF000000)
                        )
                    )
                    val washCenter = androidx.compose.ui.geometry.Offset(width * 0.24f, -height * 0.10f)
                    val washRadius = width * 1.30f
                    val washBrush = Brush.radialGradient(
                        colors = listOf(
                            DerbisNavigationBlue.copy(alpha = 0.13f),
                            DerbisNavigationBlue.copy(alpha = 0.04f),
                            Color.Transparent
                        ),
                        center = washCenter,
                        radius = washRadius
                    )
                    val fadeTop = height * 0.18f
                    val bottomFadeBrush = Brush.verticalGradient(
                        colors = listOf(
                            Color.Transparent,
                            Color.Black.copy(alpha = 0.85f),
                            Color.Black
                        ),
                        startY = fadeTop,
                        endY = height * 0.46f
                    )
                    val fadeSize = androidx.compose.ui.geometry.Size(width, height - fadeTop)
                    onDrawBehind {
                        drawRect(backgroundBrush)
                        drawCircle(brush = washBrush, radius = washRadius, center = washCenter)
                        drawRect(
                            brush = bottomFadeBrush,
                            topLeft = androidx.compose.ui.geometry.Offset(0f, fadeTop),
                            size = fadeSize
                        )
                    }
                }
            }
    )
}

internal fun homeSectionLazyKey(
    position: Int,
