@Composable
private fun HomeQuickPickRow(
    track: Track,
    isCurrent: Boolean,
    isPlaying: Boolean,
    isResolving: Boolean,
    onPlay: () -> Unit,
    onActions: (() -> Unit)? = null
) {
    val strings = LocalDerbisStrings.current
    val shape = DerbisCardDesign.ThumbShape
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .heightIn(min = 60.dp)
            .clip(shape)
            .then(
                if (isCurrent) Modifier.background(DerbisCyan.copy(alpha = 0.07f)) else Modifier
            )
            .pressable(onClick = onPlay)
            .padding(start = 2.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(10.dp)
    ) {
        Box(
            modifier = Modifier
                .size(52.dp)
                .clip(DerbisHomeDesign.ThumbShape),
            contentAlignment = Alignment.Center
        ) {
            CoverImage(
                track = track,
                modifier = Modifier.fillMaxSize(),
                highRes = false
            )
            if (isCurrent) {
                Box(
                    modifier = Modifier
                        .matchParentSize()
                        .background(Color.Black.copy(alpha = 0.18f)),
                    contentAlignment = Alignment.Center
                ) {
                    if (isResolving) {
                        DerbisLoadingIndicator(
                            modifier = Modifier.size(18.dp),
                            color = DerbisCyan
                        )
                    } else {
                        ActiveTrackEqualizer(
                            color = DerbisCyan,
                            isPlaying = isPlaying,
                            width = 18.dp,
                            height = 13.dp
                        )
                    }
                }
            }
        }
        Column(
            modifier = Modifier.weight(1f),
            verticalArrangement = Arrangement.spacedBy(DerbisCardDesign.CaptionLineGap)
        ) {
            Text(
                text = track.title,
                color = if (isCurrent) DerbisCyan else DerbisText,
                style = DerbisType.cardTitle,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
            Text(
                text = track.artist,
                color = DerbisMuted,
                style = DerbisType.caption,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
        }
        if (onActions != null) {
            IconButton(
                onClick = onActions,
                modifier = Modifier.size(48.dp)
            ) {
                Icon(
                    imageVector = Icons.Rounded.MoreVert,
                    contentDescription = strings.songOptions,
                    tint = DerbisMuted,
                    modifier = Modifier.size(22.dp)
                )
            }
        } else {
            Spacer(modifier = Modifier.width(8.dp))
        }
    }
}

private data class HomeHeroUpdate(
    val track: Track,
    val sourceTitle: String,
    val verifiedRelease: Boolean
)

private fun pickHeroUpdate(state: DerbisUiState): HomeHeroUpdate? {
    val currentId = state.currentTrack?.id
    val verifiedReleases = state.homeSections
        .asSequence()
        .filter { isVerifiedReleaseSectionTitle(it.title) }
        .flatMap { section ->
            section.tracks.asSequence()
                .filter { isReliableMusicUpdateCandidate(it) }
                .map { track -> HomeHeroUpdate(track, section.title, true) }
        }
    val trustedEditorial = state.homeSections
        .asSequence()
        .filterNot { isQuickPicksSectionTitle(it.title) }
        .filterNot { isVerifiedReleaseSectionTitle(it.title) }
        .flatMap { section ->
            section.tracks.asSequence()
                .filter { isReliableMusicUpdateCandidate(it) }
                .map { track -> HomeHeroUpdate(track, section.title, false) }
        }
    val chartUpdates = state.charts
        .asSequence()
        .filter { isReliableMusicUpdateCandidate(it) }
        .map { track -> HomeHeroUpdate(track, "YouTube Charts Italia", false) }
    val libraryUpdates = sequenceOf(
        state.tracks.asSequence(),
        state.favorites.asSequence(),
        state.currentTrack?.let { sequenceOf(it) } ?: emptySequence()
    )
        .flatten()
        .filter { isReliableMusicUpdateCandidate(it) }
        .map { track -> HomeHeroUpdate(track, track.source.ifBlank { "YouTube Music" }, false) }
    return sequenceOf(verifiedReleases, trustedEditorial, chartUpdates, libraryUpdates)
        .flatten()
        .distinctBy { it.track.id }
        .firstOrNull { it.track.id != currentId }
}

@Composable
internal fun StableRemoteArtwork(
    url: String,
    contentDescription: String?,
    modifier: Modifier,
    contentScale: ContentScale,
    highRes: Boolean = true,
    alignment: Alignment = Alignment.Center
) {
    val context = LocalContext.current
    val resizedUrl = remember(url, highRes) {
        if (highRes) fullResolutionArtworkUrl(url) else DerbisArtworkCache.large(url)
    }
    val request = remember(context, resizedUrl) {
        ImageRequest.Builder(context)
            .data(resizedUrl)
            .memoryCachePolicy(CachePolicy.ENABLED)
            .diskCachePolicy(CachePolicy.ENABLED)
            .networkCachePolicy(CachePolicy.ENABLED)
            .crossfade(false)
            .build()
    }
    AsyncImage(
        model = request,
        contentDescription = contentDescription,
        contentScale = contentScale,
        alignment = alignment,
        filterQuality = FilterQuality.High,
        modifier = modifier
    )
}

