@Composable
private fun ResonanceShelf(
    tracks: List<Track>,
    comments: Map<String, ResonanceCommentSnippet>,
    currentId: String?,
    isPlaying: Boolean,
    isResolving: Boolean,
    onPlay: (Track) -> Unit,
    onOpenComments: (Track) -> Unit
) {
    val strings = LocalDerbisStrings.current
    val displayTracks = tracks
    if (displayTracks.isEmpty()) return

    Column(verticalArrangement = Arrangement.spacedBy(homeHeaderContentGap())) {
        HomeSectionHeader(
            title = strings.mostCommentedTracks,
            subtitle = strings.tapToOpenComments,
            modifier = Modifier.padding(horizontal = HomeHorizontalInset)
        )
        BoxWithConstraints(modifier = Modifier.fillMaxWidth()) {
            val cardWidth = (maxWidth - HomeHorizontalInset - 24.dp)
                .coerceIn(292.dp, 330.dp)
            val resonanceState = rememberLazyListState()
            val resonanceDepth = carouselDepthEnabled()
            LazyRow(
                state = resonanceState,
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(12.dp),
                contentPadding = PaddingValues(
                    start = HomeHorizontalInset,
                    end = HomeHorizontalShelfEndPadding
                )
            ) {
                itemsIndexed(
                    items = displayTracks,
                    key = { index, track -> "resonance-featured-$index-${DerbisPersonalOrbit.identityKey(track)}" },
                    contentType = { _, _ -> "resonance-featured-card" }
                ) { index, track ->
                    ResonanceFeaturedCard(
                        toneIndex = index,
                        modifier = Modifier.derbisCarouselDepth(
                            state = resonanceState,
                            key = "resonance-featured-$index-${DerbisPersonalOrbit.identityKey(track)}",
                            enabled = resonanceDepth
                        ),
                        track = track,
                        snippet = comments[track.id],
                        active = track.id == currentId,
                        isPlaying = isPlaying,
                        isResolving = isResolving,
                        cardWidth = cardWidth,
                        onPlay = { onPlay(track) },
                        onOpenComments = { onOpenComments(track) }
                    )
                }
            }
        }
    }
}

private val ResonanceCardShape = RoundedCornerShape(28.dp)
private val ResonanceBubbleShape = RoundedCornerShape(topStart = 22.dp, topEnd = 22.dp, bottomEnd = 22.dp, bottomStart = 6.dp)
private val ResonanceBubbleTones = listOf(
    Color(0xFFE57399),
    Color(0xFFE8A85C),
    Color(0xFF5FB8A6),
    Color(0xFFB98AE0)
)

@Composable
private fun ResonanceFeaturedCard(
    toneIndex: Int,
    track: Track,
    snippet: ResonanceCommentSnippet?,
    active: Boolean,
    isPlaying: Boolean,
    isResolving: Boolean,
    cardWidth: Dp,
    onPlay: () -> Unit,
    onOpenComments: () -> Unit,
    modifier: Modifier = Modifier
) {
    val strings = LocalDerbisStrings.current
    val appearance = rememberResonanceAppearance(toneIndex)
    val shape = appearance.shape
    val quoteShape = appearance.quoteShape
    val colors = MaterialTheme.colorScheme
    val bubbleTint = appearance.bubbleTint
    val commentCount = snippet?.countText
        ?.let(::youtubeCommentCountBadge)
        ?.takeIf(String::isNotBlank)
    val author = snippet?.author?.trim().orEmpty()

    Column(
        modifier = modifier
            .width(cardWidth)
            .clip(shape)
            .background(colors.surfaceContainerHigh)
            .then(appearance.outline)
            .then(if (active) Modifier.background(DerbisText.copy(alpha = 0.05f)) else Modifier)
            .padding(8.dp)
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .height(ResonanceQuoteHeight)
                .clip(quoteShape)
                .background(bubbleTint)
                .semantics(mergeDescendants = true) {}
                .pressable(onClick = onOpenComments)
                .padding(start = 14.dp, end = 14.dp, top = 12.dp, bottom = 10.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp)
        ) {
            ResonanceQuoteHeader(
                author = author,
                avatarUrl = snippet?.authorAvatarUrl.orEmpty(),
                commentCount = commentCount,
                loading = snippet?.isLoading == true
            )
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .weight(1f),
                contentAlignment = Alignment.CenterStart
            ) {
                when {
                    snippet?.isLoading == true -> ResonanceCommentShimmer()
                    snippet?.disabled == true -> ResonanceQuoteText(strings.commentsDisabled, muted = true)
                    snippet?.hasComment == true -> ResonanceQuoteText(snippet.text, muted = false)
                    else -> ResonanceQuoteText(strings.tapToOpenComments, muted = true)
                }
            }
        }
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .semantics(mergeDescendants = true) {}
                .pressable(onClick = onPlay)
                .padding(start = 6.dp, end = 4.dp, top = 10.dp, bottom = 4.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            CoverImage(
                track = track,
                modifier = Modifier
                    .size(48.dp)
                    .clip(DerbisCardDesign.ArtworkShape),
                highRes = false
            )
            Column(
                modifier = Modifier.weight(1f),
                verticalArrangement = Arrangement.spacedBy(DerbisCardDesign.CaptionLineGap)
            ) {
                Text(
                    text = track.title,
                    color = if (active) DerbisCyan else DerbisText,
                    style = DerbisType.contentTitle,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )
                Text(
                    text = track.artist,
                    color = DerbisMuted,
                    style = DerbisType.metadata,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )
            }
            Box(
                modifier = Modifier
                    .size(44.dp)
                    .clip(resonancePlayShape(active && isPlaying))
                    .background(if (active) colors.primaryContainer else DerbisText.copy(alpha = 0.10f)),
                contentAlignment = Alignment.Center
            ) {
                when {
                    active && isResolving -> DerbisLoadingIndicator(
                        modifier = Modifier.size(18.dp),
                        color = DerbisCyan
                    )
                    active -> ActiveTrackEqualizer(
                        color = DerbisCyan,
                        isPlaying = isPlaying,
                        width = 16.dp,
                        height = 12.dp
                    )
                    else -> Icon(
                        imageVector = Icons.Rounded.PlayArrow,
                        contentDescription = strings.play,
                        tint = DerbisText,
                        modifier = Modifier.size(22.dp)
                    )
                }
            }
        }
    }
}

private data class ResonanceAppearance(val shape: Shape, val quoteShape: Shape, val bubbleTint: Color, val outline: Modifier)

@Composable
private fun rememberResonanceAppearance(toneIndex: Int): ResonanceAppearance {
    val nocturne = DerbisIsNocturne
    val colors = MaterialTheme.colorScheme
    val tone = ResonanceBubbleTones[toneIndex.coerceAtLeast(0) % ResonanceBubbleTones.size]
    return remember(nocturne, colors, tone) {
        if (nocturne) {
            val shape = RoundedCornerShape(Nocturne78Design.cardCorner)
            ResonanceAppearance(shape, RoundedCornerShape(Nocturne78Design.artworkCorner), colors.surfaceContainer, Modifier.border(1.dp, colors.outline, shape))
        } else ResonanceAppearance(ResonanceCardShape, ResonanceBubbleShape, lerp(colors.surfaceContainerHighest, tone, 0.30f), Modifier)
    }
}

@Composable
private fun resonancePlayShape(playing: Boolean): Shape =
    if (DerbisIsNocturne) RoundedCornerShape(Nocturne78Design.controlCorner)
    else rememberDerbisPlayMorphShape(playing = playing, animated = LocalAnimationsEnabled.current)

