private fun ResonanceQuoteHeader(
    author: String,
    avatarUrl: String,
    commentCount: String?,
    loading: Boolean
) {
    Row(
        modifier = Modifier.fillMaxWidth(),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        if (avatarUrl.isNotBlank()) {
            StableRemoteArtwork(
                url = avatarUrl,
                contentDescription = null,
                modifier = Modifier
                    .size(24.dp)
                    .clip(CircleShape),
                contentScale = ContentScale.Crop,
                highRes = false
            )
        } else {
            Box(
                modifier = Modifier
                    .size(24.dp)
                    .background(DerbisText.copy(alpha = 0.10f), CircleShape),
                contentAlignment = Alignment.Center
            ) {
                Icon(
                    imageVector = Icons.Rounded.ChatBubbleOutline,
                    contentDescription = null,
                    tint = DerbisMuted,
                    modifier = Modifier.size(13.dp)
                )
            }
        }
        Text(
            text = author,
            color = DerbisText.copy(alpha = 0.86f),
            style = DerbisType.caption,
            fontWeight = FontWeight.SemiBold,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
            modifier = Modifier.weight(1f)
        )
        if (loading) {
            DerbisLoadingIndicator(modifier = Modifier.size(12.dp), color = DerbisMuted)
