@Composable
private fun StudioPersonalListeningShelf(
    style: HomeStyle,
    tracks: List<Track>,
    userName: String,
    profilePhotoPath: String,
    profilePhotoVersion: Long,
    accountAvatarUrl: String,
    currentId: String?,
    isPlaying: Boolean,
    isResolving: Boolean,
    onPlay: (Track) -> Unit,
    onPlayAll: () -> Unit,
    onTrackActions: (Track) -> Unit
) {
    if (DerbisSkinManagesLayout) {
        Column(verticalArrangement = Arrangement.spacedBy(14.dp)) {
            Box(Modifier.padding(horizontal = 20.dp)) {
                StudioHomeOrbitHeader(userName = userName, profilePhotoPath = profilePhotoPath,
                    profilePhotoVersion = profilePhotoVersion, accountAvatarUrl = accountAvatarUrl, onPlayAll = onPlayAll)
            }
            SkinOrbitTracks(tracks, currentId, isPlaying, isResolving, onPlay, onTrackActions)
        }
        return
    }
    val columns = when (style) {
        HomeStyle.Editorial, HomeStyle.Immersive -> 2
        else -> HOME_PERSONAL_ORBIT_GRID_COLUMNS
    }
    val pages = remember(tracks, columns) {
        homePersonalOrbitPages(tracks)
            .flatten()
            .flatten()
            .chunked(columns * columns)
            .map { page -> page.chunked(columns) }
    }
    if (pages.isEmpty()) return
    val pagerState = rememberPagerState(pageCount = { pages.size })
    LaunchedEffect(pages.size) {
        if (pagerState.currentPage > pages.lastIndex) pagerState.scrollToPage(pages.lastIndex)
    }
    val pageKey: (Int) -> String = { pageIndex ->
        pages.getOrNull(pageIndex)?.firstOrNull()?.firstOrNull()
            ?.let(DerbisPersonalOrbit::identityKey)
            ?.takeIf(String::isNotBlank)
            ?.let { "orbit-page-$it" }
            ?: "orbit-page-index-$pageIndex"
    }
    val orbitPage: @Composable (Int, Modifier) -> Unit = { pageIndex, pageModifier ->
        Column(
            modifier = pageModifier.padding(
                start = DerbisHomeDesign.HorizontalInset,
                end = DerbisHomeDesign.OrbitPageEndInset
            ),
            verticalArrangement = Arrangement.spacedBy(DerbisHomeDesign.OrbitTileGap)
        ) {
            val pageRows = pages.getOrNull(pageIndex).orEmpty()
            pageRows.forEachIndexed { rowIndex, rowTracks ->
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(DerbisHomeDesign.OrbitTileGap)
                ) {
                    rowTracks.forEachIndexed { columnIndex, track ->
                        key(DerbisPersonalOrbit.identityKey(track)) {
                            StudioPersonalOrbitTile(
                                style = style,
                                index = rowIndex * columns + columnIndex,
                                shape = studioOrbitShape(
                                    style = style,
                                    index = rowIndex * columns + columnIndex,
                                    fallback = derbisGroupedGridShape(
                                        row = rowIndex,
                                        column = columnIndex,
                                        rows = pageRows.size,
                                        columns = columns
                                    )
                                ),
                                track = track,
                                isCurrent = track.id == currentId,
                                isPlaying = isPlaying && track.id == currentId,
                                isResolving = isResolving && track.id == currentId,
                                onPlay = { onPlay(track) },
                                onActions = { onTrackActions(track) },
                                modifier = Modifier.weight(1f)
                            )
                        }
                    }
                    repeat(columns - rowTracks.size) {
                        Spacer(modifier = Modifier.weight(1f))
                    }
                }
            }
        }
    }

    Column(verticalArrangement = Arrangement.spacedBy(homeHeaderContentGap())) {
        HomeSectionInset {
            StudioHomeOrbitHeader(
                style = style,
                userName = userName,
                profilePhotoPath = profilePhotoPath,
                profilePhotoVersion = profilePhotoVersion,
                accountAvatarUrl = accountAvatarUrl,
                onPlayAll = onPlayAll
            )
        }
        BoxWithConstraints(modifier = Modifier.fillMaxWidth()) {
            val wall = maxWidth >= DerbisHomeDesign.OrbitWallMinWidth
            if (wall) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .horizontalScroll(rememberScrollState())
                ) {
                    pages.indices.forEach { pageIndex ->
                        key(pageKey(pageIndex)) {
                            orbitPage(pageIndex, Modifier.width(DerbisHomeDesign.OrbitWallPageWidth))
                        }
                    }
                }
            } else {
                Column(verticalArrangement = Arrangement.spacedBy(DerbisHomeDesign.OrbitDotsTopGap)) {
                    HorizontalPager(
                        state = pagerState,
                        modifier = Modifier.fillMaxWidth(),
                        key = pageKey
                    ) { pageIndex ->
                        orbitPage(pageIndex, Modifier.fillMaxWidth())
                    }
                    if (pages.size > 1) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(
                                DerbisHomeDesign.OrbitDotGap,
                                Alignment.CenterHorizontally
                            ),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            pages.indices.forEach { index ->
                                Box(
                                    modifier = Modifier
                                        .size(DerbisHomeDesign.OrbitDotSize)
                                        .background(
                                            if (pagerState.currentPage == index) {
                                                DerbisText
                                            } else {
                                                DerbisText.copy(alpha = 0.30f)
                                            },
                                            CircleShape
                                        )
                                )
                            }
                        }
                    }
                }
            }
        }
    }
}

