@Composable
private fun DownloadsFolderCard(count: Int, onClick: () -> Unit) {
    val strings = LocalDerbisStrings.current
    val cardShape = RoundedCornerShape(16.dp)
    val liquidGlass = DerbisIsLiquidGlass
    Surface(
        color = if (liquidGlass) Color.Transparent else Color.White.copy(alpha = 0.045f),
        border = if (liquidGlass) null else BorderStroke(1.dp, Color.White.copy(alpha = 0.08f)),
        shape = cardShape,
        modifier = Modifier
            .fillMaxWidth()
            .clickable(onClick = onClick)
            .then(
                if (liquidGlass) {
                    Modifier.derbisGlass(
                        shape = cardShape,
                        baseTint = DerbisCyan,
                        fallbackColor = DerbisPanel.copy(alpha = 0.68f),
                        fallbackBorderColor = Color.White.copy(alpha = 0.28f),
                        intensity = DerbisGlassIntensity.Subtle,
                        artworkTint = DerbisActivePalette.cyan
                    )
                } else {
                    Modifier
                }
            )
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 16.dp, vertical = 18.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            Box(
                modifier = Modifier
                    .size(48.dp)
                    .background(Color.White.copy(alpha = 0.06f), RoundedCornerShape(12.dp))
                    .border(BorderStroke(1.dp, Color.White.copy(alpha = 0.10f)), RoundedCornerShape(12.dp)),
                contentAlignment = Alignment.Center
            ) {
                Icon(
                    imageVector = Icons.Rounded.DownloadDone,
                    contentDescription = null,
                    tint = DerbisCyan,
                    modifier = Modifier.size(24.dp)
                )
            }
            Column(modifier = Modifier.weight(1f)) {
                Text(
                    text = LocalDerbisStrings.current.downloadsFolder,
                    color = DerbisText,
                    fontSize = 16.sp,
                    fontWeight = FontWeight.Bold
                )
                Text(
                    text = strings.formatDownloadedTrackCount(count),
                    color = DerbisMuted,
                    fontSize = 13.sp,
                    fontWeight = FontWeight.Normal
                )
            }
            Icon(
                imageVector = Icons.AutoMirrored.Rounded.KeyboardArrowRight,
                contentDescription = null,
                tint = DerbisMuted,
                modifier = Modifier.size(24.dp)
            )
        }
    }
}

@Composable
private fun DownloadsFolderOverlay(
    state: DerbisUiState,
    viewModel: DerbisViewModel,
    onClose: () -> Unit
) {
    val strings = LocalDerbisStrings.current
    val downloadsAccent = rememberNowPlayingAccent(state.currentTrack, DerbisCyan)
    val downloadsStyle = DerbisConnectedDefaults.style(accent = downloadsAccent)
    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(DerbisInk)
    ) {
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .statusBarsPadding(),
            contentPadding = PaddingValues(start = 16.dp, end = 16.dp, top = 8.dp, bottom = derbisTabContentBottomPadding(state.currentTrack != null)),
            verticalArrangement = Arrangement.spacedBy(downloadsStyle.gap)
        ) {
            item(contentType = "downloads-header") {
                Row(
                    modifier = Modifier.fillMaxWidth().padding(top = 12.dp, bottom = 18.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    DerbisBackButton(onClick = onClose, contentDescription = LocalDerbisStrings.current.back)
                    Spacer(Modifier.width(8.dp))
                    Column(modifier = Modifier.weight(1f)) {
                        Text(
                            text = LocalDerbisStrings.current.offlineDownloadsPlain,
                            color = DerbisText,
                            fontSize = 24.sp,
                            fontWeight = FontWeight.Black
                        )
                        Text(
                            text = strings.formatSavedTrackCount(state.downloads.size),
                            color = DerbisMuted,
                            fontSize = 14.sp
                        )
                    }
                }
            }
            if (state.downloads.isEmpty()) {
                item {
                    EmptyState(strings.noOfflineDownloads)
                }
            } else {
                itemsIndexed(
                    state.downloads,
                    key = { _, download -> "dlfolder-${download.id}" },
                    contentType = { _, _ -> "download-saved" }
                ) { downloadIndex, download ->
                    DownloadRow(
                        download = download,
                        isCurrent = download.trackId == state.currentTrack?.id,
                        isPlaying = state.isPlaying,
                        position = DerbisConnectedPosition.of(downloadIndex, state.downloads.size),
                        style = downloadsStyle,
                        accent = downloadsAccent,
                        onPlay = { viewModel.playDownloaded(download) },
                        onDelete = { viewModel.deleteDownload(download) }
                    )
                }
            }
        }
    }
}

@Composable
private fun LibraryScreen(
    viewModel: LibraryViewModel,
    state: DerbisUiState,
    listState: LazyListState,
    onOpenDownloads: () -> Unit
) {
    val strings = LocalDerbisStrings.current
    var addTarget by remember { mutableStateOf<Track?>(null) }
    var showCreate by remember { mutableStateOf(false) }
    var filter by rememberSaveable { mutableStateOf(LibraryFilter.All) }
    val showPlaylists = filter == LibraryFilter.All || filter == LibraryFilter.Playlists
    val showDownloads = filter == LibraryFilter.All || filter == LibraryFilter.Downloads
    val showSongs = filter == LibraryFilter.All || filter == LibraryFilter.Songs
    val showArtists = filter == LibraryFilter.All || filter == LibraryFilter.Artists
    val showPulse = filter == LibraryFilter.All
    Box(modifier = Modifier.fillMaxSize()) {
        LazyColumn(
            state = listState,
            modifier = Modifier
                .fillMaxSize()
                .statusBarsPadding(),
            contentPadding = PaddingValues(start = 16.dp, end = 16.dp, top = 14.dp, bottom = derbisTabContentBottomPadding(state.currentTrack != null)),
            verticalArrangement = Arrangement.spacedBy(18.dp)
        ) {
            item(key = "lib-header", contentType = "lib-header") {
                LibraryHeader(
                    title = strings.libraryTitle,
                    subtitle = strings.librarySubtitle,
                    playlistCount = state.playlists.size,
                    downloadCount = state.downloads.size,
                    favoriteCount = state.favorites.size
                )
            }

            item(key = "lib-filters", contentType = "lib-filters") {
                LibraryFilterChips(
                    selected = filter,
                    playlistCount = state.playlists.size,
                    songCount = state.favorites.size + state.recentListens.size,
                    artistCount = state.followedArtists.size,
                    downloadCount = state.downloads.size,
                    onSelect = { filter = it }
                )
            }

            if (showPlaylists) {
                item(key = "lib-playlists-header", contentType = "lib-section-header") {
                    LibrarySectionHeader(
                        title = cleanLibraryLabel(strings.playlists),
                        detail = strings.personalPlaylists,
                        count = state.playlists.size,
                        icon = Icons.AutoMirrored.Rounded.QueueMusic,
                        accent = DerbisViolet,
                        actionLabel = strings.newItem,
                        onAction = { showCreate = true }
                    )
                }
                if (state.playlists.isEmpty()) {
                    item(key = "lib-playlists-empty", contentType = "lib-empty") {
                        LibraryEmptyState(
                            icon = Icons.AutoMirrored.Rounded.QueueMusic,
                            title = strings.createFirstPlaylist,
                            detail = strings.createFirstPlaylistSubtitle,
                            accent = DerbisViolet,
                            actionLabel = strings.newItem,
                            onAction = { showCreate = true }
                        )
                    }
                } else {
                    items(state.playlists, key = { "pl-${it.id}" }, contentType = { "lib-playlist" }) { playlist ->
                        PlaylistRow(
                            playlist = playlist,
                            onOpen = { viewModel.openPlaylist(playlist.id) },
                            onPlay = { viewModel.playPlaylist(playlist.id) },
                            onDelete = { viewModel.deletePlaylist(playlist.id) }
                        )
                    }
                }
            }

            if (showDownloads) {
                item(key = "lib-downloads-header", contentType = "lib-section-header") {
                    LibrarySectionHeader(
                        title = cleanLibraryLabel(strings.downloads),
                        detail = strings.offline,
                        count = state.downloads.size,
                        icon = Icons.Rounded.DownloadDone,
                        accent = DerbisCyan
                    )
                }
                if (state.downloads.isEmpty()) {
                    item(key = "lib-downloads-empty", contentType = "lib-empty") {
                        LibraryEmptyState(
                            icon = Icons.Rounded.Download,
                            title = strings.noOfflineDownloads,
                            detail = strings.downloadTrackHint,
                            accent = DerbisCyan
                        )
                    }
                } else {
                    item(key = "lib-downloads-card", contentType = "lib-downloads-card") {
                        DownloadsFolderCard(
                            count = state.downloads.size,
                            onClick = onOpenDownloads
                        )
                    }
                }
            }

            if (showSongs) {
                item(key = "lib-favorites-header", contentType = "lib-section-header") {
                    LibrarySectionHeader(
                        title = cleanLibraryLabel(strings.favorites),
                        detail = strings.savedTracks,
                        count = state.favorites.size,
                        icon = Icons.Rounded.Favorite,
                        accent = DerbisPink
                    )
                }
                if (state.favorites.isEmpty()) {
                    item(key = "lib-favorites-empty", contentType = "lib-empty") {
                        LibraryEmptyState(
                            icon = Icons.Rounded.FavoriteBorder,
                            title = strings.favoritesEmpty,
                            detail = strings.tapHeartToAdd,
                            accent = DerbisPink
                        )
                    }
                } else {
                    item(key = "lib-favorites-carousel", contentType = "lib-carousel") {
                        RowCarousel(
                            tracks = state.favorites,
                            currentId = state.currentTrack?.id,
                            isPlaying = state.isPlaying,
                            isResolving = state.isResolving,
                            favoriteIds = state.favoriteIds,
                            onPlay = { viewModel.playFrom(state.favorites, it) },
                            onFavorite = { viewModel.toggleFavorite(it) },
                            onAddToPlaylist = { addTarget = it },
                            onAddToQueue = { viewModel.addToQueue(it) },
                            onDownload = { viewModel.exportTrack(it) }
                        )
                    }
                }
            }

            if (showArtists && state.followedArtists.isNotEmpty()) {
                item(key = "lib-artists-header", contentType = "lib-section-header") {
                    LibrarySectionHeader(
                        title = strings.followedArtistsTitle,
                        detail = strings.followedArtistsSubtitle,
                        count = state.followedArtists.size,
                        icon = Icons.Rounded.Person,
                        accent = CinematicGold
                    )
                }
                item(key = "lib-artists-row", contentType = "lib-artists-row") {
                    FollowedArtistsRow(
                        artists = state.followedArtists,
                        onOpen = { viewModel.openArtistByName(it.name) }
                    )
                }
            }

            if (showArtists && state.followedArtists.isEmpty() && filter == LibraryFilter.Artists) {
                item(key = "lib-artists-empty", contentType = "lib-empty") {
                    LibraryEmptyState(
                        icon = Icons.Rounded.Person,
                        title = strings.followedArtistsTitle,
                        detail = strings.followedArtistsSubtitle,
                        accent = CinematicGold
                    )
                }
            }

            if (showPulse) {
                item(key = "lib-pulse-divider", contentType = "lib-divider") {
                    LibrarySectionDivider(label = strings.pulseSectionBand)
                }
                item(key = "lib-pulse-header", contentType = "lib-section-header") {
                    LibrarySectionHeader(
                        title = strings.pulseTitle,
                        detail = strings.pulseSubtitle,
                        count = state.listeningPulse.plays,
                        icon = Icons.Rounded.Insights,
                        accent = DerbisCyan
                    )
                }
                item(key = "lib-pulse-card", contentType = "lib-pulse-card") {
                    ListeningPulseProCard(
                        pulse = state.listeningPulse,
                        strings = strings,
                        onOpenInsights = viewModel::openListeningInsights
                    )
                }
            }

            if (showSongs) {
                item(key = "lib-history-header", contentType = "lib-section-header") {
                    LibrarySectionHeader(
                        title = strings.listeningHistory,
                        detail = strings.listeningHistorySubtitle,
                        count = state.recentListens.size,
                        icon = Icons.Rounded.History,
                        accent = DerbisViolet
                    )
                }
                if (state.recentListens.isEmpty()) {
                    item(key = "lib-history-empty", contentType = "lib-empty") {
                        LibraryEmptyState(
                            icon = Icons.Rounded.History,
                            title = strings.listeningHistoryEmptyTitle,
                            detail = strings.listeningHistoryEmptyDetail,
                            accent = DerbisViolet
                        )
                    }
                } else {
                    item(key = "lib-history-recap", contentType = "lib-history-recap") {
                        ListeningHistoryRecapCard(
                            tracks = state.recentListens,
                            currentTrackId = state.currentTrack?.id,
                            isPlaying = state.isPlaying,
                            isResolving = state.isResolving,
                            onPlay = { track -> viewModel.playFrom(state.recentListens, track) }
                        )
                    }
                }
            }
        }

        if (showCreate) {
            PlaylistCreateDialog(
                onDismiss = { showCreate = false },
                onConfirm = { name ->
                    viewModel.createPlaylist(name)
                    showCreate = false
                }
            )
        }

        addTarget?.let { track ->
            AddToPlaylistDialog(
                track = track,
                playlists = state.playlists,
                onDismiss = { addTarget = null },
                onAddTo = { playlistId ->
                    viewModel.addToPlaylist(playlistId, track)
                    addTarget = null
                },
                onCreateWith = { name ->
                    viewModel.createPlaylist(name, track)
                    addTarget = null
                }
            )
        }
    }
}

@Composable
private fun ListeningHistoryRecapCard(
    tracks: List<Track>,
    currentTrackId: String?,
    isPlaying: Boolean,
    isResolving: Boolean,
    onPlay: (Track) -> Unit
) {
    val strings = LocalDerbisStrings.current
    val recentTracks = remember(tracks) {
        tracks
            .distinctBy { track ->
                track.id.ifBlank { "${track.title.lowercase()}|${track.artist.lowercase()}" }
            }
            .take(6)
    }
    val latest = recentTracks.first()
    val visibleArtwork = recentTracks.take(5)
    val uniqueArtists = remember(tracks) {
        tracks.map { it.artist.trim().lowercase() }.filter { it.isNotBlank() }.distinct().size
    }
    val uniqueTracks = remember(tracks) {
        tracks.distinctBy { it.id.ifBlank { "${it.title.lowercase()}|${it.artist.lowercase()}" } }.size
    }
    val primary = remember(latest.accentStart) { Color(latest.accentStart) }
    val secondary = remember(latest.accentEnd) { Color(latest.accentEnd) }
    val stackWidth = ((visibleArtwork.size - 1).coerceAtLeast(0) * 34 + 62).dp
    val latestIsCurrent = latest.id == currentTrackId
    val playingLatest = latestIsCurrent && isPlaying
    val resolvingLatest = latestIsCurrent && isResolving

    Surface(
        color = DerbisPanel.copy(alpha = 0.84f),
        shape = RoundedCornerShape(28.dp),
        border = BorderStroke(1.dp, Color.White.copy(alpha = 0.10f)),
        modifier = Modifier
            .fillMaxWidth()
            .pressable(pressedScale = 0.985f) { onPlay(latest) }
    ) {
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .background(
                    Brush.linearGradient(
                        listOf(
                            primary.copy(alpha = 0.18f),
                            DerbisPanel.copy(alpha = 0.90f),
                            secondary.copy(alpha = 0.12f)
                        )
                    )
                )
        ) {
            Column(
                modifier = Modifier.padding(horizontal = 18.dp, vertical = 17.dp),
                verticalArrangement = Arrangement.spacedBy(15.dp)
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.SpaceBetween
                ) {
                    Column(verticalArrangement = Arrangement.spacedBy(3.dp)) {
                        Text(
                            text = strings.trailTitle,
                            color = primary.playerMix(Color.White, 0.62f),
                            fontSize = 10.sp,
                            fontWeight = FontWeight.Black,
                            letterSpacing = 1.15.sp
                        )
                        Text(
                            text = "${tracks.size} ${strings.trailPlays} · $uniqueArtists ${strings.statArtists}",
                            color = Color.White.copy(alpha = 0.60f),
                            fontSize = 12.sp,
                            fontWeight = FontWeight.SemiBold
                        )
                    }
                    Surface(
                        color = Color.Black.copy(alpha = 0.24f),
                        shape = CircleShape,
                        border = BorderStroke(1.dp, Color.White.copy(alpha = 0.10f))
                    ) {
                        Text(
                            text = "$uniqueTracks ${strings.trailUnique}",
                            color = Color.White.copy(alpha = 0.78f),
                            fontSize = 10.sp,
                            fontWeight = FontWeight.Bold,
                            modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp)
                        )
                    }
                }

                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(16.dp)
                ) {
                    Box(
                        modifier = Modifier
                            .width(stackWidth)
                            .height(66.dp)
                    ) {
                        visibleArtwork.forEachIndexed { index, track ->
                            val selected = track.id == currentTrackId
                            AsyncImage(
                                model = track.thumbnailUrl.ifBlank { track.largeThumbnailUrl },
                                contentDescription = track.title,
                                contentScale = ContentScale.Crop,
                                modifier = Modifier
                                    .offset(x = (index * 34).dp)
                                    .zIndex(index.toFloat())
                                    .size(62.dp)
                                    .shadow(8.dp, RoundedCornerShape(17.dp))
                                    .clip(RoundedCornerShape(17.dp))
                                    .border(
                                        width = if (selected) 2.dp else 1.dp,
                                        color = if (selected) {
                                            primary.playerMix(Color.White, 0.34f)
                                        } else {
                                            Color.White.copy(alpha = 0.16f)
                                        },
                                        shape = RoundedCornerShape(17.dp)
                                    )
                                    .pressable(pressedScale = 0.94f) { onPlay(track) }
                            )
                        }
                    }

                    Column(
                        modifier = Modifier.weight(1f),
                        verticalArrangement = Arrangement.spacedBy(4.dp)
                    ) {
                        Text(
                            text = strings.trailLastPlayed,
                            color = Color.White.copy(alpha = 0.48f),
                            fontSize = 10.sp,
                            fontWeight = FontWeight.Bold
                        )
                        Text(
                            text = latest.title,
                            color = Color.White,
                            fontSize = 17.sp,
                            lineHeight = DerbisTypeRhythm.lineHeight(17.sp),
                            fontWeight = FontWeight.Black,
                            maxLines = 2,
                            overflow = TextOverflow.Ellipsis
                        )
                        Text(
                            text = latest.artist,
                            color = Color.White.copy(alpha = 0.58f),
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Medium,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                    }

                    Box(
                        modifier = Modifier
                            .size(43.dp)
                            .background(
                                brush = Brush.linearGradient(listOf(primary, secondary)),
                                shape = CircleShape
                            )
                            .border(1.dp, Color.White.copy(alpha = 0.22f), CircleShape),
                        contentAlignment = Alignment.Center
                    ) {
                        when {
                            resolvingLatest -> CircularProgressIndicator(
                                modifier = Modifier.size(20.dp),
                                strokeWidth = 2.4.dp,
                                color = Color.White
                            )
                            playingLatest -> Icon(
                                imageVector = Icons.Rounded.GraphicEq,
                                contentDescription = null,
                                tint = Color.White,
                                modifier = Modifier.size(23.dp)
                            )
                            else -> Icon(
                                imageVector = Icons.Rounded.PlayArrow,
                                contentDescription = null,
                                tint = Color.White,
                                modifier = Modifier.size(25.dp)
                            )
                        }
                    }
                }

                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    ListeningHistoryMetric(
                        modifier = Modifier.weight(1f),
                        icon = Icons.Rounded.Headphones,
                        value = tracks.size.toString(),
                        label = strings.statPlays,
                        accent = primary
                    )
                    ListeningHistoryMetric(
                        modifier = Modifier.weight(1f),
                        icon = Icons.Rounded.Person,
                        value = uniqueArtists.toString(),
                        label = strings.statArtists,
                        accent = secondary
                    )
                    ListeningHistoryMetric(
                        modifier = Modifier.weight(1f),
                        icon = Icons.Rounded.MusicNote,
                        value = uniqueTracks.toString(),
                        label = strings.statTracks,
                        accent = primary.playerMix(secondary, 0.5f)
                    )
                }
            }
        }
    }
}

@Composable
private fun ListeningHistoryMetric(
    modifier: Modifier,
    icon: ImageVector,
    value: String,
    label: String,
    accent: Color
) {
    Surface(
        color = Color.Black.copy(alpha = 0.20f),
        shape = RoundedCornerShape(15.dp),
        border = BorderStroke(1.dp, Color.White.copy(alpha = 0.08f)),
        modifier = modifier
    ) {
        Row(
            modifier = Modifier.padding(horizontal = 10.dp, vertical = 9.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(7.dp)
        ) {
            Icon(
                imageVector = icon,
                contentDescription = null,
                tint = accent.playerMix(Color.White, 0.42f),
                modifier = Modifier.size(16.dp)
            )
            Column(verticalArrangement = Arrangement.spacedBy(3.dp)) {
                Text(
                    text = value,
                    color = Color.White,
                    fontSize = 12.sp,
                    fontWeight = FontWeight.Black
                )
                Text(
                    text = label,
                    color = Color.White.copy(alpha = 0.46f),
                    fontSize = 9.sp,
                    fontWeight = FontWeight.SemiBold,
                    maxLines = 1
                )
            }
        }
    }
}

private enum class LibraryFilter { All, Playlists, Songs, Artists, Downloads }

@Composable
private fun LibraryFilterChips(
    selected: LibraryFilter,
    playlistCount: Int,
    songCount: Int,
    artistCount: Int,
    downloadCount: Int,
    onSelect: (LibraryFilter) -> Unit
) {
    val strings = LocalDerbisStrings.current
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .horizontalScroll(rememberScrollState()),
        horizontalArrangement = Arrangement.spacedBy(9.dp)
    ) {
        LibraryFilterChip(strings.all, Icons.Rounded.LibraryMusic, DerbisCyan, null, selected == LibraryFilter.All) { onSelect(LibraryFilter.All) }
        LibraryFilterChip(cleanLibraryLabel(strings.playlists), Icons.AutoMirrored.Rounded.QueueMusic, DerbisViolet, playlistCount, selected == LibraryFilter.Playlists) { onSelect(LibraryFilter.Playlists) }
        LibraryFilterChip(cleanLibraryLabel(strings.songs), Icons.Rounded.MusicNote, DerbisPink, songCount, selected == LibraryFilter.Songs) { onSelect(LibraryFilter.Songs) }
        LibraryFilterChip(cleanLibraryLabel(strings.artists), Icons.Rounded.Person, CinematicGold, artistCount, selected == LibraryFilter.Artists) { onSelect(LibraryFilter.Artists) }
        LibraryFilterChip(cleanLibraryLabel(strings.downloads), Icons.Rounded.DownloadDone, DerbisCyan, downloadCount, selected == LibraryFilter.Downloads) { onSelect(LibraryFilter.Downloads) }
    }
}

@Composable
private fun LibraryFilterChip(
    label: String,
    icon: ImageVector,
    accent: Color,
    count: Int?,
    selected: Boolean,
    onClick: () -> Unit
) {
    val background = if (selected) accent.copy(alpha = 0.18f) else CinematicGlass.copy(alpha = 0.5f)
    val borderColor = if (selected) accent.copy(alpha = 0.55f) else Color.White.copy(alpha = 0.08f)
    val contentColor = if (selected) DerbisText else DerbisMuted
    val chipShape = RoundedCornerShape(999.dp)
    val liquidGlass = DerbisIsLiquidGlass
    Surface(
        color = if (liquidGlass) Color.Transparent else background,
        border = if (liquidGlass) null else BorderStroke(1.dp, borderColor),
        shape = chipShape,
        modifier = Modifier
            .pressable(onClick = onClick)
            .then(
                if (liquidGlass) {
                    Modifier.derbisGlass(
                        shape = chipShape,
                        baseTint = if (selected) accent else Color.White,
                        fallbackColor = background,
                        fallbackBorderColor = borderColor,
                        intensity = DerbisGlassIntensity.Subtle,
                        artworkTint = DerbisActivePalette.cyan
                    )
                } else {
                    Modifier
                }
            )
    ) {
        Row(
            modifier = Modifier.padding(horizontal = 13.dp, vertical = 9.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(7.dp)
        ) {
            Icon(icon, null, tint = if (selected) accent else DerbisMuted, modifier = Modifier.size(16.dp))
            Text(label, color = contentColor, fontSize = 13.sp, fontWeight = FontWeight.Bold, maxLines = 1)
            if (count != null && count > 0) {
                Text(count.toString(), color = if (selected) accent else DerbisMuted.copy(alpha = 0.75f), fontSize = 12.sp, fontWeight = FontWeight.Black)
            }
        }
    }
}

@Composable
private fun LibraryHeader(
    title: String,
    subtitle: String,
    playlistCount: Int,
    downloadCount: Int,
    favoriteCount: Int
) {
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(top = 4.dp),
        verticalArrangement = Arrangement.spacedBy(14.dp)
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            verticalAlignment = Alignment.Bottom,
            horizontalArrangement = Arrangement.SpaceBetween
        ) {
            Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(4.dp)) {
                Text(
                    text = title,
                    color = DerbisText,
                    fontSize = 35.sp,
                    lineHeight = DerbisTypeRhythm.lineHeight(35.sp),
                    fontWeight = FontWeight.Black,
                    letterSpacing = (-0.7).sp
                )
                Text(
                    text = subtitle,
                    color = DerbisMuted.copy(alpha = 0.84f),
                    fontSize = 14.sp,
                    lineHeight = DerbisTypeRhythm.lineHeight(14.sp),
                    fontWeight = FontWeight.SemiBold,
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis
                )
            }
            Box(
                modifier = Modifier
                    .size(48.dp)
                    .clip(CircleShape)
                    .background(Brush.linearGradient(listOf(DerbisCyan.copy(alpha = 0.24f), DerbisViolet.copy(alpha = 0.20f))))
                    .border(1.dp, Color.White.copy(alpha = 0.12f), CircleShape),
                contentAlignment = Alignment.Center
            ) {
                Icon(Icons.Rounded.LibraryMusic, null, tint = DerbisCyan, modifier = Modifier.size(25.dp))
            }
        }
        val strings = LocalDerbisStrings.current
        Row(
            modifier = Modifier.horizontalScroll(rememberScrollState()),
            horizontalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            LibraryStatPill(Icons.AutoMirrored.Rounded.QueueMusic, playlistCount.toString(), strings.playlistsPlain, DerbisViolet)
            LibraryStatPill(Icons.Rounded.DownloadDone, downloadCount.toString(), strings.offline, DerbisCyan)
            LibraryStatPill(Icons.Rounded.Favorite, favoriteCount.toString(), strings.favoritesPlain, DerbisPink)
        }
    }
}

@Composable
private fun LibraryStatPill(icon: ImageVector, value: String, label: String, accent: Color) {
    val pillShape = RoundedCornerShape(999.dp)
    val liquidGlass = DerbisIsLiquidGlass
    Surface(
        color = if (liquidGlass) Color.Transparent else CinematicGlass.copy(alpha = 0.54f),
        border = if (liquidGlass) null else BorderStroke(1.dp, Color.White.copy(alpha = 0.085f)),
        shape = pillShape,
        modifier = if (liquidGlass) {
            Modifier.derbisGlass(
                shape = pillShape,
                baseTint = accent,
                fallbackColor = CinematicGlass.copy(alpha = 0.54f),
                fallbackBorderColor = Color.White.copy(alpha = 0.22f),
                intensity = DerbisGlassIntensity.Subtle,
                artworkTint = DerbisActivePalette.cyan
            )
        } else {
            Modifier
        }
    ) {
        Row(
            modifier = Modifier.padding(horizontal = 12.dp, vertical = 8.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(7.dp)
        ) {
            Icon(icon, null, tint = accent, modifier = Modifier.size(16.dp))
            Text(value, color = DerbisText, fontSize = 13.sp, fontWeight = FontWeight.Black)
            Text(label, color = DerbisMuted, fontSize = 12.sp, fontWeight = FontWeight.Bold)
        }
    }
}

@Composable
private fun ListeningPulseCard(pulse: ListeningPulse, strings: DerbisStrings) {
    val locale = remember(strings.code) { Locale.forLanguageTag(strings.code) }
    val percent = remember(locale) { java.text.NumberFormat.getPercentInstance(locale) }
    Surface(
        modifier = Modifier.fillMaxWidth(),
        color = CinematicGlass.copy(alpha = 0.6f),
        border = BorderStroke(1.dp, Color.White.copy(alpha = 0.09f)),
        shape = RoundedCornerShape(22.dp)
    ) {
        Column(
            modifier = Modifier.padding(18.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            if (!pulse.hasSignal) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    Icon(Icons.Rounded.Insights, null, tint = DerbisCyan, modifier = Modifier.size(22.dp))
                    Text(
                        text = strings.pulseEmpty,
                        color = DerbisMuted,
                        fontSize = 14.sp,
                        fontWeight = FontWeight.SemiBold
                    )
                }
                return@Column
            }
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                PulseStat(
                    modifier = Modifier.weight(1f),
                    icon = Icons.Rounded.Headphones,
                    value = pulse.totalMinutes.toString(),
                    label = strings.pulseMinutes,
                    accent = DerbisCyan
                )
                PulseStat(
                    modifier = Modifier.weight(1f),
                    icon = Icons.Rounded.PlayArrow,
                    value = pulse.plays.toString(),
                    label = strings.pulsePlays,
                    accent = DerbisViolet
                )
                PulseStat(
                    modifier = Modifier.weight(1f),
                    icon = Icons.Rounded.LocalFireDepartment,
                    value = pulse.streakDays.toString(),
                    label = strings.pulseStreak,
                    accent = DerbisOrange
                )
                PulseStat(
                    modifier = Modifier.weight(1f),
                    icon = Icons.Rounded.TaskAlt,
                    value = percent.format(pulse.completionRate / 100.0),
                    label = strings.pulseCompletion,
                    accent = DerbisPink
                )
            }
            PulseWeekChart(pulse = pulse, label = strings.pulseWeek, languageCode = strings.code)
            if (pulse.topArtists.isNotEmpty()) {
                PulseArtistsRow(artists = pulse.topArtists, label = strings.pulseTopArtists, minuteShort = strings.pulseMinuteShort)
            }
            if (pulse.peakHour >= 0) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    Icon(Icons.Rounded.Schedule, null, tint = DerbisMuted, modifier = Modifier.size(15.dp))
                    Text(
                        text = "${strings.pulsePeakHour} · ${pulse.peakHour.toString().padStart(2, '0')}:00",
                        color = DerbisMuted,
                        fontSize = 12.sp,
                        fontWeight = FontWeight.Bold
                    )
                }
            }
        }
    }
}

@Composable
private fun PulseStat(
    modifier: Modifier = Modifier,
    icon: ImageVector,
    value: String,
    label: String,
    accent: Color
) {
    Column(
        modifier = modifier
            .clip(RoundedCornerShape(16.dp))
            .background(accent.copy(alpha = 0.10f))
            .border(1.dp, accent.copy(alpha = 0.18f), RoundedCornerShape(16.dp))
            .padding(vertical = 12.dp, horizontal = 6.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(4.dp)
    ) {
        Icon(icon, null, tint = accent, modifier = Modifier.size(17.dp))
        Text(value, color = DerbisText, fontSize = 17.sp, fontWeight = FontWeight.Black, maxLines = 1)
        Text(
            text = label,
            color = DerbisMuted,
            fontSize = 10.sp,
            fontWeight = FontWeight.Bold,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis
        )
    }
}

@Composable
private fun PulseWeekChart(pulse: ListeningPulse, label: String, languageCode: String) {
    val peak = pulse.weekPeakMs
    val locale = remember(languageCode) { Locale.forLanguageTag(languageCode) }
    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
        Text(label, color = DerbisMuted, fontSize = 12.sp, fontWeight = FontWeight.Bold)
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .height(56.dp),
            horizontalArrangement = Arrangement.spacedBy(6.dp),
            verticalAlignment = Alignment.Bottom
        ) {
            pulse.week.forEach { day ->
                val fraction = if (peak > 0L) (day.listenedMs.toFloat() / peak.toFloat()).coerceIn(0.06f, 1f) else 0.06f
                Box(
                    modifier = Modifier
                        .weight(1f)
                        .fillMaxHeight(fraction)
                        .clip(RoundedCornerShape(topStart = 6.dp, topEnd = 6.dp))
                        .background(
                            Brush.verticalGradient(
                                listOf(
                                    DerbisCyan.copy(alpha = if (day.listenedMs > 0L) 0.9f else 0.16f),
                                    DerbisViolet.copy(alpha = if (day.listenedMs > 0L) 0.75f else 0.12f)
                                )
                            )
                        )
                )
            }
        }
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(6.dp)
        ) {
            pulse.week.forEach { day ->
                val dayLabel = day.date.dayOfWeek
                    .getDisplayName(DayTextStyle.SHORT_STANDALONE, locale)
                    .replace(".", "")
                Text(
                    text = dayLabel,
                    color = DerbisMuted.copy(alpha = 0.8f),
                    fontSize = 10.sp,
                    fontWeight = FontWeight.Bold,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.weight(1f)
                )
            }
        }
    }
}

@Composable
