                Text(detail, color = DerbisMuted, fontSize = 12.5.sp, lineHeight = DerbisTypeRhythm.lineHeight(12.5.sp), fontWeight = FontWeight.Medium, maxLines = 2, overflow = TextOverflow.Ellipsis)
