}

private fun cleanLibraryLabel(value: String): String {
    return value.dropWhile { !it.isLetterOrDigit() }.trim()
}

@Composable
private fun DownloadRow(
    download: DownloadedTrack,
    isCurrent: Boolean,
    isPlaying: Boolean,
    position: DerbisConnectedPosition,
    style: DerbisConnectedStyle,
    accent: Color,
    onPlay: () -> Unit,
    onDelete: () -> Unit
) {
    val strings = LocalDerbisStrings.current
    val artworkBrush = remember(accent) {
        Brush.linearGradient(listOf(accent.copy(alpha = 0.32f), DerbisViolet.copy(alpha = 0.28f)))
    }
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .derbisConnectedSurface(position, style, selected = isCurrent)
            .derbisPressable(onClick = onPlay, pressedScale = DerbisPressScale.Row)
            .padding(horizontal = 10.dp, vertical = 9.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(14.dp)
    ) {
        Box(
            modifier = Modifier
                .size(54.dp)
                .clip(DownloadRowArtworkShape)
                .background(artworkBrush),
            contentAlignment = Alignment.Center
        ) {
            if (isCurrent) {
                DerbisPlayingIndicator(
                    playing = isPlaying,
                    color = accent,
                    size = 20.dp,
                    contentDescription = strings.playing
                )
            } else {
                Icon(Icons.Rounded.DownloadDone, null, tint = accent, modifier = Modifier.size(24.dp))
            }
        }
        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
            Text(download.title, color = if (isCurrent) accent else DerbisText, fontSize = 16.sp, fontWeight = FontWeight.Black, maxLines = 1, overflow = TextOverflow.Ellipsis)
            Text(download.artist, color = DerbisMuted, fontSize = 14.sp, fontWeight = FontWeight.Medium, maxLines = 1, overflow = TextOverflow.Ellipsis)
            Text(
                if (download.embeddedMetadata) "Music/Derbis · ${LocalDerbisStrings.current.coverAndTags}" else "Music/Derbis",
                color = DerbisMuted.copy(alpha = 0.7f),
                fontSize = 11.sp,
                fontWeight = FontWeight.SemiBold,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
        }
        IconButton(onClick = onDelete) {
            Icon(Icons.Rounded.Delete, contentDescription = LocalDerbisStrings.current.remove, tint = DerbisMuted, modifier = Modifier.size(22.dp))
        }
    }
}

