@Composable
private fun AddToPlaylistDialog(
    track: Track,
    playlists: List<com.yasuda.derbis.domain.Playlist>,
    onDismiss: () -> Unit,
    onAddTo: (String) -> Unit,
    onCreateWith: (String) -> Unit
) {
    val strings = LocalDerbisStrings.current
    var creating by remember { mutableStateOf(false) }
    var name by remember { mutableStateOf("") }
    var playlistQuery by remember { mutableStateOf("") }
    val visiblePlaylists = remember(playlists, playlistQuery) {
        val query = playlistQuery.trim()
        if (query.isBlank()) playlists else playlists.filter { playlist ->
            playlist.name.contains(query, ignoreCase = true)
        }
    }
    AlertDialog(
        onDismissRequest = onDismiss,
        containerColor = DerbisPanel,
        title = { Text(LocalDerbisStrings.current.addToPlaylist, color = DerbisText, fontWeight = FontWeight.Black) },
        text = {
            Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                if (creating) {
                    OutlinedTextField(
                        value = name,
                        onValueChange = { name = it },
                        singleLine = true,
                        placeholder = { Text(LocalDerbisStrings.current.newPlaylistName, color = DerbisMuted) },
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedTextColor = DerbisText,
                            unfocusedTextColor = DerbisText,
                            focusedBorderColor = DerbisCyan,
                            unfocusedBorderColor = DerbisMuted.copy(alpha = 0.4f),
                            cursorColor = DerbisCyan
                        )
                    )
                } else {
                    OutlinedTextField(
                        value = playlistQuery,
                        onValueChange = { playlistQuery = it },
                        singleLine = true,
                        modifier = Modifier.fillMaxWidth(),
                        placeholder = { Text(strings.searchPlaceholder, color = DerbisMuted) },
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedTextColor = DerbisText,
                            unfocusedTextColor = DerbisText,
                            focusedBorderColor = DerbisCyan,
                            unfocusedBorderColor = DerbisMuted.copy(alpha = 0.4f),
                            cursorColor = DerbisCyan
                        )
                    )
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(8.dp))
                            .clickable { creating = true }
                            .padding(vertical = 10.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        Icon(Icons.Rounded.Add, null, tint = DerbisCyan)
                        Text(LocalDerbisStrings.current.createNewPlaylist, color = DerbisCyan, fontWeight = FontWeight.Bold)
                    }
                    visiblePlaylists.forEach { pl ->
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(RoundedCornerShape(8.dp))
                                .clickable { onAddTo(pl.id) }
                                .padding(vertical = 10.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(10.dp)
                        ) {
                            Icon(Icons.AutoMirrored.Rounded.QueueMusic, null, tint = DerbisMuted)
                            Text(pl.name, color = DerbisText, fontWeight = FontWeight.SemiBold, maxLines = 1, overflow = TextOverflow.Ellipsis)
                        }
                    }
                    if (visiblePlaylists.isEmpty() && playlistQuery.isNotBlank()) {
                        Text(strings.formatNoSearchResults(playlistQuery), color = DerbisMuted, fontSize = 13.sp)
                    }
                }
            }
        },
        confirmButton = {
            if (creating) {
                TextButton(onClick = { if (name.isNotBlank()) onCreateWith(name) }) {
                    Text(LocalDerbisStrings.current.createAndAdd, color = DerbisCyan, fontWeight = FontWeight.Bold)
                }
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) { Text(strings.close, color = DerbisMuted) }
        }
    )
}

@Composable
private fun PlaylistDetailOverlay(viewModel: DerbisViewModel, state: DerbisUiState) {
    val playlist = state.openPlaylist ?: return
    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(DerbisInk)
    ) {
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .statusBarsPadding(),
            contentPadding = PaddingValues(start = 16.dp, end = 16.dp, top = 8.dp, bottom = derbisTabContentBottomPadding(state.currentTrack != null)),
            verticalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            item {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    DerbisBackButton(onClick = { viewModel.closePlaylist() }, contentDescription = LocalDerbisStrings.current.back)
                    Spacer(Modifier.width(4.dp))
                    Column(modifier = Modifier.weight(1f)) {
                        Text(playlist.name, color = DerbisText, fontSize = 26.sp, fontWeight = FontWeight.Black, maxLines = 1, overflow = TextOverflow.Ellipsis)
                        Text(LocalDerbisStrings.current.formatTrackCount(playlist.size), color = DerbisMuted, fontSize = 14.sp)
                    }
                    if (playlist.tracks.isNotEmpty()) {
                        val shareContext = LocalContext.current
                        val shareStrings = LocalDerbisStrings.current
                        IconButton(
                            onClick = {
                                val link = viewModel.playlistShareLink(playlist)
                                if (link != null) {
                                    val intent = Intent(Intent.ACTION_SEND).apply {
                                        type = "text/plain"
                                        putExtra(Intent.EXTRA_SUBJECT, playlist.name)
                                        putExtra(Intent.EXTRA_TEXT, playlist.name + "\n" + link)
                                    }
                                    shareContext.startActivity(Intent.createChooser(intent, shareStrings.sharePlaylist))
                                }
                            }
                        ) {
                            Icon(
                                Icons.Rounded.Share,
                                contentDescription = shareStrings.sharePlaylist,
                                tint = DerbisCyan,
                                modifier = Modifier.size(25.dp)
                            )
                        }
                        IconButton(onClick = { viewModel.exportOpenPlaylist() }) {
                            Icon(Icons.Rounded.DownloadDone, contentDescription = LocalDerbisStrings.current.downloadPlaylist, tint = DerbisViolet, modifier = Modifier.size(27.dp))
                        }
                        DerbisPlayAllIconButton(onClick = { viewModel.playPlaylist(playlist.id) })
                    }
                }
            }
            if (playlist.tracks.isEmpty()) {
                item { EmptyState(LocalDerbisStrings.current.playlistEmpty) }
            } else {
                itemsIndexed(playlist.tracks, key = { _, track -> "pldetail-${track.id}" }) { index, track ->
                    val current = track.id == state.currentTrack?.id
                    Box(
                        modifier = Modifier
                            .padding(vertical = 1.dp)
                            .clip(derbisGroupedListShape(index, playlist.tracks.size))
                            .background(if (current) DerbisCyan.copy(alpha = 0.14f) else DerbisText.copy(alpha = 0.05f))
                    ) {
                        TrackRow(
                            track = track,
                            isCurrent = track.id == state.currentTrack?.id,
                            isPlaying = state.isPlaying && track.id == state.currentTrack?.id,
                            isResolving = state.isResolving && track.id == state.currentTrack?.id,
                            isFavorite = track.id in state.favoriteIds,
                            onClick = { viewModel.playPlaylist(playlist.id, track.id) },
                            onFavorite = { viewModel.toggleFavorite(track) },
                            isDownloading = track.id in state.downloadingTrackIds,
                            isDownloaded = track.id in state.downloadedTrackIds,
                            downloadProgress = state.downloadProgressByTrackId[track.id],
                            onDownload = { viewModel.exportTrack(track) },
                            onArtist = { viewModel.openArtist(track) },
                            onRemove = { viewModel.removeFromPlaylist(playlist.id, track.id) }
                        )
                    }
                }
            }
        }
        state.currentTrack?.let { current ->
            AlbumNowPlayingDock(
                track = current,
                isPlaying = state.isPlaying,
                isResolving = state.isResolving,
                progress = progressOf(state.positionMs, state.durationMs),
                animated = state.animationsEnabled,
                onToggle = viewModel::togglePlay,
                onOpenPlayer = viewModel::openPlayerScreen,
                modifier = Modifier
                    .align(Alignment.BottomCenter)
                    .navigationBarsPadding()
                    .padding(start = 16.dp, end = 16.dp, bottom = 14.dp)
            )
        }
    }
}

@Composable
private fun PlayerImmersiveBackdrop(
    artworkUrl: String,
    ambience: PlayerAmbience,
    isPlaying: Boolean,
    animationsEnabled: Boolean,
    modifier: Modifier = Modifier
) {
    val context = LocalContext.current
    val primary = animateColorAsState(
        targetValue = ambience.primary,
        animationSpec = if (animationsEnabled) tween(900, easing = LinearOutSlowInEasing) else snap(),
        label = "player-backdrop-primary"
    )
    val secondary = animateColorAsState(
        targetValue = ambience.secondary,
        animationSpec = if (animationsEnabled) tween(900, easing = LinearOutSlowInEasing) else snap(),
        label = "player-backdrop-secondary"
    )
    val base = animateColorAsState(
        targetValue = ambience.base,
        animationSpec = if (animationsEnabled) tween(900, easing = LinearOutSlowInEasing) else snap(),
        label = "player-backdrop-base"
    )
    val imageAlpha by animateFloatAsState(
        targetValue = if (isPlaying) 0.72f else 0.58f,
        animationSpec = if (animationsEnabled) tween(500, easing = FastOutSlowInEasing) else snap(),
        label = "player-backdrop-image-alpha"
    )
    val ambientMatrix = remember { createPlayerAmbientColorMatrix() }
    val ambientColorFilter = remember(ambientMatrix) { ColorFilter.colorMatrix(ambientMatrix) }

    Box(modifier = modifier) {
        Box(modifier = Modifier.fillMaxSize().background(base.value))
        if (artworkUrl.isNotBlank()) {
            AnimatedContent(
                targetState = artworkUrl,
                transitionSpec = {
                    if (animationsEnabled) {
                        fadeIn(tween(440, easing = LinearOutSlowInEasing)) togetherWith
                            fadeOut(tween(300, easing = FastOutSlowInEasing))
                    } else {
                        EnterTransition.None togetherWith ExitTransition.None
                    }
                },
                label = "player-backdrop-artwork"
            ) { url ->
                val ambientImageRequest = remember(context, url) {
                    ImageRequest.Builder(context)
                        .data(DerbisArtworkCache.large(url))
                        .size(512, 512)
                        .diskCachePolicy(CachePolicy.ENABLED)
                        .memoryCachePolicy(CachePolicy.ENABLED)
                        .crossfade(false)
                        .build()
                }
                AsyncImage(
                    model = ambientImageRequest,
                    contentDescription = null,
                    contentScale = ContentScale.Crop,
                    colorFilter = ambientColorFilter,
                    modifier = Modifier
                        .fillMaxSize()
                        .blur(52.dp)
                        .graphicsLayer {
                            scaleX = 1.12f
                            scaleY = 1.12f
                            alpha = imageAlpha
                        }
                )
            }
        }
        Box(
            modifier = Modifier
                .fillMaxSize()
                .drawBehind {
                    val animatedPrimary = primary.value
                    val animatedSecondary = secondary.value
                    val animatedBase = base.value
                    drawRect(
                        Brush.verticalGradient(
                            colorStops = arrayOf(
                                0.00f to animatedBase.copy(alpha = 0.90f),
                                0.18f to animatedPrimary.copy(alpha = 0.26f),
                                0.54f to Color.Transparent,
                                0.78f to animatedSecondary.copy(alpha = 0.22f),
                                1.00f to Color.Black.copy(alpha = 0.88f)
                            )
                        )
                    )
                    drawRect(
                        Brush.radialGradient(
                            colors = listOf(
                                animatedPrimary.copy(alpha = 0.20f),
                                Color.Transparent
                            ),
                            center = Offset(size.width * 0.20f, size.height * 0.16f),
                            radius = size.maxDimension * 0.82f
                        )
                    )
                }
        )
    }
}

@Composable
private fun PlayerArtworkCanvas(
    track: Track,
    artworkUrl: String,
    motionArtwork: com.yasuda.derbis.feature.motion.MotionArtwork?,
    livingArtwork: LivingArtworkColors?,
    animationsEnabled: Boolean,
    isPlaying: Boolean,
    cornerRadius: Dp,
    canvasQuality: DerbisCanvasQuality,
    modifier: Modifier = Modifier
) {
    val context = LocalContext.current
    val artworkShadow by animateDpAsState(
        targetValue = if (isPlaying) 26.dp else 14.dp,
        animationSpec = if (animationsEnabled) tween(420, easing = FastOutSlowInEasing) else snap(),
        label = "player-artwork-shadow"
    )
    val primary = Color(track.accentStart)
    val artworkShape = RoundedCornerShape(cornerRadius)

    Box(modifier = modifier, contentAlignment = Alignment.Center) {
        Box(
            modifier = Modifier
                .fillMaxSize()
                .shadow(
                    elevation = artworkShadow,
                    shape = artworkShape,
                    clip = false,
                    ambientColor = primary.copy(alpha = 0.42f),
                    spotColor = Color.Black.copy(alpha = 0.80f)
                )
                .clip(artworkShape)
                .background(Color.Black.copy(alpha = 0.24f), artworkShape)
        ) {
            MotionArtworkLayer(
                artwork = motionArtwork,
                enabled = animationsEnabled,
                isPlaying = isPlaying,
                cornerRadius = cornerRadius,
                presentation = MotionArtworkPresentation.Card,
                quality = canvasQuality,
                livingArtwork = livingArtwork,
                modifier = Modifier.fillMaxSize()
            ) {
                if (artworkUrl.isNotBlank()) {
                    AsyncImage(
                        model = ImageRequest.Builder(context)
                            .data(artworkUrl)
                            .crossfade(true)
                            .diskCachePolicy(CachePolicy.ENABLED)
                            .memoryCachePolicy(CachePolicy.ENABLED)
                            .build(),
                        contentDescription = null,
                        contentScale = ContentScale.Crop,
                        modifier = Modifier.fillMaxSize()
                    )
                } else {
                    InstantArtworkPlaceholder(modifier = Modifier.fillMaxSize())
                }
            }
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .border(
                        width = DerbisPlayerDesign.Hairline,
                        color = Color.White.copy(alpha = 0.12f),
                        shape = artworkShape
                    )
            )
        }
    }
}

@Composable
