internal fun youtubeCommentCountBadge(value: String): String {
    val normalized = value.replace('\u00A0', ' ').trim()
    if (normalized.isBlank()) return ""
    return CommentCountBadgePattern
        .find(normalized)
        ?.value
        ?.replace(" ", "")
        .orEmpty()
}

