@Composable
private fun PlayerSimilarSongCard(
    track: Track,
    queued: Boolean,
    canPlay: Boolean,
    canAddToQueue: Boolean,
    accent: Color,
    playLabel: String,
    addLabel: String,
    onPlay: () -> Unit,
    onAddToQueue: () -> Unit
) {
    Column(
        modifier = Modifier
            .width(SimilarSongCardWidth)
            .graphicsLayer { alpha = if (canPlay) 1f else SimilarSongDisabledAlpha }
            .pressable(enabled = canPlay, onClick = onPlay),
        verticalArrangement = Arrangement.spacedBy(DerbisPlayerDesign.SpaceSm)
    ) {
        Box(
            modifier = Modifier
                .size(SimilarSongCardWidth)
                .clip(DerbisPlayerDesign.ShapeSm)
                .background(DerbisPanelSoft)
        ) {
            val artworkUrl = track.thumbnailUrl.ifBlank { track.largeThumbnailUrl }
