@Composable
private fun PlayerInlineLyricsSection(
    trackId: String,
    lyrics: List<com.yasuda.derbis.domain.LyricLine>,
    lyricsLoading: Boolean,
    positionMs: Long,
    durationMs: Long,
    primaryContent: Color,
    compact: Boolean,
    strings: DerbisStrings,
    onSeek: (Float) -> Unit
) {
    var showInlineLyrics by remember(trackId) { mutableStateOf(false) }

    when {
        lyrics.isNotEmpty() && !showInlineLyrics -> {
            Surface(
                color = Color.Black.copy(alpha = 0.20f),
                border = BorderStroke(1.dp, Color.White.copy(alpha = 0.10f)),
                shape = RoundedCornerShape(20.dp),
                modifier = Modifier
                    .fillMaxWidth()
                    .pressable { showInlineLyrics = true }
            ) {
                Row(
                    modifier = Modifier.padding(
                        horizontal = 18.dp,
                        vertical = if (compact) 12.dp else 13.dp
                    ),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.SpaceBetween
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Icon(
                            Icons.AutoMirrored.Rounded.Subject,
                            null,
                            tint = primaryContent,
                            modifier = Modifier.size(19.dp)
                        )
                        Spacer(modifier = Modifier.width(9.dp))
                        Text(
                            strings.showLyrics,
                            color = Color.White,
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Bold
                        )
                    }
                    Icon(
                        Icons.AutoMirrored.Rounded.KeyboardArrowRight,
                        null,
                        tint = Color.White.copy(alpha = 0.55f),
                        modifier = Modifier.size(20.dp)
                    )
                }
            }
        }

        lyrics.isNotEmpty() -> {
            val listState = rememberLazyListState()
            val lyricsAnimationsEnabled = LocalAnimationsEnabled.current
            val visualActiveIndex = remember(lyrics, positionMs, lyricsAnimationsEnabled) {
                activeLyricIndex(
                    lyricsLineFocusPositionMs(positionMs, lyricsAnimationsEnabled),
                    lyrics
                )
            }
            var inlineAutoScroll by remember(trackId) { mutableStateOf(true) }
            var inlineAutoScrolling by remember(trackId) { mutableStateOf(false) }

            LaunchedEffect(listState.isScrollInProgress, inlineAutoScrolling) {
                if (listState.isScrollInProgress && !inlineAutoScrolling) {
                    inlineAutoScroll = false
                } else if (!listState.isScrollInProgress && !inlineAutoScrolling && !inlineAutoScroll) {
                    delay(INLINE_LYRICS_AUTOSCROLL_RESUME_MS)
                    inlineAutoScroll = true
                }
            }

            LaunchedEffect(visualActiveIndex, inlineAutoScroll, lyricsAnimationsEnabled) {
                if (visualActiveIndex >= 0 && inlineAutoScroll) {
                    inlineAutoScrolling = true
                    runCatching {
                        val target = maxOf(0, visualActiveIndex - 1)
                        if (lyricsAnimationsEnabled) {
                            listState.animateScrollToItem(target)
                        } else {
                            listState.scrollToItem(target)
                        }
                    }
                    inlineAutoScrolling = false
                }
            }

            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(400.dp)
                    .padding(vertical = 8.dp)
                    .background(Color.Black.copy(alpha = 0.26f), RoundedCornerShape(28.dp))
                    .border(BorderStroke(1.dp, Color.White.copy(alpha = 0.11f)), RoundedCornerShape(28.dp))
            ) {
                LazyColumn(
                    state = listState,
                    modifier = Modifier.fillMaxSize(),
                    contentPadding = PaddingValues(start = 22.dp, end = 22.dp, top = 52.dp, bottom = 28.dp),
                    verticalArrangement = Arrangement.spacedBy(16.dp)
                ) {
                    itemsIndexed(
                        items = lyrics,
                        key = { index, line -> "${line.startMs}-${line.role.name}-$index" }
                    ) { index, line ->
                        val isActive = index == visualActiveIndex
                        val lineColor by animateColorAsState(
                            targetValue = if (isActive) primaryContent else Color.White.copy(alpha = 0.48f),
                            animationSpec = DerbisMotion.spec(lyricsAnimationsEnabled, tween(DerbisMotion.Durations.Short, easing = DerbisMotion.Easings.Decelerate)),
                            label = "inline-lyrics-color"
                        )
                        val lineScale by animateFloatAsState(
                            targetValue = if (isActive) 1.02f else 1f,
                            animationSpec = DerbisMotion.physics(lyricsAnimationsEnabled, DerbisMotion.spatial),
                            label = "inline-lyrics-scale"
                        )
                        Text(
                            text = line.text,
                            color = lineColor,
                            fontSize = if (isActive) 24.sp else 19.sp,
                            lineHeight = if (isActive) 29.sp else 24.sp,
                            fontWeight = if (isActive) FontWeight.Black else FontWeight.Medium,
                            modifier = Modifier
                                .graphicsLayer {
                                    scaleX = lineScale
                                    scaleY = lineScale
                                    transformOrigin = TransformOrigin(0f, 0.5f)
                                }
                                .clickable {
                                    onSeek(progressOf(line.startMs, durationMs))
                                }
                        )
                    }
                }
                IconButton(
                    onClick = { showInlineLyrics = false },
                    modifier = Modifier
                        .align(Alignment.TopEnd)
                        .padding(8.dp)
                ) {
                    Icon(
                        Icons.Rounded.Close,
                        strings.close,
                        tint = Color.White.copy(alpha = 0.62f)
                    )
                }
            }
        }

        lyricsLoading -> {
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(104.dp)
                    .background(Color.Black.copy(alpha = 0.22f), RoundedCornerShape(24.dp))
                    .border(BorderStroke(1.dp, Color.White.copy(alpha = 0.10f)), RoundedCornerShape(24.dp)),
                contentAlignment = Alignment.Center
            ) {
                CircularProgressIndicator(
                    color = primaryContent,
                    strokeWidth = 3.dp
                )
            }
        }
    }
}


internal data class MiniPlayerModel(
    val track: Track,
    val isPlaying: Boolean,
    val isResolving: Boolean,
    val progress: Float,
    val bufferedProgress: Float,
    val liveNowPlaying: String,
    val animated: Boolean,
    val gesturesEnabled: Boolean,
    val swipeTrackChangeEnabled: Boolean,
    val stepDirection: Int
)

internal data class MiniPlayerPlaybackActions(
    val open: () -> Unit,
    val toggle: () -> Unit,
    val next: () -> Unit,
    val previous: () -> Unit,
    val close: () -> Unit
)

internal data class MiniPlayerExpansionActions(
    val start: () -> Unit,
    val drag: (Float) -> Unit,
    val end: (Float) -> Unit
)

@Composable
private fun PlayerScreen(
    viewModel: PlayerViewModel,
    state: DerbisUiState,
    morphAnchors: PlayerMorphAnchors,
    morphActive: () -> Boolean,
    collapseActions: PlayerCollapseActions,
    motionSuspended: Boolean
) {
    val track = state.currentTrack
    val strings = LocalDerbisStrings.current
    var playlistTarget by remember(track?.id) { mutableStateOf<Track?>(null) }
    val queuedTrackIds = remember(state.queue) {
        state.queue.mapTo(HashSet(state.queue.size)) { it.id }
    }
    val visibleSimilarSongs = remember(state.similarSongs, state.artistExclusions) {
        state.artistExclusions.filterTracks(state.similarSongs)
    }

    DerbisNowPlaying(
        viewModel = viewModel,
        state = state,
        morphAnchors = morphAnchors,
        morphActive = morphActive,
        collapseActions = collapseActions,
        motionSuspended = motionSuspended,
        gestureLayerContent = { activeTrack, config, mediaActions, uiActions, videoTransform, modifier ->
            PlayerGestureLayer(
                config = config,
                mediaActions = mediaActions,
                uiActions = uiActions,
                videoTransform = videoTransform,
                modifier = modifier
            )
        },
        // Keep Now Playing focused on playback. Engagement and comments are not rendered as
        // provider-style buttons beneath the track metadata.
        engagementContent = { _ -> },
        similarSongsContent = { activeTrack ->
            PlayerSimilarSongsSection(
                similarSongs = visibleSimilarSongs,
                queuedTrackIds = queuedTrackIds,
                canPlayNow = !state.jam.isActive || state.jam.canControlPlayback,
                canAddToQueue = !state.jam.isActive || state.jam.canAddTracks,
                loading = state.similarSongsLoading,
                radioEnabled = state.radioEnabled,
                accent = Color(activeTrack.accentStart).playerMix(Color.White, 0.48f),
                compact = false,
                strings = strings,
                onPlay = viewModel::playSimilarSong,
                onAddToQueue = viewModel::addToQueue,
                onStartRadio = viewModel::startSongRadio
            )
        },
        errorContent = {
            PlayerError(state.playerError)
        },
        playlistDialogContent = {
            playlistTarget?.let { target ->
                AddToPlaylistDialog(
                    track = target,
                    playlists = state.playlists,
                    onDismiss = { playlistTarget = null },
                    onAddTo = { playlistId ->
                        viewModel.addToPlaylist(playlistId, target)
                        playlistTarget = null
                    },
                    onCreateWith = { name ->
                        viewModel.createPlaylist(name, target)
                        playlistTarget = null
                    }
                )
            }
        },
        onOpenPlaylistDialog = { selected -> playlistTarget = selected }
    )
}

@Composable
private fun PlayerGestureLayer(
    config: PlayerGestureConfig,
    mediaActions: PlayerGestureMediaActions,
    uiActions: PlayerGestureUiActions,
    videoTransform: MutableState<PlayerVideoTransform>? = null,
    modifier: Modifier = Modifier
) {
    val environment = config.environment
    val zoomModifier = if (videoTransform == null) {
        modifier
    } else {
        modifier.playerVideoZoomGestures(
            key = config.trackId,
            enabled = true,
            transform = videoTransform,
            onTakeOver = { mediaActions.swipeSettled(false) },
            onTransform = { zoomChange, pan, sizePx ->
                videoTransform.value = videoTransform.value
                    .applyPlayerVideoGesture(zoomChange, pan, sizePx)
            }
        )
    }
    // Tap, long-press, and vertical swipe shortcuts were retired. Horizontal track switching is
    // retained as its own explicit setting, while video pinch/drag transforms remain independent.
    val inputModifier = zoomModifier.playerAxisDragGestures(
        key = "${config.trackId}:${config.settings.swipeTrackChangeEnabled}",
        enabled = config.settings.swipeTrackChangeEnabled,
        rightToLeft = environment.rightToLeft,
        edgeZonesEnabled = false,
        verticalEnabled = false
    ) { event ->
        handlePlayerHorizontalGesture(event, mediaActions)
    }
    Box(modifier = inputModifier)
}

private fun handlePlayerHorizontalGesture(
    event: PlayerDragEvent,
    mediaActions: PlayerGestureMediaActions
) {
    when (event) {
        is PlayerDragEvent.HorizontalOffset -> mediaActions.swipeOffset(event.offsetPx)
        is PlayerDragEvent.HorizontalSettled -> settlePlayerHorizontalGesture(event, mediaActions)
        PlayerDragEvent.Cancelled -> mediaActions.swipeSettled(false)
        is PlayerDragEvent.VerticalStart,
        is PlayerDragEvent.VerticalDrag,
        is PlayerDragEvent.VerticalSettled -> Unit
    }
}

private fun settlePlayerHorizontalGesture(
    event: PlayerDragEvent.HorizontalSettled,
    mediaActions: PlayerGestureMediaActions
) {
    when (event.result) {
        PlayerSwipeResult.Next -> mediaActions.next()
        PlayerSwipeResult.Previous -> mediaActions.previous()
        PlayerSwipeResult.Settle -> Unit
    }
    mediaActions.swipeSettled(event.result != PlayerSwipeResult.Settle)
}

@Composable
private fun PlayerTimeline(
    positionMs: Long,
    bufferedPositionMs: Long,
    durationMs: Long,
    activeColor: Color,
    secondaryColor: Color,
    isPlaying: Boolean,
    animationsEnabled: Boolean,
    compact: Boolean,
    onSeek: (Float) -> Unit
) {
    Column(modifier = Modifier.fillMaxWidth()) {
        PremiumSeekbar(
            positionMs = positionMs,
            durationMs = durationMs,
            bufferedPositionMs = bufferedPositionMs,
            isPlaying = isPlaying,
            onSeekTo = { seekMs ->
                if (durationMs > 0L) {
                    onSeek((seekMs.toFloat() / durationMs.toFloat()).coerceIn(0f, 1f))
                }
            },
            activeColor = activeColor,
            trailingColor = secondaryColor,
            inactiveColor = DerbisPlayerDesign.TrackInactive,
            animated = animationsEnabled
        )
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = DerbisPlayerDesign.SpaceXxs),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(
                text = formatSeekbarMillis(positionMs),
                color = DerbisPlayerDesign.TextSecondary,
                fontSize = if (compact) 11.sp else 11.5.sp,
                fontWeight = FontWeight.Medium,
                letterSpacing = 0.3.sp
            )
            Text(
                text = if (durationMs > 0L) formatSeekbarMillis(durationMs) else formatDuration(durationMs),
                color = DerbisPlayerDesign.TextTertiary,
                fontSize = if (compact) 11.sp else 11.5.sp,
                fontWeight = FontWeight.Medium,
                letterSpacing = 0.3.sp
            )
        }
    }
}

@Composable
private fun PlayerOptionsRow(
    speed: Float,
    sleepMinutes: Int,
    sleepTimerEndOfTrack: Boolean,
    audioNormalization: Boolean,
    activeColor: Color,
    secondaryColor: Color,
    compact: Boolean,
    onSpeed: () -> Unit,
    onSleep: () -> Unit,
    onNormalization: () -> Unit,
    onAmbient: () -> Unit
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(
                top = if (compact) 1.dp else 2.dp,
                bottom = if (compact) 3.dp else 4.dp
            ),
        horizontalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        OptionChip(
            icon = Icons.Rounded.GraphicEq,
            label = LocalDerbisStrings.current.normalizationShort,
            active = audioNormalization,
            activeColor = activeColor,
            modifier = Modifier.weight(1f),
            compact = compact,
            onClick = onNormalization
        )
        OptionChip(
            icon = Icons.Rounded.Speed,
            label = "${trimSpeed(speed)}x",
            active = speed != 1f,
            activeColor = activeColor.playerMix(secondaryColor, 0.35f),
            modifier = Modifier.weight(1f),
            compact = compact,
            onClick = onSpeed
        )
        OptionChip(
            icon = Icons.Rounded.Bedtime,
            label = when {
                sleepTimerEndOfTrack -> LocalDerbisStrings.current.sleepTimerEndOfTrack
                sleepMinutes > 0 -> LocalDerbisStrings.current.formatSleepTimerMinutes(sleepMinutes)
                else -> LocalDerbisStrings.current.timer
            },
            active = sleepMinutes > 0 || sleepTimerEndOfTrack,
            activeColor = secondaryColor,
            modifier = Modifier.weight(1f),
            compact = compact,
            onClick = onSleep
        )
        OptionChip(
            icon = Icons.Rounded.Nightlight,
            label = LocalDerbisStrings.current.ambientMode,
            active = false,
            activeColor = secondaryColor,
            modifier = Modifier.weight(1f),
            compact = compact,
            onClick = onAmbient
        )
    }
}

@Composable
private fun OptionChip(
    icon: ImageVector,
    label: String,
    active: Boolean,
    activeColor: Color,
    modifier: Modifier,
    compact: Boolean,
    enabled: Boolean = true,
    onClick: () -> Unit
) {
    val alpha by animateFloatAsState(
        targetValue = if (enabled) 1f else 0.5f,
        animationSpec = spring(dampingRatio = 0.8f, stiffness = 400f),
        label = "player-option-alpha"
    )
    val background = if (active) activeColor.copy(alpha = 0.28f) else Color.Black.copy(alpha = 0.20f)
    val effectiveBackground = background.playerCompositeOver(PlayerDarkSurface)
    val contentColor = if (active) {
        activeColor.playerContentColor(listOf(effectiveBackground))
    } else {
        Color.White.playerContentColor(listOf(effectiveBackground))
    }
    val borderColor = if (active) activeColor.copy(alpha = 0.58f) else Color.White.copy(alpha = 0.10f)

    Surface(
        color = background,
        border = BorderStroke(DerbisPlayerDesign.Hairline, borderColor),
        shape = DerbisPlayerDesign.ShapeSm,
        modifier = modifier
            .height(if (compact) 40.dp else 42.dp)
            .graphicsLayer { this.alpha = alpha }
            .pressable(enabled = enabled, onClick = onClick)
    ) {
        Row(
            modifier = Modifier.fillMaxSize(),
            horizontalArrangement = Arrangement.Center,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Icon(
                icon,
                null,
                tint = contentColor,
                modifier = Modifier.size(if (compact) 16.dp else 16.dp)
            )
            Spacer(modifier = Modifier.width(if (compact) 6.dp else 6.dp))
            Text(
                text = label,
                color = contentColor,
                fontSize = if (compact) 11.5.sp else 12.sp,
                fontWeight = FontWeight.Bold,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
        }
    }
}

@Composable
private fun ShareOptionChip(track: Track, modifier: Modifier = Modifier) {
    val context = LocalContext.current
    val strings = LocalDerbisStrings.current
    Surface(
        color = Color.White.copy(alpha = 0.06f),
        border = BorderStroke(1.dp, Color.White.copy(alpha = 0.1f)),
        shape = CircleShape,
        modifier = modifier
            .size(48.dp)
            .pressable {
                val link = track.videoUrl.ifBlank { "https://music.youtube.com/watch?v=${track.id}" }
                val intent = Intent(Intent.ACTION_SEND).apply {
                    type = "text/plain"
                    putExtra(Intent.EXTRA_SUBJECT, "${track.title} — ${track.artist}")
                    putExtra(Intent.EXTRA_TEXT, "${track.title} — ${track.artist}\n$link")
                }
                context.startActivity(Intent.createChooser(intent, strings.shareSong))
            }
    ) {
        Box(contentAlignment = Alignment.Center) {
            Icon(Icons.Rounded.Share, null, tint = DerbisText, modifier = Modifier.size(20.dp))
        }
    }
}

private fun trimSpeed(speed: Float): String {
    return if (speed % 1f == 0f) speed.toInt().toString() else speed.toString().trimEnd('0').trimEnd('.')
}

@Composable
private fun LanguageSelector(selectedCode: String, onSelect: (String) -> Unit, modifier: Modifier = Modifier) {
    Column(
        modifier = modifier.fillMaxWidth(),
        verticalArrangement = Arrangement.spacedBy(10.dp)
    ) {
        DerbisLanguageCatalog.languages.forEach { language ->
            val selected = language.code == DerbisLanguageCatalog.normalize(selectedCode)
            val scale by animateFloatAsState(
                targetValue = if (selected) 1.02f else 1f,
                animationSpec = spring(dampingRatio = 0.6f, stiffness = 300f),
                label = "scale"
            )
            val rowColor by animateColorAsState(
                targetValue = if (selected) DerbisCyan else DerbisAdaptiveCardDeep,
                animationSpec = tween(200),
                label = "language-row"
            )

            Surface(
                color = rowColor,
                shape = RoundedCornerShape(22.dp),
                border = BorderStroke(
                    width = 1.dp,
                    color = if (selected) DerbisCyan else DerbisAdaptiveHairline
                ),
                modifier = Modifier
                    .fillMaxWidth()
                    .scale(scale)
                    .pressable(onClick = { onSelect(language.code) })
            ) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 16.dp, vertical = 16.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(16.dp)
                ) {
                    Surface(
                        color = if (selected) Color.White.copy(alpha = 0.2f) else Color.White.copy(alpha = 0.05f),
                        shape = CircleShape,
                        modifier = Modifier.size(42.dp)
                    ) {
                        Box(contentAlignment = Alignment.Center) {
                            Text(
                                text = language.flag,
                                fontSize = 18.sp
                            )
                        }
                    }
                    Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
                        Text(
                            text = language.nativeName,
                            color = if (selected) DerbisBlack else DerbisText,
                            fontSize = 16.sp,
                            fontWeight = FontWeight.Bold,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                        if (!language.englishName.equals(language.nativeName, ignoreCase = true)) {
                            Text(
                                text = language.englishName,
                                color = if (selected) DerbisBlack.copy(alpha = 0.6f) else DerbisMuted,
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Medium,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis
                            )
                        }
                    }

                    AnimatedVisibility(
                        visible = selected,
                        enter = scaleIn(spring(dampingRatio = 0.5f, stiffness = 400f)) + fadeIn(),
                        exit = scaleOut() + fadeOut()
                    ) {
                        Surface(
                            color = DerbisBlack,
                            shape = CircleShape,
                            modifier = Modifier.size(28.dp)
                        ) {
                            Box(contentAlignment = Alignment.Center) {
                                Icon(Icons.Rounded.Check, contentDescription = null, tint = DerbisCyan, modifier = Modifier.size(16.dp))
                            }
                        }
                    }
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
private fun SettingsOverlay(
    onExitApplication: () -> Unit,
    backEnabled: Boolean,
    miniPlayerVisible: Boolean,
    animationsEnabled: Boolean,
    dynamicColor: Boolean,
    sponsorBlock: Boolean,
    skipSilence: Boolean,
    updateInfo: AppUpdateInfo?,
    isCheckingUpdates: Boolean,
    currentLanguageCode: String,
    themePreset: String,
    interfaceSettings: DerbisInterfaceSettings,
    ambientSettings: DerbisAmbientSettings,
    excludedArtists: List<ExcludedArtist>,
    downloadSettings: DerbisDownloadSettings,
    smartOfflineSettings: DerbisSmartOfflineSettings,
    advancedQueuePrefetchTracks: Int,
    advancedQueuePrefetchOnMobileData: Boolean,
    backupSettings: DerbisBackupSettings,
    automationSettings: DerbisAutomationSettings,
    vaultStatus: DerbisVaultStatus,
    lastBackupAtMs: Long,
    backupLocationUri: String?,
    downloadQueue: List<OfflineDownloadTask>,
    playbackDiagnostics: String,
    lastFmConfigured: Boolean,
    lastFmAuthorizationPending: Boolean,
    listenBrainzConfigured: Boolean,
    audDConfigured: Boolean,
    networkSettings: DerbisNetworkSettings,
    networkProxyPasswordSet: Boolean,
    networkTesting: Boolean,
    networkTestOutcome: DerbisNetworkTestOutcome?,
    networkErrors: List<DerbisNetworkSettingsError>,
    lyricsProviderOrdering: LyricsProviderOrdering,
    onNetworkSettings: (DerbisNetworkSettings, String?) -> Unit,
    onTestNetwork: (DerbisNetworkSettings, String?) -> Unit,
    onLyricsProviderOrdering: (LyricsProviderOrdering) -> Unit,
    onOpenJam: () -> Unit,
    onOpenThemeStudio: () -> Unit,
    onOpenLyricsStudio: () -> Unit = {},
    homeStudioStyle: HomeStyle = HomeStyle.Original,
    onOpenHomeStudio: () -> Unit = {},
    miniPlayerStyle: MiniPlayerStyle = MiniPlayerStyle.Original,
    onOpenMiniPlayerStudio: () -> Unit = {},
    navigationStyle: NavStyle = NavStyle.Original,
    onOpenNavigationStudio: () -> Unit = {},
    onOpenAudioSettings: () -> Unit,
    onInterfaceSettings: (DerbisInterfaceSettings) -> Unit,
    onAmbientSettings: (DerbisAmbientSettings) -> Unit,
    onOpenAmbient: () -> Unit,
    onIncludeArtist: (ExcludedArtist) -> Unit,
    onDownloadSettings: (DerbisDownloadSettings) -> Unit,
    onSmartOfflineSettings: (DerbisSmartOfflineSettings) -> Unit,
    onRefreshSmartOffline: () -> Unit,
    onAdvancedQueuePrefetch: (Int) -> Unit,
    onAdvancedQueuePrefetchOnMobileData: (Boolean) -> Unit,
    onSelectDownloadLocation: () -> Unit,
    onClearDownloadLocation: () -> Unit,
    onBackupSettings: (DerbisBackupSettings) -> Unit,
    onAutomationSettings: (DerbisAutomationSettings) -> Unit,
    onAnimations: (Boolean) -> Unit,
    motionArtworkEnabled: Boolean,
    onMotionArtwork: (Boolean) -> Unit,
    onDynamicColor: (Boolean) -> Unit,
    onSponsorBlock: (Boolean) -> Unit,
    onSkipSilence: (Boolean) -> Unit,
    onLanguage: (String) -> Unit,
    onCheckUpdates: () -> Unit,
    onDownloadUpdate: () -> Unit,
    onOpenVersionHistory: () -> Unit,
    onCreateBackup: () -> Unit,
    onRestoreBackup: () -> Unit,
    onBackupNow: () -> Unit,
    onManageBackups: () -> Unit,
    onSelectBackupLocation: () -> Unit,
    onClearBackupLocation: () -> Unit,
    onPauseDownload: (String) -> Unit,
    onResumeDownload: (String) -> Unit,
    onCancelDownload: (String) -> Unit,
    onShareDiagnostics: () -> Unit,
    onOpenPlaybackDiagnostics: () -> Unit,
    onBeginLastFm: (String, String) -> Unit,
    onCompleteLastFm: () -> Unit,
    onClearLastFm: () -> Unit,
    onSaveListenBrainz: (String) -> Unit,
    onClearListenBrainz: () -> Unit,
    onSaveAudD: (String) -> Unit,
    onClearAudD: () -> Unit,
    onRedoQuestionnaire: () -> Unit,
    profilePhotoSet: Boolean,
    onPickProfilePhoto: () -> Unit,
    onRemoveProfilePhoto: () -> Unit,
    onOpenYoutubeMusic: () -> Unit,
    onClose: () -> Unit
) {
    val strings = LocalDerbisStrings.current
    val automationCopy = strings.automationCopy()
    var languageExpanded by remember { mutableStateOf(false) }
    var activeCategory by rememberSaveable { mutableStateOf<String?>(null) }
    var settingsQuery by rememberSaveable { mutableStateOf("") }
    val batteryContext = LocalContext.current
    val batteryLifecycleOwner = LocalLifecycleOwner.current
    var batteryCheckToken by remember { mutableStateOf(0) }
    val batteryUnrestricted = remember(batteryCheckToken) {
        batteryContext.getSystemService(PowerManager::class.java)
        ?.isIgnoringBatteryOptimizations(batteryContext.packageName) == true
    }
    var selectedDownloadFolderName by remember(downloadSettings.destinationTreeUri) { mutableStateOf<String?>(null) }
    LaunchedEffect(downloadSettings.destinationTreeUri, batteryCheckToken) {
        selectedDownloadFolderName = if (downloadSettings.destinationTreeUri.isBlank()) {
            null
        } else {
            withContext(Dispatchers.IO) {
                DownloadFolderAccess.displayName(batteryContext, downloadSettings.destinationTreeUri)
            }
        }
    }
    DisposableEffect(batteryLifecycleOwner) {
        val observer = LifecycleEventObserver { _, event ->
            if (event == Lifecycle.Event.ON_RESUME) batteryCheckToken++
        }
        batteryLifecycleOwner.lifecycle.addObserver(observer)
        onDispose { batteryLifecycleOwner.lifecycle.removeObserver(observer) }
    }
    BackHandler(enabled = backEnabled && activeCategory != null) { activeCategory = null }
    val categoryLocale = remember(strings.code) { Locale.forLanguageTag(strings.code.replace('_', '-')) }
    fun categoryTitle(value: String): String = settingsCategoryTitle(value, categoryLocale)
    val categories = remember(strings.code, DerbisActivePalette) {
        listOf(
            SettingsCategoryMeta("skins", com.yasuda.derbis.ui.i18n.DerbisSkinStrings.forCode(strings.code).title, "Derbis Default · Nocturne 78 · Liquid Glass · Torque · Ivory · Spotify Style · Apple Music Style · TIDAL Style · YouTube Music Style", Icons.Rounded.Style, DerbisViolet, SettingsHubGroup.Appearance),
            SettingsCategoryMeta("design", categoryTitle(strings.design), "${strings.theme} · ${strings.animations} · ${strings.dynamicColor}", Icons.Rounded.Palette, DerbisViolet, SettingsHubGroup.Appearance),
            SettingsCategoryMeta("home", categoryTitle(strings.homeInterfaceSection), "${strings.compactHome} · ${strings.newReleases} · ${strings.top50Charts}", Icons.Rounded.Home, DerbisViolet, SettingsHubGroup.Appearance),
            SettingsCategoryMeta("player", categoryTitle(strings.player), "${strings.playerGestureHorizontalSwipe} · ${strings.sponsorBlock} · ${strings.skipSilence}", Icons.Rounded.PlayArrow, DerbisPink, SettingsHubGroup.Listening),
            SettingsCategoryMeta("audio", strings.audioEngine, strings.audioEngineSubtitle, Icons.Rounded.GraphicEq, DerbisPink, SettingsHubGroup.Listening),
            SettingsCategoryMeta("lyrics", categoryTitle(strings.lyricsAnalysisSection), strings.lyricsAnalysisCompact, Icons.Rounded.Insights, DerbisPink, SettingsHubGroup.Listening),
            SettingsCategoryMeta("jam", categoryTitle(strings.jamTitle), strings.jamSubtitle, Icons.Rounded.Groups, DerbisPink, SettingsHubGroup.Listening),
            SettingsCategoryMeta("downloads", categoryTitle(strings.downloads), "${strings.wifiOnly} · ${strings.simultaneousDownloads}", Icons.Rounded.Download, DerbisBlue, SettingsHubGroup.Library),
            SettingsCategoryMeta("backup", strings.vaultTitle, "${strings.backupNow} · ${strings.restoreBackup}", Icons.Rounded.History, DerbisBlue, SettingsHubGroup.Library),
            SettingsCategoryMeta("youtube_music", "YouTube Music", com.yasuda.derbis.ui.i18n.youtubeMusicCopy(strings.code).introduction, Icons.Rounded.AccountCircle, DerbisCyan, SettingsHubGroup.Accounts),
            SettingsCategoryMeta("integrations", categoryTitle(strings.integrations), "Last.fm · ListenBrainz · AudD", Icons.Rounded.Link, DerbisCyan, SettingsHubGroup.Accounts),
            SettingsCategoryMeta("system", categoryTitle(strings.preferences), "${strings.batteryUnrestricted} · ${strings.language}", Icons.Rounded.Settings, DerbisOrange, SettingsHubGroup.System),
            SettingsCategoryMeta("network", categoryTitle(strings.networkTitle), strings.networkSubtitle, Icons.Rounded.Public, DerbisOrange, SettingsHubGroup.System),
            SettingsCategoryMeta("app", categoryTitle(strings.app), "${strings.updates} · ${BuildConfig.VERSION_NAME}", Icons.Rounded.Info, DerbisOrange, SettingsHubGroup.System)
        )
    }
    val settingsSearchIndex = remember(strings.code) {
        SettingsSearchIndex(
            entries = settingsSearchEntries(
                strings = strings,
                locale = categoryLocale,
                updatesAvailable = BuildConfig.UPSTREAM_UPDATES_ENABLED,
                aaudioOutputAvailable = NativeAudioIntegration.isAaudioOutputSupported()
            ),
            locale = categoryLocale
        )
    }
    val settingsSearchResults = remember(settingsQuery, settingsSearchIndex) {
        settingsSearchIndex.search(settingsQuery)
    }
    Box(
        modifier = Modifier
        .fillMaxSize()
        .background(if (SkinChrome.active) SolidColor(DerbisBlack) else Brush.verticalGradient(listOf(DerbisInk, DerbisBlack)))
        .windowInsetsPadding(DerbisHorizontalSafeInsets)
    ) {
        AnimatedContent(
            targetState = activeCategory,
            label = "settingsNav",
            transitionSpec = {
                if (animationsEnabled) {
                    fadeIn() togetherWith fadeOut()
                } else {
                    EnterTransition.None togetherWith ExitTransition.None
                }
            }
        ) { current ->
            val meta = categories.firstOrNull { it.id == current }
            val settingsListState = remember(current) { LazyListState() }
            val bottomContentInset = animatedBottomContentInset(
                collapsed = DerbisBottomContentGap,
                expanded = DerbisMiniPlayerHeight + DerbisBottomContentGap,
                miniPlayerVisible = miniPlayerVisible,
                animationsEnabled = animationsEnabled
            )
            CompositionLocalProvider(LocalSettingsAccent provides meta?.accent) {
            LazyColumn(
                state = settingsListState,
                modifier = Modifier
                .fillMaxSize()
                .statusBarsPadding()
                .navigationBarsPadding(),
                contentPadding = PaddingValues(start = 18.dp, end = 18.dp, top = 18.dp, bottom = maxOf(40.dp, bottomContentInset)),
                verticalArrangement = Arrangement.spacedBy(if (current == null) 0.dp else SettingsGroupGap)
            ) {
                if (current == null) {
                    item {
                        SettingsHubHeader(onClose)
                        Spacer(modifier = Modifier.height(14.dp))
                    }
                    item {
                        BasicTextField(
                            value = settingsQuery,
                            onValueChange = { settingsQuery = it },
                            singleLine = true,
                            textStyle = TextStyle(color = DerbisText, fontSize = 15.sp, fontWeight = FontWeight.SemiBold),
                            cursorBrush = SolidColor(DerbisCyan),
                            modifier = Modifier
                                .fillMaxWidth()
                                .semantics { contentDescription = strings.settingsSearchPlaceholder }
                                .padding(bottom = 16.dp)
                                .background(DerbisAdaptiveCard, if (SkinChrome.active) SkinChrome.fieldShape else CircleShape)
                                .padding(horizontal = 18.dp, vertical = 16.dp),
                            decorationBox = { innerTextField ->
                                Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                                    Icon(Icons.Rounded.Search, null, tint = DerbisCyan, modifier = Modifier.size(20.dp))
                                    Box(modifier = Modifier.weight(1f)) {
                                        if (settingsQuery.isBlank()) Text(strings.settingsSearchPlaceholder, color = DerbisMuted, fontSize = 15.sp)
                                        innerTextField()
                                    }
                                    if (settingsQuery.isNotBlank()) {
                                        IconButton(onClick = { settingsQuery = "" }, modifier = Modifier.size(48.dp)) {
                                            Icon(Icons.Rounded.Close, strings.clear, tint = DerbisMuted)
                                        }
                                    }
                                }
                            }
                        )
                        Spacer(modifier = Modifier.height(10.dp))
                    }
                    if (settingsQuery.isNotBlank()) {
                        if (settingsSearchResults.isEmpty()) {
                            item(key = "settings_search_empty") {
                                Text(
                                    strings.settingsSearchEmpty,
                                    color = DerbisMuted,
                                    fontSize = 14.sp,
                                    fontWeight = FontWeight.SemiBold,
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(vertical = 24.dp),
                                    textAlign = TextAlign.Center
                                )
                            }
                        }
                        items(settingsSearchResults, key = SettingsSearchResult::id) { result ->
                            SettingsSearchResultRow(result.title, result.description, result.categoryLabel) {
                                if (result.categoryId == SETTINGS_CATEGORY_AUDIO) {
                                    onOpenAudioSettings()
                                } else if (result.categoryId == "youtube_music") {
                                    onOpenYoutubeMusic()
                                } else {
                                    activeCategory = result.categoryId
                                }
                            }
                        }
                    } else {
                    item(key = "settings_studios") {
                        val studioContext = LocalContext.current
                        SettingsStudioShelf(
                            title = strings.settingsHubCopy[SettingsHubText.Studios],
                            subtitle = strings.settingsHubCopy[SettingsHubText.StudiosHint],
                            entries = listOf(
                                SettingsStudioEntry("skins", com.yasuda.derbis.ui.i18n.DerbisSkinStrings.forCode(strings.code).title, Icons.Rounded.Style, DerbisPink, MaterialShapes.Cookie7Sided) { activeCategory = "skins" },
                                SettingsStudioEntry("theme", strings.themeStudio, Icons.Rounded.Palette, DerbisViolet, MaterialShapes.Cookie9Sided, onOpenThemeStudio),
                                SettingsStudioEntry("home", strings.homeStudioCopy.title, Icons.Rounded.Home, DerbisCyan, MaterialShapes.Clover4Leaf, onOpenHomeStudio),
                                SettingsStudioEntry("mini_player", strings.miniPlayerStudioCopy[MiniStudioText.Title], Icons.Rounded.SmartDisplay, DerbisPink, MaterialShapes.Sunny, onOpenMiniPlayerStudio),
                                SettingsStudioEntry("navigation", strings.navigationStudioCopy[NavStudioText.Title], Icons.Rounded.Dashboard, DerbisBlue, MaterialShapes.Pill, onOpenNavigationStudio),
                                SettingsStudioEntry("lyrics", strings.lyricsStudio, Icons.Rounded.AutoAwesome, DerbisOrange, MaterialShapes.SoftBurst, onOpenLyricsStudio),
                                SettingsStudioEntry("widget", strings.widgetStudioCopy[WidgetStudioText.Title], Icons.Rounded.Widgets, DerbisCyan, MaterialShapes.Gem) {
                                    studioContext.startActivity(WidgetStudioActivity.intent(studioContext))
                                }
                            ).filterNot { skinManagesStudio(it.id) }
                        )
                    }
                    SettingsHubGroup.entries.forEach { group ->
                        val groupCategories = categories.filter { it.group == group }
                        if (groupCategories.isEmpty()) return@forEach
                        item(key = "settings_group_${group.name}") {
                            SettingsHubGroupLabel(settingsHubGroupTitle(group, strings))
                        }
                        itemsIndexed(groupCategories, key = { _, item -> item.id }) { index, category ->
                            SettingsCategoryCard(
                                meta = category,
                                index = index,
                                count = groupCategories.size
                            ) {
                                when (category.id) {
                                    "audio" -> onOpenAudioSettings()
                                    "youtube_music" -> onOpenYoutubeMusic()
                                    else -> activeCategory = category.id
                                }
                            }
                        }
                    }
                    item { SettingsHubFooter(onExitApplication) }
                    }
                } else {
                    item {
                        SettingsDetailHeader(
                            title = meta?.title.orEmpty(),
                            summary = meta?.summary.orEmpty(),
                            icon = meta?.icon ?: Icons.Rounded.Settings,
                            accent = meta?.accent ?: DerbisCyan,
                            onBack = { activeCategory = null }
                        )
                    }
                    settingsGroupedItems { when (current) {
                        "network" -> {
                            item {
                                SettingsToggle(
                                    icon = Icons.Rounded.NetworkCell,
                                    title = "Data Saver",
                                    subtitle = "Turn off background queue, search, lyrics, Canvas, and artwork prefetching. Automatic downloads wait for Wi-Fi; automatic video is capped at 360p. Tracks, searches, and imports you start yourself still work.",
                                    checked = interfaceSettings.dataSaverEnabled,
                                    onCheckedChange = { enabled ->
                                        onInterfaceSettings(interfaceSettings.copy(dataSaverEnabled = enabled))
                                    }
                                )
                            }
                            item {
                                NetworkSettingsPanel(
                                    settings = networkSettings,
                                    proxyPasswordSet = networkProxyPasswordSet,
                                    testing = networkTesting,
                                    testOutcome = networkTestOutcome,
                                    errors = networkErrors,
                                    onApply = onNetworkSettings,
                                    onTest = onTestNetwork
                                )
                            }
                        }
                        "jam" -> item {
                            Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                                val remoteJamConfigured = com.yasuda.derbis.feature.jam.DerbisJamRelay.isConfigured
                                Text(
                                    if (remoteJamConfigured) "Choose LAN Jam or Server Jam for each room" else strings.jamSubtitle,
                                    color = DerbisMuted,
                                    fontSize = 13.sp,
                                    fontWeight = FontWeight.SemiBold
                                )
                                Text(
                                    if (remoteJamConfigured) {
                                        "Server Jam is available through the Derbis Jam relay; LAN Jam remains available for the same Wi-Fi network. Each listener streams from their own available source."
                                    } else {
                                        "LAN Jam is available on the same Wi-Fi network. Server Jam is enabled only when this build is configured with the Derbis Jam relay."
                                    },
                                    color = DerbisMuted,
                                    fontSize = 12.sp,
                                    fontWeight = FontWeight.SemiBold
                                )
                                TextButton(onClick = onOpenJam, modifier = Modifier.fillMaxWidth()) {
                                    Text(
                                        strings.jamTitle,
                                        color = DerbisCyan,
                                        fontSize = 15.sp,
                                        fontWeight = FontWeight.Bold
                                    )
                                }
                            }
                        }
                        "integrations" -> {
                            item { DeviceIntegrationSettingsPanel() }
                            item {
                                IntegrationSettingsPanel(
                                    lastFmConfigured,
                                    lastFmAuthorizationPending,
                                    listenBrainzConfigured,
                                    audDConfigured,
                                    onBeginLastFm,
                                    onCompleteLastFm,
                                    onClearLastFm,
                                    onSaveListenBrainz,
                                    onClearListenBrainz,
                                    onSaveAudD,
                                    onClearAudD,
                                    motionArtworkEnabled = interfaceSettings.motionArtworkEnabled,
                                    onToggleMotionArtwork = {
                                        onInterfaceSettings(interfaceSettings.copy(motionArtworkEnabled = it))
                                    }
                                )
                            }
                        }
                        "skins" -> {
                            item {
                                SettingsSkinSelection(interfaceSettings, onInterfaceSettings)
                            }
                        }
                        "design" -> {
                            item {
                                SettingsButton(
                                    icon = Icons.Rounded.Palette,
                                    title = strings.themeStudio,
                                    subtitle = DerbisThemes.byId(themePreset).label,
                                    enabled = interfaceSettings.skin == DerbisSkin.Default,
                                    onClick = onOpenThemeStudio
                                )
                            }
                            item {
                                SettingsButton(
                                    icon = Icons.Rounded.AutoAwesome,
                                    title = strings.lyricsStudio,
                                    subtitle = strings.lyricsStudioSubtitle,
                                    onClick = onOpenLyricsStudio
                                )
                            }
                            item {
                                SettingsButton(
                                    icon = Icons.Rounded.Home,
                                    title = strings.homeStudioCopy.title,
                                    subtitle = skinHomeStyleLabel(homeStudioStyle) + " · " + strings.homeStudioCopy.subtitle,
                                    onClick = onOpenHomeStudio
                                )
                            }
                            item {
                                SettingsButton(
                                    icon = Icons.Rounded.SmartDisplay,
                                    title = strings.miniPlayerStudioCopy[MiniStudioText.Title],
                                    subtitle = miniPlayerStyleName(miniPlayerStyle) + " · " + strings.miniPlayerStudioCopy[MiniStudioText.Subtitle],
                                    enabled = interfaceSettings.skin == DerbisSkin.Default,
                                    onClick = onOpenMiniPlayerStudio
                                )
                            }
                            item {
                                SettingsButton(
                                    icon = Icons.Rounded.Dashboard,
                                    title = strings.navigationStudioCopy[NavStudioText.Title],
                                    subtitle = navigationStyleName(navigationStyle) + " · " + strings.navigationStudioCopy[NavStudioText.Subtitle],
                                    enabled = interfaceSettings.skin == DerbisSkin.Default,
                                    onClick = onOpenNavigationStudio
                                )
                            }
                            item {
                                val widgetStudioContext = LocalContext.current
                                SettingsButton(
                                    icon = Icons.Rounded.Widgets,
                                    title = strings.widgetStudioCopy[WidgetStudioText.Title],
                                    subtitle = strings.widgetStudioCopy[WidgetStudioText.Subtitle],
                                    onClick = { widgetStudioContext.startActivity(WidgetStudioActivity.intent(widgetStudioContext)) }
                                )
                            }
                            skinSettingsItems(interfaceSettings.skin, defaults = {
                            item {
                                SettingsChoiceRow(
                                    icon = Icons.Rounded.TextFields,
                                    title = strings.appFont,
                                    subtitle = strings.appFontSubtitle,
                                    options = DerbisFontPreset.entries.map { preset -> preset.name to preset.displayName },
                                    selected = interfaceSettings.fontPreset.name,
                                    onSelect = { value ->
                                        onInterfaceSettings(
                                            interfaceSettings.copy(fontPreset = DerbisFontPreset.from(value))
                                        )
                                    }
                                )
                            }
                            })
                            item {
                                SettingsToggle(
                                    icon = Icons.Rounded.Bolt,
                                    title = strings.animations,
                                    subtitle = strings.animationsSubtitle,
                                    checked = animationsEnabled,
                                    onCheckedChange = onAnimations
                                )
                            }
                            item {
                                SettingsToggle(
                                    icon = Icons.Rounded.AutoAwesome,
                                    title = strings.motionArtwork,
                                    subtitle = strings.motionArtworkSubtitle,
                                    checked = motionArtworkEnabled,
                                    onCheckedChange = onMotionArtwork
                                )
                            }
                            item {
                                SettingsToggle(
                                    icon = Icons.Rounded.Block,
                                    title = "AI Slop",
                                    subtitle = "Block music, videos, and recommendations explicitly marked as AI-generated.",
                                    checked = interfaceSettings.blockAiContent,
                                    onCheckedChange = { enabled ->
