@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
private fun SettingsTile(
    modifier: Modifier = Modifier,
    onClick: (() -> Unit)? = null,
    checked: Boolean? = null,
    onCheckedChange: ((Boolean) -> Unit)? = null,
    enabled: Boolean = true,
    groupIndex: Int? = null,
    groupCount: Int? = null,
    color: Color = if (DerbisIsSpotify || DerbisIsYouTubeMusic) Color.Transparent else if (DerbisIsAppleMusic) AppleMusicDesign.groupedBackground else DerbisAdaptiveCard,
    content: @Composable () -> Unit
) {
    val interactionSource = remember { MutableInteractionSource() }
    val slot = LocalSettingsGroupSlot.current
    val index = groupIndex ?: slot?.index ?: 0
    val count = groupCount ?: slot?.count ?: 1
    val first = index == 0
    val last = index == count - 1
    val shape = settingsTileShape(interactionSource, first, last)
    val liquidGlass = DerbisIsLiquidGlass
    val tileModifier = modifier
        .fillMaxWidth()
        .then(if (SkinChrome.active) Modifier.padding(vertical = 1.dp) else Modifier)
        .then(
            if (liquidGlass) {
                Modifier.derbisGlass(
                    shape = shape,
                    baseTint = Color.White,
                    fallbackColor = color.copy(alpha = 0.72f),
                    fallbackBorderColor = Color.White.copy(alpha = 0.28f),
                    intensity = DerbisGlassIntensity.Subtle,
                    artworkTint = DerbisActivePalette.cyan
                )
            } else {
                Modifier
            }
        )
    val tileColor = if (liquidGlass) Color.Transparent else color
    when {
        checked != null && onCheckedChange != null -> Surface(
            checked = checked,
            onCheckedChange = onCheckedChange,
            enabled = enabled,
            shape = shape,
            color = tileColor,
            interactionSource = interactionSource,
            modifier = tileModifier,
            content = content
        )
        onClick != null -> Surface(
            onClick = onClick,
            enabled = enabled,
            shape = shape,
            color = tileColor,
            interactionSource = interactionSource,
            modifier = tileModifier,
            content = content
        )
        else -> Surface(shape = shape, color = tileColor, modifier = tileModifier, content = content)
    }
}

