@Composable
private fun PlayerColorModeSetting(
    settings: DerbisInterfaceSettings,
    onSettings: (DerbisInterfaceSettings) -> Unit
) {
    val strings = LocalDerbisStrings.current
    val mode = settings.playerColorMode
    var previewAccent by remember(settings.playerColorAccent) { mutableStateOf<Int?>(null) }
    val effectiveAccent = previewAccent ?: settings.playerColorAccent
    SettingsTile {
        Column(modifier = Modifier.padding(14.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {
            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(14.dp)) {
                SettingsTileIcon(icon = Icons.Rounded.ColorLens, accent = LocalSettingsAccent.current ?: DerbisViolet)
                SettingsTileText(
                    title = strings.playerColors,
                    subtitle = strings.playerColorsSubtitle,
                    modifier = Modifier.weight(1f)
                )
            }
            PlayerColorModePreview(mode = mode, customAccent = effectiveAccent)
            FlowRow(
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                verticalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                PlayerColorMode.entries.forEach { option ->
                    SettingsChoiceChip(
                        label = when (option) {
                            PlayerColorMode.Dynamic -> strings.playerColorsDynamic
                            PlayerColorMode.Theme -> strings.playerColorsTheme
                            PlayerColorMode.Custom -> strings.playerColorsCustom
                        },
                        active = option == mode,
                        onClick = { onSettings(settings.copy(playerColorMode = option)) }
                    )
                }
            }
            Text(
                text = when (mode) {
                    PlayerColorMode.Dynamic -> strings.playerColorsDynamicHint
                    PlayerColorMode.Theme -> strings.playerColorsThemeHint
                    PlayerColorMode.Custom -> strings.playerColorsCustomHint
                },
                style = MaterialTheme.typography.bodySmall,
                color = DerbisMuted
            )
            if (mode == PlayerColorMode.Custom) {
                MiniColorEditor(
                    color = settings.playerColorAccent,
                    copy = strings.miniPlayerStudioCopy,
                    onPreviewColor = { previewAccent = it },
                    onCancelPreview = { previewAccent = null },
                    onColor = {
                        previewAccent = null
                        onSettings(settings.copy(playerColorAccent = it))
                    }
                )
            }
        }
    }
}

private val PlayerColorPreviewSongs = listOf(
    Color(0xFFE0566F) to Color(0xFFF2A65A),
    Color(0xFF3D7BF0) to Color(0xFF39C6C0),
    Color(0xFF7BC96F) to Color(0xFFE3D25B)
)

@Composable
private fun PlayerColorModePreview(mode: PlayerColorMode, customAccent: Int) {
    val theme = DerbisActivePalette
    val fixed = remember(mode, customAccent, theme) { playerFixedAccents(mode, theme, customAccent) }
    val animated = LocalAnimationsEnabled.current
    Row(horizontalArrangement = Arrangement.spacedBy(8.dp), modifier = Modifier.fillMaxWidth()) {
        PlayerColorPreviewSongs.forEach { (songPrimary, songSecondary) ->
            val pair = fixed ?: harmonizePlayerAccents(songPrimary, songSecondary)
            val ambience = remember(pair) { playerAmbienceOf(pair.primary, pair.secondary) }
            val spec = DerbisPlayerDesign.motion(animated, DerbisPlayerDesign.paletteTween<Color>())
            val top by animateColorAsState(ambience.tint, spec, label = "player-color-preview-top")
            val bottom by animateColorAsState(ambience.base, spec, label = "player-color-preview-bottom")
            val highlight by animateColorAsState(playerHighlightOf(pair.primary, pair.secondary), spec, label = "player-color-preview-accent")
            Box(
                modifier = Modifier
                    .weight(1f)
                    .height(72.dp)
                    .clip(RoundedCornerShape(18.dp))
                    .background(Brush.verticalGradient(listOf(top, bottom)))
            ) {
                Box(
                    modifier = Modifier
                        .padding(10.dp)
                        .size(22.dp)
                        .clip(RoundedCornerShape(7.dp))
                        .background(Brush.linearGradient(listOf(songPrimary, songSecondary)))
                )
                Box(
                    modifier = Modifier
                        .align(Alignment.CenterEnd)
                        .padding(end = 10.dp)
                        .size(20.dp)
                        .clip(CircleShape)
                        .background(highlight)
                )
                Box(
                    modifier = Modifier
                        .align(Alignment.BottomStart)
                        .padding(start = 10.dp, end = 10.dp, bottom = 12.dp)
                        .fillMaxWidth()
                        .height(3.dp)
                        .clip(CircleShape)
                        .background(Color.White.copy(alpha = 0.16f))
                ) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth(0.55f)
                            .fillMaxHeight()
                            .background(highlight)
                    )
                }
            }
        }
    }
}

@Composable
private fun SettingsChoiceChip(label: String, active: Boolean, onClick: () -> Unit) {
    val corner = derbisExpressiveToggleCorner(active, unchecked = 12.dp, checkedCorner = 22.dp, label = "settingsChoiceCorner")
    val skinned = SkinChrome.active
    val selectedBorder = if (DerbisIsTorque || DerbisIsIvory) DerbisActivePalette.blue else SkinChrome.chipSelectedContent
    Surface(
        selected = active,
        onClick = onClick,
        shape = if (skinned) SkinChrome.chipShape else RoundedCornerShape(corner),
        color = settingsChoiceContainer(active),
        contentColor = settingsChoiceContent(active),
        border = if (skinned) BorderStroke(1.dp, if (active) selectedBorder else DerbisAdaptiveHairline) else null
    ) {
        Row(
            modifier = Modifier.heightIn(min = 40.dp).padding(horizontal = 16.dp, vertical = 9.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(6.dp)
        ) {
            AnimatedVisibility(visible = active) {
                Icon(Icons.Rounded.Check, contentDescription = null, modifier = Modifier.size(16.dp))
            }
            Text(label, fontSize = 13.sp, fontWeight = FontWeight.Bold)
        }
    }
}

