@Composable
private fun DownloadQueueSettingsCard(
    tasks: List<OfflineDownloadTask>,
    onPause: (String) -> Unit,
    onResume: (String) -> Unit,
    onCancel: (String) -> Unit
) {
    SettingsTile {
        Column(modifier = Modifier.padding(14.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
            Text(LocalDerbisStrings.current.persistentQueue, color = DerbisText, fontSize = 15.sp, fontWeight = FontWeight.Black)
            tasks.forEach { task ->
                Column(verticalArrangement = Arrangement.spacedBy(7.dp)) {
                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                        Column(modifier = Modifier.weight(1f)) {
                            Text(task.title.ifBlank { LocalDerbisStrings.current.song }, color = DerbisText, fontSize = 13.sp, fontWeight = FontWeight.Bold, maxLines = 1, overflow = TextOverflow.Ellipsis)
                            Text("${LocalDerbisStrings.current.localizeDownloadState(task.state)} • ${task.progress.coerceIn(0, 100)}%", color = DerbisMuted, fontSize = 11.sp, fontWeight = FontWeight.SemiBold)
                        }
                        val canResume = task.state == "PAUSED" || task.state == "FAILED"
                        val actionDescription = if (canResume) LocalDerbisStrings.current.formatResumeDownload(task.title) else LocalDerbisStrings.current.formatPauseDownload(task.title)
                        IconButton(onClick = { if (canResume) onResume(task.taskKey) else onPause(task.taskKey) }) {
                            Icon(if (canResume) Icons.Rounded.PlayArrow else Icons.Rounded.Pause, actionDescription, tint = DerbisCyan)
                        }
                        IconButton(onClick = { onCancel(task.taskKey) }) {
                            Icon(Icons.Rounded.Close, LocalDerbisStrings.current.formatCancelDownload(task.title), tint = DerbisPink)
                        }
                    }
                    Box(modifier = Modifier.fillMaxWidth().height(5.dp).background(Color.White.copy(alpha = 0.08f), CircleShape)) {
                        Box(modifier = Modifier.fillMaxWidth(task.progress.coerceIn(0, 100) / 100f).fillMaxHeight().background(DerbisCyan, CircleShape))
                    }
                }
            }
        }
    }
}

@Composable
private fun SettingsSectionLabel(text: String) {
    val strings = LocalDerbisStrings.current
    val locale = remember(strings.code) { Locale.forLanguageTag(strings.code.replace('_', '-')) }
    val title = remember(text, locale) {
        text.trim().lowercase(locale).replaceFirstChar { character ->
            if (character.isLowerCase()) character.titlecase(locale) else character.toString()
        }
    }
    if (DerbisIsIvory) {
        Text(
            title, color = IvoryDesign.onInk, style = MaterialTheme.typography.titleMedium, maxLines = 1, overflow = TextOverflow.Ellipsis,
            modifier = Modifier.padding(top = 18.dp, bottom = 8.dp).fillMaxWidth().heightIn(min = 52.dp)
                .clip(RoundedCornerShape(PrismDesign.controlCorner)).background(IvoryDesign.ink)
                .wrapContentHeight(Alignment.CenterVertically).padding(horizontal = 18.dp).semantics { heading() }
        )
        return
    }
    if (DerbisIsSpotify) {
        SpotifySettingsHeading(title)
        return
    }
    if (DerbisIsAppleMusic) {
        Text(
            title.uppercase(locale), color = AppleMusicDesign.secondaryLabel, style = MaterialTheme.typography.bodySmall,
            modifier = Modifier.padding(start = 16.dp, top = 22.dp, bottom = 6.dp).semantics { heading() }
        )
        return
    }
    Text(
        SkinChrome.label(title, locale),
        color = if (DerbisIsPrism && !DerbisIsTorque) DerbisMuted else DerbisCyan,
        fontSize = if (SkinChrome.labelsUppercase) 12.sp else 14.sp,
        fontWeight = if (SkinChrome.active) FontWeight.Medium else FontWeight.Bold,
        letterSpacing = if (SkinChrome.labelsUppercase) 1.6.sp else 0.2.sp,
        modifier = Modifier
            .padding(start = 8.dp, top = 18.dp, bottom = 8.dp)
            .semantics { heading() }
    )
}

