@Composable
private fun SettingsUpdateCard(
    updateInfo: AppUpdateInfo?,
    isChecking: Boolean,
    onCheck: () -> Unit,
    onDownload: () -> Unit
) {
    val availableUpdate = updateInfo?.takeIf { it.isNewer }
    val hasUpdate = availableUpdate != null
    Surface(
        color = Color.Transparent,
        border = BorderStroke(1.dp, if (hasUpdate) DerbisCyan.copy(alpha = 0.22f) else Color.White.copy(alpha = 0.1f)),
        shape = RoundedCornerShape(20.dp),
        modifier = Modifier.fillMaxWidth()
    ) {
        Column(
            modifier = Modifier
                .background(
                    Brush.linearGradient(
                        listOf(
                            if (hasUpdate) DerbisCyan.copy(alpha = 0.17f) else Color.White.copy(alpha = 0.055f),
                            Color.White.copy(alpha = 0.035f),
                            if (hasUpdate) DerbisViolet.copy(alpha = 0.13f) else Color.White.copy(alpha = 0.04f)
                        )
                    )
                )
                .padding(14.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                Box(
                    modifier = Modifier
                        .size(42.dp)
                        .background(DerbisCyan.copy(alpha = 0.16f), RoundedCornerShape(14.dp)),
                    contentAlignment = Alignment.Center
                ) {
                    if (isChecking) {
                        CircularProgressIndicator(modifier = Modifier.size(20.dp), strokeWidth = 2.dp, color = DerbisCyan)
                    } else {
                        Icon(Icons.Rounded.Bolt, null, tint = DerbisCyan, modifier = Modifier.size(21.dp))
                    }
                }
                Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(3.dp)) {
                    Text(
                        text = if (hasUpdate) LocalDerbisStrings.current.updateAvailable else LocalDerbisStrings.current.updates,
                        color = DerbisText,
                        fontSize = 16.sp,
                        fontWeight = FontWeight.Black
                    )
                    Text(
                        text = when {
                            isChecking -> LocalDerbisStrings.current.checkingLatestVersion
                            availableUpdate != null -> LocalDerbisStrings.current.formatLatestVersionReady(availableUpdate.latestVersionName)
                            updateInfo != null -> LocalDerbisStrings.current.latestInstalled
                            else -> LocalDerbisStrings.current.checkNewVersions
                        },
                        color = DerbisMuted,
                        fontSize = 12.sp,
                        fontWeight = FontWeight.SemiBold
                    )
                }
            }
            availableUpdate?.let { info ->
                Surface(
                    color = Color.Black.copy(alpha = 0.16f),
                    shape = RoundedCornerShape(14.dp),
                    border = BorderStroke(1.dp, Color.White.copy(alpha = 0.07f))
                ) {
                    Column(
                        modifier = Modifier.padding(12.dp),
                        verticalArrangement = Arrangement.spacedBy(4.dp)
                    ) {
                        Text(info.releaseTitle.ifBlank { "DERBIS ${info.latestVersionName}" }, color = DerbisText, fontSize = 14.sp, fontWeight = FontWeight.Black, maxLines = 1, overflow = TextOverflow.Ellipsis)
                        Text(
                            text = if (info.directApk) LocalDerbisStrings.current.signedApkReady else LocalDerbisStrings.current.releasePageReady,
                            color = DerbisMuted,
                            fontSize = 12.sp,
                            fontWeight = FontWeight.SemiBold
                        )
                    }
                }
            }
            Row(
                modifier = Modifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                SettingsMiniButton(
                    label = if (isChecking) LocalDerbisStrings.current.checking else LocalDerbisStrings.current.check,
                    accent = DerbisCyan,
                    enabled = !isChecking,
                    modifier = Modifier.weight(1f),
                    onClick = onCheck
                )
                if (hasUpdate) {
                    SettingsMiniButton(
                        label = LocalDerbisStrings.current.download,
                        accent = DerbisViolet,
                        enabled = !isChecking,
                        modifier = Modifier.weight(1f),
                        onClick = onDownload
                    )
                }
            }
            Text(
                text = LocalDerbisStrings.current.formatInstalledVersion(BuildConfig.VERSION_NAME),
                color = DerbisMuted.copy(alpha = 0.8f),
                fontSize = 11.sp,
                fontWeight = FontWeight.Bold
            )
        }
    }
}

