@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
private fun GreetingBar(
    userName: String,
    isResolving: Boolean,
    animationsEnabled: Boolean,
    onSearch: () -> Unit,
    onCreatePlaylist: (String) -> Unit,
    onOpenJam: () -> Unit,
    onSettings: () -> Unit
) {
    val strings = LocalDerbisStrings.current
    val greetingHour by rememberCurrentGreetingHour()
    val dayPart = remember(strings, greetingHour) { strings.greetingDayPart(greetingHour) }
    val name = remember(strings, userName) { strings.greetingName(userName) }
    val greeting = remember(userName, strings, greetingHour) { strings.formatGreeting(userName, greetingHour) }
    val today = remember(strings.code, greetingHour) {
        val locale = Locale.forLanguageTag(strings.code)
        android.icu.text.DateFormat.getInstanceForSkeleton("EEEEMMMMd", locale).format(java.util.Date())
            .replaceFirstChar { it.titlecase(locale) }
    }
    var createMenuExpanded by remember { mutableStateOf(false) }
    var createPlaylistDialogVisible by remember { mutableStateOf(false) }

    Row(
        modifier = Modifier
            .fillMaxWidth()
            .heightIn(min = DerbisHomeDesign.SettingsControlHeight)
            .padding(horizontal = 2.dp, vertical = 4.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        Row(
            modifier = Modifier.weight(1f),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            HomeLogoBadge()
            HomeGreeting(
                dayPart = dayPart,
                name = name,
                today = today,
                greeting = greeting,
                animationsEnabled = animationsEnabled,
                modifier = Modifier.weight(1f)
            )
        }
        Box {
            HomeHeaderCreateButton(
                label = strings.create,
                onClick = { createMenuExpanded = true }
            )
            DropdownMenu(
                expanded = createMenuExpanded,
                onDismissRequest = { createMenuExpanded = false }
            ) {
                DropdownMenuItem(
                    text = { Text(strings.createNewPlaylist) },
                    leadingIcon = { Icon(Icons.Rounded.Add, null) },
                    onClick = {
                        createMenuExpanded = false
                        createPlaylistDialogVisible = true
                    }
                )
                DropdownMenuItem(
                    text = { Text("Start Derbis Jam") },
                    leadingIcon = { Icon(Icons.Rounded.Groups, null) },
                    onClick = {
                        createMenuExpanded = false
                        onOpenJam()
                    }
                )
            }
        }
        HomeHeaderIconButton(
            icon = Icons.Rounded.Search,
            contentDescription = strings.search,
            polygon = MaterialShapes.Cookie4Sided,
            onClick = onSearch
        )
        HomeHeaderIconButton(
            icon = Icons.Rounded.Settings,
            contentDescription = strings.settings,
            polygon = MaterialShapes.Cookie4Sided,
            loading = isResolving,
            onClick = onSettings
        )
    }
    if (createPlaylistDialogVisible) {
        PlaylistCreateDialog(
            onDismiss = { createPlaylistDialogVisible = false },
            onConfirm = { name ->
                onCreatePlaylist(name)
                createPlaylistDialogVisible = false
            }
        )
    }
}

@Composable
private fun HomeGreeting(
    dayPart: String,
    name: String,
    today: String,
    greeting: String,
    animationsEnabled: Boolean,
    modifier: Modifier = Modifier
) {
    var greetingRevealed by rememberSaveable { mutableStateOf(!animationsEnabled) }
    val dayPartReveal = remember { Animatable(if (greetingRevealed) 1f else 0f) }
    val nameReveal = remember { Animatable(if (greetingRevealed) 1f else 0f) }
    LaunchedEffect(animationsEnabled) {
        if (!animationsEnabled) {
            dayPartReveal.snapTo(1f)
            nameReveal.snapTo(1f)
            greetingRevealed = true
            return@LaunchedEffect
        }
        if (greetingRevealed) return@LaunchedEffect
        launch { dayPartReveal.animateTo(1f, spring(dampingRatio = 0.82f, stiffness = Spring.StiffnessLow)) }
        delay(GREETING_NAME_STAGGER_MS)
        nameReveal.animateTo(1f, spring(dampingRatio = 0.68f, stiffness = Spring.StiffnessLow))
        greetingRevealed = true
    }
    Column(
        modifier = modifier.clearAndSetSemantics {
            contentDescription = greeting
            heading()
        }
    ) {
        if (name.isNotBlank()) {
            HomeGreetingDayPart(
                dayPart = dayPart,
                prominent = false,
                animationsEnabled = animationsEnabled,
                reveal = { dayPartReveal.value }
            )
            HomeGreetingName(name = name, reveal = { nameReveal.value })
        } else {
            HomeGreetingCaption(text = today, reveal = { dayPartReveal.value })
            HomeGreetingDayPart(
                dayPart = dayPart,
                prominent = true,
                animationsEnabled = animationsEnabled,
                reveal = { nameReveal.value }
            )
        }
    }
}

@Composable
private fun HomeGreetingCaption(text: String, reveal: () -> Float) {
    Text(
        text = text,
        color = if (DerbisIsLight) DerbisMuted else Color.White.copy(alpha = 0.72f),
        style = DerbisType.metadata.copy(fontWeight = FontWeight.SemiBold, letterSpacing = 0.1.sp),
        maxLines = 1,
        overflow = TextOverflow.Ellipsis,
        modifier = Modifier.graphicsLayer {
            val value = reveal()
            alpha = value
            translationY = (1f - value) * GREETING_RISE.toPx()
        }
    )
}

@Composable
private fun HomeGreetingDayPart(
    dayPart: String,
    prominent: Boolean,
    animationsEnabled: Boolean,
    reveal: () -> Float
) {
    val color = when {
        prominent && DerbisIsLight -> DerbisText
        prominent -> Color.White
        DerbisIsLight -> DerbisMuted
        else -> Color.White.copy(alpha = 0.72f)
    }
    val style = if (prominent) {
        DerbisType.screenTitle.copy(
            fontSize = GREETING_TITLE_MAX_SIZE,
            lineHeight = 29.sp,
            fontWeight = FontWeight.Black,
            letterSpacing = (-0.9).sp
        )
    } else {
        DerbisType.metadata.copy(fontWeight = FontWeight.SemiBold, letterSpacing = 0.1.sp)
    }
    Crossfade(
        targetState = dayPart,
        animationSpec = if (animationsEnabled) tween(240, easing = FastOutSlowInEasing) else snap(),
        label = "homeGreetingDayPart"
    ) { visibleDayPart ->
        Text(
            text = visibleDayPart,
            color = color,
            style = style,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
            autoSize = if (prominent) {
                TextAutoSize.StepBased(minFontSize = GREETING_TITLE_MIN_SIZE, maxFontSize = GREETING_TITLE_MAX_SIZE)
            } else {
                null
            },
            modifier = Modifier.graphicsLayer {
                val value = reveal()
                alpha = value
                translationY = (1f - value) * GREETING_RISE.toPx() * if (prominent) 1.6f else 1f
            }
        )
    }
}

@Composable
private fun HomeGreetingName(name: String, reveal: () -> Float) {
    Text(
        text = name,
        color = if (DerbisIsLight) DerbisText else Color.White,
        style = DerbisType.screenTitle.copy(
            fontSize = 26.sp,
            lineHeight = 29.sp,
            fontWeight = FontWeight.Black,
            letterSpacing = (-0.9).sp
        ),
        maxLines = 2,
        softWrap = true,
        modifier = Modifier
            .fillMaxWidth()
            .graphicsLayer {
                val value = reveal()
                alpha = value
                translationY = (1f - value) * GREETING_RISE.toPx() * 1.6f
                val scale = 0.94f + 0.06f * value
                scaleX = scale
                scaleY = scale
                transformOrigin = TransformOrigin(0f, 1f)
            }
    )
}

private const val GREETING_NAME_STAGGER_MS = 90L
private val GREETING_RISE = 14.dp
private val GREETING_TITLE_MAX_SIZE = 26.sp
private val GREETING_TITLE_MIN_SIZE = 17.sp

@Composable
internal fun rememberCurrentGreetingHour() = produceState(
    initialValue = java.util.Calendar.getInstance().get(java.util.Calendar.HOUR_OF_DAY)
) {
    while (true) {
        val now = java.util.Calendar.getInstance()
        val nextHour = (now.clone() as java.util.Calendar).apply {
            add(java.util.Calendar.HOUR_OF_DAY, 1)
            set(java.util.Calendar.MINUTE, 0)
            set(java.util.Calendar.SECOND, 0)
            set(java.util.Calendar.MILLISECOND, 0)
        }
        delay((nextHour.timeInMillis - now.timeInMillis).coerceAtLeast(1L))
        value = java.util.Calendar.getInstance().get(java.util.Calendar.HOUR_OF_DAY)
    }
}

