@Composable
private fun HomeAlbumHitRow(albums: List<AlbumHit>, animationsEnabled: Boolean, onOpen: (AlbumHit) -> Unit) {
    if (albums.isEmpty()) return
    val effectiveAnimationsEnabled = animationsEnabled && LocalAnimationsEnabled.current
    BoxWithConstraints(modifier = Modifier.fillMaxWidth()) {
        val cardWidth = rememberShelfItemWidth(maxWidth, HOME_ALBUM_CARD_WIDTH)
        LazyRow(
            horizontalArrangement = Arrangement.spacedBy(DerbisHomeDesign.ShelfItemGap),
            contentPadding = PaddingValues(start = HomeHorizontalInset, end = HomeHorizontalShelfEndPadding)
        ) {
            itemsIndexed(
                items = albums,
                key = { index, album -> "home-album-$index-${album.browseId.ifBlank { "${album.title.trim().lowercase()}|${album.artist.trim().lowercase()}" }}" },
                contentType = { _, _ -> "home-album-card" }
            ) { _, album ->
                val interaction = remember { MutableInteractionSource() }
                val isPressed by interaction.collectIsPressedAsState()
                val scale by animateFloatAsState(
                    targetValue = if (isPressed && effectiveAnimationsEnabled) 0.975f else 1f,
                    animationSpec = tween(durationMillis = 150, easing = FastOutSlowInEasing),
                    label = "homeAlbumScale"
                )
                Column(
                    modifier = Modifier
                        .graphicsLayer {
                            scaleX = scale
                            scaleY = scale
                        }
                        .width(cardWidth)
                        .clickable(
                            interactionSource = interaction,
                            indication = null,
                            onClick = { onOpen(album) }
                        ),
                    verticalArrangement = Arrangement.spacedBy(DerbisCardDesign.CaptionTopGap)
                ) {
                    val artworkShape = DerbisHomeDesign.ArtworkShape
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .aspectRatio(1f)
                            .clip(artworkShape)
                            .background(Brush.linearGradient(listOf(DerbisPanel, DerbisInk)))
                    ) {
                        if (album.thumbnailUrl.isNotBlank()) {
                            StableRemoteArtwork(
                                url = album.thumbnailUrl,
                                contentDescription = album.title,
                                contentScale = ContentScale.Crop,
                                modifier = Modifier.fillMaxSize()
                            )
                        } else {
                            Box(
                                modifier = Modifier.fillMaxSize(),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Rounded.Album,
                                    contentDescription = null,
                                    tint = DerbisCyan.copy(alpha = 0.78f),
                                    modifier = Modifier.size(42.dp)
                                )
                            }
                        }
                    }
                    DerbisCardCaption(
                        title = album.title,
                        subtitle = album.artist
                    )
                }
            }
        }
    }
}

@Composable
private fun AlbumCardRow(tracks: List<Track>, currentId: String?, animationsEnabled: Boolean, onPlay: (Track) -> Unit) {
    if (tracks.isEmpty()) return
    BoxWithConstraints(modifier = Modifier.fillMaxWidth()) {
        val cardWidth = rememberShelfItemWidth(maxWidth, DerbisHomeDesign.ArtworkCardWidth)
        LazyRow(
            horizontalArrangement = Arrangement.spacedBy(DerbisHomeDesign.ShelfItemGap),
            contentPadding = PaddingValues(start = HomeHorizontalInset, end = HomeHorizontalShelfEndPadding)
        ) {
            itemsIndexed(
                items = tracks,
                key = { index, track -> "album-card-$index-${track.id.ifBlank { "${track.title.trim().lowercase()}|${track.artist.trim().lowercase()}" }}" },
                contentType = { _, _ -> "album-card" }
            ) { _, track ->
                AlbumArtworkCard(
                    track = track,
                    isCurrent = track.id == currentId,
                    animationsEnabled = animationsEnabled,
                    width = cardWidth,
                    onPlay = { onPlay(track) }
                )
            }
        }
    }
}

@Composable
private fun rememberShelfItemWidth(
    availableWidth: Dp,
    baseWidth: Dp,
    itemGap: Dp = DerbisHomeDesign.ShelfItemGap,
    maxGrowth: Float = 1.15f
): Dp = remember(availableWidth, baseWidth, itemGap, maxGrowth) {
    val visible = availableWidth - HomeHorizontalInset
    val usable = visible - HomeHorizontalShelfEndPadding
    if (usable <= baseWidth) {
        baseWidth
    } else {
        val columns = ((visible + itemGap).value / (baseWidth + itemGap).value)
            .toInt()
            .coerceAtLeast(1)
        val exact = (usable - itemGap * (columns - 1)) / columns
        exact.coerceIn(baseWidth, baseWidth * maxGrowth)
    }
}

@Composable
private fun AlbumCardGrid(tracks: List<Track>, currentId: String?, animationsEnabled: Boolean, onPlay: (Track) -> Unit) {
    if (tracks.isEmpty()) return
    val columns = remember(tracks) {
        tracks.take(HomeSectionLayoutPolicy.ARTWORK_GRID_CAPACITY).chunked(2)
    }
    BoxWithConstraints(modifier = Modifier.fillMaxWidth()) {
        val cardWidth = rememberShelfItemWidth(maxWidth, DerbisHomeDesign.ArtworkGridCardWidth)
        LazyRow(
            horizontalArrangement = Arrangement.spacedBy(DerbisHomeDesign.ShelfItemGap),
            contentPadding = PaddingValues(start = HomeHorizontalInset, end = HomeHorizontalShelfEndPadding)
        ) {
            itemsIndexed(
                items = columns,
                key = { index, column -> "album-grid-$index-${column.firstOrNull()?.id.orEmpty()}" },
                contentType = { _, _ -> "album-grid-column" }
            ) { _, column ->
                Column(
                    modifier = Modifier.width(cardWidth),
                    verticalArrangement = Arrangement.spacedBy(DerbisHomeDesign.ShelfItemGap)
                ) {
                    column.forEach { track ->
                        AlbumArtworkCard(
                            track = track,
                            isCurrent = track.id == currentId,
                            animationsEnabled = animationsEnabled,
                            width = cardWidth,
                            onPlay = { onPlay(track) }
                        )
                    }
                }
            }
        }
    }
}

@Composable
private fun AlbumArtworkCard(
    track: Track,
    isCurrent: Boolean,
    animationsEnabled: Boolean,
    width: Dp,
    onPlay: () -> Unit
) {
    val effectiveAnimationsEnabled = animationsEnabled && LocalAnimationsEnabled.current
    val interaction = remember { MutableInteractionSource() }
    val isPressed by interaction.collectIsPressedAsState()
    val scale by animateFloatAsState(
        targetValue = if (isPressed && effectiveAnimationsEnabled) 0.975f else 1f,
        animationSpec = tween(durationMillis = 150, easing = FastOutSlowInEasing),
        label = "albumCardScale"
    )
    Column(
        modifier = Modifier
            .graphicsLayer {
                scaleX = scale
                scaleY = scale
            }
            .width(width)
            .clickable(
                interactionSource = interaction,
                indication = null,
                onClick = onPlay
            ),
        verticalArrangement = Arrangement.spacedBy(DerbisCardDesign.CaptionTopGap)
    ) {
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .aspectRatio(1f)
                .clip(DerbisCardDesign.ArtworkShape)
                .background(DerbisPanel)
        ) {
            CoverImage(
                track = track,
                modifier = Modifier.fillMaxSize(),
                highRes = false
            )
        }
        DerbisCardCaption(
            title = track.title,
            subtitle = track.artist,
            titleColor = if (isCurrent) DerbisCyan else DerbisText
        )
    }
}

@Composable
private fun RowCarousel(
    tracks: List<Track>,
    currentId: String?,
    isPlaying: Boolean,
    isResolving: Boolean,
    favoriteIds: Set<String>,
    onPlay: (Track) -> Unit,
    onFavorite: (Track) -> Unit,
    onAddToPlaylist: (Track) -> Unit,
    onAddToQueue: (Track) -> Unit,
    onDownload: (Track) -> Unit
) {
    if (tracks.isEmpty()) return
    val perPage = 4
    val pages = (tracks.size + perPage - 1) / perPage
    val pagerState = rememberPagerState(pageCount = { pages })
    HorizontalPager(
        state = pagerState,
        pageSpacing = 16.dp,
        contentPadding = PaddingValues(end = if (pages > 1) 48.dp else 0.dp)
    ) { page ->
        Column(verticalArrangement = Arrangement.spacedBy(14.dp)) {
            tracks.drop(page * perPage).take(perPage).forEach { track ->
                CompactRow(
                    track = track,
                    isCurrent = track.id == currentId,
                    isPlaying = isPlaying && track.id == currentId,
                    isResolving = isResolving && track.id == currentId,
                    isFavorite = track.id in favoriteIds,
                    onClick = { onPlay(track) },
                    onFavorite = { onFavorite(track) },
                    onAddToPlaylist = { onAddToPlaylist(track) },
                    onAddToQueue = { onAddToQueue(track) },
                    onDownload = { onDownload(track) }
                )
            }
        }
    }
}

@Composable
private fun CompactRow(
    track: Track,
    isCurrent: Boolean,
    isPlaying: Boolean,
    isResolving: Boolean,
    isFavorite: Boolean,
    onClick: () -> Unit,
    onFavorite: () -> Unit,
    onAddToPlaylist: () -> Unit,
    onAddToQueue: () -> Unit,
    onDownload: () -> Unit
) {
    val context = LocalContext.current
    val strings = LocalDerbisStrings.current
    var expanded by remember { mutableStateOf(false) }
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .pressable(onClick = onClick),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(12.dp)
    ) {
        Box {
            CoverImage(track, Modifier.size(DerbisCardDesign.RowThumb).clip(DerbisCardDesign.ThumbShape))
            if (isPlaying || isResolving) {
                Surface(color = Color.Black.copy(alpha = 0.45f), shape = DerbisCardDesign.ThumbShape, modifier = Modifier.matchParentSize()) {
                    Box(contentAlignment = Alignment.Center) {
                        if (isResolving) DerbisLoadingIndicator(modifier = Modifier.size(18.dp), color = DerbisCyan)
                        else Icon(Icons.Rounded.Equalizer, null, tint = DerbisCyan, modifier = Modifier.size(20.dp))
                    }
                }
            }
        }
        DerbisRowText(
            title = track.title,
            subtitle = track.artist,
            titleColor = if (isCurrent) DerbisCyan else DerbisText,
            modifier = Modifier.weight(1f)
        )
        Box {
            IconButton(onClick = { expanded = true }) {
                Icon(
                    imageVector = Icons.Rounded.MoreVert,
                    contentDescription = LocalDerbisStrings.current.songOptions,
                    tint = DerbisMuted,
                    modifier = Modifier.size(22.dp)
                )
            }
            DropdownMenu(expanded = expanded, onDismissRequest = { expanded = false }) {
                DropdownMenuItem(
                    text = { Text(if (isFavorite) LocalDerbisStrings.current.removeFromFavorites else LocalDerbisStrings.current.addToFavorites) },
                    leadingIcon = { Icon(if (isFavorite) Icons.Rounded.Favorite else Icons.Rounded.FavoriteBorder, null) },
                    onClick = {
                        expanded = false
                        onFavorite()
                    }
                )
                DropdownMenuItem(
                    text = { Text(LocalDerbisStrings.current.addToPlaylist) },
                    leadingIcon = { Icon(Icons.AutoMirrored.Rounded.PlaylistAdd, null) },
                    onClick = {
                        expanded = false
                        onAddToPlaylist()
                    }
                )
                DropdownMenuItem(
                    text = { Text(LocalDerbisStrings.current.addToQueue) },
                    leadingIcon = { Icon(Icons.AutoMirrored.Rounded.QueueMusic, null) },
                    onClick = {
                        expanded = false
                        onAddToQueue()
                    }
                )
                DropdownMenuItem(
                    text = { Text(LocalDerbisStrings.current.download) },
                    leadingIcon = { Icon(Icons.Rounded.Download, null) },
                    onClick = {
                        expanded = false
                        onDownload()
                    }
                )
                DropdownMenuItem(
                    text = { Text(LocalDerbisStrings.current.share) },
                    leadingIcon = { Icon(Icons.Rounded.Share, null) },
                    onClick = {
                        expanded = false
                        val shareText = buildString {
                            append(track.title)
                            if (track.artist.isNotBlank()) append(" - ").append(track.artist)
                            val link = track.videoUrl.ifBlank { track.streamUrl }
                            if (link.isNotBlank()) append("\n").append(link)
                        }
                        val intent = Intent(Intent.ACTION_SEND).apply {
                            type = "text/plain"
                            putExtra(Intent.EXTRA_TEXT, shareText)
                        }
                        context.startActivity(Intent.createChooser(intent, strings.shareSong))
                    }
                )
            }
        }
    }
}
