@Composable
private fun SearchFilterChips(
    selected: SearchFilter,
    hasArtists: Boolean,
    hasAlbums: Boolean,
    hasPlaylists: Boolean,
    hasVideos: Boolean,
    onSelect: (SearchFilter) -> Unit
) {
    val strings = LocalDerbisStrings.current
    if (DerbisIsYouTubeMusic) {
        val chips = buildList {
            add(SearchFilter.Lyrics to strings.lyrics)
            if (hasArtists) add(SearchFilter.Artists to strings.artistsLabelPlural)
            add(SearchFilter.Songs to strings.songsPlain)
            if (hasVideos) add(SearchFilter.Videos to strings.video)
            if (hasPlaylists) add(SearchFilter.Playlists to strings.playlistsPlain)
            if (hasAlbums) add(SearchFilter.Albums to strings.albumsPlain)
        }
        Row(
            modifier = Modifier
                .recentSearchesBleed(RecentSearchGutter)
                .horizontalScroll(rememberScrollState())
                .padding(horizontal = RecentSearchGutter),
            horizontalArrangement = Arrangement.spacedBy(YouTubeMusicDesign.chipGap)
        ) {
            chips.forEach { (filter, label) ->
                YouTubeMusicChip(
                    label = label,
                    selected = filter == selected,
                    leadingIcon = if (filter == SearchFilter.Lyrics) {
                        {
                            Icon(
                                painter = painterResource(R.drawable.ic_studio_lyrics),
                                contentDescription = null,
                                tint = if (filter == selected) Color.Black else YouTubeMusicDesign.text,
                                modifier = Modifier.size(15.dp)
                            )
                        }
                    } else null
                ) {
                    onSelect(if (filter == selected) SearchFilter.All else filter)
                }
            }
        }
        return
    }
    val chips = buildList {
        add(SearchFilter.All to strings.all)
        add(SearchFilter.Lyrics to strings.lyrics)
        add(SearchFilter.Songs to strings.songsPlain)
        if (hasArtists) add(SearchFilter.Artists to strings.artistsLabelPlural)
        if (hasAlbums) add(SearchFilter.Albums to strings.albumsPlain)
        if (hasPlaylists) add(SearchFilter.Playlists to strings.playlistsPlain)
        if (hasVideos) add(SearchFilter.Videos to strings.video)
    }
    Row(
        modifier = Modifier
            .recentSearchesBleed(RecentSearchGutter)
            .horizontalScroll(rememberScrollState())
            .padding(horizontal = RecentSearchGutter),
        horizontalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        chips.forEach { (filter, label) ->
            DerbisFilterPill(
                label = label,
                selected = filter == selected,
                onClick = { onSelect(filter) }
            )
        }
    }
}

private const val TOP_RESULT_BACKDROP_PIXELS = 24

@Composable
private fun TopResultCard(
    tracks: List<Track>,
    artist: ArtistHit?,
    currentTrackId: String?,
    isPlaying: Boolean,
    isResolving: Boolean,
    favoriteIds: Set<String>,
    selection: TrackSelectionState,
    onPlay: (Track) -> Unit,
    onFavorite: (Track) -> Unit,
    onAddToPlaylist: (Track) -> Unit,
    onPlayNext: (Track) -> Unit,
    onAddToQueue: (Track) -> Unit,
    onArtist: () -> Unit,
    onShuffle: () -> Unit,
    onMix: () -> Unit
) {
    val hero = tracks.firstOrNull() ?: return
    val strings = LocalDerbisStrings.current
    val cardBg = MaterialTheme.colorScheme.surfaceContainer
    val heroArtwork = hero.largeThumbnailUrl.ifBlank { hero.thumbnailUrl }

    Box(
        modifier = Modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(32.dp))
            .background(cardBg)
    ) {
        if (heroArtwork.isNotBlank()) {
            val context = LocalContext.current
            val backdropRequest = remember(heroArtwork) {
                ImageRequest.Builder(context)
                    .data(heroArtwork)
                    .size(TOP_RESULT_BACKDROP_PIXELS)
                    .crossfade(true)
                    .build()
            }
            AsyncImage(
                model = backdropRequest,
                contentDescription = null,
                contentScale = ContentScale.Crop,
                filterQuality = FilterQuality.Low,
                alpha = 0.58f,
                modifier = Modifier.matchParentSize()
            )
        }
        Box(
            modifier = Modifier
                .matchParentSize()
                .background(
                    Brush.verticalGradient(
                        0f to cardBg.copy(alpha = 0.30f),
                        0.42f to cardBg.copy(alpha = 0.78f),
                        1f to cardBg
                    )
                )
        )
        Column(modifier = Modifier.padding(top = 18.dp, bottom = 10.dp)) {
            Text(
                text = strings.topResult.uppercase(Locale.forLanguageTag(strings.code)),
                color = MaterialTheme.colorScheme.primary,
                fontSize = 11.sp,
                fontWeight = FontWeight.Black,
                letterSpacing = 1.6.sp,
                maxLines = 1,
                modifier = Modifier.padding(start = 20.dp, end = 20.dp, bottom = 12.dp)
            )

            TopResultArtistHeader(
                hero = hero,
                artist = artist,
                enabled = !selection.isActive,
                onArtist = onArtist
            )

            TopResultActions(
                enabled = !selection.isActive,
                onPlay = { onPlay(hero) },
                onShuffle = onShuffle,
                onMix = onMix
            )

            tracks.take(3).forEachIndexed { index, track ->
                val selectionKey = trackSelectionKey(track)
                TopResultTrackRow(
                    track = track,
                    emphasized = index == 0,
                    isCurrent = track.id == currentTrackId,
                    isPlaying = isPlaying && track.id == currentTrackId,
                    isResolving = isResolving && track.id == currentTrackId,
                    isFavorite = track.id in favoriteIds,
                    selected = selection.isSelected(selectionKey),
                    selectionActive = selection.isActive,
                    onLongClick = { selection.start(selectionKey) },
                    onPlay = {
                        if (selection.isActive) selection.toggle(selectionKey) else onPlay(track)
                    },
                    onFavorite = { onFavorite(track) },
                    onAddToPlaylist = { onAddToPlaylist(track) },
                    onPlayNext = { onPlayNext(track) },
                    onAddToQueue = { onAddToQueue(track) },
                    onArtist = onArtist
                )
            }
        }
    }
}

