@Composable
private fun TopResultTrackRow(
    track: Track,
    emphasized: Boolean,
    isCurrent: Boolean,
    isPlaying: Boolean,
    isResolving: Boolean,
    isFavorite: Boolean,
    selected: Boolean,
    selectionActive: Boolean,
    onLongClick: () -> Unit,
    onPlay: () -> Unit,
    onFavorite: () -> Unit,
    onAddToPlaylist: () -> Unit,
    onPlayNext: () -> Unit,
    onAddToQueue: () -> Unit,
    onArtist: () -> Unit
) {
    val strings = LocalDerbisStrings.current

    Row(
        modifier = Modifier
            .fillMaxWidth()
            .background(if (selected) DerbisCyan.copy(alpha = 0.10f) else Color.Transparent)
            .semantics { this.selected = selected }
            .combinedClickable(onClick = onPlay, onLongClick = onLongClick)
            .padding(horizontal = 20.dp, vertical = if (emphasized) 8.dp else 6.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Box(
            modifier = Modifier
                .size(SearchRowArtworkSize)
                .clip(SearchRowArtworkShape)
        ) {
            CoverImage(track, Modifier.fillMaxSize())
            if (isPlaying || isResolving) {
                Surface(
                    color = Color.Black.copy(alpha = 0.52f),
                    modifier = Modifier.matchParentSize()
                ) {
                    Box(contentAlignment = Alignment.Center) {
                        if (isResolving) {
                            DerbisLoadingIndicator(
                                modifier = Modifier.size(18.dp),
                                color = DerbisCyan
                            )
                        } else {
                            Icon(
                                imageVector = Icons.Rounded.Equalizer,
                                contentDescription = null,
                                tint = DerbisCyan,
                                modifier = Modifier.size(20.dp)
                            )
                        }
                    }
                }
            }
        }

        Spacer(modifier = Modifier.width(12.dp))

        Column(
            modifier = Modifier.weight(1f),
            verticalArrangement = Arrangement.spacedBy(2.dp)
        ) {
            Text(
                text = track.title,
                color = if (isCurrent) DerbisCyan else DerbisText,
                fontSize = if (emphasized) 17.sp else 15.sp,
                fontWeight = if (emphasized) FontWeight.Bold else FontWeight.SemiBold,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )

            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(5.dp)
            ) {
                if (track.explicit) {
                    Surface(
                        color = if (DerbisIsLight) DerbisPanelSoft else Color.White.copy(alpha = 0.12f),
                        shape = RoundedCornerShape(3.dp),
                        modifier = Modifier.size(width = 14.dp, height = 14.dp)
                    ) {
                        Box(contentAlignment = Alignment.Center) {
                            Text(
                                text = "E",
                                color = DerbisMuted,
                                fontSize = 9.sp,
                                fontWeight = FontWeight.Bold,
                                lineHeight = 9.sp
                            )
                        }
                    }
                }

                val subtitle = remember(track.youtubeViewCount, track.durationMs, strings.code) {
                    val plays = formatSearchViewCount(track.youtubeViewCount, strings.code)
                    val songLabel = strings.song
                    when {
                        plays.isNotBlank() -> "$songLabel • $plays ${strings.pulsePlays}"
                        track.durationMs > 0L -> "$songLabel • ${formatDuration(track.durationMs)}"
                        else -> songLabel
                    }
                }

                Text(
                    text = subtitle,
                    color = DerbisMuted,
                    fontSize = 13.sp,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )
            }
        }

        if (selectionActive) {
            Icon(
                imageVector = if (selected) Icons.Rounded.CheckCircle else Icons.Rounded.RadioButtonUnchecked,
                contentDescription = null,
                tint = if (selected) DerbisCyan else DerbisMuted,
                modifier = Modifier.size(28.dp)
            )
        } else {
            var menuExpanded by remember(track.id) { mutableStateOf(false) }
            Box {
                IconButton(
                    onClick = { menuExpanded = true },
                    modifier = Modifier.size(36.dp)
                ) {
                    Icon(
                        imageVector = Icons.Rounded.MoreVert,
                        contentDescription = strings.more,
                        tint = DerbisMuted,
                        modifier = Modifier.size(20.dp)
                    )
                }
                DropdownMenu(
                    expanded = menuExpanded,
                    onDismissRequest = { menuExpanded = false },
                    modifier = Modifier
                        .background(DerbisPanel)
                        .border(1.dp, DerbisAdaptiveHairline, RoundedCornerShape(8.dp))
                ) {
                    DropdownMenuItem(
                        text = { Text(if (isFavorite) strings.removeFromFavorites else strings.addToFavorites, color = DerbisText) },
                        leadingIcon = {
                            Icon(
                                if (isFavorite) Icons.Rounded.Favorite else Icons.Rounded.FavoriteBorder,
                                null,
                                tint = if (isFavorite) DerbisPink else DerbisText
                            )
                        },
                        onClick = {
                            menuExpanded = false
                            onFavorite()
                        }
                    )
                    DropdownMenuItem(
                        text = { Text(strings.playNext, color = DerbisText) },
                        leadingIcon = { Icon(Icons.AutoMirrored.Rounded.QueueMusic, null, tint = DerbisText) },
                        onClick = {
                            menuExpanded = false
                            onPlayNext()
                        }
                    )
                    DropdownMenuItem(
                        text = { Text(strings.addToQueue, color = DerbisText) },
                        leadingIcon = { Icon(Icons.AutoMirrored.Rounded.QueueMusic, null, tint = DerbisText) },
                        onClick = {
                            menuExpanded = false
                            onAddToQueue()
                        }
                    )
                    DropdownMenuItem(
                        text = { Text(strings.addToPlaylist, color = DerbisText) },
                        leadingIcon = { Icon(Icons.AutoMirrored.Rounded.PlaylistAdd, null, tint = DerbisText) },
                        onClick = {
                            menuExpanded = false
                            onAddToPlaylist()
                        }
                    )
                    DropdownMenuItem(
                        text = { Text(strings.openArtist, color = DerbisText) },
                        leadingIcon = { Icon(Icons.Rounded.Person, null, tint = DerbisText) },
                        onClick = {
                            menuExpanded = false
                            onArtist()
                        }
                    )
                }
            }
        }
    }
}

@Composable
private fun SearchTrackPlayCount(track: Track) {
    if (track.youtubeViewCount <= 0L) return
    val strings = LocalDerbisStrings.current
    val count = remember(track.youtubeViewCount, strings.code) {
        formatSearchViewCount(track.youtubeViewCount, strings.code)
    }
    Text(
        text = "${strings.song} • $count ${strings.pulsePlays}",
        color = DerbisMuted.copy(alpha = 0.88f),
        fontSize = 11.5.sp,
        fontWeight = FontWeight.SemiBold,
        maxLines = 1,
        overflow = TextOverflow.Ellipsis
    )
}

internal fun formatSearchViewCount(views: Long, languageCode: String): String {
    if (views <= 0L) return ""
    val locale = Locale.forLanguageTag(languageCode.replace('_', '-'))
    val (divisor, suffix) = when {
        views >= 1_000_000_000L -> 1_000_000_000.0 to if (locale.language == "it") "Mld" else "B"
        views >= 1_000_000L -> 1_000_000.0 to if (locale.language == "it") "Mln" else "M"
        views >= 1_000L -> 1_000.0 to if (locale.language == "it") "mila" else "K"
        else -> 1.0 to ""
    }
    val scaled = views / divisor
    val pattern = if (divisor > 1.0 && scaled < 10.0 && kotlin.math.abs(scaled - scaled.toLong()) > 0.05) "%.1f" else "%.0f"
    val number = String.format(locale, pattern, scaled)
    return if (suffix.isBlank()) number else "$number $suffix"
}

private val SearchRowArtworkSize = 56.dp
private val SearchRowArtworkShape = RoundedCornerShape(14.dp)

@Composable
private fun SearchTrackCard(
    track: Track,
    isCurrent: Boolean,
    isPlaying: Boolean,
    isResolving: Boolean,
    isFavorite: Boolean,
    selected: Boolean = false,
    selectionActive: Boolean = false,
    onLongClick: () -> Unit = {},
    isDownloading: Boolean,
    isDownloaded: Boolean,
    downloadProgress: Int?,
    onClick: () -> Unit,
    onFavorite: () -> Unit,
    onAddToPlaylist: () -> Unit,
    onDownload: () -> Unit
) {
    val strings = LocalDerbisStrings.current
    val rowAccent = if (isCurrent) rememberNowPlayingAccent(track, DerbisCyan) else DerbisCyan
    val rowPadding by animateDpAsState(
        targetValue = if (isCurrent || selected) 9.dp else 0.dp,
        animationSpec = if (LocalAnimationsEnabled.current) DerbisMotion.standard() else snap(),
        label = "search-track-row-padding"
    )
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clip(TrackRowShape)
            .background(
                if (isCurrent) {
                    cinematicGlassBrush(Color(track.accentStart), Color(track.accentEnd), 0.82f)
                } else {
                    SolidColor(Color.Transparent)
                }
            )
            .border(
                1.dp,
                when {
                    selected -> DerbisCyan.copy(alpha = 0.58f)
                    isCurrent -> rowAccent.copy(alpha = 0.30f)
                    else -> Color.Transparent
                },
                TrackRowShape
            )
            .semantics { this.selected = selected }
            .derbisPressable(
                onClick = onClick,
                onLongClick = onLongClick,
                pressedScale = DerbisPressScale.Row
            )
            .padding(horizontal = rowPadding, vertical = 7.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(DerbisCardDesign.RowTextGap)
    ) {
        Box {
            CoverImage(track, Modifier.size(SearchRowArtworkSize).clip(SearchRowArtworkShape))
            if (isPlaying || isResolving) {
                Surface(color = Color.Black.copy(alpha = 0.5f), shape = SearchRowArtworkShape, modifier = Modifier.matchParentSize()) {
                    Box(contentAlignment = Alignment.Center) {
                        if (isResolving) {
                            DerbisLoadingIndicator(modifier = Modifier.size(20.dp), color = rowAccent)
                        } else {
                            DerbisPlayingIndicator(
                                playing = isPlaying,
                                color = rowAccent,
                                size = 20.dp,
                                contentDescription = strings.playing
                            )
                        }
                    }
                }
            }
        }
        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(DerbisCardDesign.RowLineGap)) {
            Text(
                track.title,
                color = if (isCurrent) rowAccent else DerbisText,
                style = DerbisType.contentTitle.copy(fontWeight = if (isCurrent) FontWeight.Bold else FontWeight.SemiBold),
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
            val playsLabel = remember(track.youtubeViewCount, strings.code, strings.pulsePlays) {
                formatSearchViewCount(track.youtubeViewCount, strings.code)
                    .takeIf(String::isNotBlank)
                    ?.let { "$it ${strings.pulsePlays}" }
                    .orEmpty()
            }
            Row(verticalAlignment = Alignment.CenterVertically) {
                Text(
                    track.artist,
                    color = DerbisMuted,
                    style = DerbisType.metadata,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    modifier = Modifier.weight(1f, fill = false)
                )
                if (playsLabel.isNotEmpty()) {
                    Text(
                        " · $playsLabel",
                        color = DerbisMuted,
                        style = DerbisType.metadata,
                        maxLines = 1,
                        softWrap = false
                    )
                }
            }
        }
        if (selectionActive) {
            Icon(
                imageVector = if (selected) Icons.Rounded.CheckCircle else Icons.Rounded.RadioButtonUnchecked,
                contentDescription = null,
                tint = if (selected) DerbisCyan else DerbisMuted,
                modifier = Modifier.size(28.dp)
            )
        } else {
            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(0.dp)) {
                DownloadButton(
                    isDownloading = isDownloading,
                    isDownloaded = isDownloaded,
                    progress = downloadProgress,
                    onDownload = onDownload
                )
                IconButton(onClick = onAddToPlaylist, modifier = Modifier.size(36.dp)) {
                    Icon(
                        Icons.AutoMirrored.Rounded.PlaylistAdd,
                        contentDescription = LocalDerbisStrings.current.addToPlaylist,
                        tint = DerbisMuted,
                        modifier = Modifier.size(24.dp)
                    )
                }
                IconButton(onClick = onFavorite, modifier = Modifier.size(36.dp)) {
                    Icon(
                        imageVector = if (isFavorite) Icons.Rounded.Favorite else Icons.Rounded.FavoriteBorder,
                        contentDescription = LocalDerbisStrings.current.favorite,
                        tint = if (isFavorite) DerbisPink else DerbisMuted,
                        modifier = Modifier.size(24.dp)
                    )
                }
            }
        }
    }
}

