@Composable
private fun PlaylistHitRow(
    playlists: List<PlaylistHit>,
    onOpen: (PlaylistHit) -> Unit,
    onPlay: (PlaylistHit) -> Unit,
    onDownload: (PlaylistHit) -> Unit
) {
    val context = LocalContext.current
    val strings = LocalDerbisStrings.current
    LazyRow(horizontalArrangement = Arrangement.spacedBy(12.dp)) {
        itemsIndexed(
            items = playlists,
            key = { index, playlist ->
                "playlist-hit-$index-${playlist.playlistId.ifBlank { playlist.title.trim().lowercase(Locale.ROOT) }}"
            },
            contentType = { _, _ -> "playlist-hit" }
        ) { _, playlist ->
            val trackCount = playlist.trackCountLabel.trim()
            Column(
                modifier = Modifier.width(164.dp),
                verticalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                Box(modifier = Modifier.size(164.dp)) {
                    Box(
                        modifier = Modifier
                            .matchParentSize()
                            .clip(RoundedCornerShape(28.dp))
                            .background(MaterialTheme.colorScheme.surfaceContainerHigh)
                            .derbisPressable(
                                onClick = { onOpen(playlist) },
                                pressedScale = DerbisPressScale.Tile,
                                role = Role.Button,
                                onClickLabel = strings.open
                            ),
                        contentAlignment = Alignment.Center
                    ) {
                        if (playlist.thumbnailUrl.isNotBlank()) {
                            val request = remember(playlist.thumbnailUrl) {
                                ImageRequest.Builder(context).data(playlist.thumbnailUrl).crossfade(true).build()
                            }
                            AsyncImage(
                                model = request,
                                contentDescription = null,
                                contentScale = ContentScale.Crop,
                                modifier = Modifier.matchParentSize()
                            )
                        } else {
                            Icon(Icons.AutoMirrored.Rounded.PlaylistPlay, null, tint = DerbisMuted, modifier = Modifier.size(44.dp))
                        }
                        Box(
                            modifier = Modifier
                                .matchParentSize()
                                .background(
                                    Brush.verticalGradient(
                                        0.55f to Color.Transparent,
                                        1f to Color.Black.copy(alpha = 0.42f)
                                    )
                                )
                        )
                    }
                    PlaylistHitPlayBadge(
                        label = strings.play,
                        onClick = { onPlay(playlist) },
                        modifier = Modifier
                            .align(Alignment.BottomEnd)
                            .padding(10.dp)
                    )
                    Surface(
                        color = Color.Black.copy(alpha = 0.38f),
                        contentColor = Color.White,
                        shape = CircleShape,
                        modifier = Modifier
                            .align(Alignment.TopEnd)
                            .padding(10.dp)
                            .size(36.dp)
                            .clickable(onClickLabel = strings.downloadPlaylist, role = Role.Button) { onDownload(playlist) }
                    ) {
                        Box(contentAlignment = Alignment.Center) {
                            Icon(
                                imageVector = Icons.Rounded.Download,
                                contentDescription = strings.downloadPlaylist,
                                modifier = Modifier.size(18.dp)
                            )
                        }
                    }
                }
                Column(
                    modifier = Modifier
                        .padding(horizontal = 4.dp)
                        .clickable(onClickLabel = strings.open, role = Role.Button) { onOpen(playlist) },
                    verticalArrangement = Arrangement.spacedBy(3.dp)
                ) {
                    Text(
                        playlist.title,
                        color = DerbisText,
                        fontSize = 15.sp,
                        fontWeight = FontWeight.Bold,
                        lineHeight = 18.sp,
                        maxLines = 2,
                        overflow = TextOverflow.Ellipsis
                    )
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        if (playlist.author.isNotBlank()) {
                            Text(
                                playlist.author,
                                color = DerbisMuted,
                                fontSize = 11.sp,
                                fontWeight = FontWeight.SemiBold,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis,
                                modifier = Modifier.weight(1f, fill = false)
                            )
                        }
                        if (trackCount.isNotEmpty()) {
                            Text(
                                if (playlist.author.isNotBlank()) " · $trackCount" else trackCount,
                                color = DerbisMuted,
                                fontSize = 11.sp,
                                fontWeight = FontWeight.SemiBold,
                                maxLines = 1,
                                softWrap = false
                            )
                        }
                    }
                }
            }
        }
    }
}

