        itemsIndexed(
            items = albums,
            key = { index, album -> "album-hit-$index-${album.browseId.ifBlank { "${album.title.trim().lowercase(Locale.ROOT)}-${album.artist.trim().lowercase(Locale.ROOT)}" }}" },
            contentType = { _, _ -> "album-hit" }
        ) { _, album ->
            Column(
                modifier = Modifier
                    .width(164.dp)
                    .derbisPressable(
                        onClick = { onClick(album) },
                        pressedScale = DerbisPressScale.Tile,
                        role = Role.Button,
                        onClickLabel = album.title
                    ),
                verticalArrangement = Arrangement.spacedBy(3.dp)
            ) {
                Box(
                    modifier = Modifier
                        .padding(bottom = 5.dp)
                        .size(164.dp)
                        .clip(RoundedCornerShape(28.dp))
                        .background(MaterialTheme.colorScheme.surfaceContainerHigh),
                    contentAlignment = Alignment.Center
                ) {
                    if (album.thumbnailUrl.isNotBlank()) {
                        AsyncImage(
                            model = ImageRequest.Builder(LocalContext.current).data(album.thumbnailUrl).crossfade(true).build(),
                            contentDescription = album.title,
                            contentScale = ContentScale.Crop,
                            modifier = Modifier.matchParentSize()
                        )
                    } else {
                        Icon(Icons.Rounded.Album, null, tint = DerbisMuted, modifier = Modifier.size(40.dp))
                    }
                    onDownload?.let { download ->
                        val downloadLabel = LocalDerbisStrings.current.download
                        Surface(
                            color = Color.Black.copy(alpha = 0.38f),
                            contentColor = Color.White,
                            shape = CircleShape,
                            modifier = Modifier
                                .align(Alignment.TopEnd)
                                .padding(10.dp)
                                .size(36.dp)
                                .clickable(onClickLabel = downloadLabel, role = Role.Button) { download(album) }
                        ) {
                            Box(contentAlignment = Alignment.Center) {
                                Icon(
                                    Icons.Rounded.Download,
                                    contentDescription = downloadLabel,
                                    modifier = Modifier.size(18.dp)
                                )
                            }
                        }
                    }
                }
                Text(
                    album.title,
                    color = DerbisText,
                    fontSize = 15.sp,
                    fontWeight = FontWeight.Bold,
                    lineHeight = 18.sp,
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                    modifier = Modifier.padding(horizontal = 4.dp)
                )
                Text(
                    listOf(album.year, album.artist).filter { it.isNotBlank() }.joinToString(" · "),
                    color = DerbisMuted,
                    style = DerbisType.caption,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    modifier = Modifier.padding(horizontal = 4.dp)
                )
            }
        }
    }
}

@Composable
private fun TrackRow(
    track: Track,
    isCurrent: Boolean,
    isPlaying: Boolean,
    isResolving: Boolean,
    isFavorite: Boolean,
    onClick: () -> Unit,
    onFavorite: () -> Unit,
    isDownloading: Boolean = false,
    isDownloaded: Boolean = false,
    downloadProgress: Int? = null,
    onDownload: (() -> Unit)? = null,
    onArtist: (() -> Unit)? = null,
    onAddToPlaylist: (() -> Unit)? = null,
    onRemove: (() -> Unit)? = null
) {
    val strings = LocalDerbisStrings.current
    val rowAccent = if (isCurrent) rememberNowPlayingAccent(track, DerbisCyan) else DerbisCyan
    val currentBackground = if (isCurrent) {
        remember(track.accentStart, track.accentEnd) {
            cinematicGlassBrush(Color(track.accentStart), Color(track.accentEnd), 0.82f)
        }
    } else {
        TrackRowTransparentBrush
    }
    val rowPadding by animateDpAsState(
        targetValue = if (isCurrent) 9.dp else 0.dp,
        animationSpec = if (LocalAnimationsEnabled.current) DerbisMotion.standard() else snap(),
        label = "track-row-padding"
    )
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clip(TrackRowShape)
            .background(currentBackground)
            .border(
                1.dp,
                if (isCurrent) rowAccent.copy(alpha = 0.30f) else Color.Transparent,
                TrackRowShape
            )
            .derbisPressable(onClick = onClick, pressedScale = DerbisPressScale.Row)
            .padding(horizontal = rowPadding, vertical = 8.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(DerbisCardDesign.RowTextGap)
    ) {
        Box {
            CoverImage(track, Modifier.size(56.dp).clip(TrackRowArtworkShape))
            if (isPlaying || isResolving) {
                Surface(color = Color.Black.copy(alpha = 0.5f), shape = TrackRowArtworkShape, modifier = Modifier.matchParentSize()) {
                    Box(contentAlignment = Alignment.Center) {
                        if (isResolving) {
                            DerbisLoadingIndicator(modifier = Modifier.size(20.dp), color = rowAccent)
                        } else {
                            DerbisPlayingIndicator(
                                playing = isPlaying,
                                color = rowAccent,
                                size = 20.dp,
                                contentDescription = strings.playing
                            )
                        }
                    }
                }
            }
        }
        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(2.dp)) {
            Text(
                track.title,
                color = if (isCurrent) rowAccent else DerbisText,
                style = DerbisType.contentTitle.copy(fontWeight = if (isCurrent) FontWeight.Bold else FontWeight.SemiBold),
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                Text(
                    track.artist,
                    color = DerbisMuted,
                    style = DerbisType.metadata,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    modifier = if (onArtist != null) Modifier.clickable { onArtist() } else Modifier
                )
            }
        }
        Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(0.dp)) {
            if (onDownload != null) {
                DownloadButton(
                    isDownloading = isDownloading,
                    isDownloaded = isDownloaded,
                    progress = downloadProgress,
                    onDownload = onDownload
                )
            }
            if (onAddToPlaylist != null) {
                IconButton(onClick = onAddToPlaylist, modifier = Modifier.size(36.dp)) {
                    Icon(
                        Icons.AutoMirrored.Rounded.PlaylistAdd,
                        contentDescription = LocalDerbisStrings.current.addToPlaylist,
                        tint = DerbisMuted,
                        modifier = Modifier.size(24.dp)
                    )
                }
            }
            IconButton(onClick = onFavorite, modifier = Modifier.size(36.dp)) {
                Icon(
                    imageVector = if (isFavorite) Icons.Rounded.Favorite else Icons.Rounded.FavoriteBorder,
                    contentDescription = LocalDerbisStrings.current.favorite,
                    tint = if (isFavorite) DerbisPink else DerbisMuted,
                    modifier = Modifier.size(24.dp)
                )
            }
            if (onRemove != null) {
                IconButton(onClick = onRemove, modifier = Modifier.size(36.dp)) {
                    Icon(Icons.Rounded.Delete, contentDescription = LocalDerbisStrings.current.remove, tint = DerbisMuted, modifier = Modifier.size(22.dp))
                }
            }
        }
    }
}

private enum class DownloadVisualState { Idle, Working, Done }

@Composable
private fun DownloadButton(isDownloading: Boolean, isDownloaded: Boolean, progress: Int? = null, onDownload: () -> Unit) {
    val animated = LocalAnimationsEnabled.current
    val strings = LocalDerbisStrings.current
    val visual = when {
        isDownloading -> DownloadVisualState.Working
        isDownloaded -> DownloadVisualState.Done
        else -> DownloadVisualState.Idle
    }
    val ringProgress by animateFloatAsState(
        targetValue = (progress ?: 0).coerceIn(0, 100) / 100f,
        animationSpec = DerbisMotion.spec(animated, DerbisMotion.standard(DerbisMotion.Durations.Medium)),
        label = "download-ring-progress"
    )
    IconButton(onClick = { if (!isDownloading && !isDownloaded) onDownload() }) {
        AnimatedContent(
            targetState = visual,
            transitionSpec = { downloadStateTransform(animated, initialState, targetState) },
            contentAlignment = Alignment.Center,
            label = "download-state"
        ) { shown ->
            when (shown) {
                DownloadVisualState.Working -> {
                    val label = progress?.coerceIn(1, 99)?.let { "$it%" } ?: "..."
                    Box(contentAlignment = Alignment.Center, modifier = Modifier.size(34.dp)) {
                        if (progress == null) {
                            CircularProgressIndicator(modifier = Modifier.size(28.dp), strokeWidth = 2.dp, color = DerbisCyan)
                        } else {
                            CircularProgressIndicator(
                                progress = { ringProgress },
                                modifier = Modifier.size(28.dp),
                                strokeWidth = 2.dp,
                                color = DerbisCyan,
                                trackColor = DerbisCyan.copy(alpha = 0.18f)
                            )
                        }
                        Text(label, color = DerbisCyan, fontSize = 8.sp, fontWeight = FontWeight.Black, maxLines = 1)
                    }
                }
                DownloadVisualState.Done -> Icon(Icons.Rounded.DownloadDone, contentDescription = strings.downloaded, tint = DerbisCyan, modifier = Modifier.size(23.dp))
                DownloadVisualState.Idle -> Icon(Icons.Rounded.Download, contentDescription = strings.download, tint = DerbisMuted, modifier = Modifier.size(23.dp))
            }
        }
    }
}

private fun downloadStateTransform(
    animated: Boolean,
    from: DownloadVisualState,
    to: DownloadVisualState
): ContentTransform {
    if (!animated) return EnterTransition.None togetherWith ExitTransition.None
    val completed = from == DownloadVisualState.Working && to == DownloadVisualState.Done
    val enter = if (completed) {
        scaleIn(DerbisMotion.feedback.spec(), initialScale = 0.6f) + fadeIn(DerbisMotion.fade(DerbisMotion.Durations.Quick))
    } else {
        scaleIn(DerbisMotion.settle.spec(), initialScale = 0.85f) + fadeIn(DerbisMotion.fade(DerbisMotion.Durations.Short))
    }
    val exit = scaleOut(DerbisMotion.fade(DerbisMotion.Durations.Quick), targetScale = if (completed) 1.12f else 0.85f) +
        fadeOut(DerbisMotion.fade(DerbisMotion.Durations.Instant))
    return enter togetherWith exit
}

@Composable
private fun PlayerArtworkMorphLayer(
    track: Track,
    anchors: PlayerMorphAnchors,
    active: () -> Boolean,
    expansion: () -> Float
) {
    val density = LocalDensity.current
    val startCornerPx = with(density) { DerbisPlayerDesign.MiniArtworkCorner.toPx() }
    val fullWidthPx = anchors.fullBounds?.width ?: 0f
    val cardCornerPx = with(density) { DerbisPlayerShapes.artworkCorner(fullWidthPx.toDp()).toPx() }
    val flightShadowPx = with(density) { PlayerMorphFlightShadow.toPx() }
    val artworkUrl = remember(track) { preferredPlayerArtworkUrl(track) }
    Box(
        modifier = Modifier
            .layout { measurable, constraints ->
                val rect = if (active()) {
                    anchors.resolve(playerMorphFraction(expansion()))
                } else {
                    anchors.idleBounds(constraints.maxWidth.toFloat())
                }
                if (rect == null) {
                    val placeable = measurable.measure(Constraints.fixed(0, 0))
                    layout(0, 0) { placeable.place(0, 0) }
                } else {
                    val placeable = measurable.measure(
                        Constraints.fixed(rect.width.roundToInt(), rect.height.roundToInt())
                    )
                    layout(placeable.width, placeable.height) {
                        placeable.place(rect.left.roundToInt(), rect.top.roundToInt())
                    }
                }
            }
            .graphicsLayer {
                if (!active()) {
                    alpha = 0f
                    shadowElevation = 0f
                    return@graphicsLayer
                }
                val fraction = playerMorphFraction(expansion())
                val flightAlpha = anchors.flightAlpha()
                val endCornerPx = if (anchors.targetsStage) 0f else cardCornerPx
                alpha = flightAlpha
                shadowElevation = flightShadowPx * fraction * flightAlpha
                shape = when (anchors.landing) {
                    PlayerMorphLanding.Cookie -> derbisCookieLandingShape(fraction)
                    PlayerMorphLanding.FlowPlaying, PlayerMorphLanding.FlowPaused -> flowLandingShape(
                        fraction = fraction,
                        startCorner = startCornerPx,
                        side = size.minDimension,
                        playing = anchors.landing == PlayerMorphLanding.FlowPlaying
                    )
                    PlayerMorphLanding.Rounded -> RoundedCornerShape(morphCornerRadius(startCornerPx, endCornerPx, fraction))
                }
                clip = true
            }
    ) {
        CoverImage(track, Modifier.fillMaxSize())
        SeamlessArtworkImage(url = artworkUrl, modifier = Modifier.fillMaxSize()) {}
    }
}

internal fun handleMiniPlayerDragEvent(
    event: PlayerDragEvent,
    trackId: String,
    playbackActions: MiniPlayerPlaybackActions,
    expansionActions: MiniPlayerExpansionActions,
    haptics: DerbisHaptics,
    horizontalGesturesEnabled: Boolean,
    swipe: PlayerSwipeMotion
) {
    when (event) {
        is PlayerDragEvent.HorizontalOffset -> {
            if (horizontalGesturesEnabled) swipe.follow(trackId, event.offsetPx)
        }
        is PlayerDragEvent.HorizontalSettled -> {
            val committed = horizontalGesturesEnabled && event.result != PlayerSwipeResult.Settle
            if (committed) {
                handleMiniPlayerSwipeResult(event.result, playbackActions, haptics)
            }
            swipe.release(committed = committed, carry = true)
        }
        is PlayerDragEvent.VerticalStart -> expansionActions.start()
        is PlayerDragEvent.VerticalDrag -> handleMiniPlayerVerticalDrag(event, expansionActions)
        is PlayerDragEvent.VerticalSettled -> settleMiniPlayerVerticalDrag(
            event,
            playbackActions,
            expansionActions
        )
        PlayerDragEvent.Cancelled -> {
            swipe.release(committed = false, carry = false)
            expansionActions.end(0f)
        }
    }
}

private fun handleMiniPlayerSwipeResult(
    result: PlayerSwipeResult,
    playbackActions: MiniPlayerPlaybackActions,
    haptics: DerbisHaptics
) {
    when (result) {
        PlayerSwipeResult.Next -> {
            haptics.perform(DerbisHapticAction.TrackSwipe)
            playbackActions.next()
        }
        PlayerSwipeResult.Previous -> {
            haptics.perform(DerbisHapticAction.TrackSwipe)
            playbackActions.previous()
        }
        PlayerSwipeResult.Settle -> Unit
    }
}

private fun handleMiniPlayerVerticalDrag(
    event: PlayerDragEvent.VerticalDrag,
    expansionActions: MiniPlayerExpansionActions
) {
    if (event.peeked) expansionActions.drag(event.deltaPx)
}

private fun settleMiniPlayerVerticalDrag(
    event: PlayerDragEvent.VerticalSettled,
    playbackActions: MiniPlayerPlaybackActions,
    expansionActions: MiniPlayerExpansionActions
) {
    expansionActions.end(event.velocityPx)
    val result = resolveMiniPlayerDismiss(
        event.totalPx,
        event.velocityPx,
        event.heightPx
    )
    if (!event.peeked && result == PlayerVerticalResult.Collapse) playbackActions.close()
}

private const val MiniPlayerCarryFraction = 0.5f
private val MiniPlayerCardBase = PlayerDarkSurface
private val MiniPlayerToggleRing = 54.dp
private val MiniPlayerToggleCore = 36.dp
private val MiniPlayerRingStroke = 3.dp
private const val MiniPlayerSpinMillis = 14_000
private val MiniPlayerTrayTop = 4.dp
private val MiniPlayerTrayBottom = 10.dp
private val MiniPlayerCardGutter = 12.dp
private val MiniPlayerGlowElevation = 18.dp

@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
internal fun MiniPlayer(
    model: MiniPlayerModel,
    morphAnchors: PlayerMorphAnchors,
    compaction: () -> Float,
    artworkHidden: () -> Boolean,
    playbackActions: MiniPlayerPlaybackActions,
    expansionActions: MiniPlayerExpansionActions,
    fixedAccents: PlayerAccentPair? = null
) {
    val track = model.track
    val isPlaying = model.isPlaying
    val isResolving = model.isResolving
    val liveRadio = track.isLiveRadio()
    val animated = model.animated
    val microMotion = LocalDerbisVisualCapabilities.current.microMotion
    val gesturesEnabled = model.gesturesEnabled
    val strings = LocalDerbisStrings.current
    val radioStrings = com.yasuda.derbis.ui.i18n.DerbisLiveRadioCatalog.forCode(strings.code)
    val miniRightToLeft = LocalLayoutDirection.current == LayoutDirection.Rtl
    val miniHaptics = LocalDerbisHaptics.current
    val context = LocalContext.current
    val fallbackPalette = remember(track.accentStart, track.accentEnd) {
        ArtworkPalette(track.accentStart, track.accentEnd)
    }
    val paletteKey = remember(track.id, track.thumbnailUrl, track.largeThumbnailUrl) {
        ArtworkPaletteCache.key(
            trackId = track.id,
            thumbnailUrl = track.thumbnailUrl,
            largeThumbnailUrl = track.largeThumbnailUrl
        )
    }
    val memoryPalette = remember(paletteKey) {
        ArtworkPaletteCache.peek(paletteKey)
    }
    val artworkPaletteState = remember(paletteKey) {
        mutableStateOf(memoryPalette ?: fallbackPalette)
    }

    LaunchedEffect(paletteKey) {
        if (memoryPalette == null) {
            val persistedPalette = ArtworkPaletteCache.load(context, paletteKey)
            if (persistedPalette != null) {
                artworkPaletteState.value = persistedPalette
            }
        }
    }

    val activePalette = artworkPaletteState.value
    val targetAccentStart = Color(activePalette.start)
    val targetAccentEnd = Color(activePalette.end)
    val artworkTargets = remember(targetAccentStart, targetAccentEnd) {
        harmonizePlayerAccents(targetAccentStart, targetAccentEnd)
    }
    val harmonizedTargets = fixedAccents ?: artworkTargets
    val accentStart by animateColorAsState(
        targetValue = harmonizedTargets.primary,
        animationSpec = if (animated) DerbisPlayerDesign.paletteTween() else snap(),
        label = "mini-accent-start"
    )
    val accentEnd by animateColorAsState(
        targetValue = harmonizedTargets.secondary,
        animationSpec = if (animated) DerbisPlayerDesign.paletteTween() else snap(),
        label = "mini-accent-end"
    )
    val miniProgressColor = accentStart.playerMix(Color.White, 0.72f)
    val miniPrimaryContent = DerbisPlayerDesign.TextPrimary
    val miniSecondaryContent = DerbisPlayerDesign.TextSecondary
    val animatedProgress = animateFloatAsState(
        targetValue = model.progress.coerceIn(0f, 1f),
        animationSpec = if (animated) tween(420, easing = LinearOutSlowInEasing) else snap(),
        label = "mini-progress"
    )
    val swipe = rememberPlayerSwipeMotion(animated)
    val cardShape = CircleShape
    val artworkShape = MaterialShapes.Cookie9Sided.toShape()
    val horizontalGesturesEnabled = miniPlayerHorizontalGesturesEnabled(
        gesturesEnabled = gesturesEnabled,
        swipeTrackChangeEnabled = model.swipeTrackChangeEnabled,
        liveRadio = liveRadio
    )

    Box(modifier = Modifier.fillMaxWidth()) {
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .padding(
                    start = MiniPlayerCardGutter,
                    end = MiniPlayerCardGutter,
                    top = MiniPlayerTrayTop,
                    bottom = MiniPlayerTrayBottom
                )
        ) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .dockLerpHeight(compaction, DerbisPlayerDesign.MiniHeight, DerbisPlayerDesign.MiniHeightCompact)
                    .playerMorphAnchor(morphAnchors, PlayerMorphSlot.MiniCard)
                    .shadow(
                        elevation = MiniPlayerGlowElevation,
                        shape = cardShape,
                        ambientColor = accentStart.copy(alpha = 0.40f),
                        spotColor = accentStart.copy(alpha = 0.55f)
                    )
                    .clip(cardShape)
                    .drawWithCache {
                        val fill = Brush.horizontalGradient(
                            colorStops = arrayOf(
                                0f to MiniPlayerCardBase.playerAmbienceMix(accentStart, 0.56f),
                                0.55f to MiniPlayerCardBase.playerAmbienceMix(accentStart, 0.32f),
                                1f to MiniPlayerCardBase.playerAmbienceMix(accentEnd, 0.22f)
                            )
                        )
                        val sheen = Brush.verticalGradient(
                            listOf(Color.White.copy(alpha = 0.07f), Color.Transparent)
                        )
                        onDrawWithContent {
                            drawRect(fill)
                            drawRect(sheen)
                            drawContent()
                        }
                    }
                    .playerAxisDragGestures(
                        key = "${track.id}:$horizontalGesturesEnabled",
                        enabled = gesturesEnabled,
                        rightToLeft = miniRightToLeft,
                        edgeZonesEnabled = false
                    ) { event ->
                        handleMiniPlayerDragEvent(
                            event = event,
                            trackId = track.id,
                            playbackActions = playbackActions,
                            expansionActions = expansionActions,
                            haptics = miniHaptics,
                            horizontalGesturesEnabled = horizontalGesturesEnabled,
                            swipe = swipe
                        )
                    }
                    .semantics { onClick(label = strings.expandPlayer, action = null) }
                    .pressable(pressedScale = DerbisPressScale.Row, onClick = playbackActions.open)
                    .padding(start = 8.dp, end = 8.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                AnimatedContent(
                    targetState = track,
                    modifier = Modifier
                        .weight(1f)
                        .clipToBounds()
                        .onSizeChanged { size -> swipe.carryLimitPx = size.width * MiniPlayerCarryFraction },
                    transitionSpec = { DerbisMotion.miniTrackSwap(animated) },
                    contentKey = { it.id },
                    label = "mini-track"
                ) { shownTrack ->
                    val current = shownTrack.id == track.id
                    Row(
                        modifier = Modifier.graphicsLayer {
                            val offset = swipe.offsetFor(shownTrack.id)
                            translationX = offset
                            alpha = playerSwipeContentAlpha(offset, size.width)
                        },
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        Box(
                            modifier = Modifier
                                .then(if (current) Modifier.playerMorphAnchor(morphAnchors, PlayerMorphSlot.Mini) else Modifier)
                                .dockLerpSize(compaction, DerbisPlayerDesign.MiniArtwork, DerbisPlayerDesign.MiniArtworkCompact)
                                .animateEnterExit(
                                    enter = DerbisMotion.miniArtworkEnter(microMotion),
                                    exit = ExitTransition.None
                                )
                                .graphicsLayer { alpha = if (current && artworkHidden()) 0f else 1f }
                        ) {
                            MiniPlayerSpinningArtwork(
                                track = shownTrack,
                                spinning = current && isPlaying && animated && microMotion,
                                shape = artworkShape
                            )
                        }
                        Column(
                            modifier = Modifier
                                .weight(1f)
                                .animateEnterExit(
                                    enter = DerbisMotion.miniMetadataEnter(microMotion, model.stepDirection),
                                    exit = ExitTransition.None
                                ),
                            verticalArrangement = Arrangement.Center
                        ) {
                            Text(
                                text = shownTrack.title,
                                color = miniPrimaryContent,
                                fontSize = 15.sp,
                                lineHeight = DerbisTypeRhythm.lineHeight(15.sp),
                                fontWeight = FontWeight.SemiBold,
                                letterSpacing = (-0.2).sp,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis,
                                modifier = Modifier.derbisMarquee(enabled = animated, repeatDelayMillis = 3_200)
                            )
                            Text(
                                text = if (liveRadio) {
                                    model.liveNowPlaying.ifBlank { "${radioStrings.live} / ${shownTrack.artist}" }
                                } else shownTrack.artist,
                                color = miniSecondaryContent,
                                fontSize = 13.sp,
                                lineHeight = DerbisTypeRhythm.lineHeight(13.sp),
                                fontWeight = FontWeight.Medium,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis,
                                modifier = Modifier.dockFoldHeight(compaction)
                            )
                        }
                    }
                }
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(2.dp)
                ) {
                    MiniPlayerToggleButton(
                        isPlaying = isPlaying,
                        isResolving = isResolving,
                        liveRadio = liveRadio,
                        progress = { animatedProgress.value },
                        accent = miniProgressColor,
                        animated = animated,
                        onToggle = playbackActions.toggle
                    )
                    Row(
                        modifier = Modifier.dockFoldWidth(compaction),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                    if (!liveRadio) {
                        PlayerRoundIconButton(
                            icon = Icons.Rounded.SkipNext,
                            contentDescription = strings.next,
                            size = 42.dp,
                            iconSize = 24.dp,
                            tint = miniPrimaryContent,
                            background = Color.White.copy(alpha = 0.10f),
                            borderColor = Color.Transparent,
                            onClick = playbackActions.next
                        )
                    }
                    Box(
                        modifier = Modifier
                            .sizeIn(minWidth = 40.dp, minHeight = DerbisPlayerDesign.MinimumTouchTarget)
                            .pressable(onClick = playbackActions.close),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(
                            imageVector = Icons.Rounded.Close,
                            contentDescription = strings.closePlayer,
                            tint = DerbisPlayerDesign.TextTertiary,
                            modifier = Modifier.size(18.dp)
                        )
                    }
                    }
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
internal fun MiniPlayerToggleButton(
    isPlaying: Boolean,
    isResolving: Boolean,
    liveRadio: Boolean,
    progress: () -> Float,
    accent: Color,
    animated: Boolean,
    onToggle: () -> Unit,
    modifier: Modifier = Modifier
) {
    val strings = LocalDerbisStrings.current
    val morphShape = rememberDerbisPlayMorphShape(playing = isPlaying, animated = animated)
    val ringTrack = Color.White.copy(alpha = 0.14f)
    val ringStroke = with(LocalDensity.current) { Stroke(width = MiniPlayerRingStroke.toPx(), cap = StrokeCap.Round) }
    Box(
        modifier = modifier
            .size(MiniPlayerToggleRing)
            .semantics(mergeDescendants = true) {}
            .pressable(onClick = onToggle),
        contentAlignment = Alignment.Center
    ) {
        when {
            isResolving -> CircularWavyProgressIndicator(
                modifier = Modifier.fillMaxSize(),
                color = accent,
                trackColor = ringTrack,
                stroke = ringStroke,
                trackStroke = ringStroke
            )
            liveRadio -> CircularWavyProgressIndicator(
                progress = { 1f },
                modifier = Modifier.fillMaxSize(),
                color = accent,
                trackColor = ringTrack,
                stroke = ringStroke,
                trackStroke = ringStroke
            )
            else -> CircularWavyProgressIndicator(
                progress = progress,
                modifier = Modifier.fillMaxSize(),
                color = accent,
                trackColor = ringTrack,
                stroke = ringStroke,
                trackStroke = ringStroke,
                amplitude = { if (isPlaying && animated) 1f else 0f }
            )
        }
        Box(
            modifier = Modifier
                .size(MiniPlayerToggleCore)
                .clip(morphShape)
                .background(accent),
            contentAlignment = Alignment.Center
        ) {
            DerbisPlayPauseGlyph(
                playing = isPlaying,
                color = PlayerDarkSurface,
                contentDescription = if (isPlaying) strings.pause else strings.play,
                modifier = Modifier.size(20.dp)
            )
        }
    }
}

@Composable
private fun MiniPlayerSpinningArtwork(track: Track, spinning: Boolean, shape: Shape) {
    val rotation = remember { Animatable(0f) }
    LaunchedEffect(spinning) {
        if (!spinning) return@LaunchedEffect
        while (true) {
            val start = rotation.value % 360f
            rotation.snapTo(start)
            rotation.animateTo(
                targetValue = start + 360f,
                animationSpec = tween(durationMillis = MiniPlayerSpinMillis, easing = LinearEasing)
            )
        }
    }
    Box(
        modifier = Modifier
            .fillMaxSize()
            .graphicsLayer { rotationZ = rotation.value }
            .clip(shape)
    ) {
        CoverImage(track, Modifier.fillMaxSize())
    }
}

@Composable
internal fun PlayerRoundIconButton(
    icon: ImageVector,
    contentDescription: String?,
