@Composable
private fun CircleIconButton(
    icon: ImageVector,
    tint: Color,
    background: Color,
    onClick: () -> Unit,
    contentDescription: String? = null
) {
    val resolvedBackground = if (DerbisIsLight && background.alpha < 0.2f) DerbisAdaptiveChip else background
    val resolvedBorder = if (DerbisIsLight && background.alpha < 0.2f) DerbisAdaptiveHairline else Color.Transparent
    Box(
        modifier = Modifier
            .size(46.dp)
            .background(resolvedBackground, CircleShape)
            .border(Dp.Hairline, resolvedBorder, CircleShape)
            .pressable(onClick = onClick),
        contentAlignment = Alignment.Center
    ) {
        Icon(icon, contentDescription, tint = tint, modifier = Modifier.size(21.dp))
    }
}

@Composable
private fun ExploreScreen(
    viewModel: ExploreViewModel,
    state: DerbisUiState,
    liveRadioOpen: Boolean,
    backEnabled: Boolean,
    onLiveRadioOpenChange: (Boolean) -> Unit,
    onOpenJam: () -> Unit
) {
    val strings = LocalDerbisStrings.current
    LaunchedEffect(strings.code) { viewModel.ensureExplore(strings) }
    val context = LocalContext.current
    val listState = rememberLazyListState()
    var addToPlaylistTarget by remember { mutableStateOf<Track?>(null) }
    var exploreDestination by rememberSaveable { mutableStateOf<String?>(null) }
    var exploreMoodReturn by rememberSaveable { mutableStateOf<String?>(null) }
    LaunchedEffect(state.exploreOpenRequest) {
        val requestedZoneId = state.exploreOpenRequest ?: return@LaunchedEffect
        exploreMoodReturn = null
        exploreDestination = exploreMoodDestination(requestedZoneId)
        viewModel.consumeExploreOpenRequest()
    }

    val zones = remember(strings) { ExploreCatalog.getZones(strings) }
    val selectedZone = remember(zones, state.exploreZoneId) {
        zones.firstOrNull { zone -> zone.id == state.exploreZoneId }
    }
    val localFreshTracks = state.exploreFreshTracks
    val worldFreshTracks = state.exploreWorldFreshTracks
    var freshScope by rememberSaveable { mutableStateOf(ExploreFreshScope.Local) }
    val freshScopes = remember(localFreshTracks, worldFreshTracks) {
        exploreFreshScopes(localFreshTracks, worldFreshTracks)
    }
    val freshFeed = remember(freshScope, localFreshTracks, worldFreshTracks) {
        exploreFreshFeed(freshScope, localFreshTracks, worldFreshTracks)
    }
    val freshTracks = remember(freshFeed) { freshFeed.spotlight + freshFeed.moment }
    val momentPages = remember(freshFeed) { exploreMomentPages(freshFeed.moment) }
    val freshRegionLabel = remember(state.languageCode) {
        ChartsCatalog.defaultRegionForLanguage(state.languageCode).label
    }
    val freshSection = remember(freshScopes, freshFeed, momentPages, freshRegionLabel) {
        ExploreFreshSection(freshScopes, freshFeed, momentPages, freshRegionLabel)
    }
    val rows = remember(
        zones,
        state.isFreshCurrentsLoading,
        freshFeed.spotlight.isNotEmpty(),
        freshScopes.size > 1,
        momentPages.isNotEmpty()
    ) {
        buildExploreRows(
            zones = zones,
            isFreshLoading = state.isFreshCurrentsLoading,
            hasFreshTracks = freshFeed.spotlight.isNotEmpty(),
            hasFreshScopes = freshScopes.size > 1,
            hasFreshMoment = momentPages.isNotEmpty()
        )
    }
    val availableAnchors = remember(rows) { exploreAvailableAnchors(rows) }

    val onShortcut: (ExploreShortcut) -> Unit = { shortcut ->
        when (shortcut) {
            ExploreShortcut.NewReleases -> exploreDestination = ExploreNewReleasesDestination
            ExploreShortcut.Moods -> exploreDestination = ExploreMoodsDestination
        }
    }
    val onPlayFresh: (() -> Unit)? = freshTracks.firstOrNull()?.let { first ->
        { viewModel.playFrom(freshTracks, first) }
    }

    val exploreMixAccent = rememberNowPlayingAccent(state.currentTrack, DerbisCyan)
    var trackStoryShareTarget by remember { mutableStateOf<Track?>(null) }
    val shareFreshTrack: (Track) -> Unit = { track ->
        trackStoryShareTarget = track
    }
    val onPlayFreshTrack: (Track) -> Unit = { track ->
        if (track.id == state.currentTrack?.id) viewModel.togglePlay()
        else viewModel.playFrom(freshTracks, track)
    }
    val freshTrackActions: @Composable (Track) -> Unit = { track ->
        DiscoveryTrackActions(
            trackTitle = track.title,
            isFavorite = track.id in state.favoriteIds,
            onFavorite = { viewModel.toggleFavorite(track) },
            onAddToPlaylist = { addToPlaylistTarget = track },
            onShare = { shareFreshTrack(track) },
            onOpenAlbum = if (track.album.isNotBlank()) {
                { viewModel.openAlbum(trackAlbumHit(track)) }
            } else {
                null
            }
        )
    }
    val exploreBottomInset = tabBarBottomContentInset(
        miniPlayerVisible = state.currentTrack != null,
        animationsEnabled = state.animationsEnabled
    )
    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Color.Transparent)
    ) {
        if (DerbisIsYouTubeMusic) {
            YouTubeMusicExploreScreen(
                viewModel, listState, state.currentTrack?.id, exploreBottomInset, availableAnchors, onShortcut, onOpenJam, onLiveRadioOpenChange,
                onOpenMood = { title, params ->
                    exploreMoodReturn = null
                    exploreDestination = exploreCategoryDestination(ExploreCategory(title, params))
                }
            ) { addToPlaylistTarget = it }
        } else LazyColumn(
            state = listState,
            modifier = Modifier.fillMaxSize().statusBarsPadding(),
            contentPadding = PaddingValues(top = 14.dp, bottom = exploreBottomInset),
            verticalArrangement = Arrangement.spacedBy(14.dp)
        ) {
            items(
                items = rows,
                key = { row -> row.key },
                contentType = { row -> row::class }
            ) { row ->
                ExploreContentRow(
                    row = row,
                    state = state,
                    viewModel = viewModel,
                    fresh = freshSection,
                    availableAnchors = availableAnchors,
                    mixAccent = exploreMixAccent,
                    onShortcut = onShortcut,
                    onPlayFresh = onPlayFresh,
                    onSelectFreshScope = { scope -> freshScope = scope },
                    onOpenJam = onOpenJam,
                    onOpenRadio = { onLiveRadioOpenChange(true) },
                    onOpenMoods = {
                        exploreMoodReturn = null
                        exploreDestination = ExploreMoodsDestination
                    },
                    onOpenZone = { zone ->
                        viewModel.selectExploreZone(zone)
                        exploreMoodReturn = null
                        exploreDestination = exploreMoodDestination(zone.id)
                    },
                    onPlayTrack = onPlayFreshTrack,
                    trackActions = freshTrackActions
                )
            }
        }

        ExploreOverlays(
            state = state,
            viewModel = viewModel,
            strings = strings,
            zones = zones,
            backEnabled = backEnabled,
            liveRadioOpen = liveRadioOpen,
            addToPlaylistTarget = addToPlaylistTarget,
            exploreDestination = exploreDestination,
            exploreMoodReturn = exploreMoodReturn,
            onAddToPlaylistTargetChange = { addToPlaylistTarget = it },
            onDestinationChange = { exploreDestination = it },
            onMoodReturnChange = { exploreMoodReturn = it },
            onLiveRadioOpenChange = onLiveRadioOpenChange
        )

        trackStoryShareTarget?.let { track ->
            TrackStoryShareSheet(
                track = track,
                onDismiss = { trackStoryShareTarget = null }
            )
        }
    }
}

@Immutable
private class ExploreFreshSection(
    val scopes: List<ExploreFreshScope>,
    val feed: ExploreFreshFeed,
    val momentPages: List<List<Track>>,
    val regionLabel: String
)

@Composable
private fun ExploreContentRow(
    row: ExploreRow,
    state: DerbisUiState,
    viewModel: ExploreViewModel,
    fresh: ExploreFreshSection,
    availableAnchors: Set<ExploreAnchor>,
    mixAccent: Color,
    onShortcut: (ExploreShortcut) -> Unit,
    onPlayFresh: (() -> Unit)?,
    onSelectFreshScope: (ExploreFreshScope) -> Unit,
    onOpenJam: () -> Unit,
    onOpenRadio: () -> Unit,
    onOpenMoods: () -> Unit,
    onOpenZone: (ExploreZone) -> Unit,
    onPlayTrack: (Track) -> Unit,
    trackActions: @Composable (Track) -> Unit
) {
    val strings = LocalDerbisStrings.current
    when (row) {
        ExploreRow.Shortcuts -> Column(
            verticalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            ExplorePageHeader(
                title = strings.exploreTitle,
                subtitle = strings.exploreSubtitle,
                modifier = Modifier.padding(horizontal = HomeHorizontalInset)
            )
            ExplorePrimaryShortcuts(
                availableAnchors = availableAnchors,
                onSelect = onShortcut,
                onOpenJam = onOpenJam,
                onOpenRadio = onOpenRadio,
                modifier = Modifier
            )
        }
        ExploreRow.MixTools -> Column(
            verticalArrangement = Arrangement.spacedBy(6.dp)
        ) {
            ExploreSectionHeader(title = strings.derbisMix, subtitle = strings.mixCreate)
            DerbisMixLauncherPanel(
                familiarity = state.mixFamiliarity,
                loading = state.mixLoading,
                accent = mixAccent,
                onFamiliarityChange = viewModel::setMixFamiliarity,
                onStartMix = { kind -> viewModel.startDerbisMix(kind) },
                onOpenYourSound = viewModel::openYourSound,
                onOpenMixLab = { viewModel.openMixLab() },
                modifier = Modifier.padding(horizontal = HomeHorizontalInset)
            )
        }
        is ExploreRow.Header -> ExploreAnchorHeader(
            anchor = row.anchor,
            onPlayFresh = onPlayFresh,
            onOpenMoods = onOpenMoods
        )
        ExploreRow.FreshLoading -> Box(
            modifier = Modifier.fillMaxWidth().padding(vertical = 28.dp),
            contentAlignment = Alignment.Center
        ) {
            DiscoveryLoadingIndicator(modifier = Modifier.size(40.dp), color = MaterialTheme.colorScheme.primary)
        }
        ExploreRow.FreshEmpty -> Box(modifier = Modifier.padding(horizontal = HomeHorizontalInset)) {
            EmptyState(strings.exploreEmpty)
        }
        ExploreRow.FreshScopes -> ExploreFreshScopeRail(
            scopes = fresh.scopes,
            selected = fresh.feed.scope,
            localLabel = fresh.regionLabel,
            onSelect = onSelectFreshScope
        )
        ExploreRow.FreshSpotlight -> ExploreFreshSpotlight(
            tracks = fresh.feed.spotlight,
            currentTrackId = state.currentTrack?.id,
            isPlaying = state.isPlaying,
            isResolving = state.isResolving,
            onPlay = onPlayTrack,
            onOpenAlbum = { track -> viewModel.openAlbum(trackAlbumHit(track)) },
            actions = { track -> trackActions(track) }
        )
        ExploreRow.FreshMoment -> Column(
            verticalArrangement = Arrangement.spacedBy(6.dp)
        ) {
            ExploreFreshMomentHeader(
                title = strings.freshMomentTitle,
                onShowAll = { onShortcut(ExploreShortcut.NewReleases) }
            )
            ExploreFreshMomentRail(
                pages = fresh.momentPages,
                currentTrackId = state.currentTrack?.id,
                isPlaying = state.isPlaying,
                isResolving = state.isResolving,
                onPlay = onPlayTrack,
                actions = { track -> trackActions(track) }
            )
        }
        is ExploreRow.MoodRail -> ExploreMoodRailRow(
            zones = row.zones,
            selectedZoneId = state.exploreZoneId,
            onOpenAll = onOpenMoods,
            onOpenZone = onOpenZone,
            onStartZoneMix = { zone ->
                viewModel.startDerbisMix(
                    kind = DerbisMixKind.Genre,
                    seedQuery = zone.query,
                    label = zone.label
                )
            }
        )
    }
}

@Composable
private fun ExploreAnchorHeader(
    anchor: ExploreAnchor,
    onPlayFresh: (() -> Unit)?,
    onOpenMoods: () -> Unit
) {
    val strings = LocalDerbisStrings.current
    when (anchor) {
        ExploreAnchor.Fresh -> ExploreFreshSectionHeader(
            title = strings.exploreFresh,
            onPlayAll = onPlayFresh
        )
        ExploreAnchor.Moods -> ExploreSectionHeader(
            title = strings.exploreMoods,
            onShowAll = onOpenMoods
        )
    }
}

@Composable
private fun ExploreMoodRailRow(
    zones: List<ExploreZone>,
    selectedZoneId: String?,
    onOpenAll: () -> Unit,
    onOpenZone: (ExploreZone) -> Unit,
    onStartZoneMix: (ExploreZone) -> Unit
) {
    val strings = LocalDerbisStrings.current
    val moodZones = remember(zones) {
        val filtered = zones.filter { it.id != ExploreCatalog.NEW_RELEASES_ZONE_ID }
        if (filtered.isNotEmpty()) filtered else zones
    }
    val rows = remember(moodZones) { moodZones.take(ExploreMoodGridLimit).chunked(2) }

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = HomeHorizontalInset),
        verticalArrangement = Arrangement.spacedBy(10.dp)
    ) {
        rows.forEach { row ->
            Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                row.forEach { zone ->
                    key(zone.id) {
                        val artworkUrl = rememberExploreMoodArtworkUrl(zone)
                        ExploreDiscoveryCategoryCard(
                            title = zone.label,
                            identity = zone.id,
                            artworkUrl = artworkUrl,
                            accentColors = if (DerbisIsNocturne) DerbisPanel to DerbisPanelSoft else Color(zone.accentStart) to Color(zone.accentEnd),
                            modifier = Modifier
                                .weight(1f)
                                .height(100.dp),
                            onLongClick = { onStartZoneMix(zone) },
                            onClick = { onOpenZone(zone) }
                        )
                    }
                }
                if (row.size == 1) {
                    ExploreDiscoveryCategoryCard(
                        title = strings.showAll,
                        identity = "all-moods",
                        accentColors = Color(0xFF343C48) to Color(0xFF202632),
                        modifier = Modifier
                            .weight(1f)
                            .height(100.dp),
                        onClick = onOpenAll
                    )
                }
            }
        }
    }
}

private const val ExploreMoodGridLimit = 8

@Composable
private fun ExploreOverlays(
    state: DerbisUiState,
    viewModel: ExploreViewModel,
    strings: DerbisStrings,
    zones: List<ExploreZone>,
    backEnabled: Boolean,
    liveRadioOpen: Boolean,
    addToPlaylistTarget: Track?,
    exploreDestination: String?,
    exploreMoodReturn: String?,
    onAddToPlaylistTargetChange: (Track?) -> Unit,
    onDestinationChange: (String?) -> Unit,
    onMoodReturnChange: (String?) -> Unit,
    onLiveRadioOpenChange: (Boolean) -> Unit
) {
    val appleStyle = DerbisIsAppleMusic
    addToPlaylistTarget?.let { target ->
        AddToPlaylistDialog(
            track = target,
            playlists = state.playlists,
            onDismiss = { onAddToPlaylistTargetChange(null) },
            onAddTo = { playlistId ->
                viewModel.addToPlaylist(playlistId, target)
                onAddToPlaylistTargetChange(null)
            },
            onCreateWith = { name ->
                viewModel.createPlaylist(name, target)
                onAddToPlaylistTargetChange(null)
            }
        )
    }

    when (exploreDestination) {
        ExploreNewReleasesDestination -> ExploreNewReleasesDestinationScreen(
            releases = state.exploreNewReleases,
            isLoading = state.isNewReleasesLoading,
            strings = strings,
            backEnabled = backEnabled,
            onBack = { onDestinationChange(null) },
            onOpenRelease = viewModel::openAlbum,
            bottomInset = exploreDestinationBottomInset(state)
        )
        ExploreMoodsDestination -> ExploreMoodsDestinationScreen(
            zones = zones,
            categories = state.exploreCategories,
            categoryArtwork = state.exploreCategoryArtwork,
            isLoading = state.isExploreCategoriesLoading,
            strings = strings,
            backEnabled = backEnabled,
            onBack = { onDestinationChange(null) },
            onOpenZone = { zone ->
                viewModel.selectExploreZone(zone)
                onMoodReturnChange(ExploreMoodsDestination)
                onDestinationChange(exploreMoodDestination(zone.id))
            },
            onOpenCategory = { category ->
                if (!appleStyle) viewModel.selectExploreCategory(category)
                onMoodReturnChange(ExploreMoodsDestination)
                onDestinationChange(exploreCategoryDestination(category))
            },
            onRequestCategoryArtwork = viewModel::ensureExploreCategoryArtwork,
            bottomInset = exploreDestinationBottomInset(state)
        )
        else -> ExploreMoodCollectionDestination(
            destination = exploreDestination,
            returnDestination = exploreMoodReturn,
            zones = zones,
            state = state,
            strings = strings,
            viewModel = viewModel,
            onTrackActions = onAddToPlaylistTargetChange,
            backEnabled = backEnabled,
            onDestinationChange = onDestinationChange
        )
    }


    if (liveRadioOpen) {
        LiveRadioScreen(
            languageCode = state.languageCode,
            currentStationId = state.currentTrack
                ?.takeIf { it.isLiveRadio() }
                ?.id
                ?.removePrefix("live-radio:"),
            isPlaying = state.isPlaying,
            backEnabled = backEnabled,
            onBack = { onLiveRadioOpenChange(false) },
            onPlay = viewModel::playLiveRadio
        )
    }
}

@Composable
private fun ExploreMoodCollectionDestination(
    destination: String?,
    returnDestination: String?,
    zones: List<ExploreZone>,
    state: DerbisUiState,
    strings: DerbisStrings,
    viewModel: ExploreViewModel,
    onTrackActions: (Track) -> Unit,
    backEnabled: Boolean,
    onDestinationChange: (String?) -> Unit
) {
    val providerCategory = exploreCategoryDestinationValue(destination)
    if (providerCategory != null) {
        val activeCategory = state.exploreCategories
            .firstOrNull { category -> category.params == providerCategory.params }
            ?: providerCategory
        if (DerbisIsAppleMusic) {
            AppleMusicGenreScreen(
                title = activeCategory.title,
                storefront = ChartsCatalog.region(state.selectedChartId).country,
                currentId = state.currentTrack?.id,
                bottomInset = exploreDestinationBottomInset(state),
                exploreViewModel = viewModel,
                onTrackActions = onTrackActions,
                backEnabled = backEnabled,
                onBack = { onDestinationChange(returnDestination) }
            )
            return
        }
        val categoryTracks: @Composable () -> Unit = {
            val isActive = state.exploreCategoryParams == providerCategory.params
            val tracks = if (isActive) state.exploreTracks else emptyList()
            LaunchedEffect(providerCategory.params, state.languageCode, isActive) {
                if (!isActive) viewModel.selectExploreCategory(activeCategory)
            }
            ExploreCollectionDestinationScreen(
                identity = providerCategory.params,
                title = activeCategory.title,
                subtitle = activeCategory.section.ifBlank { strings.exploreMoods },
                zone = null,
                tracks = tracks,
                isLoading = state.isExploreLoading || !isActive,
                currentTrackId = state.currentTrack?.id,
                isPlaying = state.isPlaying,
                strings = strings,
                backEnabled = backEnabled,
                onBack = { onDestinationChange(returnDestination) },
                onPlayAll = { tracks.firstOrNull()?.let { viewModel.playFrom(tracks, it) } },
                onPlayTrack = { track -> viewModel.playFrom(tracks, track) },
                onRequestTrackArtwork = viewModel::ensureExploreTrackArtwork,
                bottomInset = exploreDestinationBottomInset(state)
            )
        }
        if (DerbisIsSpotify) {
            SpotifyGenreScreen(
                title = activeCategory.title,
                params = providerCategory.params,
                languageCode = state.languageCode,
                bottomInset = exploreDestinationBottomInset(state),
                backEnabled = backEnabled,
                onBack = { onDestinationChange(returnDestination) },
                onOpenPlaylist = viewModel::openPlaylistHit,
                fallback = categoryTracks
            )
        } else if (DerbisIsYouTubeMusic) {
            YouTubeMusicGenreScreen(
                title = activeCategory.title,
                params = providerCategory.params,
                languageCode = state.languageCode,
                bottomInset = exploreDestinationBottomInset(state),
                backEnabled = backEnabled,
                onBack = { onDestinationChange(returnDestination) },
                onSearch = viewModel::openSearch,
                onOpenPlaylist = viewModel::openPlaylistHit,
                fallback = categoryTracks
            )
        } else {
            categoryTracks()
        }
        return
    }

    val zoneId = exploreMoodDestinationId(destination) ?: return
    val zone = zones.firstOrNull { candidate -> candidate.id == zoneId } ?: return
    val isActive = state.exploreZoneId == zone.id
    val tracks = if (isActive) state.exploreTracks else emptyList()
    LaunchedEffect(zone.id, state.languageCode, isActive) {
        if (!isActive) viewModel.selectExploreZone(zone)
    }
    ExploreCollectionDestinationScreen(
        identity = zone.id,
        title = zone.label,
        subtitle = strings.exploreMoods,
        zone = zone,
        tracks = tracks,
        isLoading = state.isExploreLoading || !isActive,
        currentTrackId = state.currentTrack?.id,
        isPlaying = state.isPlaying,
        strings = strings,
        backEnabled = backEnabled,
        onBack = { onDestinationChange(returnDestination) },
        onPlayAll = { tracks.firstOrNull()?.let { viewModel.playFrom(tracks, it) } },
        onPlayTrack = { track -> viewModel.playFrom(tracks, track) },
        onRequestTrackArtwork = viewModel::ensureExploreTrackArtwork,
        bottomInset = exploreDestinationBottomInset(state)
    )
}

@Composable
private fun exploreDestinationBottomInset(state: DerbisUiState): Dp = tabBarBottomContentInset(
    miniPlayerVisible = state.currentTrack != null,
    animationsEnabled = state.animationsEnabled
)

@Composable
private fun ExploreFreshSectionHeader(
    title: String,
    onPlayAll: (() -> Unit)?
) {
    DerbisSectionHeader(
        title = remember(title) { cleanHomeSectionTitle(title) },
        titleColor = MaterialTheme.colorScheme.onSurface,
        modifier = Modifier.padding(horizontal = HomeHorizontalInset, vertical = 2.dp)
    ) {
        onPlayAll?.let { action -> DerbisSectionPlayAll(onClick = action) }
    }
}

@Composable
private fun ExploreSectionHeader(
    title: String,
    subtitle: String? = null,
