@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
internal fun ExplorePrimaryShortcuts(
    availableAnchors: Set<ExploreAnchor>,
    onSelect: (ExploreShortcut) -> Unit,
    onOpenJam: () -> Unit,
    onOpenRadio: () -> Unit,
    modifier: Modifier = Modifier
) {
    val strings = LocalDerbisStrings.current
    val radioStrings = com.yasuda.derbis.ui.i18n.DerbisLiveRadioCatalog.forCode(strings.code)
    val colors = MaterialTheme.colorScheme
    val entries = buildList {
        if (ExploreAnchor.Fresh in availableAnchors) {
            add(ExploreShortcutEntry("releases", Icons.Rounded.AutoAwesome, strings.exploreNewReleases, MaterialShapes.Sunny, colors.primaryContainer, colors.onPrimaryContainer) { onSelect(ExploreShortcut.NewReleases) })
        }
        if (ExploreAnchor.Moods in availableAnchors) {
            add(ExploreShortcutEntry("moods", Icons.Rounded.Mood, strings.exploreMoods, MaterialShapes.Clover4Leaf, colors.secondaryContainer, colors.onSecondaryContainer) { onSelect(ExploreShortcut.Moods) })
        }
        add(ExploreShortcutEntry("radio", Icons.Rounded.Radio, radioStrings.title, MaterialShapes.SoftBurst, colors.errorContainer, colors.onErrorContainer, onOpenRadio))
        add(ExploreShortcutEntry("jam", Icons.Rounded.PersonAdd, strings.jamTitle, MaterialShapes.Cookie9Sided, colors.inversePrimary, colors.onPrimaryContainer, onOpenJam))
    }
    Column(
        modifier = modifier
            .fillMaxWidth()
            .padding(horizontal = HomeHorizontalInset),
        verticalArrangement = Arrangement.spacedBy(if (DerbisIsAppleMusic) 0.dp else 10.dp)
    ) {
        entries.chunked(if (DerbisIsAppleMusic) 1 else if (DerbisIsYouTubeMusic) 3 else 2).forEach { pair ->
            Row(horizontalArrangement = Arrangement.spacedBy(if (DerbisIsYouTubeMusic) 16.dp else 10.dp)) {
                pair.forEach { entry ->
                    key(entry.key) {
                        ExploreShortcutTile(entry = entry, modifier = Modifier.weight(1f))
                    }
                }
                if (DerbisIsYouTubeMusic) {
                    repeat(3 - pair.size) { Spacer(modifier = Modifier.weight(1f)) }
                } else if (pair.size == 1 && !DerbisIsAppleMusic) {
                    Spacer(modifier = Modifier.weight(1f))
                }
            }
        }
    }
}

@Immutable
private class ExploreShortcutEntry(
    val key: String,
    val icon: ImageVector,
    val label: String,
    val polygon: RoundedPolygon,
    val container: Color,
    val content: Color,
    val onClick: () -> Unit
)

@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
private fun ExploreShortcutTile(
    entry: ExploreShortcutEntry,
    modifier: Modifier = Modifier
) {
    if (DerbisIsSpotify) {
        SpotifyExploreTile(entry.label, entry.icon, modifier, entry.onClick)
    } else if (DerbisIsYouTubeMusic) {
        YouTubeMusicShortcutTile(entry.label, entry.icon, entry.onClick, modifier)
    } else if (DerbisIsAppleMusic) {
        AppleMusicLinkRow(entry.label, entry.icon, modifier, entry.onClick)
    } else {
        DerbisExploreShortcutTile(entry, modifier)
    }
}

@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
private fun DerbisExploreShortcutTile(
    entry: ExploreShortcutEntry,
    modifier: Modifier
) {
    val colors = MaterialTheme.colorScheme
    val animationsEnabled = LocalAnimationsEnabled.current
    val interaction = remember { MutableInteractionSource() }
    val pressed by interaction.collectIsPressedAsState()
    val rotation by animateFloatAsState(
        targetValue = if (pressed && animationsEnabled) -14f else 0f,
        animationSpec = spring(dampingRatio = Spring.DampingRatioMediumBouncy, stiffness = Spring.StiffnessMedium),
        label = "explore-shortcut-rotation"
    )
    val nocturne = DerbisIsNocturne
    val skinned = DerbisSkinManagesLayout
    val iconShape = if (skinned) SkinChrome.iconShape else entry.polygon.toShape()
    val tileShape = exploreShortcutShape()
    val tileSurface = if (DerbisIsLiquidGlass) {
        Modifier.derbisGlass(
            shape = tileShape,
            baseTint = entry.container,
            fallbackColor = DerbisPanel.copy(alpha = 0.72f),
            fallbackBorderColor = Color.White.copy(alpha = 0.30f),
            intensity = DerbisGlassIntensity.Subtle,
            artworkTint = DerbisActivePalette.cyan
        )
    } else {
        Modifier.background(if (skinned) DerbisPanel else lerp(colors.surfaceContainerHigh, entry.container, 0.32f))
    }
    Row(
        modifier = modifier
            .heightIn(min = 68.dp)
            .clip(tileShape)
            .then(tileSurface)
            .derbisPressable(
                onClick = entry.onClick,
                onClickLabel = entry.label,
                role = Role.Button,
                pressedScale = DerbisPressScale.Control,
                interactionSource = interaction
            )
            .padding(start = 10.dp, end = 12.dp, top = 10.dp, bottom = 10.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(12.dp)
    ) {
        Box(
            modifier = Modifier
                .size(46.dp)
                .graphicsLayer { rotationZ = rotation }
                .clip(iconShape)
                .background(if (skinned) SkinChrome.iconBackground else entry.container),
            contentAlignment = Alignment.Center
        ) {
            Icon(
                imageVector = entry.icon,
                contentDescription = null,
                tint = if (skinned) SkinChrome.iconTint else entry.content,
                modifier = Modifier
                    .size(22.dp)
                    .graphicsLayer { rotationZ = -rotation }
            )
        }
        BasicText(
            text = entry.label,
            style = MaterialTheme.typography.titleSmall.copy(fontWeight = if (skinned) FontWeight.Medium else FontWeight.Bold, color = colors.onSurface),
            maxLines = if (nocturne) 2 else 1,
            overflow = TextOverflow.Ellipsis,
            autoSize = TextAutoSize.StepBased(minFontSize = 11.sp, maxFontSize = 14.sp),
            modifier = Modifier.weight(1f)
        )
    }
}

@Composable
private fun TrackGlassCard(
    track: Track,
    isCurrent: Boolean,
    isPlaying: Boolean,
    isFavorite: Boolean,
    onClick: () -> Unit,
    onFavorite: () -> Unit,
    onShare: () -> Unit,
    onAddToPlaylist: () -> Unit
) {
    val scale by animateFloatAsState(if (isCurrent) 1.02f else 1f, label = "scale")
    var menuExpanded by remember { mutableStateOf(false) }
    Column(
        modifier = Modifier
            .width(140.dp)
            .graphicsLayer {
                scaleX = scale
                scaleY = scale
            }
            .clip(RoundedCornerShape(6.dp))
            .clickable(onClick = onClick),
        verticalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        Box(
            modifier = Modifier
                .size(140.dp)
                .clip(RoundedCornerShape(6.dp))
                .border(Dp.Hairline, Color.White.copy(alpha = 0.15f), RoundedCornerShape(6.dp))
        ) {
            AsyncImage(
                model = ImageRequest.Builder(LocalContext.current)
                    .data(track.thumbnailUrl)
                    .crossfade(true)
                    .build(),
                contentDescription = null,
                contentScale = ContentScale.Crop,
                modifier = Modifier.fillMaxSize()
            )
            if (isCurrent) {
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .background(Color.Black.copy(alpha = 0.4f)),
                    contentAlignment = Alignment.Center
                ) {
                    if (isPlaying) {
                        Icon(Icons.Rounded.Pause, null, tint = Color.White, modifier = Modifier.size(32.dp))
                    } else {
                        Icon(Icons.Rounded.PlayArrow, null, tint = Color.White, modifier = Modifier.size(32.dp))
                    }
                }
            }

            Box(
                modifier = Modifier
                    .align(Alignment.TopEnd)
                    .padding(4.dp)
            ) {
                IconButton(
                    onClick = { menuExpanded = true },
                    modifier = Modifier
                        .size(28.dp)
                        .background(Color.Black.copy(alpha = 0.5f), CircleShape)
                ) {
                    Icon(Icons.Rounded.MoreVert, contentDescription = LocalDerbisStrings.current.more, tint = Color.White, modifier = Modifier.size(18.dp))
                }
                DropdownMenu(
                    expanded = menuExpanded,
                    onDismissRequest = { menuExpanded = false },
                    modifier = Modifier.background(CinematicGlass)
                ) {
                    DropdownMenuItem(
                        text = { Text(if (isFavorite) LocalDerbisStrings.current.removeFromFavorites else LocalDerbisStrings.current.addToFavorites, color = Color.White) },
                        onClick = {
                            onFavorite()
                            menuExpanded = false
                        }
                    )
                    DropdownMenuItem(
                        text = { Text(LocalDerbisStrings.current.share, color = Color.White) },
                        onClick = {
                            onShare()
                            menuExpanded = false
                        }
                    )
                    DropdownMenuItem(
                        text = { Text(LocalDerbisStrings.current.addToPlaylist, color = Color.White) },
                        onClick = {
                            onAddToPlaylist()
                            menuExpanded = false
                        }
                    )
                }
            }
        }
        Column(verticalArrangement = Arrangement.spacedBy(2.dp)) {
            Text(
                track.title,
                color = Color.White,
                fontSize = 14.sp,
                lineHeight = DerbisTypeRhythm.lineHeight(14.sp),
                fontWeight = FontWeight.SemiBold,
                maxLines = 2,
                overflow = TextOverflow.Ellipsis
            )
            Text(
                track.artist,
                color = DerbisMuted.copy(alpha = 0.76f),
                fontSize = 12.sp,
                fontWeight = FontWeight.SemiBold,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
        }
    }
}

@Composable
private fun VideoGlassCard(
    track: Track,
    isCurrent: Boolean,
    isPlaying: Boolean,
    onClick: () -> Unit
) {
    val strings = LocalDerbisStrings.current
    val viewCount = remember(track.youtubeViewCount, strings.code) {
        formatSearchViewCount(track.youtubeViewCount, strings.code)
    }
    val metadata = remember(track.artist, viewCount) {
        listOf(track.artist.trim(), viewCount.trim())
            .filter(String::isNotBlank)
            .joinToString(" · ")
    }
    Column(
        modifier = Modifier
            .width(260.dp)
            .pressable(onClick = onClick),
        verticalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        val shape = RoundedCornerShape(11.dp)
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .aspectRatio(16f / 9f)
                .clip(shape)
                .background(DerbisPanelSoft)
                .then(
                    if (isCurrent) {
                        Modifier.border(1.5.dp, Color.White.copy(alpha = 0.72f), shape)
                    } else {
                        Modifier
                    }
                )
        ) {
            AsyncImage(
                model = ImageRequest.Builder(LocalContext.current)
                    .data(track.largeThumbnailUrl.ifEmpty { track.thumbnailUrl })
                    .crossfade(true)
                    .build(),
                contentDescription = track.title,
                contentScale = ContentScale.Crop,
                modifier = Modifier.fillMaxSize()
            )
            Box(
                modifier = Modifier
                    .matchParentSize()
                    .background(
                        Brush.verticalGradient(
                            colorStops = arrayOf(
                                0f to Color.Transparent,
                                0.76f to Color.Transparent,
                                1f to Color.Black.copy(alpha = 0.24f)
                            )
                        )
                    )
            )
            if (isCurrent) {
                Box(
                    modifier = Modifier
                        .align(Alignment.BottomStart)
                        .padding(10.dp)
                        .size(32.dp)
                        .background(Color.Black.copy(alpha = 0.58f), CircleShape),
                    contentAlignment = Alignment.Center
                ) {
                    if (isPlaying) {
                        DerbisPlayingIndicator(
                            playing = true,
                            color = Color.White,
                            size = 16.dp,
                            contentDescription = strings.playing
                        )
                    } else {
                        Icon(
                            imageVector = Icons.Rounded.PlayArrow,
                            contentDescription = strings.play,
                            tint = Color.White,
                            modifier = Modifier.size(18.dp)
                        )
                    }
                }
            }
        }
        Text(
            text = track.title,
            color = DerbisText,
            fontSize = 14.5.sp,
            lineHeight = DerbisTypeRhythm.lineHeight(14.5.sp),
            fontWeight = FontWeight.SemiBold,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis
        )
        if (metadata.isNotBlank()) {
            Text(
                text = metadata,
                color = DerbisMuted,
                fontSize = 12.sp,
                lineHeight = DerbisTypeRhythm.lineHeight(12.sp),
                fontWeight = FontWeight.Normal,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
        }
    }
}

