@Composable
internal fun BottomTabs(
    selected: DerbisTab,
    compaction: () -> Float,
    onSelect: (DerbisTab) -> Unit
) {
    val entries = rememberDerbisTabEntries()
    val animationsEnabled = LocalAnimationsEnabled.current
    val haptics = LocalDerbisHaptics.current
    val isLight = DerbisIsLight
    val selectedTint = DerbisText
    val selectedIndex = entries.indexOfFirst { it.tab == selected }.coerceAtLeast(0)
    val indicatorPosition by animateFloatAsState(
        targetValue = selectedIndex.toFloat(),
        animationSpec = if (animationsEnabled) {
            spring(dampingRatio = 0.76f, stiffness = Spring.StiffnessMediumLow)
        } else {
            snap()
        },
        label = "tab-indicator-position"
    )
    val indicatorColor = selectedTint.copy(alpha = if (isLight) 0.08f else 0.11f)

    Column(modifier = Modifier.fillMaxWidth()) {
            BoxWithConstraints(
                modifier = Modifier
                    .dockClipHeight(compaction, DerbisTabBarHeight - DerbisTabBarCompactHeight)
                    .fillMaxWidth()
                    .height(DerbisTabBarHeight)
            ) {
                val slotWidth = maxWidth / entries.size
                val indicatorWidth = (slotWidth - 34.dp).coerceIn(40.dp, 52.dp)
                val density = LocalDensity.current
                val slotPx = with(density) { slotWidth.toPx() }
                val indicatorPx = with(density) { indicatorWidth.toPx() }
                val indicatorTopPx = with(density) { DerbisTabIndicatorTop.roundToPx() }

                Box(
                    modifier = Modifier
                        .offset {
                            IntOffset(
                                (slotPx * indicatorPosition + (slotPx - indicatorPx) / 2f).roundToInt(),
                                indicatorTopPx
                            )
                        }
                        .size(width = indicatorWidth, height = DerbisTabIndicatorHeight)
                        .background(indicatorColor, DerbisTabIndicatorShape)
                )

                Row(
                    modifier = Modifier
                        .fillMaxSize()
                        .selectableGroup(),
                    verticalAlignment = Alignment.Top
                ) {
                    entries.forEach { entry ->
                        val isSelected = entry.tab == selected
                        TabButton(
                            entry = entry,
                            isSelected = isSelected,
                            selectedTint = selectedTint,
                            compaction = compaction,
                            onClick = {
                                if (!isSelected) {
                                    haptics.perform(DerbisHapticAction.SeekSnap)
                                }
                                onSelect(entry.tab)
                            }
                        )
                    }
                }
            }
            Spacer(modifier = Modifier.navigationBarsPadding())
    }
}


