    DerbisSkinManagesLayout && id in setOf("theme", "mini_player", "navigation")

private fun searchFieldContainer(focused: Boolean, scheme: androidx.compose.material3.ColorScheme): Color = when {
    DerbisIsTorque -> Color(0xFFF1F1F1)
    DerbisIsSpotify -> SpotifyDesign.searchField
    DerbisIsYouTubeMusic -> YouTubeMusicDesign.surfaceHigh
    DerbisIsAppleMusic -> AppleMusicDesign.fill
    DerbisIsIvory -> DerbisActivePalette.ink
    DerbisIsPrism -> if (focused) scheme.surfaceContainerHigh else scheme.surfaceContainer
    else -> if (focused) scheme.surfaceContainerHighest else scheme.surfaceContainerHigh
}

private fun searchFieldIconTint(active: Boolean, scheme: androidx.compose.material3.ColorScheme): Color = when {
    DerbisIsTorque -> Color(0xFF111111)
    DerbisIsSpotify -> SpotifyDesign.searchFieldText
    DerbisIsYouTubeMusic -> YouTubeMusicDesign.textSecondary
    DerbisIsAppleMusic -> AppleMusicDesign.secondaryLabel
    DerbisIsIvory -> DerbisText
    DerbisIsPrism -> if (active) scheme.primary else scheme.onSurfaceVariant
    else -> if (active) scheme.onPrimaryContainer else scheme.onSurfaceVariant
}

private fun searchFieldCorner(fallback: Dp): Dp = when {
    DerbisIsNocturne -> Nocturne78Design.cardCorner
    DerbisIsSpotify -> SpotifyDesign.corner
    DerbisIsYouTubeMusic -> 20.dp
    DerbisIsAppleMusic -> AppleMusicDesign.cornerL
    DerbisIsPrism -> PrismDesign.controlCorner
    else -> fallback
}

private fun searchFocusRing(scheme: androidx.compose.material3.ColorScheme, focusRingAlpha: Float): Brush =
    if (DerbisIsPrism) SolidColor(scheme.primary.copy(alpha = 0.7f * focusRingAlpha)) else Brush.linearGradient(
        listOf(
            scheme.primary.copy(alpha = 0.9f * focusRingAlpha),
            scheme.tertiary.copy(alpha = 0.75f * focusRingAlpha),
            scheme.primary.copy(alpha = 0.35f * focusRingAlpha)
        )
    )

@Composable
private fun SettingsHubHeader(onClose: () -> Unit) {
    val strings = LocalDerbisStrings.current
    if (SkinChrome.active) PrismPageHeader(strings.settings, strings.settingsSubtitle) {
        IconButton(onClick = onClose, modifier = Modifier.size(48.dp)) { Icon(Icons.Rounded.Close, strings.close, tint = DerbisText) }
    } else Row(
        modifier = Modifier.fillMaxWidth(),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.SpaceBetween
    ) {
        Column {
            Text(strings.settings, color = DerbisText, fontSize = 28.sp, fontWeight = FontWeight.Black)
            Text(strings.settingsSubtitle, color = DerbisMuted, fontSize = 13.sp, fontWeight = FontWeight.SemiBold)
        }
        CircleIconButton(
            icon = Icons.Rounded.Close,
            tint = DerbisText,
            background = Color.White.copy(alpha = 0.08f),
            onClick = onClose,
            contentDescription = strings.close
        )
    }
}

@Composable
private fun SettingsSkinSelection(interfaceSettings: DerbisInterfaceSettings, onInterfaceSettings: (DerbisInterfaceSettings) -> Unit) {
    SkinSelector(
        selected = interfaceSettings.skin,
        onSelect = { skin ->
            onInterfaceSettings(
                interfaceSettings.copy(
                    skin = skin,
                    liquidGlassEnabled = if (skin == DerbisSkin.LiquidGlass) true else interfaceSettings.liquidGlassEnabled
                )
            )
        }
    )
    if (interfaceSettings.skin == DerbisSkin.LiquidGlass) {
        PrismSettingsPanel(interfaceSettings.prism) { onInterfaceSettings(interfaceSettings.copy(prism = it)) }
    }
    if (interfaceSettings.skin == DerbisSkin.Torque) {
        TorqueSettingsPanel(interfaceSettings.torque) { onInterfaceSettings(interfaceSettings.copy(torque = it)) }
    }
    if (interfaceSettings.skin == DerbisSkin.Ivory) {
        IvorySettingsPanel(interfaceSettings.ivory) { onInterfaceSettings(interfaceSettings.copy(ivory = it)) }
    }
}

@Composable
private fun settingsTileShape(interactionSource: MutableInteractionSource, first: Boolean, last: Boolean): Shape {
    val outer = if (SkinChrome.active) SkinChrome.outerCorner else derbisExpressiveCorner(interactionSource, rest = 24.dp, pressed = 14.dp, label = "settingsTileOuter")
    val inner = if (SkinChrome.active) SkinChrome.innerCorner else derbisExpressiveCorner(interactionSource, rest = 6.dp, pressed = 14.dp, label = "settingsTileInner")
    return RoundedCornerShape(
        topStart = if (first) outer else inner,
        topEnd = if (first) outer else inner,
        bottomEnd = if (last) outer else inner,
        bottomStart = if (last) outer else inner
    )
}

private fun settingsChoiceContainer(active: Boolean): Color =
    if (SkinChrome.active) {
        if (active) SkinChrome.chipSelectedContainer else Color.Transparent
    } else if (active) DerbisCyan else Color.White.copy(alpha = 0.06f)

private fun settingsChoiceContent(active: Boolean): Color =
    if (SkinChrome.active) {
        if (active) SkinChrome.chipSelectedContent else DerbisText
    } else if (active) DerbisBlack else DerbisText

private fun exploreShortcutShape(): Shape = when {
    DerbisIsPrism -> PrismDesign.cut(PrismDesign.surfaceCorner)
    DerbisIsNocturne -> RoundedCornerShape(Nocturne78Design.cardCorner)
    else -> RoundedCornerShape(22.dp)
}

private fun artistPlayBackground(playContainer: Color, playShape: Shape): Modifier =
    when {
        DerbisIsPrism -> Modifier.clip(CircleShape).background(PrismAccent.gradient())
        DerbisIsNocturne -> Modifier.clip(RoundedCornerShape(Nocturne78Design.controlCorner)).background(DerbisPanelSoft)
            .border(1.dp, DerbisCyan, RoundedCornerShape(Nocturne78Design.controlCorner))
        else -> Modifier.background(playContainer, playShape)
    }

private fun albumTrackDownloadStatus(presentation: AlbumTrackRowPresentation, strings: DerbisStrings): String =
    if (presentation.isDownloading && !presentation.isDownloaded) {
        strings.formatDownloadProgress(presentation.downloadProgress ?: 1)
    } else {
        ""
    }

private fun albumTrackSubtitle(artist: String, status: String): String =
    listOf(artist, status).filter { it.isNotBlank() }.joinToString(" · ")

private fun albumTrackDuration(track: Track, spotify: Boolean): String =
    if (spotify) "" else formatDuration(track.durationMs).takeIf { it != "--:--" }.orEmpty()

private fun albumTrackRowBackground(presentation: AlbumTrackRowPresentation, stage: AlbumStageColors, spotify: Boolean): Color = when {
    presentation.selected -> stage.accent.copy(alpha = 0.26f)
    spotify -> Color.Transparent
    presentation.isCurrent -> stage.accent.copy(alpha = 0.16f)
    else -> stage.content.copy(alpha = 0.055f)
}

private fun albumTrackShowsArtist(trackArtist: String, albumArtist: String, spotify: Boolean): Boolean =
    trackArtist.isNotBlank() && (spotify || !trackArtist.trim().equals(albumArtist.trim(), ignoreCase = true))

@Composable
internal fun artistHeroNameSpacing(): TextUnit = when {
    DerbisIsTorque -> 2.sp
    DerbisIsSpotify -> (-1.4).sp
    else -> DerbisType.heroTitle.letterSpacing
}

private fun artistShuffleBackground(highlight: Color): Color = when {
    DerbisIsSpotify -> Color.Transparent
    DerbisSkinManagesLayout -> DerbisPanel
    else -> highlight.copy(alpha = 0.22f)
}

private fun artistShuffleTint(): Color = if (DerbisIsSpotify) SpotifyDesign.subdued else DerbisText

private fun artistShuffleIconSize(): Dp = if (DerbisIsSpotify) 28.dp else 22.dp

private fun artistPlaySize(): Dp = if (DerbisIsSpotify) SpotifyDesign.playButton else 62.dp

private fun searchSectionTitleWeight(): FontWeight = when {
    DerbisIsTorque || DerbisIsSpotify -> FontWeight.Bold
    DerbisIsIvory -> FontWeight.SemiBold
    DerbisSkinManagesLayout -> FontWeight.Normal
    else -> FontWeight.Black
}

private fun searchSectionTitleSpacing(): TextUnit = when {
    DerbisIsTorque || DerbisIsNocturne -> 1.8.sp
    DerbisIsIvory -> 0.2.sp
    DerbisIsSpotify -> (-0.4).sp
    else -> (-0.3).sp
}

private fun artistPlayContent(fallback: Color): Color = when {
    DerbisIsSpotify || DerbisIsYouTubeMusic -> Color.Black
    DerbisIsPrism -> Color.White
    DerbisIsNocturne -> DerbisCyan
    else -> fallback
}

private fun artistBiographyBackground(accentBrush: Brush): Modifier =
    Modifier.clip(if (DerbisSkinManagesLayout) RoundedCornerShape(SkinChrome.outerCorner) else ArtistBiographyShape)
        .background(DerbisPanel)
        .then(if (DerbisSkinManagesLayout) Modifier else Modifier.background(accentBrush))
